// Named save slots: world seed + edit log (world/editLog.js) + player
// state + inventory + game mode + a snapshot of whoever was connected in
// multiplayer at the time. Backed by IndexedDB, not localStorage —
// unlike every other piece of persisted state in this codebase
// (gameMode.js, settings.js, worldSeed.js, renderDistance.js, ...), a save
// blob can genuinely run from a few KB to low single-digit MB in a long or
// explosion-heavy session (world/editLog.js's own module comment), and
// multiple named slots multiply that — comfortably past what
// localStorage's ~5-10MB total quota should be trusted with. Those other,
// small settings stay exactly as they are; this is the one deliberate
// exception, not a wholesale migration.
//
// Gathers save data by importing the handful of modules that actually own
// it directly (player/state.js, inventory.js, gameMode.js, worldSeed.js,
// world/editLog.js, net/remotePlayers.js) — the same thing gameMode.js
// already does by importing player/state.js. loadGame() deliberately does
// NOT apply anything itself, only returns the saved blob — applying a load
// means rebuilding the space session and streaming chunks in a specific
// order (main.js's job, see the save/load plan), not something this module
// should reach into game state to do.

import { player } from '../player/state.js';
import { slots, getSelectedSlot } from '../inventory.js';
import { getGameMode } from '../gameMode.js';
import { getWorldSeedInput } from '../worldSeed.js';
import * as editLog from '../world/editLog.js';
import { remotePlayers } from '../net/remotePlayers.js';

const DB_NAME = 'blocksSaves';
const DB_VERSION = 1;
const STORE_NAME = 'slots';

// Opened lazily — never at import time (this codebase's own convention:
// gameMode.js/worldSeed.js/etc. all read persisted state only from an
// explicit init*() call, never as an import side effect — and here it also
// means importing this module in a non-browser context, e.g. `npm test`'s
// Node environment where `indexedDB` doesn't exist, never throws unless a
// save/load function is actually called).
let dbPromise = null;

function openDb() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB is not available in this browser/context'));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return dbPromise;
}

function promisifyRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function store(mode) {
  const db = await openDb();
  return db.transaction(STORE_NAME, mode).objectStore(STORE_NAME);
}

async function allRecords() {
  return promisifyRequest((await store('readonly')).getAll());
}

let nextId = null;   // lazily discovered from whatever's already saved

async function reserveNextId() {
  if (nextId === null) {
    const all = await allRecords();
    nextId = all.reduce((max, s) => Math.max(max, s.id), 0);
  }
  return ++nextId;
}

// Metadata only (id/name/savedAt/seedInput) for the load/save slot-list UI
// — the caller doesn't need a slot's full edit log just to show a list.
// (Reads the full record set under the hood; splitting into a separate
// metadata-only object store would avoid that, but isn't worth the extra
// complexity for the handful of slots a player realistically keeps.)
export async function listSaveSlots() {
  const all = await allRecords();
  return all
    .map(({ id, name, savedAt, seedInput }) => ({ id, name, savedAt, seedInput }))
    .sort((a, b) => b.savedAt - a.savedAt);
}

function gatherSaveData() {
  // Remote players' own inventory is never transmitted by the protocol at
  // all (src/net/protocol.js has no such message), so there's nothing to
  // save there beyond identity/appearance and last-known position/health —
  // see the save/load plan's own scoping note.
  const multiplayerPlayers = [...remotePlayers.values()].map(p => ({
    name: p.name,
    appearance: p.appearance,
    pos: { x: p.pos.x, y: p.pos.y, z: p.pos.z },
    yaw: p.yaw,
    hp: p.hp,
  }));

  return {
    version: 1,
    seedInput: getWorldSeedInput(),
    edits: editLog.serializeEdits(),
    player: {
      pos: { x: player.pos.x, y: player.pos.y, z: player.pos.z },
      yaw: player.yaw,
      pitch: player.pitch,
      hp: player.hp,
      maxHp: player.maxHp,
      flying: player.flying,
      // Space-only persistent orientation (see player/state.js's own
      // comment) — restoring it is what keeps the camera from visibly
      // "popping" to a fresh alignment the instant you load back in.
      spaceAlignQuat: {
        x: player.spaceAlignQuat.x, y: player.spaceAlignQuat.y,
        z: player.spaceAlignQuat.z, w: player.spaceAlignQuat.w,
      },
    },
    // Slots are already plain, JSON-safe objects (inventory.js's own
    // module comment) — cloned per-slot so later mutating the live
    // inventory can never reach back into an already-saved blob.
    inventory: { slots: slots.map(s => (s ? { ...s } : null)), selectedSlot: getSelectedSlot() },
    gameMode: getGameMode(),
    multiplayerPlayers: multiplayerPlayers.length ? multiplayerPlayers : undefined,
  };
}

// `overwriteId`, if given, replaces that slot in place (keeping its id);
// otherwise a new slot is created. Returns the slot id either way, and
// clears world/editLog.js's own dirty flag on success — the whole point
// the "quit without saving" reminder exists to protect against.
export async function saveGame(slotName, { overwriteId } = {}) {
  const data = gatherSaveData();
  const savedAt = Date.now();
  const id = overwriteId ?? await reserveNextId();
  const record = {
    id, name: slotName || ('Save ' + id), savedAt, seedInput: data.seedInput, data,
  };
  const s = await store('readwrite');
  await promisifyRequest(s.put(record));
  editLog.clearDirty();
  return id;
}

// Returns the raw saved blob (or null if the slot doesn't exist) — see the
// module comment on why this doesn't apply anything itself.
export async function loadGame(slotId) {
  const s = await store('readonly');
  const record = await promisifyRequest(s.get(slotId));
  return record ? record.data : null;
}

export async function deleteSaveSlot(slotId) {
  const s = await store('readwrite');
  await promisifyRequest(s.delete(slotId));
}
