// The 3x3 crafting grid.
//
// Recipes are shaped: the pattern has to match the layout of blocks in the
// grid, not just the ingredients. To keep it forgiving, the pattern is matched
// against the grid's bounding box, so a recipe drawn in the top-left corner
// still works if you build it in the middle.
//
// Pure logic — no DOM, no three.js — so the matcher is testable on its own.

import { VEHICLE_RECIPES, vehicleItem } from './vehicles/types.js';
import { TOOL_RECIPES, toolItem } from './tools/types.js';

export const GRID_SIZE = 3;
export const GRID_CELLS = GRID_SIZE * GRID_SIZE;

// The grid itself: 9 cells, each null or a block stack.
export const craftGrid = Array(GRID_CELLS).fill(null);

// The block id in a cell, or null.
function cellId(cell) {
  return cell && cell.kind === 'block' ? cell.id : null;
}

// Smallest rectangle containing everything in a 3x3 pattern, so a shape can be
// compared regardless of where it was drawn.
function boundsOf(pattern) {
  let minR = GRID_SIZE, maxR = -1, minC = GRID_SIZE, maxC = -1;
  for (let r = 0; r < GRID_SIZE; r++) {
    for (let c = 0; c < GRID_SIZE; c++) {
      if (pattern[r * GRID_SIZE + c] == null) continue;
      if (r < minR) minR = r;
      if (r > maxR) maxR = r;
      if (c < minC) minC = c;
      if (c > maxC) maxC = c;
    }
  }
  if (maxR === -1) return null;   // nothing in the grid
  return { minR, maxR, minC, maxC, rows: maxR - minR + 1, cols: maxC - minC + 1 };
}

// Exported for tests only — checked there against every recipe in every pool,
// since craftingResult() would otherwise silently make a colliding recipe
// unreachable instead of erroring.
export function sameShape(a, b) {
  const ba = boundsOf(a), bb = boundsOf(b);
  if (!ba || !bb) return false;
  if (ba.rows !== bb.rows || ba.cols !== bb.cols) return false;
  for (let r = 0; r < ba.rows; r++) {
    for (let c = 0; c < ba.cols; c++) {
      const av = a[(ba.minR + r) * GRID_SIZE + (ba.minC + c)];
      const bv = b[(bb.minR + r) * GRID_SIZE + (bb.minC + c)];
      if ((av ?? null) !== (bv ?? null)) return false;
    }
  }
  return true;
}

// What the current grid would produce, or null. Doesn't consume anything.
export function craftingResult(grid = craftGrid) {
  const pattern = grid.map(cellId);
  for (const [key, recipe] of Object.entries(VEHICLE_RECIPES)) {
    if (sameShape(pattern, recipe)) return { kind: 'vehicle', vehicleKey: key };
  }
  for (const [key, recipe] of Object.entries(TOOL_RECIPES)) {
    if (sameShape(pattern, recipe)) return { kind: 'tool', toolKey: key };
  }
  return null;
}

// Takes one of each ingredient and returns the finished item, or null if the
// grid doesn't currently make anything.
export function takeCraftingResult(grid = craftGrid) {
  const result = craftingResult(grid);
  if (!result) return null;
  for (let i = 0; i < GRID_CELLS; i++) {
    const cell = grid[i];
    if (!cell) continue;
    cell.count--;
    if (cell.count <= 0) grid[i] = null;
  }
  return result.kind === 'vehicle' ? vehicleItem(result.vehicleKey) : toolItem(result.toolKey);
}

// How many of each block a recipe needs, for the recipe book.
export function recipeCost(recipe) {
  const cost = new Map();
  for (const id of recipe) {
    if (id == null) continue;
    cost.set(id, (cost.get(id) || 0) + 1);
  }
  return cost;
}

// Whether a recipe is buildable right now, given a way to ask how much of a
// block is available. `countOf(id)` is injected rather than importing
// inventory.js directly — keeps this pure and testable without a real
// inventory, the same reasoning the rest of this module follows. The recipe
// book uses this to brighten and tick off anything you can already build.
export function canCraftRecipe(recipe, countOf) {
  for (const [id, need] of recipeCost(recipe)) {
    if (countOf(id) < need) return false;
  }
  return true;
}

export function clearCraftGrid() {
  for (let i = 0; i < GRID_CELLS; i++) craftGrid[i] = null;
}
