// Score, and the escalating difficulty it drives.
//
// The idea: killing things earns score, and score makes the game harder — you
// take more damage, you deal less, and more mobs come looking for you. The
// difficulty slider controls how fast that spiral turns, both by scaling the
// points you earn and by shortening the score span needed to reach full threat.
//
// Everything here is derived from two numbers — `score` and `slider` — so
// nothing can drift out of step.

const STORAGE_KEY = 'blocksDifficulty';

// Score needed for full threat at the middle of the slider. Lower means the
// game turns nasty sooner.
const BASE_SCORE_SPAN = 1500;

// What full threat does.
const MAX_INCOMING  = 2.6;    // damage you take is multiplied up to this
const MIN_OUTGOING  = 0.35;   // damage you deal is multiplied down to this
const EXTRA_MOBS    = 22;     // added to the base mob cap
const SPAWN_SPEEDUP = 0.6;    // fraction knocked off the spawn interval
const CLOSER_MIN    = 8;      // blocks nearer the minimum spawn distance comes
const CLOSER_MAX    = 10;     // ...and the maximum

export const MIN_SLIDER = 1;
export const MAX_SLIDER = 100;

let score = 0;
let best = 0;
let slider = 50;
let escalatingSpawns = true;
const listeners = [];

export function onDifficultyChange(fn) { listeners.push(fn); }
function notify() { for (const fn of listeners) fn(); }

// ── Settings ─────────────────────────────────────────────

export function getSlider() { return slider; }
export function getEscalatingSpawns() { return escalatingSpawns; }

export function setSlider(value) {
  const next = Math.max(MIN_SLIDER, Math.min(MAX_SLIDER, Math.round(Number(value) || MIN_SLIDER)));
  if (next === slider) return;
  slider = next;
  save();
  notify();
}

export function setEscalatingSpawns(on) {
  const next = !!on;
  if (next === escalatingSpawns) return;
  escalatingSpawns = next;
  save();
  notify();
}

function save() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ slider, escalatingSpawns, best }));
  } catch { /* private mode */ }
}

// Called from main.js so importing this module has no side effects.
export function initDifficulty() {
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); } catch { /* ignore */ }
  if (saved) {
    if (Number.isFinite(saved.slider)) {
      slider = Math.max(MIN_SLIDER, Math.min(MAX_SLIDER, Math.round(saved.slider)));
    }
    if (typeof saved.escalatingSpawns === 'boolean') escalatingSpawns = saved.escalatingSpawns;
    if (Number.isFinite(saved.best)) best = saved.best;
  }
  notify();
}

// ── Score ────────────────────────────────────────────────

export function getScore() { return score; }
export function getBestScore() { return best; }

// 0 at the bottom of the slider, 1 at the top.
function sliderFraction() { return slider / MAX_SLIDER; }

// Points are worth more on higher difficulty, so the score — and therefore the
// difficulty it drives — climbs faster. This is the "snake gets quicker" knob.
export function scoreMultiplier() { return 0.5 + sliderFraction() * 2.5; }

// How much score full threat takes. Shrinks as the slider rises, so the two
// effects compound: more points per kill AND fewer points needed.
export function threatSpan() { return BASE_SCORE_SPAN / (0.6 + sliderFraction() * 1.4); }

export function addScore(points) {
  if (points <= 0) return 0;
  const gained = Math.round(points * scoreMultiplier());
  score += gained;
  if (score > best) { best = score; save(); }
  notify();
  return gained;
}

// A run is over when you die; the spiral resets with it.
export function resetScore() {
  score = 0;
  notify();
}

// ── Derived difficulty ───────────────────────────────────

// 0 at the start of a run, 1 once the score span is reached.
export function getThreat() {
  return Math.min(1, score / threatSpan());
}

// Damage the player receives, scaled up as the run goes on.
export function scaleIncoming(damage) {
  return Math.max(1, Math.round(damage * (1 + getThreat() * (MAX_INCOMING - 1))));
}

// Damage the player deals, scaled down as the run goes on. Never quite zero,
// or a long run would become unwinnable.
export function scaleOutgoing(damage) {
  return Math.max(1, Math.round(damage * (1 - getThreat() * (1 - MIN_OUTGOING))));
}

// Mob pressure. At threat 0 these return the base values unchanged, so the
// opening of a run plays exactly as it did before difficulty existed — the
// escalation only adds from there. Turning off escalating spawns pins it there
// permanently, for when the swarm outruns your ability to score.
export function mobPressure({ maxMobs, interval, minDist, maxDist }) {
  const t = escalatingSpawns ? getThreat() : 0;
  return {
    maxMobs:  Math.round(maxMobs + t * EXTRA_MOBS),
    interval: interval * (1 - t * SPAWN_SPEEDUP),
    minDist:  Math.max(6, minDist - t * CLOSER_MIN),
    maxDist:  Math.max(12, maxDist - t * CLOSER_MAX),
  };
}
