// Frame timing. Measurement only — nothing here changes how the game runs.
//
// Sampling is always on, even when the counter or the F3 overlay is hidden,
// so the stats are meaningful the moment you look at them.

const WINDOW = 180;           // frames kept for averages (~3s at 60fps)
const REDRAW_INTERVAL = 0.25; // seconds between counter repaints, so it's readable
const STALL_CUTOFF_MS = 1000; // above this it's a paused tab, not a slow frame

let firstFrame = true;

// Ring buffer of frame durations in milliseconds.
const frames = new Array(WINDOW).fill(0);
let head = 0;
let filled = 0;

let sinceRedraw = 0;
let displayFps = 0;
let displayMs  = 0;

// `dt` must be the UNCLAMPED frame delta in seconds — main.js clamps its own
// copy to keep physics stable, and that would hide exactly the slow frames
// we're trying to measure.
export function recordFrame(dt) {
  const ms = dt * 1000;
  // The first frame spans module load and chunk preload, and the frame after a
  // tab switch spans however long the tab was hidden. Neither is a real frame.
  if (firstFrame) { firstFrame = false; return; }
  if (ms > STALL_CUTOFF_MS) return;
  frames[head] = ms;
  head = (head + 1) % WINDOW;
  if (filled < WINDOW) filled++;

  sinceRedraw += dt;
  if (sinceRedraw >= REDRAW_INTERVAL) {
    const s = getStats();
    displayFps = s.avgFps;
    displayMs  = s.avgMs;
    sinceRedraw = 0;
    renderCounter();
  }
}

// avgFps is the mean over the window. lowFps is the "1% low": the mean of the
// slowest 1% of frames, which is what you feel as stutter even when the
// average looks fine. Note it's a mean of the worst frames, not a percentile
// index — with a window this small an index would skip a lone bad frame.
export function getStats() {
  if (filled === 0) return { avgFps: 0, avgMs: 0, lowFps: 0, worstMs: 0 };

  const sample = frames.slice(0, filled);
  let total = 0;
  for (const ms of sample) total += ms;
  const avgMs = total / filled;

  const sorted = [...sample].sort((a, b) => a - b);
  const lowCount = Math.max(1, Math.round(filled * 0.01));
  let lowTotal = 0;
  for (let i = sorted.length - lowCount; i < sorted.length; i++) lowTotal += sorted[i];
  const lowMs = lowTotal / lowCount;
  const worstMs = sorted[sorted.length - 1];

  return {
    avgMs,
    avgFps: avgMs > 0 ? 1000 / avgMs : 0,
    lowFps: lowMs > 0 ? 1000 / lowMs : 0,
    worstMs,
  };
}

function renderCounter() {
  const el = document.getElementById('fps');
  if (!el) return;
  el.textContent = Math.round(displayFps) + ' FPS  ' + displayMs.toFixed(1) + ' ms';
  // Green above 50, amber 30-50, red below.
  el.style.color = displayFps >= 50 ? '#7fdc7f' : displayFps >= 30 ? '#e8c46a' : '#e87a7a';
}

export function resetStats() {
  frames.fill(0);
  head = 0;
  filled = 0;
}
