// Biome blending and large-scale terrain features: rolling plains fading
// into hills and mountains, deserts, canyons cut into high ground, lakes
// settling into low ground, and rare volcanoes.
//
// Everything here runs on the SAME seeded noise field terrain.js already
// samples for height, just at different scales and coordinate offsets —
// decorrelated the same way terrain.js's tree placement already decorrelates
// from the height sample itself (a large fixed offset into the noise field),
// rather than needing a separate permutation table per feature. Keeping it
// to one noise object is also what keeps re-seeding cheap: changing the
// world seed only ever rebuilds two permutation tables (terrain + ore), not
// one per biome feature.

import { CHUNK_HEIGHT, SEA_LEVEL } from '../config.js';

// Regional tendency fields — how mountainous vs flat an area is, and how wet
// vs dry — sampled at a much larger scale than the height noise itself, so
// whole regions read as "hilly" or "a desert" rather than flickering block
// to block. Fewer octaves than the height sample too: these only need to
// wander slowly, not add fine detail.
const ELEV_SCALE     = 0.0015;
const MOISTURE_SCALE = 0.0022;
const CANYON_SCALE   = 0.006;
const BASIN_SCALE    = 0.0032;

// Height amplitude per tier, in blocks either side of SEA_LEVEL (12).
// MOUNTAINS_AMP is deliberately capped well under CHUNK_HEIGHT (64) — a
// worst-case peak (SEA_LEVEL + amplitude) has to leave headroom below the
// column height limit for a volcano cone to stack on top of, and for a few
// blocks of open air above the highest possible ground so nothing pokes
// through the world's own ceiling.
const PLAINS_AMP    = 12;
const HILLS_AMP     = 26;
const MOUNTAINS_AMP = 42;

const SNOW_LINE_OFFSET  = 34;               // added to seaLevel — only genuine mountain peaks qualify
const DESERT_THRESHOLD  = -0.35;            // moisture below this is desert
const CANYON_THRESHOLD  = 0.965;            // very narrow — a gash, not a valley
const CANYON_DEPTH      = 34;
const BASIN_THRESHOLD   = 0.55;
const BASIN_DEPTH       = 20;

function smoothstep(edge0, edge1, x) {
  const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

// Folds smooth rolling noise around zero and inverts it — the standard trick
// for turning gentle hills into sharp folded ridges: what used to be a
// smooth zero-crossing becomes a sharp peak instead.
function ridged(n) { return 1 - Math.abs(n); }

// Volcanoes: rare, isolated cones on a coarse grid. Each cell either has one
// — jittered off-centre so they don't form an obvious lattice — or doesn't,
// decided by a cheap deterministic hash of the cell coordinates rather than
// a whole extra noise field just for "does this region have one".
const VOLCANO_CELL   = 192;
const VOLCANO_CHANCE = 0.35;
const VOLCANO_RADIUS = 26;
const VOLCANO_HEIGHT = 24;
const CRATER_RADIUS  = 7;
const CRATER_DEPTH   = 12;

function hash2(a, b) {
  let h = (a * 374761393 + b * 668265263) >>> 0;
  h = (h ^ (h >>> 13)) >>> 0;
  h = Math.imul(h, 1274126177) >>> 0;
  return (h ^ (h >>> 16)) >>> 0;
}

// Null if this column isn't within any volcano's reach; otherwise its
// distance from the nearest one's peak, for the caller to shape a cone from.
function volcanoAt(wx, wz) {
  const ccx = Math.floor(wx / VOLCANO_CELL), ccz = Math.floor(wz / VOLCANO_CELL);
  let best = null;
  // A peak jittered near a cell's edge could still reach into a neighbouring
  // cell's columns, so every column has to check its own cell and all 8
  // around it, not just its own.
  for (let dcx = -1; dcx <= 1; dcx++) {
    for (let dcz = -1; dcz <= 1; dcz++) {
      const cx = ccx + dcx, cz = ccz + dcz;
      const h = hash2(cx, cz);
      if ((h % 1000) / 1000 >= VOLCANO_CHANCE) continue;
      const jx = ((h >>> 8) & 0xff) / 255;
      const jz = ((h >>> 16) & 0xff) / 255;
      const peakX = cx * VOLCANO_CELL + VOLCANO_CELL * (0.3 + jx * 0.4);
      const peakZ = cz * VOLCANO_CELL + VOLCANO_CELL * (0.3 + jz * 0.4);
      const dist = Math.hypot(wx - peakX, wz - peakZ);
      if (dist <= VOLCANO_RADIUS && (!best || dist < best.dist)) best = { dist };
    }
  }
  return best;
}

// Everything terrain.js needs for one column: how tall it is, what it's
// made of, and whether it should even have trees. `noise` is the SAME
// makeNoise() instance terrain.js's height sample uses.
//
// `seaLevel`/`ceiling` default to Earth's own SEA_LEVEL/CHUNK_HEIGHT-4,
// preserving today's exact behaviour for every existing caller — but are
// overridable so world/earthTerrain.js can call this over a planet's own
// (u, v) tangent coordinates with `height`/`surfaceY` measured relative to
// that planet's own coreRadius instead of a fixed absolute world Y (the
// same "height becomes radius" substitution world/planetTerrain.js already
// made for the alien generator).
export function terrainColumn(noise, wx, wz, { seaLevel = SEA_LEVEL, ceiling = CHUNK_HEIGHT - 4 } = {}) {
  const h = noise.octave(wx * 0.008, wz * 0.008, 6, 0.5, 2.0);

  const elevT = noise.octave(wx * ELEV_SCALE + 4000, wz * ELEV_SCALE + 4000, 3, 0.5, 2.0);
  const moisture = noise.octave(wx * MOISTURE_SCALE + 8000, wz * MOISTURE_SCALE + 8000, 3, 0.5, 2.0);

  // Blend plains -> hills -> mountains smoothly by regional elevation
  // tendency, rather than switching abruptly at a threshold — a hard switch
  // reads as a cliff running along an invisible line; a blend reads as a
  // foothill.
  // The edges here are calibrated against the noise field's actual output
  // range, not the theoretical [-1, 1] a naive reading of octave() might
  // suggest — 3 octaves of value-gradient noise at this persistence only
  // ever reaches roughly [-0.6, 0.6] in practice (measured empirically over
  // a wide scan), so thresholds written against a full unit range meant
  // "mountains" could climb to their full amplitude only in a mathematical
  // limit that real terrain never actually reaches — no true peaks, and by
  // extension no snow, since SNOW_LINE needs that full amplitude to be
  // reachable at all.
  const toHills = smoothstep(-0.45, -0.05, elevT);
  const toMountains = smoothstep(0.05, 0.4, elevT);
  const amplitude = PLAINS_AMP + (HILLS_AMP - PLAINS_AMP) * toHills
                              + (MOUNTAINS_AMP - HILLS_AMP) * toMountains;

  // Mountains use a ridged fold of the SAME height sample, not a second
  // noise query — folding what's already there into peaks costs nothing
  // extra and still grades seamlessly into the hills around it, since both
  // read from the identical underlying value.
  const shaped = h * (1 - toMountains) + ridged(h) * toMountains;
  let height = seaLevel + shaped * amplitude;

  // Deserts flatten whatever the elevation blend produced into low dunes — a
  // desert halfway up a mountainside would look absurd, so this only ever
  // pulls height down towards a flat baseline, never up, and only applies
  // away from real mountains regardless of how dry the air up there reads.
  let isDesert = moisture < DESERT_THRESHOLD && toMountains < 0.5;
  if (isDesert) {
    const duneAmp = 6;
    height = height * 0.15 + (seaLevel + h * duneAmp) * 0.85;
  }

  // Canyons: a narrow ridged gash, cut only into hills and mountains — the
  // open plains stay open, but raised ground can be sliced clean through.
  const canyonN = noise.octave(wx * CANYON_SCALE + 12000, wz * CANYON_SCALE + 12000, 2, 0.5, 2.0);
  const canyonMask = ridged(canyonN);
  if (canyonMask > CANYON_THRESHOLD && toHills > 0.3) {
    height -= smoothstep(CANYON_THRESHOLD, 1, canyonMask) * CANYON_DEPTH;
  }

  // Lake basins: a broad, gentle dip in low ground. No separate water-
  // placement logic needed here — terrain.js already floods anything below
  // SEA_LEVEL, so a basin deep enough to cross that line becomes a lake on
  // its own, inland and away from any coast.
  const basinN = noise.octave(wx * BASIN_SCALE + 16000, wz * BASIN_SCALE + 16000, 3, 0.5, 2.0);
  if (basinN > BASIN_THRESHOLD && toMountains < 0.3) {
    height -= smoothstep(BASIN_THRESHOLD, 1, basinN) * BASIN_DEPTH;
  }

  // Volcanoes: an isolated cone added on top of whatever the terrain already
  // does there, with a crater dished out of its peak.
  let isVolcanic = false;
  const volcano = volcanoAt(wx, wz);
  if (volcano) {
    const rise = Math.max(0, 1 - volcano.dist / VOLCANO_RADIUS);
    height += rise * rise * VOLCANO_HEIGHT;
    if (volcano.dist < CRATER_RADIUS) {
      height -= (1 - volcano.dist / CRATER_RADIUS) * CRATER_DEPTH;
    }
    isVolcanic = rise > 0.15;
    // A volcanic cone always wins over a desert flag at the same spot —
    // terrain.js's surface-material pick already treats isVolcanic as the
    // higher-priority case (gravel/stone over sand), so the flags shouldn't
    // disagree about what kind of ground this actually is.
    if (isVolcanic) isDesert = false;
  }

  // Clamped well inside the column: never below bedrock, and never so close
  // to the ceiling that a volcano cone would have nowhere left to rise into.
  const surfaceY = Math.max(1, Math.min(ceiling, Math.round(height)));
  const isSandy = isDesert || surfaceY <= seaLevel + 1;
  const isSnowy = !isDesert && !isVolcanic && surfaceY >= seaLevel + SNOW_LINE_OFFSET;

  return { surfaceY, isSandy, isSnowy, isDesert, isVolcanic, isMountainous: toMountains > 0.5 };
}
