// Sun, sky fill and shadow casting for the Next Level preset.
//
// Nothing here exists in Potato mode: the lights are removed from the scene
// entirely, so lit materials don't cost anything and there are no shader
// recompiles from light-count changes while playing.
//
// The shadow camera is a small orthographic box that follows the player. A
// world this size can't be covered by one shadow map at usable resolution, so
// it covers the near field and fog hides the boundary.

import * as THREE from 'three';
import { scene, ambientLight, renderer } from '../core/scene.js';

const SHADOW_RANGE   = 44;    // half-size of the shadow camera box, in blocks
// Was 2048 — at 88 blocks across (SHADOW_RANGE*2) that's still ~11.6
// texels per block, plenty crisp for perfectly flat voxel faces, for a
// quarter of the shadow-map render/sample cost. Shadow map resolution and
// filtering (see PCFShadowMap below) are two of the more expensive knobs
// in the whole Next Level pipeline, since — unlike baked ambient occlusion,
// a one-off meshing cost — both are paid by EVERY lit, shadow-receiving
// fragment on screen, every frame, scaling with render distance the same
// way the rest of the visible scene does.
const SHADOW_MAP     = 1024;
const SUN_DISTANCE   = 90;    // how far up the light sits from its target

export const sun = new THREE.DirectionalLight(0xfff2d0, 2.2);
sun.castShadow = true;
sun.shadow.mapSize.set(SHADOW_MAP, SHADOW_MAP);
sun.shadow.camera.left   = -SHADOW_RANGE;
sun.shadow.camera.right  =  SHADOW_RANGE;
sun.shadow.camera.top    =  SHADOW_RANGE;
sun.shadow.camera.bottom = -SHADOW_RANGE;
sun.shadow.camera.near   = 1;
sun.shadow.camera.far    = SUN_DISTANCE * 2.2;
// Voxel faces are perfectly flat, which makes them prone to shadow acne.
sun.shadow.bias = -0.0012;
sun.shadow.normalBias = 0.06;

// Bounced light from sky and ground, so shadowed faces aren't pitch black.
export const skyFill = new THREE.HemisphereLight(0xb8d8ff, 0x6a5540, 0.55);

let enabled = false;

export function setLightingEnabled(on) {
  if (on === enabled) return;
  enabled = on;
  if (on) {
    scene.add(sun);
    scene.add(sun.target);
    scene.add(skyFill);
  } else {
    scene.remove(sun);
    scene.remove(sun.target);
    scene.remove(skyFill);
  }
  if (renderer) {
    renderer.shadowMap.enabled = on;
    // PCFShadowMap, not PCFSoftShadowMap — soft filtering takes noticeably
    // more texture samples per fragment, paid by every lit, shadow-
    // receiving pixel on screen every frame (see SHADOW_MAP's own
    // comment); PCF (not Basic) still anti-aliases the shadow edge, just
    // with fewer taps, which reads fine against perfectly flat voxel faces.
    renderer.shadowMap.type = THREE.PCFShadowMap;
    renderer.shadowMap.needsUpdate = true;
  }
}

export function isLightingEnabled() { return enabled; }

// Keeps the shadow box centred on the player and points the sun from the
// direction the day/night cycle says it should be.
export function updateLighting(playerPos, sunDir, sunColor, sunIntensity) {
  if (!enabled) return;
  sun.target.position.set(playerPos.x, playerPos.y, playerPos.z);
  sun.target.updateMatrixWorld();
  sun.position.set(
    playerPos.x + sunDir.x * SUN_DISTANCE,
    playerPos.y + sunDir.y * SUN_DISTANCE,
    playerPos.z + sunDir.z * SUN_DISTANCE
  );
  sun.color.copy(sunColor);
  sun.intensity = sunIntensity;

  // Kept low so shadowed faces stay clearly darker than lit ones; below the
  // horizon it stands in as a dim blue moonlight.
  const fillBase = 0.12, fillPeak = 0.25;
  skyFill.intensity = fillBase + Math.max(0, sunDir.y) * fillPeak;
}

// Ambient level used by Potato, restored when leaving Next Level so the flat
// look is byte-for-byte what it was.
export function setAmbientForPreset(nextLevel) {
  ambientLight.intensity = nextLevel ? 0.25 : 0.6;
}
