// Moving an axis-aligned box through the voxel world.
//
// Shared by the player and by mobs, so both obey the same rules: they collide
// with blocks, they can't pass through walls, and they have to jump to get up
// a step. Before this existed mobs simply snapped to the surface height of
// whatever column they stood over, which let them levitate up cliffs and trees.
//
// The box samples its four footprint corners on every axis. Vertically that
// means it rests on any block it overlaps, so you can stand part-way over a
// ledge — see the bridging notes in CLAUDE.md.
//
// Axes resolve one at a time (x, then z, then y) so sliding along a wall works.
//
// `isSolidFn` is what lets a curved planet reuse every line of this file
// completely unmodified: world/sphericalMotion.js calls moveBox with a
// closure that converts a *locally-oriented* x/y/z (where "y" is defined as
// away from whatever gravity source is nearby) back to world space before
// doing the real voxel lookup — every call site provides one explicitly.

const CORNER_SIGNS = [[-1, -1], [1, -1], [-1, 1], [1, 1]];

// Set by resolveAxis during a moveBox call. Module-level rather than allocated
// per call — moveBox runs for every entity, every frame.
let grounded = false;

// True when any corner of the box is over solid ground. Matches the vertical
// collision below, so "supported" means exactly "won't start falling".
export function hasFootSupport(x, y, z, radius, isSolidFn) {
  const fy = y - 0.1;
  for (let i = 0; i < 4; i++) {
    if (isSolidFn(x + CORNER_SIGNS[i][0] * radius, fy, z + CORNER_SIGNS[i][1] * radius)) return true;
  }
  return false;
}

function resolveAxis(pos, vel, axis, dt, radius, height, sneak, sneakSteps, isSolidFn) {
  // Only the moving axis changes, so track it as a scalar rather than cloning
  // a vector three times per frame.
  const nextVal = pos[axis] + vel[axis] * dt;
  const nx = axis === 'x' ? nextVal : pos.x;
  const ny = axis === 'y' ? nextVal : pos.y;
  const nz = axis === 'z' ? nextVal : pos.z;

  const vertical = axis === 'y';
  const movingDown = vel.y < 0;
  // Falling tests the bottom of the box, rising tests the top; horizontal
  // movement tests feet, waist and head.
  const levels = vertical ? 1 : 3;

  for (let c = 0; c < 4; c++) {
    const ox = CORNER_SIGNS[c][0] * radius;
    const oz = CORNER_SIGNS[c][1] * radius;
    for (let k = 0; k < levels; k++) {
      const oy = vertical
        ? (movingDown ? 0 : height)
        : (k === 0 ? 0 : k === 1 ? height * 0.5 : height);

      let checkX = nx + (axis === 'x' ? 0 : ox);
      const checkY = ny + oy;
      let checkZ = nz + (axis === 'z' ? 0 : oz);
      if (axis === 'x') checkX += vel.x > 0 ? radius : -radius;
      if (axis === 'z') checkZ += vel.z > 0 ? radius : -radius;

      if (isSolidFn(checkX, checkY, checkZ)) {
        vel[axis] = 0;
        // Only landing counts as grounded. Checking after zeroing the velocity
        // would also treat a bumped head as standing on something.
        if (vertical && movingDown) grounded = true;
        return;
      }
    }
  }

  // Crouching on solid ground: shorten the step until the box is still
  // supported, so you creep right up to the lip of a block instead of walking
  // off it. If even the smallest step hangs over the edge, stop.
  if (sneak && !vertical) {
    for (let i = sneakSteps; i >= 1; i--) {
      const cand = pos[axis] + (nextVal - pos[axis]) * (i / sneakSteps);
      const cx = axis === 'x' ? cand : pos.x;
      const cz = axis === 'z' ? cand : pos.z;
      if (hasFootSupport(cx, pos.y, cz, radius, isSolidFn)) { pos[axis] = cand; return; }
    }
    vel[axis] = 0;
    return;
  }

  pos[axis] = nextVal;
}

// Advances `pos` by `vel * dt`, stopping at blocks. Returns true if the box
// ended the step standing on something.
export function moveBox(pos, vel, dt, radius, height, sneak, sneakSteps, isSolidFn) {
  grounded = false;
  resolveAxis(pos, vel, 'x', dt, radius, height, sneak, sneakSteps, isSolidFn);
  resolveAxis(pos, vel, 'z', dt, radius, height, sneak, sneakSteps, isSolidFn);
  resolveAxis(pos, vel, 'y', dt, radius, height, false, sneakSteps, isSolidFn);
  return grounded;
}
