// Things mobs throw at the player. Straight-line travel, no gravity.

import { PLAYER_HEIGHT } from '../config.js';
import { worldIsSolid } from '../world/activeWorld.js';
import { scene } from '../core/scene.js';
import { player } from '../player/state.js';
import { hurtPlayer } from '../player/health.js';
import { buildProjectileMesh } from './mobMeshes.js';

const HIT_RADIUS = 0.8;
const LIFETIME   = 5;

export const projectiles = [];

// Aimed at where the player is right now — no leading, so strafing dodges
// it. Prop, speed and damage all come from the throwing mob's own type
// (mobTypes.js), so every mob's distance attack looks and feels different.
export function spawnProjectile(mob) {
  const td = mob.typeDef;
  const mesh = buildProjectileMesh(td.projectile);

  const origin = mob.pos.clone();
  origin.y += td.height * 0.8;
  mesh.position.copy(origin);
  scene.add(mesh);

  const target = player.pos.clone();
  target.y += PLAYER_HEIGHT * 0.5;
  const dir = target.clone().sub(origin).normalize();

  projectiles.push({
    mesh,
    pos:     origin.clone(),
    vel:     dir.multiplyScalar(td.throwSpeed ?? 10),
    dmg:     td.throwDmg,
    mobType: mob.type,
    life:    LIFETIME,
  });
}

export function updateMobProjectiles(dt) {
  for (let i = projectiles.length - 1; i >= 0; i--) {
    const p = projectiles[i];
    p.life -= dt;
    p.pos.addScaledVector(p.vel, dt);
    p.mesh.position.copy(p.pos);
    p.mesh.rotation.y += dt * 5;

    if (p.pos.distanceTo(player.pos) < HIT_RADIUS) {
      hurtPlayer(p.dmg, { kind: 'mob', mobType: p.mobType });
      scene.remove(p.mesh);
      projectiles.splice(i, 1);
      continue;
    }

    if (worldIsSolid(p.pos.x, p.pos.y, p.pos.z) || p.life <= 0) {
      scene.remove(p.mesh);
      projectiles.splice(i, 1);
    }
  }
}

export function clearMobProjectiles() {
  for (const p of projectiles) scene.remove(p.mesh);
  projectiles.length = 0;
}
