// The multiplayer panel on the pause overlay: name, appearance swatches,
// server address, connect/disconnect and who's currently in the game.
//
// A view module, per the usual rule — it renders what it's told and reports
// intent through handlers.

import { SWATCHES, APPEARANCE_PARTS } from '../net/appearance.js';

const PART_LABELS = {
  shirt: 'Shirt', shorts: 'Trousers', skin: 'Skin', hair: 'Hair',
};

let onChange = null;   // ({ name, appearance }) => void

export function initMultiplayerUI({ profile, defaultUrl, onProfileChange, onConnect, onDisconnect }) {
  onChange = onProfileChange;

  const nameInput = document.getElementById('mp-name');
  if (nameInput) {
    nameInput.value = profile.name;
    nameInput.addEventListener('input', () => {
      onChange({ name: nameInput.value.slice(0, 20) });
    });
    // Typing in the panel must not leak into movement or hotbar keys.
    for (const ev of ['keydown', 'keyup', 'keypress']) {
      nameInput.addEventListener(ev, e => e.stopPropagation());
    }
  }

  const urlInput = document.getElementById('mp-url');
  if (urlInput) {
    urlInput.value = defaultUrl;
    for (const ev of ['keydown', 'keyup', 'keypress']) {
      urlInput.addEventListener(ev, e => e.stopPropagation());
    }
  }

  buildSwatches(profile);

  const connectBtn = document.getElementById('mp-connect');
  if (connectBtn) {
    connectBtn.addEventListener('click', () => {
      const url = (urlInput && urlInput.value.trim()) || defaultUrl;
      onConnect(url);
    });
  }
  const disconnectBtn = document.getElementById('mp-disconnect');
  if (disconnectBtn) disconnectBtn.addEventListener('click', () => onDisconnect());
}

function buildSwatches(profile) {
  const host = document.getElementById('mp-appearance');
  if (!host) return;
  host.innerHTML = '';

  for (const part of APPEARANCE_PARTS) {
    const row = document.createElement('div');
    row.className = 'swatch-row';

    const label = document.createElement('span');
    label.className = 'swatch-label';
    label.textContent = PART_LABELS[part] || part;
    row.appendChild(label);

    SWATCHES[part].forEach((option, index) => {
      const dot = document.createElement('button');
      dot.type = 'button';
      dot.className = 'swatch' + (profile[part] === index ? ' active' : '');
      dot.dataset.part = part;
      dot.dataset.index = String(index);
      dot.title = option.name;
      dot.style.background = '#' + option.hex.toString(16).padStart(6, '0');
      dot.addEventListener('click', () => {
        for (const el of row.querySelectorAll('.swatch')) el.classList.remove('active');
        dot.classList.add('active');
        onChange({ [part]: index });
      });
      row.appendChild(dot);
    });

    host.appendChild(row);
  }
}

export function renderNetStatus(status, detail = '') {
  const el = document.getElementById('mp-status');
  if (el) {
    const text = {
      offline:    'Not connected',
      connecting: 'Connecting…',
      online:     'Connected',
      error:      'Connection failed' + (detail ? ' — ' + detail : ''),
    }[status] || status;
    el.textContent = text;
    el.dataset.state = status;
  }
  const connectBtn = document.getElementById('mp-connect');
  const disconnectBtn = document.getElementById('mp-disconnect');
  if (connectBtn) connectBtn.disabled = status === 'online' || status === 'connecting';
  if (disconnectBtn) disconnectBtn.disabled = status === 'offline' || status === 'error';
}

// `players` is an array of { name }, not counting yourself.
export function renderPlayerList(players) {
  const el = document.getElementById('mp-players');
  if (!el) return;
  if (players.length === 0) {
    el.textContent = 'No one else here yet.';
    return;
  }
  el.textContent = 'In game: ' + players.map(p => p.name).join(', ');
}
