// Everyone else in the world: their bodies, their floating name tags, and the
// interpolation that turns 20 snapshots a second into smooth movement.

import * as THREE from 'three';
import { PLAYER_HEIGHT, PLAYER_RADIUS } from '../config.js';
import { scene } from '../core/scene.js';
import { buildHumanoidGeometry, MOB_MATERIAL, MODEL_HEIGHT } from '../entities/mobMeshes.js';
import { appearanceColors } from './appearance.js';
import { healthColorCss } from '../ui/healthColor.js';

const BODY_SCALE = PLAYER_HEIGHT / MODEL_HEIGHT;
const TAG_HEIGHT = PLAYER_HEIGHT + 0.45;
// How quickly a body catches up to the latest snapshot. High enough to feel
// responsive, low enough to hide the 50 ms between packets.
const SMOOTHING = 14;

const TAG_W = 256, TAG_H = 72;

export const remotePlayers = new Map();   // id -> player record

function drawNameTag(player) {
  const canvas = player.tagCanvas;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, TAG_W, TAG_H);

  ctx.font = 'bold 34px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Outline first so the name stays readable against any background.
  ctx.lineWidth = 7;
  ctx.strokeStyle = 'rgba(0,0,0,0.85)';
  ctx.strokeText(player.name, TAG_W / 2, 26);
  ctx.fillStyle = '#ffffff';
  ctx.fillText(player.name, TAG_W / 2, 26);

  // Health bar, only once they've actually taken a hit — an untouched player
  // just gets a name.
  if (player.damaged) {
    const hp = Math.max(0, Math.min(1, player.hp / 100));
    const w = 170, h = 12, x = (TAG_W - w) / 2, y = 50;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(x - 2, y - 2, w + 4, h + 4);
    ctx.fillStyle = '#3a3a3a';
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = healthColorCss(hp);
    ctx.fillRect(x, y, w * hp, h);
  }

  player.tagTexture.needsUpdate = true;
  player.tagHpDrawn = player.hp;
}

function buildBody(player) {
  if (player.mesh) {
    scene.remove(player.mesh);
    player.mesh.geometry.dispose();
  }
  const geo = buildHumanoidGeometry(appearanceColors(player.appearance), BODY_SCALE);
  const mesh = new THREE.Mesh(geo, MOB_MATERIAL);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  mesh.position.copy(player.pos);
  scene.add(mesh);
  player.mesh = mesh;
}

export function addRemotePlayer({ id, name, appearance }) {
  if (remotePlayers.has(id)) {
    updateRemoteProfile({ id, name, appearance });
    return remotePlayers.get(id);
  }

  const canvas = document.createElement('canvas');
  canvas.width = TAG_W;
  canvas.height = TAG_H;
  const texture = new THREE.CanvasTexture(canvas);
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: texture, transparent: true, depthTest: true,
  }));
  sprite.scale.set(1.9, 0.54, 1);
  scene.add(sprite);

  const player = {
    id,
    name: name || 'Player ' + id,
    appearance: appearance || {},
    pos: new THREE.Vector3(0, -1000, 0),   // parked until the first snapshot
    target: new THREE.Vector3(0, -1000, 0),
    yaw: 0,
    targetYaw: 0,
    hp: 100,
    damaged: false,     // no bar until something has hurt them
    crouching: false,
    dead: false,
    mesh: null,
    sprite,
    tagCanvas: canvas,
    tagTexture: texture,
    tagHpDrawn: 100,
    seen: false,
  };

  remotePlayers.set(id, player);
  buildBody(player);
  drawNameTag(player);
  return player;
}

export function updateRemoteProfile({ id, name, appearance }) {
  const player = remotePlayers.get(id);
  if (!player) return;
  let looksChanged = false;
  if (appearance && JSON.stringify(appearance) !== JSON.stringify(player.appearance)) {
    player.appearance = appearance;
    looksChanged = true;
  }
  if (name && name !== player.name) {
    player.name = name;
    drawNameTag(player);
  }
  if (looksChanged) buildBody(player);
}

export function removeRemotePlayer(id) {
  const player = remotePlayers.get(id);
  if (!player) return;
  if (player.mesh) {
    scene.remove(player.mesh);
    player.mesh.geometry.dispose();
  }
  scene.remove(player.sprite);
  player.sprite.material.map.dispose();
  player.sprite.material.dispose();
  remotePlayers.delete(id);
}

export function clearRemotePlayers() {
  for (const id of [...remotePlayers.keys()]) removeRemotePlayer(id);
}

// Latest positions from the server. Anything not mentioned is left where it is.
export function applySnapshot(states, selfId) {
  for (const [rawId, s] of Object.entries(states)) {
    const id = Number(rawId);
    if (id === selfId) continue;
    const player = remotePlayers.get(id);
    if (!player || !s || !s.pos) continue;
    player.target.set(s.pos[0], s.pos[1], s.pos[2]);
    player.targetYaw = s.yaw || 0;
    player.crouching = !!s.crouching;
    player.dead = !!s.dead;
    if (typeof s.hp === 'number') {
      if (s.hp < player.hp || s.hp < 100) player.damaged = true;
      player.hp = s.hp;
    }
    // First packet: snap rather than gliding in from the parking spot.
    if (!player.seen) {
      player.seen = true;
      player.pos.copy(player.target);
      player.yaw = player.targetYaw;
    }
  }
}

// Shortest-path angle interpolation, so spinning past ±180° doesn't unwind.
function lerpAngle(from, to, t) {
  let diff = (to - from) % (Math.PI * 2);
  if (diff > Math.PI) diff -= Math.PI * 2;
  if (diff < -Math.PI) diff += Math.PI * 2;
  return from + diff * t;
}

export function updateRemotePlayers(dt) {
  const t = 1 - Math.exp(-SMOOTHING * dt);
  for (const player of remotePlayers.values()) {
    player.pos.lerp(player.target, t);
    player.yaw = lerpAngle(player.yaw, player.targetYaw, t);

    const visible = player.seen && !player.dead;
    if (player.mesh) {
      player.mesh.visible = visible;
      player.mesh.position.copy(player.pos);
      player.mesh.rotation.y = player.yaw + Math.PI;   // model faces -z at yaw 0
      player.mesh.scale.y = player.crouching ? 0.75 : 1;
    }

    player.sprite.visible = visible;
    player.sprite.position.set(
      player.pos.x,
      player.pos.y + (player.crouching ? TAG_HEIGHT - 0.35 : TAG_HEIGHT),
      player.pos.z
    );

    if (player.damaged && Math.abs(player.hp - player.tagHpDrawn) > 2) drawNameTag(player);
  }
}

// Hit box for shooting other players, matching the local player's dimensions.
export function remotePlayerTargets() {
  const out = [];
  for (const player of remotePlayers.values()) {
    if (!player.seen || player.dead) continue;
    out.push({
      id: player.id,
      pos: player.pos,
      height: PLAYER_HEIGHT,
      radius: PLAYER_RADIUS + 0.1,   // a little forgiving
    });
  }
  return out;
}

// Bearing and distance to every visible player, for the compass-style
// directional indicator in ui/radar.js. `angle` is degrees clockwise from
// straight ahead (0 = directly in front, 90 = to the right, 180 = behind) —
// screen-relative, not compass-north-relative, since there's no map here to
// give north a meaning.
export function remotePlayerBearings(pos, yaw) {
  const out = [];
  for (const player of remotePlayers.values()) {
    if (!player.seen || player.dead) continue;
    const dx = player.pos.x - pos.x;
    const dz = player.pos.z - pos.z;
    const distance = Math.hypot(dx, player.pos.y - pos.y, dz);
    // The yaw that would point the camera directly at the target, by the same
    // convention player/view.js's camera uses (forward = (-sin(yaw), 0, -cos(yaw))).
    const targetYaw = Math.atan2(-dx, -dz);
    let angle = ((yaw - targetYaw) * 180) / Math.PI;
    angle = ((angle % 360) + 360) % 360;
    out.push({ id: player.id, name: player.name, angle, distance });
  }
  return out;
}
