// WebSocket connection to the LAN server.
//
// This module owns the socket and nothing else: it turns incoming frames into
// handler callbacks supplied by main.js, so the networking layer never reaches
// into game state directly.

import { MSG, PORT, encode, decode } from './protocol.js';

let socket = null;
let selfId = null;
let status = 'offline';        // offline | connecting | online | error
const handlers = new Map();
const statusListeners = [];

// Same host the page came from. The port comes from the server itself when it
// served this page (it injects __BONDBLOCKS_PORT__), which keeps the default
// right even on a non-standard port. Falling back to PORT covers the dev setup,
// where Vite serves the page on its own port and the game server is separate.
export function defaultServerUrl() {
  const host = (typeof location !== 'undefined' && location.hostname) || 'localhost';
  const injected = typeof window !== 'undefined' ? window.__BONDBLOCKS_PORT__ : undefined;
  const port = Number.isInteger(injected) ? injected : PORT;
  return `ws://${host}:${port}`;
}

export function getStatus() { return status; }
export function getSelfId() { return selfId; }
export function isOnline()  { return status === 'online'; }

export function onStatusChange(fn) { statusListeners.push(fn); }

function setStatus(next, detail = '') {
  status = next;
  for (const fn of statusListeners) fn(next, detail);
}

// Register a handler for one message type.
export function on(type, fn) { handlers.set(type, fn); }

export function send(type, data) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return false;
  socket.send(encode(type, data));
  return true;
}

export function connect(url, joinPayload) {
  disconnect();
  setStatus('connecting');

  try {
    socket = new WebSocket(url);
  } catch (err) {
    setStatus('error', String(err && err.message || err));
    return;
  }

  const opened = socket;

  socket.addEventListener('open', () => {
    // A socket from an earlier connect() attempt finishing late: let it go
    // rather than joining twice.
    if (socket !== opened) {
      console.warn('[net] ignoring a stale socket that opened late');
      try { opened.close(); } catch { /* already gone */ }
      return;
    }
    console.log('[net] socket open, sending join');
    try {
      const payload = joinPayload();
      if (!send(MSG.JOIN, payload)) {
        setStatus('error', 'socket opened but the join could not be sent');
        return;
      }
      console.log('[net] join sent as', payload && payload.name);
    } catch (err) {
      // Without this the socket sits open forever having said nothing, and
      // the panel just reads "Connecting…" with no explanation.
      console.error('[net] building the join message failed', err);
      setStatus('error', 'could not build your profile: ' + (err && err.message || err));
      try { opened.close(); } catch { /* already gone */ }
    }
  });

  socket.addEventListener('message', ev => {
    const msg = decode(ev.data);
    if (!msg) return;
    if (msg.type === MSG.WELCOME) {
      selfId = msg.data.id;
      setStatus('online');
      console.log('[net] joined as player', selfId);
    }
    const fn = handlers.get(msg.type);
    if (fn) fn(msg.data);
  });

  socket.addEventListener('close', ev => {
    console.log('[net] socket closed', ev && ev.code, ev && ev.reason);
    if (status === 'connecting') {
      // Opened and shut without ever completing the handshake.
      setStatus('error', `server closed the connection (code ${ev && ev.code})`);
    } else if (status !== 'error') {
      setStatus('offline');
    }
    selfId = null;
    socket = null;
  });

  socket.addEventListener('error', () => {
    // The browser deliberately hides the reason; the usual causes are the
    // server not running or the wrong address.
    console.error('[net] socket error');
    setStatus('error', 'could not reach the server');
  });
}

// Typed conveniences so game code doesn't juggle message names.
export function sendState(state)          { send(MSG.STATE, state); }
export function sendHit(target, damage)   { send(MSG.HIT, { target, damage }); }
export function sendBlock(x, y, z, id)    { send(MSG.BLOCK, { x, y, z, id }); }
export function sendCrater(x, y, z, r)    { send(MSG.CRATER, { x, y, z, radius: r }); }
export function sendDied(by = null)        { send(MSG.DIED, { by }); }
export function sendProfile(name, appearance) { send(MSG.PROFILE, { name, appearance }); }
export function sendRestorePlayer(target, pos, yaw, hp) {
  send(MSG.RESTORE_PLAYER, { target, pos, yaw, hp });
}

export function disconnect() {
  if (socket) {
    const s = socket;
    socket = null;
    try { s.close(); } catch { /* already gone */ }
  }
  selfId = null;
  if (status !== 'offline') setStatus('offline');
}
