// Hotbar rendering. Builds the slots from HOTBAR_SIZE and paints them from an
// inventory array passed in — it never reads game state directly.

import { HOTBAR_SIZE } from '../config.js';
import { WEAPON_TYPES } from '../weapons/types.js';
import { itemIconUrl } from './itemIcons.js';

export function initHotbar() {
  const bar = document.getElementById('hotbar');
  if (!bar) return;
  bar.innerHTML = '';
  for (let i = 0; i < HOTBAR_SIZE; i++) {
    const slot = document.createElement('div');
    slot.className = 'slot' + (i === 0 ? ' active' : '');
    slot.dataset.slot = String(i);
    slot.innerHTML =
      '<div class="block-icon" id="icon-' + i + '"></div>' +
      '<span class="slot-num">' + (i + 1) + '</span>' +
      '<span class="item-count" id="count-' + i + '"></span>';
    bar.appendChild(slot);
  }
}

export function setActiveSlot(n) {
  const prev = document.querySelector('.slot.active');
  if (prev) prev.classList.remove('active');
  const next = document.querySelector('.slot[data-slot="' + n + '"]');
  if (next) next.classList.add('active');
}

export function refreshHotbar(inventory) {
  for (let i = 0; i < HOTBAR_SIZE; i++) {
    const icon  = document.getElementById('icon-' + i);
    const count = document.getElementById('count-' + i);
    const item  = inventory[i];
    if (!icon) continue;
    if (item) {
      const url = itemIconUrl(item);
      icon.style.backgroundImage = url ? `url(${url})` : 'none';
      const glow = item.kind === 'weapon' && WEAPON_TYPES[item.weaponKey].glow;
      icon.style.filter = glow ? 'drop-shadow(0 0 5px rgba(180,255,80,.9))' : 'none';
      icon.style.opacity = '1';
      if (count) count.textContent = (item.kind === 'weapon' || item.count > 1) ? String(item.count) : '';
    } else {
      icon.style.backgroundImage = 'none';
      icon.style.filter = 'none';
      icon.style.opacity = '0.25';
      if (count) count.textContent = '';
    }
  }
}
