// Blocky monster models built from boxes (plus a few cones/octahedra/spheres
// for horns, shards and spore sacs), plus the props mobs throw.
//
// Each model is merged into ONE geometry with the part colours baked into
// vertex colours, and every mob shares a single material — one draw call and
// one shader program for the lot, no matter how many mobs are on screen.
//
// Every monster shares the same base humanoid frame (PARTS below, also used
// for remote players' own avatars via buildHumanoidGeometry) so the whole
// roster stays visually consistent and cheap to build. What actually makes
// each type read as a distinct monster rather than a recoloured person is:
//   - its own colour palette (mobTypes.js) — the same 3-box cluster that's
//     "glasses" on a human reads as glowing eyes once it's a bright,
//     saturated colour against a dark hide;
//   - its own scale, derived straight from its collision height so a taller
//     stat block always reads as a taller silhouette;
//   - a handful of bespoke EXTRA_PARTS merged on top for real silhouette
//     variety (horns, claws, crystal shards, spore sacs, ...) — see below.

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { MOB_TYPES } from './mobTypes.js';

// Shared across every mob. The flash material is swapped in briefly on hit
// instead of cloning and mutating a per-mob material.
export const MOB_MATERIAL = new THREE.MeshLambertMaterial({ vertexColors: true });
export const MOB_FLASH_MATERIAL = new THREE.MeshLambertMaterial({
  vertexColors: true,
  emissive: 0xff4444,
  emissiveIntensity: 0.8,
});

// [w, h, d, x, y, z, colourKey] — y values are pre-scale, as in the original.
const PARTS = [
  [0.6,  0.7,  0.3,   0,      0.9 + 0.35,          0,           'shirt'],
  [0.6,  0.45, 0.3,   0,      0.9 - 0.225 + 0.05,  0,           'shorts'],
  [0.5,  0.5,  0.5,   0,      0.9 + 0.7 + 0.25,    0,           'skin'],
  [0.5,  0.12, 0.5,   0,      0.9 + 0.7 + 0.56,    0,           'hair'],
  [0.18, 0.08, 0.06, -0.13,   0.9 + 0.7 + 0.28,    0.28,        'glasses'],
  [0.18, 0.08, 0.06,  0.13,   0.9 + 0.7 + 0.28,    0.28,        'glasses'],
  [0.08, 0.04, 0.06,  0,      0.9 + 0.7 + 0.28,    0.28,        'glasses'],
  [0.2,  0.6,  0.2,  -0.4,    0.9 + 0.3,           0,           'shirt'],
  [0.2,  0.6,  0.2,   0.4,    0.9 + 0.3,           0,           'shirt'],
  [0.25, 0.6,  0.25, -0.18,   0.3,                 0,           'shorts'],
  [0.25, 0.6,  0.25,  0.18,   0.3,                 0,           'shorts'],
  [0.27, 0.18, 0.32, -0.18,   0.09,                0.03,        'boots'],
  [0.27, 0.18, 0.32,  0.18,   0.09,                0.03,        'boots'],
];

// Bespoke bits merged on top of the shared humanoid base, keyed by mob
// type — this is what turns "a recoloured human" into something that
// actually reads as a distinct monster silhouette, without duplicating the
// whole body per type. Same [w, h, d, x, y, z, colourKey] shape as PARTS,
// plus an optional trailing [rotX, rotY, rotZ] (radians) for anything that
// wants to sit at an angle (a shard, a horn) rather than axis-aligned.
// `shape` picks the base geometry ('box' if omitted, or 'cone'/'octahedron'/
// 'sphere' for anything that shouldn't just be another cuboid).
const EXTRA_PARTS = {
  ghoul: [
    // Claws hanging past the end of each arm.
    [0.11, 0.24, 0.11, -0.4, 0.78, 0.06, 'boots'],
    [0.11, 0.24, 0.11,  0.4, 0.78, 0.06, 'boots'],
    // A tattered cloak flap behind the shoulders.
    [0.5, 0.55, 0.06, 0, 1.3, -0.2, 'shirt'],
  ],
  wretch: [
    // Bulky shoulder slabs.
    [0.32, 0.22, 0.34, -0.42, 1.55, 0, 'shirt'],
    [0.32, 0.22, 0.34,  0.42, 1.55, 0, 'shirt'],
    // A pair of tusks jutting up past the jaw.
    [0.06, 0.16, 0.06, -0.1, 1.62, 0.3, 'boots', null, 'cone'],
    [0.06, 0.16, 0.06,  0.1, 1.62, 0.3, 'boots', null, 'cone'],
  ],
  husk: [
    // Loose bandage strips trailing off the limbs.
    [0.08, 0.5,  0.06, -0.3, 0.55, 0.16, 'shirt'],
    [0.08, 0.46, 0.06,  0.32, 0.5, -0.12, 'shirt'],
    // A wrapped cloth band around the head.
    [0.52, 0.14, 0.52, 0, 2.02, 0, 'hair'],
  ],
  shardStalker: [
    // Crystal spikes jutting from each shoulder, angled outward.
    [0.09, 0.42, 0.09, -0.4, 1.7, -0.05, 'glasses', [0, 0,  0.55], 'octahedron'],
    [0.09, 0.42, 0.09,  0.4, 1.7, -0.05, 'glasses', [0, 0, -0.55], 'octahedron'],
    // A crown shard on top of the head.
    [0.11, 0.5, 0.11, 0, 2.28, 0, 'glasses', [0.35, 0, 0], 'octahedron'],
  ],
  cinderfiend: [
    // Small horns.
    [0.07, 0.22, 0.07, -0.14, 2.18, 0.05, 'glasses', [0.4, 0,  0.15], 'cone'],
    [0.07, 0.22, 0.07,  0.14, 2.18, 0.05, 'glasses', [0.4, 0, -0.15], 'cone'],
    // Glowing crack seams across the torso and one arm.
    [0.5, 0.5, 0.05, 0, 1.25, 0.18, 'glasses'],
    [0.1, 0.55, 0.1, -0.4, 1.2, 0.14, 'glasses'],
  ],
  frostbiter: [
    // Icy spikes down the back.
    [0.08, 0.35, 0.08, -0.15, 1.7, -0.24, 'hair', [-0.3, 0,  0.2], 'octahedron'],
    [0.08, 0.35, 0.08,  0.15, 1.7, -0.24, 'hair', [-0.3, 0, -0.2], 'octahedron'],
    // An icicle jutting down from the chin.
    [0.06, 0.2, 0.06, 0, 1.55, 0.28, 'hair', [0.5, 0, 0], 'cone'],
  ],
  bloatspore: [
    // A bloated overlay torso.
    [0.72, 0.56, 0.5, 0, 1.25, 0, 'shirt', null, 'sphere'],
    // A drooping mushroom-cap overhang on the head.
    [0.64, 0.16, 0.64, 0, 2.16, 0, 'shirt'],
    // A pair of glowing spore sacs on the back.
    [0.15, 0.22, 0.13, -0.28, 1.1, -0.24, 'glasses', null, 'sphere'],
    [0.15, 0.22, 0.13,  0.28, 1.1, -0.24, 'glasses', null, 'sphere'],
  ],
};

const geometryCache = new Map();

// mergeGeometries requires every input to agree on being indexed or not —
// OctahedronGeometry comes out non-indexed while Box/Cone/Sphere come out
// indexed, so mixing an octahedron extra in with the (indexed) base PARTS
// boxes fails the merge outright. Normalising everything to non-indexed
// here is what lets any shape combine with any other.
function shapeGeometry(shape, w, h, d) {
  let geo;
  switch (shape) {
    case 'cone':       geo = new THREE.ConeGeometry(Math.max(w, d) * 0.5, h, 6); break;
    case 'octahedron': geo = new THREE.OctahedronGeometry(Math.max(w, h, d) * 0.5); break;
    case 'sphere':      geo = new THREE.SphereGeometry(Math.max(w, h, d) * 0.5, 8, 6); break;
    default:            geo = new THREE.BoxGeometry(w, h, d); break;
  }
  return geo.index ? geo.toNonIndexed() : geo;
}

function coloredPart(geo, x, y, z, hex, rot) {
  if (rot) {
    if (rot[0]) geo.rotateX(rot[0]);
    if (rot[1]) geo.rotateY(rot[1]);
    if (rot[2]) geo.rotateZ(rot[2]);
  }
  geo.translate(x, y, z);
  const c = new THREE.Color(hex);
  const count = geo.getAttribute('position').count;
  const colors = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    colors[i * 3]     = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geo;
}

function partsToGeometry(list, colors, scale) {
  const parts = list.map(([w, h, d, x, y, z, key, rot, shape]) =>
    coloredPart(
      shapeGeometry(shape, w * scale, h * scale, d * scale),
      x * scale, y * scale, z * scale,
      colors[key], rot,
    )
  );
  const merged = mergeGeometries(parts, false);
  for (const p of parts) p.dispose();
  return merged;
}

// Height of the base model at scale 1, used to size it against a target
// height. Every monster's own scale is derived from its own collision
// height against this, so a taller stat block always reads as a taller
// silhouette without a per-type scale table to keep in sync by hand.
export const MODEL_HEIGHT = 2.22;
const REFERENCE_HEIGHT = 1.9;   // the stat height MODEL_HEIGHT was tuned against

// Shared by mobs and by remote players: same blocky body, different colours.
// `colors` needs shirt/shorts/skin/hair/boots/glasses.
export function buildHumanoidGeometry(colors, scale = 1) {
  return partsToGeometry(PARTS, colors, scale);
}

function buildMobGeometry(type, typeDef) {
  const scale = typeDef.height / REFERENCE_HEIGHT;
  const extra = EXTRA_PARTS[type] || [];
  return partsToGeometry([...PARTS, ...extra], typeDef.colors, scale);
}

export function buildMobMesh(type, typeDef) {
  let geo = geometryCache.get(type);
  if (!geo) {
    geo = buildMobGeometry(type, typeDef);
    geometryCache.set(type, geo);
  }
  const mesh = new THREE.Mesh(geo, MOB_MATERIAL);
  // Ignored entirely unless the Next Level preset turned shadows on.
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// ── Thrown props ─────────────────────────────────────────
// One shared geometry+material pair per projectile kind, reused across every
// instance in flight — dozens of these can be airborne at once. A couple use
// `emissive` for a glowing look (crystal/ember/ice/spore) rather than a
// light, per the "don't add lights" performance rule — emissive is free.
const PROJECTILE_DEFS = {
  boneShard:    { geo: () => new THREE.BoxGeometry(0.09, 0.4, 0.09), color: 0xe8dcc0 },
  rockChunk:    { geo: () => new THREE.DodecahedronGeometry(0.22), color: 0x6b5a4a },
  dustRock:     { geo: () => new THREE.DodecahedronGeometry(0.17), color: 0xc9b48a },
  crystalShard: { geo: () => new THREE.OctahedronGeometry(0.19), color: 0x8fd8ff, emissive: 0x1a5a7a },
  ember:        { geo: () => new THREE.SphereGeometry(0.15, 8, 6), color: 0xff7a1a, emissive: 0xaa3300 },
  iceShard:     { geo: () => new THREE.OctahedronGeometry(0.18), color: 0xd8f6ff, emissive: 0x2a6a7a },
  sporePod:     { geo: () => new THREE.SphereGeometry(0.17, 8, 6), color: 0xd9e84a, emissive: 0x4a5a10 },
};

const projectileAssetCache = new Map();

function getProjectileAssets(key) {
  let assets = projectileAssetCache.get(key);
  if (!assets) {
    const def = PROJECTILE_DEFS[key] || PROJECTILE_DEFS.rockChunk;
    const geo = def.geo();
    const mat = new THREE.MeshLambertMaterial(
      def.emissive
        ? { color: def.color, emissive: def.emissive, emissiveIntensity: 0.9 }
        : { color: def.color }
    );
    assets = { geo, mat };
    projectileAssetCache.set(key, assets);
  }
  return assets;
}

// Builds a mesh for whichever thrown prop `key` names (mobTypes.js's own
// `projectile` field) — falls back to a plain rock if the key is somehow
// unrecognised, rather than throwing mid-fight.
export function buildProjectileMesh(key) {
  const { geo, mat } = getProjectileAssets(key);
  return new THREE.Mesh(geo, mat);
}
