// Enemy spawning and AI.
//
// State machine per mob: 'wander' → 'chase' when the player comes within
// attackRange, then a one-off 'melee' attack state — its actual look and
// feel driven by the mob's own `meleeStyle` (mobTypes.js: 'lunge' | 'slam' |
// 'swipe') — that runs to completion before returning to 'chase'.
//
// Mobs move through the world with the same box collision as the player
// (world/collision.js). They can't walk through blocks and can't climb
// anything taller than their jump, so cliffs and towers have to be gone round.
//
// Killing a mob starts a death animation (entities/mobDeath.js); the mob isn't
// removed until it finishes, and its loot drops around it.

import * as THREE from 'three';
import { GRAVITY } from '../config.js';
import { moveOnSphere, alignQuaternionFor } from '../world/sphericalMotion.js';
import { gravityAt } from '../world/gravity.js';
import { spaceIsSolid, surfaceNear, surfaceNearLand, nearestPlanetTo } from '../world/spaceSession.js';
import { themeFor } from '../world/alienBiomes.js';
import { scene } from '../core/scene.js';
import { player } from '../player/state.js';
import { hurtPlayer } from '../player/health.js';
import { isCreative } from '../gameMode.js';
import { isNight } from '../sky.js';
import { MOB_TYPES } from './mobTypes.js';
import { buildMobMesh, MOB_MATERIAL, MOB_FLASH_MATERIAL } from './mobMeshes.js';
import { spawnProjectile } from './mobProjectiles.js';
import { beginDeath, updateDeath } from './mobDeath.js';
import { spawnHeart } from './hearts.js';
import { spawnGunPickupAt } from './pickups.js';
import { pickMobDropWeapon } from '../weapons/types.js';
import { addScore, scaleOutgoing, mobPressure } from '../difficulty.js';
import { attachHealthBar, updateHealthBar, removeHealthBar } from './healthBars.js';

export const mobs = [];

// Spawner tuning
const MAX_MOBS           = 20;
const MOB_SPAWN_INTERVAL = 8;    // seconds between spawn attempts
const SPAWN_MIN_DIST     = 20;
const SPAWN_MAX_DIST     = 35;
const GHOUL_SHARE        = 0.6;  // fraction of HOME spawns that are Ghoul rather than Wretch

// Every other body gets its own single, unique monster keyed to its own
// alien theme (world/alienBiomes.js's themeFor) — this is what makes
// "different planets have unique mobs" literally true rather than just a
// recolour: whichever theme a planet rolled at generation decides which one
// name ever spawns there.
export const THEME_MOB = {
  'Barrens':       'husk',
  'Crystal Fields': 'shardStalker',
  'Ashen Wastes':   'cinderfiend',
  'Frozen Wastes':  'frostbiter',
  'Toxic Mire':     'bloatspore',
};

// Jump velocities below are scaled against this — see stepMob's own comment
// on why an unscaled jumpForce is what let mobs drift off into space on a
// low-gravity body.
const JUMP_GRAVITY_REF = -GRAVITY;   // 28, home's own magnitude

const MELEE_STYLE_DURATION = { lunge: 0.45, slam: 0.6, swipe: 0.22 };
const HIT_FLASH_TIME = 0.12;     // seconds a mob stays lit up after being hit

// A mob that wanted to move but barely did is up against something; if it's on
// the ground it tries to hop over. This is what lets them climb one-block steps
// without being able to scale a wall.
const BLOCKED_FRACTION = 0.35;
const JUMP_COOLDOWN    = 0.35;

let mobSpawnTimer = 5;

// Scratch for updateMobSpawner's space branch — reused every spawn attempt
// rather than allocated (spawn attempts happen often enough, even if not
// every frame, to be worth not churning garbage over).
const spawnAlignQuat  = new THREE.Quaternion();
const spawnOffset      = new THREE.Vector3();
const spawnPos         = new THREE.Vector3();
const spawnGroundPos   = new THREE.Vector3();
// Separate scratch for stepMob's own vacuum-recovery net below — stepMob can
// run for many mobs within the same frame updateMobSpawner might also touch,
// so the two must never share one scratch vector.
const driftRecoverPos  = new THREE.Vector3();
// Scratch for dropWeapon's ground-snap.
const dropGroundPos    = new THREE.Vector3();

// Picks which mob type spawns at `pos`: the home planet mixes Ghoul/Wretch
// same as it always has, but any OTHER body spawns only its own theme's
// signature monster — see THEME_MOB above.
function pickMobTypeFor(pos) {
  const planet = nearestPlanetTo(pos);
  if (!planet || planet.id === 'home') {
    return Math.random() < GHOUL_SHARE ? 'ghoul' : 'wretch';
  }
  const theme = themeFor(planet);
  return THEME_MOB[theme.name] || 'husk';
}

// `pos` is already a real point just clear of a planet's own generated
// ground (world/spaceSession.js's surfaceNear), since there's no single
// (wx, wz) column height to look up once "up" varies by position.
export function spawnMobInSpace(type, pos) {
  createMobAt(type, pos);
}

// Spawns one mob at a random offset from `center` — shared by the dev
// console's /spawn command, so a console-spawned mob lands on the planet's
// real curved ground (via surfaceNearLand) instead of floating at whatever
// height `center` happens to be, the same reasoning updateMobSpawner's own
// inline logic below already follows.
export function spawnMobNear(type, center, minDist, maxDist) {
  const angle = Math.random() * Math.PI * 2;
  const dist  = minDist + Math.random() * (maxDist - minDist);
  const g = gravityAt(center);
  alignQuaternionFor(g.dir, spawnAlignQuat);
  spawnOffset.set(Math.cos(angle) * dist, 0, Math.sin(angle) * dist).applyQuaternion(spawnAlignQuat);
  spawnPos.copy(center).add(spawnOffset);
  if (surfaceNearLand(spawnPos, spawnGroundPos)) spawnMobInSpace(type, spawnGroundPos);
}

function createMobAt(type, pos) {
  const typeDef = MOB_TYPES[type];
  const mesh = buildMobMesh(type, typeDef);
  mesh.position.copy(pos);
  scene.add(mesh);

  mobs.push({
    type,
    typeDef,
    mesh,
    pos:            pos.clone(),
    vel:            new THREE.Vector3(),
    hp:             typeDef.hp,
    maxHp:          typeDef.hp,
    onGround:       false,
    jumpCooldown:   0,
    wanderTimer:    Math.random() * 3,
    wanderDir:      new THREE.Vector2(Math.random() - 0.5, Math.random() - 0.5).normalize(),
    meleeCooldown:  0,
    throwCooldown:  Math.random() * 2,
    flashTimer:     0,
    damaged:        false,   // health bar appears only once hurt
    healthBar:      null,
    state:          'wander',
    meleeTimer:     0,
    meleeHit:       false,
    dying:          false,
    dead:           false,
  });
}

// Sets the along-gravity component of `vel` (a full 3D velocity, evaluated
// at `pos`) so that `value` means exactly what a bare `vel.y = value`
// assignment always meant on flat ground: positive is away from whatever's
// pulling here, negative is toward it.
function setVerticalVelocity(vel, pos, value) {
  const g = gravityAt(pos);
  const alongGravity = vel.dot(g.dir);
  vel.addScaledVector(g.dir, -value - alongGravity);
}

// `dmg` is the weapon's raw damage; how much of it lands depends on how far
// into the run you are.
export function hitMob(mob, dmg) {
  if (mob.dead || mob.dying) return;
  mob.hp -= scaleOutgoing(dmg);

  // The bar only shows once something has actually hurt it.
  mob.damaged = true;
  attachHealthBar(mob);

  // Flash red by swapping to the shared flash material — no cloning, so no
  // extra shader programs to compile.
  mob.mesh.material = MOB_FLASH_MATERIAL;
  mob.flashTimer = HIT_FLASH_TIME;

  // Knock back away from the player.
  const dx = mob.pos.x - player.pos.x;
  const dz = mob.pos.z - player.pos.z;
  const len = Math.sqrt(dx * dx + dz * dz) || 1;
  mob.vel.x += (dx / len) * 4;
  mob.vel.z += (dz / len) * 4;

  if (mob.hp <= 0) killMob(mob);
}

// Starts the death animation and scatters the hearts. The weapon drop waits
// until the animation finishes so it doesn't appear mid-flourish.
export function killMob(mob) {
  if (mob.dying || mob.dead) return;
  mob.mesh.material = MOB_MATERIAL;
  removeHealthBar(mob);
  addScore(mob.typeDef.scoreValue);
  beginDeath(mob);

  const from = mob.pos.clone();
  from.y += mob.typeDef.height * 0.6;
  for (let i = 0; i < mob.typeDef.heartsDropped; i++) spawnHeart(from);
}

function dropWeapon(mob) {
  if (Math.random() >= mob.typeDef.weaponDropChance) return;
  // Snap to the ground — the mob's pos may be airborne at death-animation
  // end (e.g. the 'launch' style sends the corpse flying upward), so drop
  // the weapon at the nearest land surface rather than wherever the corpse
  // happened to stop.
  const at = surfaceNearLand(mob.pos, dropGroundPos)
    ? dropGroundPos.clone()
    : mob.pos.clone();
  spawnGunPickupAt(pickMobDropWeapon(), at);
}

export function clearMobs() {
  for (const mob of mobs) {
    removeHealthBar(mob);
    scene.remove(mob.mesh);
  }
  mobs.length = 0;
}

// Applies gravity and moves the mob through the world, hopping over anything
// it walks into. `moveX`/`moveZ` are the desired horizontal speeds — always
// plain world X/Z: mob AI below computes them as plain world-space deltas
// toward the player, the same "good enough near where you actually are"
// simplification the home planet's own huge radius makes safe (see
// CLAUDE.md's Space environment section) — a mob only ever needs to be
// convincing near wherever the player currently stands, not correct on the
// far side of the planet. moveOnSphere still resolves whatever velocity
// it's handed against the REAL curved collision geometry regardless.
function stepMob(mob, moveX, moveZ, dt) {
  const td = mob.typeDef;

  const g = gravityAt(mob.pos);
  mob.vel.addScaledVector(g.dir, g.g * dt);
  // Replace the tangential component with the desired move, leaving
  // whatever's accumulated along gravity (falling/jumping) alone — the
  // same split player/physics.js's spaceWalkStep makes.
  const alongGravity = mob.vel.dot(g.dir);
  mob.vel.set(moveX, 0, moveZ).addScaledVector(g.dir, alongGravity);

  const beforeX = mob.pos.x, beforeY = mob.pos.y, beforeZ = mob.pos.z;
  mob.onGround = moveOnSphere(mob.pos, mob.vel, dt, td.radius, td.height, false, 1, g.dir, spaceIsSolid);

  mob.jumpCooldown = Math.max(0, mob.jumpCooldown - dt);
  const wantedSq = (moveX * dt) ** 2 + (moveZ * dt) ** 2;
  const movedSq  = (mob.pos.x - beforeX) ** 2 + (mob.pos.y - beforeY) ** 2 + (mob.pos.z - beforeZ) ** 2;
  if (mob.onGround && mob.jumpCooldown === 0 &&
      wantedSq > 1e-6 && movedSq < wantedSq * BLOCKED_FRACTION) {
    // Scaled so the actual APEX HEIGHT stays the same regardless of the
    // local body's own gravity strength. jumpForce itself is tuned against
    // home's own gravity (mobTypes.js's own module comment, and
    // tests/mobs.test.js's apex-height test) — applying it unscaled on a
    // much weaker alien body sent a mob's ordinary one-block hop several
    // times higher than intended, and on a SMALL body that extra height
    // was routinely enough to cross its own gravityRange and leave the mob
    // adrift in the vacuum beyond it, with nothing left to pull it back —
    // the actual mechanism behind mobs "floating off into space" on
    // low-gravity planets. Falls back to the raw value if g.g is ever 0
    // (shouldn't happen while onGround, but dividing by it would be worse).
    const jumpVel = g.g > 0 ? td.jumpForce * Math.sqrt(g.g / JUMP_GRAVITY_REF) : td.jumpForce;
    setVerticalVelocity(mob.vel, mob.pos, jumpVel);
    mob.jumpCooldown = JUMP_COOLDOWN;
    mob.onGround = false;
  }

  // Safety net: a mob should never end up drifting through open vacuum — it
  // always spawns via surfaceNearLand, and the jump-apex scaling above is what
  // stops an ordinary hop from ever crossing a body's own gravityRange in
  // the first place. If it ever ends up there anyway (a hard knockback, a
  // future edge case this doesn't cover), pull it straight back onto the
  // nearest real surface instead of leaving it to coast through the vacuum
  // forever — world/gravity.js's own vacuum fallback is a flat world -Y
  // with zero pull, which has no relationship at all to whatever body the
  // mob actually came from, so nothing would ever bring it back on its own.
  const gNow = gravityAt(mob.pos);
  if (gNow.g === 0 && surfaceNear(mob.pos, driftRecoverPos)) {
    mob.pos.copy(driftRecoverPos);
    mob.vel.set(0, 0, 0);
    mob.onGround = true;
  }
}

export function updateMobs(dt) {
  const playerPos = player.pos;

  for (let i = mobs.length - 1; i >= 0; i--) {
    const mob = mobs[i];

    // Dying mobs keep animating but stop thinking.
    if (mob.dying) {
      if (updateDeath(mob, dt)) {
        dropWeapon(mob);
        removeHealthBar(mob);
        scene.remove(mob.mesh);
        mobs.splice(i, 1);
      }
      continue;
    }

    if (mob.dead) {
      removeHealthBar(mob);
      scene.remove(mob.mesh);
      mobs.splice(i, 1);
      continue;
    }

    if (player.dead) continue;

    const td   = mob.typeDef;
    const dist = mob.pos.distanceTo(playerPos);
    const dx   = playerPos.x - mob.pos.x;
    const dz   = playerPos.z - mob.pos.z;

    mob.mesh.rotation.set(0, Math.atan2(dx, dz), 0);

    mob.meleeCooldown = Math.max(0, mob.meleeCooldown - dt);
    mob.throwCooldown = Math.max(0, mob.throwCooldown - dt);
    mob.wanderTimer   = Math.max(0, mob.wanderTimer   - dt);

    if (mob.flashTimer > 0) {
      mob.flashTimer -= dt;
      if (mob.flashTimer <= 0) mob.mesh.material = MOB_MATERIAL;
    }

    // The one-off melee finisher — its look, motion and payload timing all
    // come from the mob's own meleeStyle (mobTypes.js).
    if (mob.state === 'melee') {
      mob.meleeTimer -= dt;
      const style = td.meleeStyle;

      if (style === 'lunge') {
        // A fast, committed dash into melee range.
        stepMob(mob, mob.lungeX, mob.lungeZ, dt);
        mob.mesh.rotation.z = -Math.PI / 3;
        if (!mob.meleeHit && mob.pos.distanceTo(playerPos) < td.meleeRange) {
          mob.meleeHit = true;
          hurtPlayer(td.meleeDmg, { kind: 'mob', mobType: mob.type });
          const kx = playerPos.x - mob.pos.x, kz = playerPos.z - mob.pos.z;
          const kl = Math.sqrt(kx * kx + kz * kz) || 1;
          player.vel.x += (kx / kl) * 8;
          player.vel.z += (kz / kl) * 8;
          setVerticalVelocity(player.vel, player.pos, 6);
        }
      } else if (style === 'slam') {
        // Winds up in place, then slams the player into the ground.
        stepMob(mob, 0, 0, dt);
        mob.mesh.rotation.z = Math.sin(mob.meleeTimer * 10) * 0.4;
        if (mob.meleeTimer <= 0 && !mob.meleeHit &&
            mob.pos.distanceTo(playerPos) < td.meleeRange + 0.5) {
          mob.meleeHit = true;
          hurtPlayer(td.meleeDmg, { kind: 'mob', mobType: mob.type });
          setVerticalVelocity(player.vel, player.pos, -12);
        }
      } else {
        // 'swipe' — a quick, no-windup strike; the damage already landed the
        // instant this state was entered below, so this is just the
        // follow-through animation.
        stepMob(mob, 0, 0, dt);
        mob.mesh.rotation.x = Math.max(0, mob.meleeTimer) * -3;
      }

      if (mob.meleeTimer <= 0) {
        mob.state = 'chase';
        mob.mesh.rotation.set(0, mob.mesh.rotation.y, 0);
        mob.meleeCooldown = td.meleeCooldown;
      }
      mob.mesh.position.copy(mob.pos);
      continue;
    }

    if (dist < td.attackRange) {
      mob.state = 'chase';
    } else if (mob.state === 'chase' && dist > td.attackRange * 1.5) {
      mob.state = 'wander';
    }

    if (dist < td.throwRange && dist > td.meleeRange && mob.throwCooldown <= 0) {
      spawnProjectile(mob);
      mob.throwCooldown = td.throwCooldown;
    }

    if (dist < td.meleeRange && mob.meleeCooldown <= 0) {
      mob.state = 'melee';
      mob.meleeTimer = MELEE_STYLE_DURATION[td.meleeStyle] ?? 0.3;
      mob.meleeHit = false;
      if (td.meleeStyle === 'lunge') {
        const d2 = Math.sqrt(dx * dx + dz * dz) || 1;
        mob.lungeX = (dx / d2) * 10;
        mob.lungeZ = (dz / d2) * 10;
      } else if (td.meleeStyle === 'swipe') {
        // Quick and decisive — lands immediately rather than after a windup.
        mob.meleeHit = true;
        hurtPlayer(td.meleeDmg, { kind: 'mob', mobType: mob.type });
      }
      continue;
    }

    let moveX = 0, moveZ = 0;
    if (mob.state === 'chase') {
      const d2 = Math.sqrt(dx * dx + dz * dz) || 1;
      if (dist > td.minChaseRange) {
        moveX = (dx / d2) * td.speed;
        moveZ = (dz / d2) * td.speed;
      } else {
        // Too close — shuffle back out to melee distance.
        moveX = -(dx / d2) * td.speed * 0.5;
        moveZ = -(dz / d2) * td.speed * 0.5;
      }
    } else {
      if (mob.wanderTimer <= 0) {
        mob.wanderDir.set(Math.random() - 0.5, Math.random() - 0.5).normalize();
        mob.wanderTimer = 2 + Math.random() * 3;
      }
      moveX = mob.wanderDir.x * td.speed * 0.4;
      moveZ = mob.wanderDir.y * td.speed * 0.4;
    }

    stepMob(mob, moveX, moveZ, dt);

    const bobSpeed = mob.state === 'chase' ? 8 : 3;
    const bob = mob.onGround ? Math.sin(performance.now() * 0.001 * bobSpeed + i) * 0.06 : 0;
    mob.mesh.position.set(mob.pos.x, mob.pos.y + bob, mob.pos.z);
    if (mob.healthBar) updateHealthBar(mob, td.height);
  }
}

// Drops a new mob just outside the player's view. The constants above are the
// opening pressure; mobPressure() only ever adds to them as the score climbs,
// so the first minutes of a run play exactly as they always did.
//
// Mobs are a survival-mode, nighttime thing: Creative has no health to lose
// them to, so spawning any at all is just noise, and daylight is meant to be
// safe — existing mobs from the night before keep wandering into the day,
// this only stops NEW ones from starting.
export function updateMobSpawner(dt) {
  if (player.dead || isCreative() || !isNight()) return;
  const pressure = mobPressure({
    maxMobs: MAX_MOBS,
    interval: MOB_SPAWN_INTERVAL,
    minDist: SPAWN_MIN_DIST,
    maxDist: SPAWN_MAX_DIST,
  });

  mobSpawnTimer -= dt;
  if (mobSpawnTimer > 0 || mobs.length >= pressure.maxMobs) return;
  mobSpawnTimer = pressure.interval;

  const angle = Math.random() * Math.PI * 2;
  const dist  = pressure.minDist + Math.random() * (pressure.maxDist - pressure.minDist);

  // The offset has to be along the player's own local tangent plane, not
  // world X/Z — the same align-rotation trick player/physics.js's
  // spaceWalkStep and player/view.js's camera both already use, so a spawn
  // point "20 blocks that way" means the same thing underfoot that it
  // visually looks like, on any face.
  const g = gravityAt(player.pos);
  alignQuaternionFor(g.dir, spawnAlignQuat);
  spawnOffset.set(Math.cos(angle) * dist, 0, Math.sin(angle) * dist).applyQuaternion(spawnAlignQuat);
  spawnPos.copy(player.pos).add(spawnOffset);
  // surfaceNearLand skips liquid columns so mobs never spawn in the water.
  if (surfaceNearLand(spawnPos, spawnGroundPos)) {
    spawnMobInSpace(pickMobTypeFor(spawnGroundPos), spawnGroundPos);
  }
}
