// Day/night cycle: drives the clear colour, fog colour and ambient light, and
// publishes the sun's direction/colour so lighting and the water shader can
// follow it.
//
// The sky has no sun to colour it by time of day — it paints a menacing red
// "day" and a near-black starry "night" (render/starfield.js draws the
// actual stars) rather than Earth's old blue sky, but the day/night
// mechanics this drives (mob spawning, isNight(), cycle length) are exactly
// what they always were; only the colours changed.

import * as THREE from 'three';
import { CHUNK_SIZE } from './config.js';
import { getRenderDistance } from './renderDistance.js';
import { getDayLengthMinutes } from './dayLength.js';
import { scene, ambientLight, renderer } from './core/scene.js';
import { isLit } from './settings.js';
import { updateLighting } from './render/lighting.js';
import { updateWaterMaterials } from './render/materials.js';
import { WATER, UNDERWATER_TINT } from './world/blocks.js';

// A full day-night cycle is twice the day length: the sun spends exactly
// half the cycle above the horizon and half below (see isNight() below), so
// one slider setting "day lasts N minutes" gets "night lasts N minutes" too,
// for free, rather than needing two independent lengths to agree.
function cycleSeconds() { return getDayLengthMinutes() * 2 * 60; }

const skyDay   = new THREE.Color(0x7a1414);
const skyDusk  = new THREE.Color(0x300808);
const skyNight = new THREE.Color(0x03030a);

const sunWarm = new THREE.Color(0xfff2d0);
const sunDusk = new THREE.Color(0xffb070);

// Read live rather than frozen at import, so the fog grows or shrinks with
// the render distance setting instead of leaving a hard pop-in edge wherever
// a fixed distance would sit — the same reasoning render distance's own
// CLAUDE.md section gives, now applying to whichever planet's terrain is
// actually streaming in nearby (world/planetStreaming.js) rather than
// Earth's flat chunk grid specifically.
function fogNearDist() { return getRenderDistance() * CHUNK_SIZE * 0.6; }
function fogFarDist()  { return getRenderDistance() * CHUNK_SIZE * 1.1; }

// Short rather than the sky's tall, colour-of-day fog — murky enough to feel
// like a different medium, but not so short it hides the surface from a
// swimmer who's only a few blocks down. The colour itself now varies by
// which liquid the eye is actually inside (blocks.js's UNDERWATER_TINT) —
// only the near/far distances stay fixed regardless of liquid.
const underwaterFogColor = new THREE.Color();
const UNDERWATER_NEAR  = 2;
const UNDERWATER_FAR   = 26;

// 0..1 through the day; 0.25 is dawn.
let dayTime = 0.25;
let lastSunHeight = 0;   // cached from the last updateSky(), for isNight()

const sunDir   = new THREE.Vector3();
const sunColor = new THREE.Color();
const skyColor = new THREE.Color();

export function getDayTime() { return dayTime; }
export function getSunDirection() { return sunDir; }

// Jumps the sky to an arbitrary point in the cycle — used by the dev console.
export function setDayTime(t) { dayTime = Math.max(0, Math.min(1, t)); }

// True whenever the sun is below the horizon — exactly half of every cycle,
// which is what makes "day lasts N minutes, night lasts N minutes" true by
// construction rather than needing separately-tuned phase boundaries.
// Mob spawning reads this directly.
export function isNight() { return lastSunHeight <= 0; }

// `underwaterLiquid` is a liquid block id (world/blocks.js) while the eye is
// submerged, or null on dry land/in the air — player/view.js computes this
// every frame from the actual block the camera sits in.
export function updateSky(dt, playerPos, underwaterLiquid = null) {
  dayTime = (dayTime + dt / cycleSeconds()) % 1;
  const t = dayTime;

  if (t < 0.2)      skyColor.copy(skyNight).lerp(skyDusk, t / 0.2);
  else if (t < 0.3) skyColor.copy(skyDusk).lerp(skyDay, (t - 0.2) / 0.1);
  else if (t < 0.7) skyColor.copy(skyDay);
  else if (t < 0.8) skyColor.copy(skyDay).lerp(skyDusk, (t - 0.7) / 0.1);
  else              skyColor.copy(skyDusk).lerp(skyNight, (t - 0.8) / 0.2);

  const underwater = underwaterLiquid !== null;
  // Underwater replaces the sky's own fog rather than blending with it — a
  // swimmer is looking through liquid, not through hazy air the colour of
  // whatever time of day it is. Falls back to WATER's own tint for any id
  // that's somehow missing an entry, so a stray liquid still looks like
  // *something* rather than crash.
  let fogColor = skyColor;
  if (underwater) {
    underwaterFogColor.setHex(UNDERWATER_TINT[underwaterLiquid] ?? UNDERWATER_TINT[WATER]);
    fogColor = underwaterFogColor;
  }
  if (renderer) renderer.setClearColor(fogColor);
  scene.fog.color.copy(fogColor);
  scene.fog.near = underwater ? UNDERWATER_NEAR : fogNearDist();
  scene.fog.far  = underwater ? UNDERWATER_FAR  : fogFarDist();

  // The sun tracks a circle overhead; dawn is at dayTime 0.25.
  const angle = (t - 0.25) * Math.PI * 2;
  const sunHeight = Math.sin(angle);
  lastSunHeight = sunHeight;
  const sunIntensity = Math.max(0, sunHeight);
  sunDir.set(Math.cos(angle) * 0.6, Math.max(0.05, sunHeight), 0.35).normalize();

  // Next Level keeps ambient deliberately low: fill light is what washes
  // cast shadows out, and the shadows are the point. Potato has no lights
  // at all, so its ambient has to carry the whole image.
  if (!isLit()) {
    ambientLight.intensity = 0.35 + sunIntensity * 0.65;
  } else {
    ambientLight.intensity = 0.10 + sunIntensity * 0.12;
  }

  if (isLit()) {
    // Warm the sun towards orange as it sits low in the sky.
    const lowness = 1 - Math.min(1, Math.max(0, sunHeight) * 2.2);
    sunColor.copy(sunWarm).lerp(sunDusk, lowness);
    updateLighting(playerPos, sunDir, sunColor, 0.3 + sunIntensity * 2.6);
    // Every water material actually built so far (one per liquid id, lazily
    // created the first time a themed lake or home's own water meshes) —
    // not just whichever liquid the player happens to be near.
    updateWaterMaterials(dt, {
      sunDir, sunColor, skyColor,
      fogColor: scene.fog.color, fogNear: scene.fog.near, fogFar: scene.fog.far,
    });
  }
}
