// A small, reusable full-screen yes/no(/cancel) dialog. No confirmation-
// dialog pattern existed anywhere in this codebase before the save/load
// feature needed one — the death screen and loading screen are both
// one-button, non-cancelable state changes, not an actual choice — so
// this is deliberately generic (arbitrary title/message/button list)
// rather than hardcoded to the one "unsaved changes" prompt that first
// needed it.

let currentButtons = [];

export function initConfirmDialog() {
  const container = document.getElementById('confirm-buttons');
  if (!container) return;
  container.addEventListener('click', e => {
    const btn = e.target.closest('button[data-index]');
    if (!btn) return;
    const action = currentButtons[Number(btn.dataset.index)];
    hideConfirmDialog();
    if (action && action.onClick) action.onClick();
  });
}

function escapeHtml(s) {
  const div = document.createElement('div');
  div.textContent = s;
  return div.innerHTML;
}

// `buttons`: [{ label, onClick, primary? }, ...] — shown left to right in
// the order given.
export function showConfirmDialog({ title, message, buttons }) {
  currentButtons = buttons || [];

  const el = document.getElementById('confirm-dialog');
  if (el) el.classList.remove('hidden');

  const titleEl = document.getElementById('confirm-title');
  if (titleEl) titleEl.textContent = title || '';

  const msgEl = document.getElementById('confirm-message');
  if (msgEl) msgEl.textContent = message || '';

  const container = document.getElementById('confirm-buttons');
  if (container) {
    container.innerHTML = currentButtons.map((b, i) => (
      `<button type="button" data-index="${i}" class="${b.primary ? 'confirm-primary' : ''}">` +
      `${escapeHtml(b.label)}</button>`
    )).join('');
  }
}

export function hideConfirmDialog() {
  const el = document.getElementById('confirm-dialog');
  if (el) el.classList.add('hidden');
}
