// What the mouse buttons do: break blocks, hit mobs, fire weapons, place
// blocks (including towering up).

import { PLAYER_HEIGHT, PLAYER_RADIUS, PLACE_COOLDOWN } from '../config.js';
import { AIR } from '../world/blocks.js';
import { getTargetBlock, setTargetBlock, isBedrockTarget, recentreOnTarget } from '../world/blockTarget.js';
import { mouse } from '../core/input.js';
import { addToInventory, consumeSelected, getSelectedItem } from '../inventory.js';
import { TOOL_TYPES } from '../tools/types.js';
import { isCreative } from '../gameMode.js';
import { hitMob } from '../entities/mobs.js';
import { fireWeapon } from '../weapons/firing.js';
import { player } from './state.js';
import { raycastBlock, raycastAttack } from './raycast.js';
import { sendHit } from '../net/client.js';
import { triggerSwing } from './viewmodel.js';
import { scaleOutgoing } from '../difficulty.js';
import { showLabel } from '../ui/hud.js';

const MELEE_DAMAGE = 10;

// Bare hands and blocks hit for the flat amount; any tool or machine hits for
// whatever it's rated at instead — a rock destroyer should hurt more than a
// hand drill.
function meleeDamageFor(item) {
  return item && item.kind === 'tool' ? TOOL_TYPES[item.toolKey].meleeDamage : MELEE_DAMAGE;
}

// Instant break, with no regard for hardness or tool — used by Creative
// (which never waits) and internally by player/mining.js once a hold-to-mine
// bar in Survival actually fills.
export function breakBlock() {
  const r = raycastBlock();
  if (!r.hit) return;
  // A space planet's own bedrock floor (world/blockTarget.js, world/
  // spaceSession.js's BEDROCK_MARGIN) — always false on Earth. Creative
  // isn't exempt: Earth's own y<0 floor isn't reachable to dig into either.
  if (isBedrockTarget(r.target)) { showLabel("Solid bedrock — can't dig any deeper."); return; }
  const minedId = getTargetBlock(r.target);
  setTargetBlock(r.target, AIR);
  if (minedId !== AIR) addToInventory(minedId);
  // Keeps the player centred on the cell they just cleared, in space —
  // see world/blockTarget.js's own comment for why that (not clearing
  // extra blocks) is what actually stops "stuck on an invisible ledge"
  // once cells shrink deep underground.
  recentreOnTarget(r.target, player.pos);
}

export function handleLeftClick() {
  if (player.dead) return;
  const item = getSelectedItem();
  if (item && item.kind === 'weapon') {
    fireWeapon();
    return;
  }
  // Punching: whichever of a mob or another player is nearer, else mine.
  const { mob, mobDist, playerId, playerDist } = raycastAttack();
  if (playerId !== null && (!mob || playerDist <= mobDist)) {
    triggerSwing();
    // Scaled here, on the attacker's side: how hard you hit depends on how far
    // into YOUR run you are. The victim then scales what lands by theirs.
    sendHit(playerId, scaleOutgoing(meleeDamageFor(item)));
    return;
  }
  if (mob) {
    triggerSwing();
    hitMob(mob, meleeDamageFor(item));
    return;
  }
  // Blocks are handled by the hold-to-mine system in player/mining.js, which
  // runs every frame off `mouse.leftHeld` — except in Creative, which never
  // had a wait and still breaks on the click itself.
  if (isCreative()) {
    triggerSwing();
    breakBlock();
  }
}

// True when the unit cube at (bx,by,bz) would overlap the player's box. Tested
// exactly rather than by block column so that a block CAN be placed at the feet
// position mid-jump — that's what makes towering up possible.
export function blockIntersectsPlayer(bx, by, bz) {
  const r = PLAYER_RADIUS;
  const p = player.pos;
  return bx < p.x + r && bx + 1 > p.x - r &&
         by < p.y + PLAYER_HEIGHT && by + 1 > p.y &&
         bz < p.z + r && bz + 1 > p.z - r;
}

let placeCooldown = 0;

export function placeBlock() {
  if (player.dead || placeCooldown > 0) return;
  const item = getSelectedItem();
  if (!item || item.kind === 'weapon') return;
  const r = raycastBlock();
  if (!r.hit) return;
  if (blockIntersectsPlayer(r.prevX, r.prevY, r.prevZ)) return;
  setTargetBlock(r.prevTarget, item.id);
  placeCooldown = PLACE_COOLDOWN;
  triggerSwing();
  consumeSelected();
}

// Holding right-click keeps placing on a cooldown. Combined with the
// intersection test above this is what lets you tower up: look down, hold
// right-click, and keep jumping — each jump clears the feet block long enough
// for the next one to be placed underneath you.
export function updateBlockPlacing(dt) {
  placeCooldown = Math.max(0, placeCooldown - dt);
  if (mouse.rightHeld) placeBlock();
}
