// The world seed: what terrain.js's noise fields are built from. Persisted
// like renderDistance.js/dayLength.js, but reading it doesn't change
// anything on its own — regenerating the actual world is a bigger, explicit
// action (main.js's regenerateWorld()) since it means throwing away chunks,
// mobs and pickups, not just re-rendering with the same voxel data.

const STORAGE_KEY = 'blocksWorldSeed';

// Empty input always maps to this — "if you don't provide a seed you always
// get the same world" means literally this one, the world the game always
// shipped with before seeds were a setting at all.
export const DEFAULT_SEED = 42;

let seedInput = '';        // raw text as the player typed/saw it, '' = default
let numericSeed = DEFAULT_SEED;
const listeners = [];

export function getWorldSeed() { return numericSeed; }
export function getWorldSeedInput() { return seedInput; }
export function onWorldSeedChange(fn) { listeners.push(fn); }

// Turns whatever the player typed into a deterministic 32-bit integer.
// A plain integer string is used directly — so typing "42" reproduces the
// classic default on purpose, the same way it would in Minecraft's seed
// box — and anything else (words, phrases, mixed characters) is hashed with
// FNV-1a, a small, fast, well-distributed non-cryptographic hash that's
// plenty for "turn this string into noise-permutation seed material".
function hashSeed(input) {
  const trimmed = String(input ?? '').trim();
  if (trimmed === '') return DEFAULT_SEED;
  if (/^-?\d+$/.test(trimmed)) return Number(trimmed) >>> 0;
  let h = 0x811c9dc5;
  for (let i = 0; i < trimmed.length; i++) {
    h ^= trimmed.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

export function setWorldSeed(input) {
  seedInput = String(input ?? '');
  numericSeed = hashSeed(seedInput);
  try { localStorage.setItem(STORAGE_KEY, seedInput); } catch { /* private mode */ }
  for (const fn of listeners) fn(numericSeed, seedInput);
}

// A short, human-typeable random seed (base-36, so it reads as a word-ish
// jumble rather than a long raw number) — easy to read aloud or write down
// to share with someone else, the same way Minecraft's random seeds are.
export function randomWorldSeed() {
  return Math.floor(Math.random() * 0xffffffff).toString(36);
}

// Reads the saved seed. Called from main.js so importing this module has no
// side effects.
export function initWorldSeed() {
  let saved = null;
  try { saved = localStorage.getItem(STORAGE_KEY); } catch { /* private mode */ }
  seedInput = saved ?? '';
  numericSeed = hashSeed(seedInput);
  for (const fn of listeners) fn(numericSeed, seedInput);
}
