// The gravity a point in the world actually feels: a "down" direction and a
// magnitude. Threaded through player physics, mob physics and the camera as
// a single choke point. Gravity comes from whichever body's own volume
// actually contains the point — set via setGravityBodies(), normally by
// world/spaceSession.js whenever the set of planets changes (the home
// planet's own gravity body covers ordinary standing-on-the-ground play, the
// same way a flat world's single constant used to). A point that isn't near
// any body at all is open vacuum: weightless (g = 0), not falling towards
// the nearest body from arbitrarily far away — there's no orbital mechanics
// here, see CLAUDE.md's Space environment section.
//
// gravityAt returns a SHARED object, mutated in place and returned — the
// same "read it before calling again" contract player/raycast.js's
// raycastBlock() already uses, so this can run every physics tick for every
// entity without allocating.

import * as THREE from 'three';

// [{ center: Vector3, radius: number, gravityRange: number, gravity: number }]
let bodies = [];

export function setGravityBodies(list) { bodies = list; }
export function getGravityBodies() { return bodies; }
export function clearGravityBodies() { bodies = []; }

const result = { dir: new THREE.Vector3(0, -1, 0), g: 0 };

export function gravityAt(worldPos) {
  for (const body of bodies) {
    const dist = worldPos.distanceTo(body.center);
    if (dist <= body.radius + body.gravityRange) {
      result.dir.copy(body.center).sub(worldPos);
      // Standing exactly on the body's own center is degenerate (no
      // meaningful direction) — pick a stable, arbitrary "down" rather than
      // dividing by zero.
      if (result.dir.lengthSq() < 1e-8) result.dir.set(0, -1, 0);
      else result.dir.normalize();
      result.g = body.gravity;
      return result;
    }
  }

  result.dir.set(0, -1, 0);
  result.g = 0;
  return result;
}
