// First-person camera: applies mouse look and parks the camera at eye height,
// plus the wireframe highlight on the targeted block.

import * as THREE from 'three';
import { MOUSE_SENS, EYE_HEIGHT, EYE_HEIGHT_CROUCHED } from '../config.js';
import { camera, highlightMesh, spaceHighlightMesh } from '../core/scene.js';
import { consumeMouseDelta } from '../core/input.js';
import { worldGetBlock } from '../world/activeWorld.js';
import { isLiquidBlock } from '../world/blocks.js';
import { targetCorners } from '../world/blockTarget.js';
import { updateCellWireframe, makeCornerScratch } from '../render/cellHighlight.js';
import { setUnderwaterOverlay } from '../ui/hud.js';
import { scopeSway } from '../weapons/scope.js';
import { gravityAt } from '../world/gravity.js';
import { updateAlignQuaternion } from '../world/sphericalMotion.js';
import { player } from './state.js';
import { raycastBlock } from './raycast.js';

const PITCH_LIMIT = Math.PI / 2 - 0.01;   // just short of straight up/down

// Scratch, reused every frame rather than allocated.
const localUp = new THREE.Vector3();
const yawPitchQuat = new THREE.Quaternion();

export function updateCamera() {
  if (player.dead) return;
  const { dx, dy } = consumeMouseDelta();
  player.yaw   -= dx * MOUSE_SENS;
  player.pitch -= dy * MOUSE_SENS;
  player.pitch  = Math.max(-PITCH_LIMIT, Math.min(PITCH_LIMIT, player.pitch));

  // The scope's sway is added on top here, not stored back into player.yaw/
  // pitch — those stay the player's actual, clean aim (what other clients
  // see, what the viewmodel's own look-sway is measured against). Only the
  // camera actually rendered — and raycast from, since raycastWeapon reads
  // the camera's real direction — wobbles.
  const sway = scopeSway();
  yawPitchQuat.setFromEuler(new THREE.Euler(player.pitch + sway.pitch, player.yaw + sway.yaw, 0, 'YXZ'));

  // Yaw/pitch above is built as if "up" were always world Y. player.
  // spaceAlignQuat is the (incrementally maintained, not recomputed from
  // scratch — see world/sphericalMotion.js's updateAlignQuaternion)
  // rotation that bends that whole reference frame so its nominal up
  // actually points along wherever gravity here points away from, the same
  // persistent orientation player/physics.js's own space movement updates
  // too, so walking forward always matches where a level camera looks.
  // Composed this way (spaceAlignQuat * yawPitchQuat), yaw/pitch is applied
  // first, then the whole result is tilted onto the local frame — on flat
  // ground (gravity dir exactly world -Y) spaceAlignQuat is the identity
  // and this reduces to exactly the original bare yaw/pitch Euler.
  const g = gravityAt(player.pos);
  localUp.copy(g.dir).negate();
  updateAlignQuaternion(player.spaceAlignQuat, g.dir);
  camera.position.copy(player.pos)
    .addScaledVector(localUp, player.crouching ? EYE_HEIGHT_CROUCHED : EYE_HEIGHT);
  camera.quaternion.copy(player.spaceAlignQuat).multiply(yawPitchQuat);

  // The eye specifically, not the body — you can be swimming with your head
  // above the surface and see fine, or standing on a submerged ledge with
  // your head under and not. Keeping the actual block id (not just a
  // boolean) is what lets the overlay/fog tint (ui/hud.js, sky.js) vary by
  // which liquid the eye is actually inside — plain water, or one of a
  // planet's own coloured ones.
  const eyeBlock = worldGetBlock(
    Math.floor(camera.position.x), Math.floor(camera.position.y), Math.floor(camera.position.z)
  );
  player.underwaterLiquid = isLiquidBlock(eyeBlock) ? eyeBlock : null;
  player.underwater = player.underwaterLiquid !== null;
  setUnderwaterOverlay(player.underwater, player.underwaterLiquid);
}

const highlightCorners = makeCornerScratch();

export function updateHighlight() {
  const r = raycastBlock();
  if (!r.hit) {
    highlightMesh.visible = false;
    spaceHighlightMesh.visible = false;
    return;
  }
  // A planet's own cell is a warped, variably-sized hexahedron, not a unit
  // cube (world/cubeSphere.js) — drawing a fixed unit-box mesh around it is
  // what made the highlight visibly misalign with the actual block.
  // targetCorners() returns null for open vacuum (shouldn't happen for a
  // real hit, but defensive).
  const corners = targetCorners(r.target, highlightCorners);
  if (corners) {
    highlightMesh.visible = false;
    updateCellWireframe(spaceHighlightMesh.geometry, corners);
    spaceHighlightMesh.visible = true;
  } else {
    spaceHighlightMesh.visible = false;
    highlightMesh.position.set(r.bx + 0.5, r.by + 0.5, r.bz + 0.5);
    highlightMesh.visible = true;
  }
}
