// The three.js scene graph and renderer.
//
// `scene` and `camera` are created at import time (they need no DOM), so any
// module can add objects to the world. The WebGL renderer needs a canvas, so
// it's created by initRenderer() from main.js — which also means non-browser
// tooling can import the game's modules without a canvas.

import * as THREE from 'three';
import {
  RENDER_DIST, CHUNK_SIZE, MAX_PIXEL_RATIO, ANTIALIAS, CAMERA_NEAR, CAMERA_FAR, DEFAULT_FOV,
} from '../config.js';

export const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x87ceeb, RENDER_DIST * CHUNK_SIZE * 0.6, RENDER_DIST * CHUNK_SIZE * 1.1);

export const camera = new THREE.PerspectiveCamera(DEFAULT_FOV, 16 / 9, CAMERA_NEAR, CAMERA_FAR);

export const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambientLight);

// Wireframe box drawn around the block under the crosshair.
export const highlightMesh = new THREE.Mesh(
  new THREE.BoxGeometry(1.002, 1.002, 1.002),
  new THREE.MeshBasicMaterial({ color: 0x000000, wireframe: true, transparent: true, opacity: 0.5 })
);
highlightMesh.visible = false;
scene.add(highlightMesh);

// Darkens over the block currently being mined, so hold-to-mine progress is
// visible rather than the block just vanishing with no warning. Opacity is
// driven every frame by player/mining.js; depthWrite is off so it never
// fights the highlight wireframe or the world mesh for the depth buffer.
export const breakOverlayMesh = new THREE.Mesh(
  new THREE.BoxGeometry(1.01, 1.01, 1.01),
  new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0, depthWrite: false })
);
breakOverlayMesh.visible = false;
scene.add(breakOverlayMesh);

// Space-only counterparts of the two meshes above: a planet's voxel cells
// are warped, variably-sized hexahedra (world/cubeSphere.js), not unit
// cubes, so the highlight/overlay geometry has to be rebuilt from the
// actually-targeted cell's own corners (render/cellHighlight.js) instead of
// just repositioning a fixed unit box. DoubleSide because a warped cell's
// winding isn't guaranteed to face the camera the way an axis-aligned
// cube's does. Geometry starts empty and is filled in on first use.
export const spaceHighlightMesh = new THREE.LineSegments(
  new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.5 })
);
spaceHighlightMesh.visible = false;
scene.add(spaceHighlightMesh);

// A jagged, progressively denser "crack" decal (render/crackTexture.js),
// swapped stage-by-stage by player/mining.js as progress climbs — white
// base colour so the texture's own painted colour shows through
// unmultiplied. `map` starts null here deliberately (crackTexture.js's own
// canvas painting needs a real `document`, which this module can't assume
// exists — some tests reach core/scene.js without ever installing the DOM
// stub tests/helpers.js provides); player/mining.js sets it, and the one
// `material.needsUpdate` that transition genuinely needs, the first time it
// actually has a stage to show. polygonOffset pulls this mesh's depth
// slightly toward the camera relative to the real terrain it sits exactly
// coincident with — without it, the two coplanar surfaces flicker
// unpredictably between "in front" and "behind" each other as the camera
// moves (ordinary depth-buffer z-fighting), which is what made the old
// plain-darkening version of this overlay look glitchy rather than just
// plain.
export const spaceBreakOverlayMesh = new THREE.Mesh(
  new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0, depthWrite: false,
    side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -4,
  })
);
spaceBreakOverlayMesh.visible = false;
scene.add(spaceBreakOverlayMesh);

export let renderer = null;

// Applied on preset change: the fill-rate lever, since MSAA can only be chosen
// when the WebGL context is created.
export function setMaxPixelRatio(max) {
  if (!renderer) return;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, max));
  renderer.setSize(window.innerWidth, window.innerHeight);
}

// Applied on entering/leaving the space environment. config.js's CAMERA_FAR
// is deliberately sized once for Earth's own maximum render-distance
// setting and left alone here — nothing about Earth's rendering should ever
// depend on this changing. Space needs a much larger far plane so a distant
// planet/moon (world/spaceSession.js) doesn't get clipped; main.js resets
// this back to CAMERA_FAR when returning to Earth.
export function setCameraFar(value) {
  camera.far = value;
  camera.updateProjectionMatrix();
}

export function initRenderer(canvas) {
  renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: ANTIALIAS,
    powerPreference: 'high-performance',
    stencil: false,          // nothing here uses the stencil buffer
    depth: true,
  });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, MAX_PIXEL_RATIO));
  renderer.setClearColor(0x87ceeb);
  resize();
  window.addEventListener('resize', resize);
  return renderer;
}

function resize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

export function render() {
  renderer.render(scene, camera);
}
