// Render distance: how many chunks stream in around the player, in each
// direction. A continuous slider like difficulty, not a preset like
// graphics, so it follows difficulty.js's pattern rather than settings.js's.
//
// Bigger costs real frame time — more chunks generated, meshed and drawn
// every frame — so this is left entirely to the player: MIN_RENDER_DIST is
// exactly what the game always shipped with, MAX_RENDER_DIST (config.js) is
// deep into "why is my fan so loud" territory, and nothing here judges the
// choice in between. world/world.js reads the live value to size its
// streaming rings; sky.js reads it to size the fog so the world doesn't just
// pop into view at the edge of what's loaded.

import { RENDER_DIST, MAX_RENDER_DIST } from './config.js';

export const MIN_RENDER_DIST = RENDER_DIST;
export { MAX_RENDER_DIST };

const STORAGE_KEY = 'blocksRenderDistance';

let renderDistance = MIN_RENDER_DIST;
const listeners = [];

export function getRenderDistance() { return renderDistance; }

export function onRenderDistanceChange(fn) { listeners.push(fn); }

function clamp(value) {
  return Math.max(MIN_RENDER_DIST, Math.min(MAX_RENDER_DIST, Math.round(Number(value) || MIN_RENDER_DIST)));
}

export function setRenderDistance(value) {
  const next = clamp(value);
  if (next === renderDistance) return;
  renderDistance = next;
  try { localStorage.setItem(STORAGE_KEY, String(next)); } catch { /* private mode */ }
  for (const fn of listeners) fn(renderDistance);
}

// Reads the saved value. Called from main.js so importing this module has no
// side effects.
export function initRenderDistance() {
  let saved = null;
  try { saved = localStorage.getItem(STORAGE_KEY); } catch { /* private mode */ }
  renderDistance = saved !== null ? clamp(saved) : MIN_RENDER_DIST;
  for (const fn of listeners) fn(renderDistance);
}
