// One definition of "what colour is this health bar".
//
// Green at full, through amber, to red at empty. Used by the player's own HP
// bar, the bars above mobs, and the ones on other players' name tags, so all
// three read the same way at a glance.
//
// Pure — no imports, no DOM, no three.js — so anything can use it.

// `fraction` is 0..1. Returns { r, g, b } in 0..255.
export function healthColor(fraction) {
  const f = Math.max(0, Math.min(1, fraction));
  // Hue 120 is green, 60 amber, 0 red — so the hue *is* the health.
  const hue = f * 120;
  // Dip the lightness through the middle so amber doesn't wash out against
  // bright terrain.
  const light = 0.42 + Math.abs(f - 0.5) * 0.12;
  return hslToRgb(hue / 360, 0.78, light);
}

export function healthColorCss(fraction) {
  const { r, g, b } = healthColor(fraction);
  return `rgb(${r},${g},${b})`;
}

// Packed 0xRRGGBB, for three.js materials.
export function healthColorHex(fraction) {
  const { r, g, b } = healthColor(fraction);
  return (r << 16) | (g << 8) | b;
}

function hslToRgb(h, s, l) {
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h * 6) % 2) - 1));
  const m = l - c / 2;
  let r = 0, g = 0, b = 0;
  const sector = Math.floor(h * 6) % 6;
  if (sector === 0)      { r = c; g = x; }
  else if (sector === 1) { r = x; g = c; }
  else if (sector === 2) { g = c; b = x; }
  else if (sector === 3) { g = x; b = c; }
  else if (sector === 4) { r = x; b = c; }
  else                   { r = c; b = x; }
  return {
    r: Math.round((r + m) * 255),
    g: Math.round((g + m) * 255),
    b: Math.round((b + m) * 255),
  };
}
