// Seeded value-gradient noise (Perlin-style). Self-contained and deterministic
// so terrain is identical for a given seed on every load.

export function makeNoise(seed) {
  const p = new Uint8Array(512);
  const base = new Uint8Array(256);
  for (let i = 0; i < 256; i++) base[i] = i;
  let s = seed >>> 0;
  for (let i = 255; i > 0; i--) {
    s = (s * 1664525 + 1013904223) >>> 0;
    const j = s % (i + 1);
    [base[i], base[j]] = [base[j], base[i]];
  }
  for (let i = 0; i < 512; i++) p[i] = base[i & 255];

  function fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }
  function lerp(a, b, t) { return a + t * (b - a); }
  function grad(hash, x, y) {
    const h = hash & 3;
    const u = h < 2 ? x : y;
    const v = h < 2 ? y : x;
    return ((h & 1) ? -u : u) + ((h & 2) ? -v : v);
  }

  function noise2(x, y) {
    const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
    x -= Math.floor(x); y -= Math.floor(y);
    const u = fade(x), v = fade(y);
    const a = p[X] + Y, b = p[X + 1] + Y;
    return lerp(
      lerp(grad(p[a],   x,   y),   grad(p[b],   x-1, y),   u),
      lerp(grad(p[a+1], x,   y-1), grad(p[b+1], x-1, y-1), u),
      v
    );
  }

  function octave(x, y, octs, persistence, lacunarity) {
    let val = 0, amp = 1, freq = 1, max = 0;
    for (let i = 0; i < octs; i++) {
      val += noise2(x * freq, y * freq) * amp;
      max += amp;
      amp *= persistence;
      freq *= lacunarity;
    }
    return val / max;
  }

  return { noise2, octave };
}

// Deterministic, dependency-free hash for placing craters, picking a
// planet's own biome theme, and any other "mix a few integers into a
// deterministic [0,1]" random draw — used by world/planetTerrain.js,
// world/alienBiomes.js and world/starSystem.js alike. Lives here (rather
// than on whichever module first needed it) so those three can all import
// it without any of them depending on each other.
export function hash32(...ints) {
  let h = 0x811c9dc5;
  for (const n of ints) {
    h ^= n | 0;
    h = Math.imul(h, 0x01000193);
  }
  h ^= h >>> 16;
  return (h >>> 0) / 0xffffffff;
}

// Cheap deterministic hash used to tint individual block faces so large flat
// areas don't look like one solid slab.
export function faceHash(wx, wy, wz, faceIdx) {
  let h = (wx * 1619 + wy * 31337 + wz * 6271 + faceIdx * 1013) >>> 0;
  h ^= h >>> 16;
  h = Math.imul(h, 0x45d9f3b) >>> 0;
  h ^= h >>> 16;
  return (h & 0xff) / 255;
}
