// The F3 debug overlay. A leaf module: it reads from every system but nothing
// reads from it, so it's safe to add whatever you need while debugging.

import { BLOCK_NAMES } from '../world/blocks.js';
import { CHUNK_SHIFT } from '../config.js';
import { resolveTargetAtPoint, getTargetBlock } from '../world/blockTarget.js';
import { spaceResolveCell } from '../world/spaceSession.js';
import { planetMeshCount, pendingPlanetChunkWork } from '../world/planetStreaming.js';
import { gravityAt } from '../world/gravity.js';
import { renderer } from '../core/scene.js';
import { player } from '../player/state.js';
import { isSprintHeld } from '../core/input.js';
import { mobs } from '../entities/mobs.js';
import { projectiles } from '../entities/mobProjectiles.js';
import { gunPickups } from '../entities/pickups.js';
import { hearts } from '../entities/hearts.js';
import { getGameMode } from '../gameMode.js';
import { getSelectedItem, itemLabel } from '../inventory.js';
import { getDayTime } from '../sky.js';
import { getWorldSeed, getWorldSeedInput } from '../worldSeed.js';
import { isDebugVisible, setDebugText } from './hud.js';
import { getStats } from './fps.js';

export function updateDebug() {
  if (!isDebugVisible()) return;
  const cell = spaceResolveCell(player.pos.x, player.pos.y, player.pos.z);
  const faceLabel = cell ? cell.faceId + ' ' + (cell.au >> CHUNK_SHIFT) + ',' + (cell.av >> CHUNK_SHIFT) : 'vacuum';
  // "Below" is wherever gravity points away from here, not always -Y — a
  // debug-only readout, so a small clone-and-nudge each call (only while F3
  // is open) is fine, unlike anywhere on a hot path.
  const belowPoint = player.pos.clone().addScaledVector(gravityAt(player.pos).dir, 0.1);
  // Resolves at the EXACT point, not a literal integer cube's centre — see
  // world/blockTarget.js's own comment on resolveTargetAtPoint for why that
  // distinction matters once a cell's real size is close to one world unit.
  const blockId = getTargetBlock(resolveTargetAtPoint(belowPoint.x, belowPoint.y, belowPoint.z));
  const fps = getStats();
  setDebugText(
    'FPS: ' + fps.avgFps.toFixed(0) + ' avg  ' + fps.lowFps.toFixed(0) + ' 1% low\n' +
    'Frame: ' + fps.avgMs.toFixed(1) + ' ms  worst ' + fps.worstMs.toFixed(1) + ' ms\n' +
    'XYZ: ' + player.pos.x.toFixed(1) + ' / ' + player.pos.y.toFixed(1) + ' / ' + player.pos.z.toFixed(1) + '\n' +
    'Face/tile: ' + faceLabel + '\n' +
    'On ground: ' + player.onGround + '  Flying: ' + player.flying + '\n' +
    'Crouching: ' + player.crouching + '  Sprinting: ' + (isSprintHeld() && !player.crouching) + '\n' +
    'Swimming: ' + player.swimming + '  Underwater: ' + player.underwater + '\n' +
    'Block below: ' + BLOCK_NAMES[blockId] + '\n' +
    'Day: ' + (getDayTime() * 24).toFixed(1) + 'h  Chunks: ' + planetMeshCount() +
      ' (+' + pendingPlanetChunkWork() + ' queued)\n' +
    'Draws: ' + (renderer ? renderer.info.render.calls : 0) +
      '  Tris: ' + (renderer ? (renderer.info.render.triangles / 1000).toFixed(0) + 'k' : '0') + '\n' +
    'Mobs: ' + mobs.length + '  Projectiles: ' + projectiles.length + '  HP: ' + player.hp + '\n' +
    'Mode: ' + getGameMode() + '  Held: ' + itemLabel(getSelectedItem()) + '\n' +
    'Guns on ground: ' + gunPickups.length + '  Hearts: ' + hearts.length + '\n' +
    'Seed: ' + getWorldSeed() + (getWorldSeedInput() ? ' ("' + getWorldSeedInput() + '")' : ' (default)')
  );
}
