// The multiplayer compass: a ring of arrows around the crosshair, one per
// other connected player, each pointing towards them and labelled with their
// name. Distance controls how strongly it reads — faint far away, solid up
// close — and angles are spread apart so two people on nearly the same
// bearing don't render as one unreadable blob.
//
// A view module: it's handed { id, name, angle, distance } entries (computed
// from game state by net/remotePlayers.js's remotePlayerBearings()) and only
// worries about where to put them on screen.

const RADIUS = 120;          // px out from the crosshair
const MIN_SEP_DEG = 30;      // minimum angular gap once spread apart
const NEAR_DIST = 6;         // full strength within this many blocks
const FAR_DIST = 100;        // faded to minimum by this many blocks
const MIN_OPACITY = 0.28;
const MAX_OPACITY = 0.95;

const items = new Map();   // id -> { el, arrow, label }

function opacityFor(distance) {
  const t = Math.min(1, Math.max(0, (distance - NEAR_DIST) / (FAR_DIST - NEAR_DIST)));
  return MAX_OPACITY - t * (MAX_OPACITY - MIN_OPACITY);
}

// Pushes angles apart until every circularly-adjacent pair is at least
// `minSepDeg` apart, preserving the order they were already in around the
// circle (so who's closest to straight-ahead never flips relative to who's
// beside them, only the tight cluster as a whole eases apart).
//
// Works by cutting the circle open at its widest existing gap — so unrolling
// it into a straight line never slices through a cluster that needs
// spreading — then a single forward pass enforces the minimum gap along that
// line, and a final shift re-centres the whole run on its original average
// so it eases apart symmetrically rather than all drifting one direction.
export function spreadAngles(entries, minSepDeg = MIN_SEP_DEG) {
  if (entries.length < 2) return entries.map(e => ({ ...e }));

  const sorted = entries.map(e => ({ ...e })).sort((a, b) => a.angle - b.angle);
  const n = sorted.length;

  let cutIndex = 0, maxGap = -1;
  for (let i = 0; i < n; i++) {
    let gap = sorted[(i + 1) % n].angle - sorted[i].angle;
    if (i === n - 1) gap += 360;
    if (gap > maxGap) { maxGap = gap; cutIndex = (i + 1) % n; }
  }

  const ordered = [...sorted.slice(cutIndex), ...sorted.slice(0, cutIndex)];
  const base = ordered[0].angle;
  const line = ordered.map(e => ({ ...e, angle: e.angle < base ? e.angle + 360 : e.angle }));

  const originalAvg = line.reduce((sum, e) => sum + e.angle, 0) / n;
  for (let i = 1; i < n; i++) {
    if (line[i].angle - line[i - 1].angle < minSepDeg) {
      line[i].angle = line[i - 1].angle + minSepDeg;
    }
  }
  const shift = originalAvg - line.reduce((sum, e) => sum + e.angle, 0) / n;
  for (const e of line) e.angle = (((e.angle + shift) % 360) + 360) % 360;

  return line;
}

function makeItem() {
  const el = document.createElement('div');
  el.className = 'radar-item';
  const arrow = document.createElement('div');
  arrow.className = 'radar-arrow';
  arrow.textContent = '▲';
  const label = document.createElement('div');
  label.className = 'radar-name';
  el.appendChild(arrow);
  el.appendChild(label);
  return { el, arrow, label };
}

export function updateRadar(entries) {
  const host = document.getElementById('player-radar');
  if (!host) return;

  const spread = spreadAngles(entries);
  const seen = new Set();

  for (const e of spread) {
    seen.add(e.id);
    let item = items.get(e.id);
    if (!item) {
      item = makeItem();
      items.set(e.id, item);
      host.appendChild(item.el);
    }
    const rad = (e.angle * Math.PI) / 180;
    const x = RADIUS * Math.sin(rad);
    const y = -RADIUS * Math.cos(rad);
    // The wrapper only translates — rotating it would tip the name label
    // sideways. The arrow inside is what rotates to point outward.
    item.el.style.transform = `translate(-50%, -50%) translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
    item.el.style.opacity = String(opacityFor(e.distance));
    item.arrow.style.transform = `rotate(${e.angle.toFixed(1)}deg)`;
    item.label.textContent = e.name;
  }

  for (const [id, item] of items) {
    if (!seen.has(id)) {
      item.el.remove();
      items.delete(id);
    }
  }
}
