// Ray queries from the camera: what block or mob is the player pointing at.
// All of them step along the ray in fixed increments — simple and fast enough
// at these ranges.

import * as THREE from 'three';
import { REACH } from '../config.js';
import { AIR, isLiquidBlock } from '../world/blocks.js';
import { worldGetBlock } from '../world/activeWorld.js';
import { resolveTargetAtPoint, sameTarget, getTargetBlock } from '../world/blockTarget.js';
import { camera } from '../core/scene.js';
import { mobs } from '../entities/mobs.js';
import { remotePlayerTargets } from '../net/remotePlayers.js';

const BLOCK_STEP  = 0.05;
const WEAPON_STEP = 0.1;

// The halfwidth raycastMobAlong tests every mob against, regardless of that
// mob's own (melee) radius — kept as one named constant so hit-zone
// classification below tests against the exact box a shot was actually
// judged to have entered.
const MOB_RAY_HALFWIDTH = 0.4;

// Rough body zones for variable weapon damage. Mobs and remote players are
// both plain upright boxes — there's no separate limb geometry to test
// against — so "arm" is approximated as the same height band as the torso,
// but out towards the edge of the box rather than through its centre; a hand
// tool's or nuke's blast doesn't need this, only aimed hitscan fire does.
const HEAD_FRACTION      = 0.82;  // top of the box, at/above this line is the head
const LEG_FRACTION       = 0.35;  // bottom of the box, below this line is a leg
const ARM_EDGE_FRACTION  = 0.55;  // that fraction of halfwidth outward counts as an arm

export function classifyHitZone(hitPoint, cx, cy, cz, halfWidth, height) {
  const top = (hitPoint.y - cy) / height;
  if (top >= HEAD_FRACTION) return 'head';
  if (top < LEG_FRACTION) return 'leg';
  const dx = hitPoint.x - cx, dz = hitPoint.z - cz;
  return Math.sqrt(dx * dx + dz * dz) >= halfWidth * ARM_EDGE_FRACTION ? 'arm' : 'torso';
}

// Reused scratch: raycastBlock runs every frame for the block highlight.
// `target`/`prevTarget` are freshly built (not mutated in place) whenever a
// hit is found — see world/blockTarget.js's own comment on why callers
// (player/mining.js in particular) need to be able to hold onto one of
// these across frames without it changing underneath them.
const dirScratch = new THREE.Vector3();
const blockHit = {
  hit: false, bx: 0, by: 0, bz: 0, prevX: 0, prevY: 0, prevZ: 0, target: null, prevTarget: null,
};

// Returns the first solid block along the view ray plus `prev*`, the empty
// cell just before it — that's where a new block gets placed.
// The returned object is reused between calls — read what you need from it
// before calling again rather than holding on to it. `bx/by/bz`/`prevX/Y/Z`
// remain literal floored world coordinates for legacy/display purposes
// (player/actions.js's own rough self-placement guard); anything that
// actually READS or WRITES the targeted cell should use `target`/
// `prevTarget` instead (world/blockTarget.js), which is what stays correct
// once a planet's own voxel cells stop being close to one world unit
// across (see CLAUDE.md's Mining section).
//
// Marching happens in world-space steps (the ray direction is a world
// vector), but each step resolves the ACTUAL cell at that EXACT fractional
// point (resolveTargetAtPoint), not a literal floor(x, y, z) cube's centre
// — see world/blockTarget.js's own comment on why that distinction matters.
export function raycastBlock() {
  const dir = camera.getWorldDirection(dirScratch);
  const origin = camera.position;
  let prevX = Math.floor(origin.x);
  let prevY = Math.floor(origin.y);
  let prevZ = Math.floor(origin.z);
  let prevTarget = resolveTargetAtPoint(origin.x, origin.y, origin.z);

  for (let t = 0; t < REACH; t += BLOCK_STEP) {
    const wx = origin.x + dir.x * t;
    const wy = origin.y + dir.y * t;
    const wz = origin.z + dir.z * t;
    const target = resolveTargetAtPoint(wx, wy, wz);
    if (sameTarget(target, prevTarget)) continue;
    const id = getTargetBlock(target);
    if (id !== AIR && !isLiquidBlock(id)) {
      blockHit.hit = true;
      blockHit.bx = Math.floor(wx); blockHit.by = Math.floor(wy); blockHit.bz = Math.floor(wz);
      blockHit.prevX = prevX; blockHit.prevY = prevY; blockHit.prevZ = prevZ;
      blockHit.target = target; blockHit.prevTarget = prevTarget;
      return blockHit;
    }
    prevX = Math.floor(wx); prevY = Math.floor(wy); prevZ = Math.floor(wz);
    prevTarget = target;
  }
  blockHit.hit = false;
  return blockHit;
}

// Slab test of a ray against one upright box. Returns the entry distance, or
// -1 for a miss.
function rayBoxDistance(origin, dir, cx, cy, cz, halfWidth, height, maxRange) {
  const invDx = 1 / dir.x, invDy = 1 / dir.y, invDz = 1 / dir.z;
  const t1 = (cx - halfWidth - origin.x) * invDx;
  const t2 = (cx + halfWidth - origin.x) * invDx;
  const t3 = (cy              - origin.y) * invDy;
  const t4 = (cy + height     - origin.y) * invDy;
  const t5 = (cz - halfWidth - origin.z) * invDz;
  const t6 = (cz + halfWidth - origin.z) * invDz;

  const tmin = Math.max(Math.min(t1, t2), Math.min(t3, t4), Math.min(t5, t6));
  const tmax = Math.min(Math.max(t1, t2), Math.max(t3, t4), Math.max(t5, t6));

  if (tmax < 0 || tmin > tmax || tmin > maxRange) return -1;
  return Math.max(0, tmin);
}

// Nearest mob along the ray within maxRange.
export function raycastMobAlong(dir, maxRange) {
  const origin = camera.position;
  let closest = null;
  let closestDist = Infinity;

  for (const mob of mobs) {
    if (mob.dead || mob.dying) continue;
    const dist = rayBoxDistance(
      origin, dir, mob.pos.x, mob.pos.y, mob.pos.z, MOB_RAY_HALFWIDTH, mob.typeDef.height, maxRange
    );
    if (dist >= 0 && dist < closestDist) {
      closestDist = dist;
      closest = mob;
    }
  }

  return { mob: closest, dist: closestDist };
}

// Nearest other player along the ray. Returns their network id, and the
// target box itself so raycastWeapon can work out where on it the shot
// landed — raycastAttack (melee) just ignores that extra field.
export function raycastPlayerAlong(dir, maxRange) {
  const origin = camera.position;
  let closestId = null;
  let closestDist = Infinity;
  let closestTarget = null;

  for (const target of remotePlayerTargets()) {
    const dist = rayBoxDistance(
      origin, dir, target.pos.x, target.pos.y, target.pos.z,
      target.radius, target.height, maxRange
    );
    if (dist >= 0 && dist < closestDist) {
      closestDist = dist;
      closestId = target.id;
      closestTarget = target;
    }
  }

  return { playerId: closestId, dist: closestDist, target: closestTarget };
}

const attackDir = new THREE.Vector3();

// What's under the crosshair within melee reach — a mob, another player, or
// neither. Callers pick whichever is nearer.
export function raycastAttack(maxRange = REACH) {
  const dir = camera.getWorldDirection(attackDir);
  const { mob, dist: mobDist } = raycastMobAlong(dir, maxRange);
  const { playerId, dist: playerDist } = raycastPlayerAlong(dir, maxRange);
  return { mob, mobDist, playerId, playerDist };
}

// Combined block+mob cast along an arbitrary direction, for weapon fire —
// raycastBlock/raycastMob are camera-forward-only and reach-limited, which
// suits mining and melee but not long-range, spread-jittered gunfire.
export function raycastWeapon(dir, maxRange) {
  const origin = camera.position;
  let blockDist = maxRange;
  let hitPoint = null;

  for (let t = 0; t < maxRange; t += WEAPON_STEP) {
    const bx = Math.floor(origin.x + dir.x * t);
    const by = Math.floor(origin.y + dir.y * t);
    const bz = Math.floor(origin.z + dir.z * t);
    const id = worldGetBlock(bx, by, bz);
    if (id !== AIR && !isLiquidBlock(id)) {
      blockDist = t;
      hitPoint = origin.clone().addScaledVector(dir, t);
      break;
    }
  }

  // Whichever is nearer wins: terrain, a mob, or another player.
  const { mob, dist: mobDist } = raycastMobAlong(dir, blockDist);
  const { playerId, dist: playerDist, target } = raycastPlayerAlong(dir, blockDist);

  if (playerId !== null && playerDist <= mobDist && playerDist <= blockDist) {
    const hp = origin.clone().addScaledVector(dir, playerDist);
    const zone = classifyHitZone(hp, target.pos.x, target.pos.y, target.pos.z, target.radius, target.height);
    return { mob: null, playerId, dist: playerDist, hitPoint: hp, zone };
  }
  if (mob) {
    const hp = origin.clone().addScaledVector(dir, mobDist);
    const zone = classifyHitZone(hp, mob.pos.x, mob.pos.y, mob.pos.z, MOB_RAY_HALFWIDTH, mob.typeDef.height);
    return { mob, playerId: null, dist: mobDist, hitPoint: hp, zone };
  }
  return { mob: null, playerId: null, dist: blockDist, hitPoint, zone: null };
}
