// Streams a planet's chunks (generation + meshing) based on player
// proximity — the planet analogue of world/world.js's own
// refreshQueues/drainQueues/updateChunks pattern, generalized from Earth's
// single infinite flat grid to a planet's bounded, six-faced grid.
//
// This is the architectural prerequisite for bigger and more numerous
// planets (see CLAUDE.md's Space environment section): generating a whole
// planet eagerly only stays cheap while planets stay tiny. Only the ONE
// planet nearest the player's own surface gets any chunk work in a given
// frame — everything else costs zero, the same way Earth never streams
// chunks on the far side of its own world. A planet nobody has approached
// yet never has a single chunk generated, ever.
//
// Owns the actual chunk meshes (the planet-side analogue of mesher.js's
// own chunkMeshes Map) — world/spaceSession.js calls back into this module
// to rebuild the one mesh a direct edit (mining/placing) touches, the same
// relationship world.js's setBlock already has with mesher.js.
//
// Generation itself is dispatched through each planet's OWN
// `planet.generateChunk` function reference (set once at construction
// time by spaceSession.js) rather than a single imported generator — the
// home body uses world/earthTerrain.js's real biome/tree/ore generator,
// every other body uses world/planetTerrain.js's simpler alien one. This
// keeps that choice out of this module entirely (never imports either
// generator, or spaceSession.js, directly) — fully generic over whatever
// each planet object was actually built with.

import { CHUNK_SIZE } from '../config.js';
import { getRenderDistance } from '../renderDistance.js';
import { chunkKey } from './store.js';
import { buildPlanetChunkMesh } from './planetMesher.js';
import { worldToFace, projectPointOntoFace, FACE_IDS } from './cubeSphere.js';
import { scene } from '../core/scene.js';

// ── Mesh lifecycle ──────────────────────────────────────────

const planetMeshes = new Map();   // "planetId,faceId,cx,cv" -> THREE.Mesh

function meshKey(planet, faceId, cx, cv) { return planet.id + ',' + faceId + ',' + cx + ',' + cv; }

// A Potato chunk is a bare Mesh; a Next Level chunk is a Group of one or
// two meshes (opaque terrain, plus a water sub-mesh where the chunk has
// any) — geometries are always per-chunk and disposed here, but materials
// never are: they're shared singletons (world/render/materials.js), so
// disposing one here would break every OTHER currently-visible chunk still
// using it.
function disposePlanetMesh(object) {
  scene.remove(object);
  if (object.isGroup) {
    for (const child of object.children) child.geometry.dispose();
  } else {
    object.geometry.dispose();
  }
}

export function rebuildPlanetChunkMesh(planet, faceId, cx, cv) {
  const key = meshKey(planet, faceId, cx, cv);
  const old = planetMeshes.get(key);
  if (old) { disposePlanetMesh(old); planetMeshes.delete(key); }
  const mesh = buildPlanetChunkMesh(planet, faceId, cx, cv);
  if (mesh) { scene.add(mesh); planetMeshes.set(key, mesh); }
}

export function hasPlanetChunkMesh(planet, faceId, cx, cv) {
  return planetMeshes.has(meshKey(planet, faceId, cx, cv));
}

// Rebuilds every currently-meshed chunk, on every active planet — called
// when the graphics preset changes (main.js's onGraphicsChange), since
// Potato and Next Level chunks are genuinely different geometry (the
// planet-streaming analogue of the old flat world's own remeshAllChunks).
// Voxel data itself is untouched; only each chunk's mesh is discarded and
// rebuilt via the now-current preset (world/planetMesher.js's own
// buildPlanetChunkMesh reads the live preset itself, so this needs no
// preset argument of its own). `planets` is whatever getActivePlanets()
// currently returns — this module never keeps its own reference to that
// list between frames, unlike the mesh map itself.
export function rebuildAllPlanetChunkMeshes(planets) {
  const byId = new Map(planets.map(p => [p.id, p]));
  for (const key of [...planetMeshes.keys()]) {
    const [planetId, faceId, cxStr, cvStr] = key.split(',');
    const planet = byId.get(planetId);
    if (!planet) continue;   // stale key from a planet that's since unloaded
    rebuildPlanetChunkMesh(planet, faceId, Number(cxStr), Number(cvStr));
  }
}

// The budgeted analogue of rebuildAllPlanetChunkMeshes, for exactly the
// same graphics-preset-switch trigger — the synchronous, do-it-all-at-once
// version above freezes the tab for however long a large streamed area
// takes to remesh, with no way to report partway progress since it's one
// long blocking call. Splitting it into "queue everything, then drain a
// budgeted amount per frame" (the same generation/mesh-queue shape
// updatePlanetStreaming already uses) is what lets main.js's loop() turn
// this into a real, progressing loading bar instead of either a frozen tab
// or a bar that sits at 0% until the whole rebuild lands in one frame.
let rebuildQueue = [];

// Snapshots every currently-meshed chunk key into the rebuild queue —
// called once, right when the preset actually changes. Doesn't rebuild
// anything itself; main.js's loop() drains it a little at a time via
// drainGraphicsRebuildQueue below.
export function queueGraphicsRebuild(planets) {
  const byId = new Map(planets.map(p => [p.id, p]));
  rebuildQueue = [...planetMeshes.keys()].filter(key => byId.has(key.split(',')[0]));
}

// How many chunks are still waiting on their new-preset mesh — what
// main.js turns into a loading-bar fraction, the same way
// pendingPlanetChunkWork() already does for streaming.
export function pendingGraphicsRebuildWork() { return rebuildQueue.length; }

export function drainGraphicsRebuildQueue(planets, budgetMs) {
  if (rebuildQueue.length === 0) return;
  const byId = new Map(planets.map(p => [p.id, p]));
  const deadline = performance.now() + budgetMs;
  while (rebuildQueue.length > 0) {
    const key = rebuildQueue.pop();
    const [planetId, faceId, cxStr, cvStr] = key.split(',');
    const planet = byId.get(planetId);
    // A planet that's since unloaded (player wandered off mid-rebuild) —
    // nothing to rebuild, but still counts as "done" for this key.
    if (planet) rebuildPlanetChunkMesh(planet, faceId, Number(cxStr), Number(cvStr));
    if (performance.now() >= deadline) return;
  }
}

// Drops one chunk entirely — its mesh AND its generated voxel data, the
// same "unload deletes both" trade Earth's own unloadChunk (mesher.js)
// makes. Safe because generation is deterministic (same planet seed): a
// chunk unloaded here regenerates identically if the player ever comes
// back, exactly like Earth's own accepted "edits outside the loaded radius
// are lost on unload" trait.
function unloadPlanetChunk(planet, faceId, cx, cv) {
  const key = meshKey(planet, faceId, cx, cv);
  const mesh = planetMeshes.get(key);
  if (mesh) { disposePlanetMesh(mesh); planetMeshes.delete(key); }
  planet.faces[faceId].deleteChunk(chunkKey(cx, cv));
}

// Every chunk belonging to `planet`, mesh and data alike — used when the
// player leaves a planet's own streaming range entirely (updatePlanetStreaming
// below) or when the whole space session is torn down (clearAllPlanetMeshes).
// A planet unload this wholesale (rather than Earth's own ring-by-ring
// unload) is fine here specifically because leaving a planet's vicinity
// means NOTHING on it is worth keeping resident — unlike Earth, where the
// player is always standing somewhere inside the one world that exists.
export function unloadAllChunksForPlanet(planet) {
  const prefix = planet.id + ',';
  for (const [key, mesh] of [...planetMeshes]) {
    if (!key.startsWith(prefix)) continue;
    disposePlanetMesh(mesh);
    planetMeshes.delete(key);
  }
  for (const faceId of FACE_IDS) planet.faces[faceId].clearChunks();
}

export function clearAllPlanetMeshes() {
  for (const mesh of planetMeshes.values()) disposePlanetMesh(mesh);
  planetMeshes.clear();
}

// F3 debug readouts (ui/debug.js) — the planet-streaming analogue of
// world/mesher.js's own chunkMeshes.size and world/world.js's own
// pendingChunkWork().
export function planetMeshCount() { return planetMeshes.size; }
export function pendingPlanetChunkWork() { return genQueue.length + meshQueue.length; }

// ── Streaming ────────────────────────────────────────────

// How far beyond a planet's own surface counts as "close enough to
// stream" — the same render-distance-scaled world-unit distance Earth's
// own fog/streaming radius already use elsewhere (getRenderDistance() *
// CHUNK_SIZE), plus a couple of rings of headroom so chunks are already
// there before the player can see the edge of them. Read live rather than
// frozen, so the render-distance slider affects planets the same way it
// already affects Earth. Exported so render/planetBodies.js can hand off
// a body's own decorative sphere right at the edge of what's actually
// streamed in, regardless of that body's own radius — see that module's
// own comment for why a body's RADIUS is the wrong thing to hide the
// sphere against.
export function streamingRangeFor() {
  return (getRenderDistance() + 2) * CHUNK_SIZE;
}

// Only the ONE planet nearest the player's own surface distance, and only
// if that distance is within streaming range — everything else gets zero
// chunk work this frame. Comparing distance-to-SURFACE (not distance to
// centre) is what makes this fair regardless of how wildly planet sizes
// differ from each other.
export function nearestPlanetWithinRange(planets, pos) {
  const range = streamingRangeFor();
  let best = null, bestDist = Infinity;
  for (const planet of planets) {
    const dist = Math.abs(pos.distanceTo(planet.center) - planet.radius);
    if (dist < bestDist && dist <= range) { bestDist = dist; best = planet; }
  }
  return best;
}

function clampTile(planet, t) {
  return Math.max(0, Math.min(planet.chunkSpan - 1, t));
}

// The chunk tile at face-tangent (u, v), clamped to the face's own valid
// domain — a point past a face's own edge (still possible right up to the
// margin candidateFaces below allows) just clamps to that face's own
// outermost tile rather than indexing negative/out-of-range.
function tileAt(planet, u, v) {
  return {
    cx: clampTile(planet, Math.floor((u + planet.halfExtent) / CHUNK_SIZE)),
    cv: clampTile(planet, Math.floor((v + planet.halfExtent) / CHUNK_SIZE)),
  };
}

// Every face whose own valid (u, v) domain the player's position projects
// into, within one chunk's worth of margin past its edge — exactly 1 away
// from any seam, 2 near a flat edge, 3 near a corner, and (since a small
// planet's halfExtent can be smaller than the margin itself) potentially
// all 6 on a planet tiny enough that every face already qualifies —
// harmlessly degenerating to "stream everything," which is exactly
// today's whole-planet behaviour, for free.
function candidateFaces(planet, pos) {
  const margin = CHUNK_SIZE;
  const limit = planet.halfExtent + margin;
  const out = [];
  for (const faceId of FACE_IDS) {
    const proj = projectPointOntoFace(pos, planet.center, planet.halfExtent, faceId);
    if (!proj) continue;
    if (Math.abs(proj.u) > limit || Math.abs(proj.v) > limit) continue;
    out.push({ faceId, u: proj.u, v: proj.v });
  }
  return out;
}

let focusPlanetId = null;
let focusFaceId = null;
let focusCx = null, focusCv = null;

// Both sorted farthest-first, same convention as world/world.js, so pop()
// yields the nearest outstanding work. Entries carry their own faceId
// since a corner can have candidate work on more than one face at once.
let genQueue = [];
let meshQueue = [];

function refreshFaceQueues(planet, pos) {
  genQueue.length = 0;
  meshQueue.length = 0;

  const meshDist = getRenderDistance();
  const genDist = meshDist + 1;

  for (const { faceId, u, v } of candidateFaces(planet, pos)) {
    const { cx: pcx, cv: pcv } = tileAt(planet, u, v);
    const store = planet.faces[faceId];

    for (let dx = -genDist; dx <= genDist; dx++) {
      for (let dv = -genDist; dv <= genDist; dv++) {
        const cx = pcx + dx, cv = pcv + dv;
        if (cx < 0 || cx >= planet.chunkSpan || cv < 0 || cv >= planet.chunkSpan) continue;
        const dist = dx * dx + dv * dv;
        if (!store.hasChunk(cx, cv)) genQueue.push({ planet, faceId, cx, cv, dist });
        if (Math.abs(dx) <= meshDist && Math.abs(dv) <= meshDist &&
            !hasPlanetChunkMesh(planet, faceId, cx, cv)) {
          meshQueue.push({ planet, faceId, cx, cv, dist });
        }
      }
    }
  }

  genQueue.sort((a, b) => b.dist - a.dist);
  meshQueue.sort((a, b) => b.dist - a.dist);
}

// Generation is cheap and meshing depends on it, so gen work always goes
// first — identical ordering to world/world.js's own drainQueues.
function drainFaceQueues(budgetMs) {
  if (genQueue.length === 0 && meshQueue.length === 0) return;
  const deadline = performance.now() + budgetMs;

  while (genQueue.length > 0) {
    const { planet, faceId, cx, cv } = genQueue.pop();
    if (!planet.faces[faceId].hasChunk(cx, cv)) planet.generateChunk(planet, faceId, cx, cv);
    if (performance.now() >= deadline) return;
  }

  while (meshQueue.length > 0) {
    const { planet, faceId, cx, cv } = meshQueue.pop();
    const store = planet.faces[faceId];
    // Safety net mirroring world.js's own: meshing needs its four in-face
    // neighbours already generated so border faces cull correctly. The gen
    // ring above normally guarantees this already. A neighbour across a
    // face's own OUTER edge (a different face entirely) isn't generated
    // here — planetMesher.js's own AIR fallback handles that seam instead
    // (see its module comment; cross-face seam stitching stays a known,
    // separate non-goal, not something this streaming change attempts).
    if (!store.hasChunk(cx, cv))                                planet.generateChunk(planet, faceId, cx, cv);
    if (cx > 0                     && !store.hasChunk(cx - 1, cv)) planet.generateChunk(planet, faceId, cx - 1, cv);
    if (cx < planet.chunkSpan - 1  && !store.hasChunk(cx + 1, cv)) planet.generateChunk(planet, faceId, cx + 1, cv);
    if (cv > 0                     && !store.hasChunk(cx, cv - 1)) planet.generateChunk(planet, faceId, cx, cv - 1);
    if (cv < planet.chunkSpan - 1  && !store.hasChunk(cx, cv + 1)) planet.generateChunk(planet, faceId, cx, cv + 1);
    rebuildPlanetChunkMesh(planet, faceId, cx, cv);
    if (performance.now() >= deadline) return;
  }
}

// Drops the streaming focus and any outstanding queued work — called when
// switching environments/sessions (nothing to resume) and when the render
// distance setting changes (the old queues were sized for the old radius).
export function resetPlanetStreamingFocus() {
  focusPlanetId = null; focusFaceId = null; focusCx = null; focusCv = null;
  genQueue.length = 0; meshQueue.length = 0;
}

// Called every frame from main.js's loop, space branch only. `planets` is
// whatever world/spaceSession.js's own getActivePlanets() currently
// answers, passed in rather than imported — this module never imports
// spaceSession.js at all; spaceSession.js is the one that imports FROM
// here (for rebuildPlanetChunkMesh, on its own direct-edit writes), so
// this ordering keeps the two modules from ever needing each other both ways.
export function updatePlanetStreaming(planets, pos, budgetMs) {
  const planet = nearestPlanetWithinRange(planets, pos);

  if (!planet) {
    if (focusPlanetId !== null) {
      const old = planets.find(p => p.id === focusPlanetId);
      if (old) unloadAllChunksForPlanet(old);
    }
    resetPlanetStreamingFocus();
    return;
  }

  if (planet.id !== focusPlanetId && focusPlanetId !== null) {
    // Arrived close enough to a DIFFERENT planet to leave the old one's own
    // streaming range — drop everything it had loaded so memory doesn't
    // grow with every body ever visited; it regenerates deterministically
    // (same seed) if the player ever comes back this way.
    const old = planets.find(p => p.id === focusPlanetId);
    if (old && old !== planet) unloadAllChunksForPlanet(old);
  }

  const primary = worldToFace(pos, planet.center, planet.halfExtent);
  const { cx, cv } = tileAt(planet, primary.u, primary.v);

  if (planet.id !== focusPlanetId || primary.faceId !== focusFaceId || cx !== focusCx || cv !== focusCv) {
    focusPlanetId = planet.id; focusFaceId = primary.faceId; focusCx = cx; focusCv = cv;
    refreshFaceQueues(planet, pos);
  }

  drainFaceQueues(budgetMs);
}

// Generates and meshes a square of tiles on one face immediately — the
// planet analogue of world/world.js's own preloadChunks, used once at
// session start for the home body's own spawn tile so the player never
// lands on ungenerated ground. Every other body wakes up purely through
// proximity (updatePlanetStreaming above) once the player is close enough
// — no explicit preload anywhere else.
export function preloadPlanetChunks(planet, faceId, cx0, cv0, radius) {
  const store = planet.faces[faceId];
  for (let dx = -radius - 1; dx <= radius + 1; dx++) {
    for (let dv = -radius - 1; dv <= radius + 1; dv++) {
      const cx = clampTile(planet, cx0 + dx), cv = clampTile(planet, cv0 + dv);
      if (!store.hasChunk(cx, cv)) planet.generateChunk(planet, faceId, cx, cv);
    }
  }
  for (let dx = -radius; dx <= radius; dx++) {
    for (let dv = -radius; dv <= radius; dv++) {
      const cx = clampTile(planet, cx0 + dx), cv = clampTile(planet, cv0 + dv);
      rebuildPlanetChunkMesh(planet, faceId, cx, cv);
    }
  }
}

// Same as preloadPlanetChunks, but starting from a face-tangent (u, v)
// point rather than an already-known tile — the convenience spaceSession.js
// actually calls with the home planet's own spawn point.
export function preloadPlanetChunksNear(planet, faceId, u, v, radius) {
  const { cx, cv } = tileAt(planet, u, v);
  preloadPlanetChunks(planet, faceId, cx, cv, radius);
}
