// The player's mutable state, kept in one plain object so every system reads
// and writes the same source of truth. No imports beyond three — anything can
// depend on this without creating a cycle.

import * as THREE from 'three';
import { CHUNK_HEIGHT } from '../config.js';

export const player = {
  pos: new THREE.Vector3(8, CHUNK_HEIGHT, 8),  // feet position, not eye
  vel: new THREE.Vector3(),
  yaw: 0,
  pitch: 0,
  onGround: false,
  crouching: false,
  flying: false,
  lastJump: 0,        // performance.now() of the last space press (fly toggle)
  hp: 100,
  maxHp: 100,
  damageFlash: 0,     // seconds of red screen flash remaining
  invincible: 0,      // seconds of damage immunity remaining
  dead: false,
  fallStartY: null,   // height fall damage is measured from
  lastAttacker: null, // network id of whoever hit us last, for kill credit
  lastDamageSource: null, // { kind, ... } describing the last hit, for the death screen
  piloting: false,    // true while flying a vehicle; ground physics stands down
  swimming: false,    // enough of the body is submerged to swim, not walk
  underwater: false,  // the eye itself is inside a liquid block (camera effects)
  underwaterLiquid: null, // which liquid block id, or null — lets the tint vary per liquid
  // Space only: a persistent orientation carried incrementally across
  // frames (world/sphericalMotion.js's updateAlignQuaternion) rather than
  // rederived from world "up" every tick, which is what keeps holding a
  // fixed heading tracing an actual straight line on a curved surface
  // regardless of which direction you set off in — see that module's own
  // comment for why recomputing from scratch every frame drifted. Shared
  // by player/physics.js's own walk heading and player/view.js's camera so
  // the two never disagree about which way "forward" currently is.
  spaceAlignQuat: new THREE.Quaternion(),
};
