// Alien biome variety: every OTHER body (world/planetTerrain.js — not the
// home planet, which has its own real generator in world/earthTerrain.js)
// gets ONE seeded theme, picked once per planet and cached the same way
// planetTerrain.js already caches its own noise instance and crater list.
// This is the direct analogue of world/biomes.js's relationship to
// world/earthTerrain.js: a thin column-fill loop (planetTerrain.js's own
// generatePlanetChunk) calls into this module for "how tall is this column,
// what biome is it, what's it made of" rather than doing any of that
// classification itself.
//
// A theme bundles everything that makes one alien world read as visibly
// different from another: its surface/subsurface blocks, its own rare deep
// ore (alongside STARMETAL, which stays universal across every theme —
// see world/blocks.js), its own coloured liquid (or none), and its own
// flora archetype (or none). Barrens is deliberately plain — today's
// original alien look, kept as one of the five possible themes so some
// planets still read as ordinary next to the exotic ones.

import { CHUNK_SIZE } from '../config.js';
import { hash32 } from './noise.js';
import { FACE_IDS } from './cubeSphere.js';
import {
  AIR, ALIEN_ROCK, REGOLITH, STARMETAL,
  CRYSTAL_SOIL, CRYSTAL_SPIRE, VOIDSTONE,
  ASH, OBSIDIAN, EMBERTHORN, MAGMA, EMBERITE,
  PERMAFROST, FROSTSPIRE, CRYOFLUID, FROSTIUM,
  FUNGAL_SOIL, FUNGAL_STALK, FUNGAL_CAP, ACID, SPORESTONE,
} from './blocks.js';

function smoothstep(edge0, edge1, x) {
  const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

// ── Flora: one archetype per exotic theme, all following the same shape
// earthTerrain.js's own tree placement uses — a per-column noise gate (a
// single raw noise2 sample, the same style earthTerrain's own tree gate
// uses, not an octave), then a short solid write straight up from the
// surface, clipped at chunk/face borders the same accepted way trees are.
// Only ever called on dry land (planetTerrain.js's generatePlanetChunk
// gates this on `surfaceIndex > liquidLevelIndex` before calling in).

function buildCrystalSpire(data, store, planet, lu, lv, surfaceIndex, noise, u, v) {
  const n = noise.noise2(u * 0.3 + 300, v * 0.3 + 300);
  if (n <= 0.6) return;
  const height = 2 + Math.floor((n - 0.6) * 7.5);   // 2-4
  for (let i = 1; i <= Math.min(height, 4); i++) {
    const ri = surfaceIndex + i;
    if (ri >= planet.chunkHeight) break;
    data[store.blockIndex(lu, ri, lv)] = CRYSTAL_SPIRE;
  }
}

function buildEmberthorn(data, store, planet, lu, lv, surfaceIndex, noise, u, v) {
  const n = noise.noise2(u * 0.32 + 400, v * 0.32 + 400);
  if (n <= 0.62) return;
  const height = n > 0.8 ? 2 : 1;
  for (let i = 1; i <= height; i++) {
    const ri = surfaceIndex + i;
    if (ri >= planet.chunkHeight) break;
    data[store.blockIndex(lu, ri, lv)] = EMBERTHORN;
  }
}

function buildFrostspire(data, store, planet, lu, lv, surfaceIndex, noise, u, v) {
  const n = noise.noise2(u * 0.28 + 500, v * 0.28 + 500);
  if (n <= 0.58) return;
  const height = 1 + Math.floor((n - 0.58) * 7);
  for (let i = 1; i <= Math.min(height, 3); i++) {
    const ri = surfaceIndex + i;
    if (ri >= planet.chunkHeight) break;
    data[store.blockIndex(lu, ri, lv)] = FROSTSPIRE;
  }
}

// A short mushroom shape — a 2-tall stalk with a small cap one layer above
// it, the same trunk-then-canopy idea earthTerrain's own trees use, just
// smaller. The cap only ever writes into AIR (never overwrites the stalk or
// anything a neighbouring column's own flora already placed), and clips at
// the chunk edge exactly like a tree's canopy does.
function buildFungalStalk(data, store, planet, lu, lv, surfaceIndex, noise, u, v) {
  const n = noise.noise2(u * 0.3 + 600, v * 0.3 + 600);
  if (n <= 0.6) return;
  const stalkHeight = 2;
  for (let i = 1; i <= stalkHeight; i++) {
    const ri = surfaceIndex + i;
    if (ri >= planet.chunkHeight) break;
    data[store.blockIndex(lu, ri, lv)] = FUNGAL_STALK;
  }
  const capRi = surfaceIndex + stalkHeight + 1;
  if (capRi >= planet.chunkHeight) return;
  for (let du = -1; du <= 1; du++) {
    for (let dv = -1; dv <= 1; dv++) {
      const llu = lu + du, llv = lv + dv;
      if (llu < 0 || llu >= CHUNK_SIZE || llv < 0 || llv >= CHUNK_SIZE) continue;
      const idx = store.blockIndex(llu, capRi, llv);
      if (data[idx] === AIR) data[idx] = FUNGAL_CAP;
    }
  }
}

// ── Themes ───────────────────────────────────────────────

export const THEMES = [
  {
    name: 'Barrens',
    surface: REGOLITH, rock: ALIEN_ROCK, deepOre: null, liquid: null, flora: null,
  },
  {
    name: 'Crystal Fields',
    surface: CRYSTAL_SOIL, rock: ALIEN_ROCK, deepOre: VOIDSTONE, liquid: null, flora: buildCrystalSpire,
  },
  {
    name: 'Ashen Wastes',
    surface: ASH, rock: OBSIDIAN, deepOre: EMBERITE, liquid: MAGMA, flora: buildEmberthorn,
  },
  {
    name: 'Frozen Wastes',
    surface: PERMAFROST, rock: ALIEN_ROCK, deepOre: FROSTIUM, liquid: CRYOFLUID, flora: buildFrostspire,
  },
  {
    name: 'Toxic Mire',
    surface: FUNGAL_SOIL, rock: ALIEN_ROCK, deepOre: SPORESTONE, liquid: ACID, flora: buildFungalStalk,
  },
];

// One theme per planet, picked once and cached on it — mirrors
// planetTerrain.js's own ensureNoise/ensureCraters caching pattern exactly.
export function themeFor(planet) {
  if (planet._theme) return planet._theme;
  const idx = Math.min(THEMES.length - 1, Math.floor(hash32(planet.seed, 0, 60) * THEMES.length));
  planet._theme = THEMES[idx];
  return planet._theme;
}

// ── Surface shaping: rolling hills (unchanged from the original alien
// generator) plus craters (unchanged), plus two NEW features — canyons and
// basins — both amplitude-relative rather than a fixed depth, the same
// "a thinner crust gets proportionally shallower features" principle
// world/blocks.js's own STARMETAL/BEDROCK_MARGIN commentary already
// documents for craters. Basins are what actually turn a theme's own
// liquid into real lakes (the flood rule lives in planetTerrain.js's
// generatePlanetChunk) rather than only ever pooling in the rare crater
// that happens to dip deep enough.

const CANYON_SCALE = 0.08, CANYON_THRESHOLD = 0.85, CANYON_DEPTH_FACTOR = 2.5;
const BASIN_SCALE  = 0.03, BASIN_THRESHOLD  = 0.5,  BASIN_DEPTH_FACTOR  = 2.2;

// A few bowl-shaped depressions per face, placed once per planet and cached
// on it — cheap, and keeps every chunk on a face agreeing about where its
// craters are without recomputing anything at generation time.
function ensureCraters(planet) {
  if (planet._craters) return planet._craters;
  const reach = planet.halfExtent * 0.6;
  const craters = {};
  for (let fi = 0; fi < FACE_IDS.length; fi++) {
    const faceId = FACE_IDS[fi];
    const list = [];
    for (let i = 0; i < planet.craterCount; i++) {
      const u = (hash32(planet.seed, fi, i, 1) * 2 - 1) * reach;
      const v = (hash32(planet.seed, fi, i, 2) * 2 - 1) * reach;
      const r = 4 + hash32(planet.seed, fi, i, 3) * 5;
      const depth = planet.amplitude * (0.5 + hash32(planet.seed, fi, i, 4) * 0.5);
      list.push({ u, v, r, depth });
    }
    craters[faceId] = list;
  }
  planet._craters = craters;
  return craters;
}

export function alienSurfaceRadiusAt(planet, faceId, noise, u, v) {
  const n = noise.octave(u * 0.045, v * 0.045, 4, 0.5, 2.0);   // ~-0.6..0.6
  let radius = planet.radius + n * planet.amplitude;

  for (const crater of ensureCraters(planet)[faceId]) {
    const du = u - crater.u, dv = v - crater.v;
    const dist = Math.hypot(du, dv);
    if (dist < crater.r) {
      const t = 1 - dist / crater.r;
      radius -= crater.depth * t * t;
    }
  }

  // Strange canyons: a narrow ridged gash, cut on every theme regardless of
  // whether it has a liquid — a dry world can still have a dramatic dry
  // chasm.
  const canyonN = noise.octave(u * CANYON_SCALE + 9000, v * CANYON_SCALE + 9000, 2, 0.5, 2.0);
  const canyonMask = 1 - Math.abs(canyonN);   // ridged fold, same trick biomes.js uses for mountains
  if (canyonMask > CANYON_THRESHOLD) {
    radius -= smoothstep(CANYON_THRESHOLD, 1, canyonMask) * planet.amplitude * CANYON_DEPTH_FACTOR;
  }

  // Basins: a broader, gentler dip — combined with the liquid flood rule in
  // planetTerrain.js, this is what actually produces lakes.
  const basinN = noise.octave(u * BASIN_SCALE + 13000, v * BASIN_SCALE + 13000, 3, 0.5, 2.0);
  if (basinN > BASIN_THRESHOLD) {
    radius -= smoothstep(BASIN_THRESHOLD, 1, basinN) * planet.amplitude * BASIN_DEPTH_FACTOR;
  }

  return radius;
}

// ── Ore: STARMETAL stays the universal rarest/deepest ore on every theme
// (unchanged — see world/blocks.js), confined to the deepest quarter of
// THIS body's own crust so it stays equally rare regardless of chunkHeight;
// a theme's own deepOre sits a little shallower but still well below the
// surface; everything else in the ore band is just the theme's common rock.
const STARMETAL_DEPTH_FRACTION = 0.25;
const THEME_ORE_DEPTH_FRACTION = 0.42;

export function alienOreAt(theme, oreNoise, u, ri, v, chunkHeight) {
  const depthFraction = ri / chunkHeight;   // 0 near bedrock, higher near the surface
  if (depthFraction < STARMETAL_DEPTH_FRACTION) {
    const n = oreNoise.noise2(u * 0.5 + ri * 0.7, v * 0.5 - ri * 0.5);
    if (n > 0.78) return STARMETAL;
  }
  if (theme.deepOre !== null && depthFraction < THEME_ORE_DEPTH_FRACTION) {
    const n2 = oreNoise.noise2(u * 0.34 - ri * 0.6, v * 0.34 + ri * 0.4);
    if (n2 > 0.7) return theme.deepOre;
  }
  return theme.rock;
}
