// Player movement, jumping and fall damage. The actual box-vs-blocks
// collision lives in world/collision.js, shared with mobs so both move by the
// same rules.

import * as THREE from 'three';
import {
  GRAVITY, JUMP_FORCE, TERMINAL_VEL,
  WALK_SPEED, SPRINT_SPEED, CROUCH_SPEED,
  PLAYER_HEIGHT, PLAYER_RADIUS, SNEAK_STEPS,
  SAFE_FALL_DIST, FALL_DAMAGE_PER_BLK,
  SWIM_SPEED, SWIM_VERTICAL_SPEED, WATER_GRAVITY, WATER_DRAG, WATER_EXIT_BOOST,
} from '../config.js';
import { AIR, isLiquidBlock } from '../world/blocks.js';
import { keys, isSprintHeld, isCrouchHeld } from '../core/input.js';
import { gravityAt } from '../world/gravity.js';
import { moveOnSphere, updateAlignQuaternion, hasFootSupportOnSphere } from '../world/sphericalMotion.js';
import { worldGetBlock, worldIsSolid } from '../world/activeWorld.js';
import { spaceIsSolid } from '../world/spaceSession.js';
import { player } from './state.js';
import { hurtPlayer } from './health.js';

const FRICTION = 0.8;   // per-frame horizontal damping when no key is held

// GRAVITY is a negative constant (config.js); this is its positive magnitude,
// and the gravity SAFE_FALL_DIST/FALL_DAMAGE_PER_BLK were originally tuned
// against — see the fall-damage scaling in spaceWalkStep below for why this
// needs its own name distinct from a body's own live `gravityAt().g`.
const HOME_GRAVITY_MAG = -GRAVITY;

// Reused every frame. physicsStep runs 60+ times a second, and allocating
// vectors here was a steady drip of garbage for the collector to sweep up.
const moveScratch = new THREE.Vector3();
const yawAxis     = new THREE.Vector3(0, 1, 0);
const yawScratch  = new THREE.Quaternion();

// Space-only scratch — see spaceWalkStep below.
const spaceGravityDir = new THREE.Vector3();
const spaceYawQuat    = new THREE.Quaternion();
const spaceTangentVel = new THREE.Vector3();

// Swimming's own gravity-aware scratch — kept separate from spaceWalkStep's
// above rather than shared, since the two could in principle be reused
// across a call boundary in a future change; physicsStep today always
// returns from swimStep before ever reaching spaceWalkStep, so there's no
// live aliasing risk yet, but keeping them distinct costs nothing and avoids
// planting one for later.
const swimGravityDir = new THREE.Vector3();
const swimUp          = new THREE.Vector3();
const swimYawQuat     = new THREE.Quaternion();
const swimTangentVel  = new THREE.Vector3();
const swimProbe       = new THREE.Vector3();
const REF_UP_TAN  = new THREE.Vector3(0, 1, 0);
const REF_FWD_TAN = new THREE.Vector3(0, 0, -1);
const tangentRight   = new THREE.Vector3();
const tangentForward = new THREE.Vector3();

// Builds a yaw-relative WASD direction vector into the shared scratch vector.
function readMoveInput() {
  moveScratch.set(0, 0, 0);
  if (keys['KeyW']) moveScratch.z -= 1;
  if (keys['KeyS']) moveScratch.z += 1;
  if (keys['KeyA']) moveScratch.x -= 1;
  if (keys['KeyD']) moveScratch.x += 1;
  return moveScratch;
}

function applyYaw(vec) {
  yawScratch.setFromAxisAngle(yawAxis, player.yaw);
  return vec.applyQuaternion(yawScratch);
}

// True once enough of the body is submerged to swim rather than walk —
// checked at the midpoint, not the feet, so wading through a shallow puddle
// still just walks along the bottom instead of triggering swim physics.
// worldGetBlock/gravityAt make this correct in space too (a body's own
// water sits at its own radius, not a literal Y) — on flat ground gravityAt
// always returns exactly world -Y, so this reduces to the original literal
// `pos.y + PLAYER_HEIGHT * 0.5` check.
function isSwimming(pos) {
  const g = gravityAt(pos);
  swimProbe.copy(pos).addScaledVector(g.dir, -PLAYER_HEIGHT * 0.5);
  return isLiquidBlock(worldGetBlock(Math.floor(swimProbe.x), Math.floor(swimProbe.y), Math.floor(swimProbe.z)));
}

// The same arbitrary-but-consistent (right, forward) tangent pair
// world/sphericalMotion.js's own (unexported) buildFrame() picks for a given
// "up" — duplicated rather than imported, since that function writes into
// ITS OWN internal scratch used by moveOnSphere and swimming needs an
// independent pair with no risk of one call's basis clobbering the other's
// mid-frame. On Earth (`upDir` exactly (0,1,0)) this reduces to plain world
// +X/-Z, matching nearWaterEdge's original literal ±X/±Z check exactly.
function buildTangentFrame(upDir) {
  const ref = Math.abs(upDir.dot(REF_FWD_TAN)) > 0.9 ? REF_UP_TAN : REF_FWD_TAN;
  tangentRight.crossVectors(ref, upDir).normalize();
  tangentForward.crossVectors(upDir, tangentRight).normalize();
}

// True when at least one of the four tangent-plane neighbours — never above
// or below along `upDir`, that's the lake bed or open sky, not a shore — is
// solid ground rather than water or air. This is the gate on the water-exit
// boost below: without it, the boost only needs to be near the *top* of the
// water to fire, which in a large open lake or sea is everywhere at once,
// turning a walled-off "climb out onto a lip" move into a repeatable,
// illegal way to skim across open water faster than swimming (or even a
// boat) should allow.
//
// Checked at BOTH feet level and one step up along `upDir`, not just one: a
// beach whose own surface sits flush with the waterline (the common case —
// world/earthTerrain.js's `isSandy` shores) has its solid block at feet
// level, not above it, while a taller lip has its solid block one above.
// Checking only the "one above" height (the first version of this fix) missed
// every flush beach, which was the actual regression: it made climbing out
// anywhere except a raised lip impossible again.
function nearWaterEdge(pos, upDir) {
  buildTangentFrame(upDir);
  // tangentRight/tangentForward are perpendicular to upDir, not to world Y —
  // away from a body's own face centres, upDir is only approximately world
  // -Y, so a "purely horizontal" (relative to gravity) tangential step can
  // still drift the WORLD-space y coordinate by a tiny fraction of a unit,
  // in either direction. That's invisible almost everywhere, but a shore
  // lip only one block thick in world-Y terms (a flush beach, exactly at
  // the waterline) can sit right at that boundary, and a drift the wrong
  // way floors into the layer below (or above) the lip instead of the lip
  // itself. Checking both `nominal - 0.06` and `nominal + 0.06` at each of
  // the two levels (feet, one above) rather than a single exact sample is
  // what makes this robust to drift landing on either side.
  for (const dir of [tangentRight, tangentForward]) {
    for (const sign of [1, -1]) {
      for (const step of [0, 1]) {
        swimProbe.copy(pos).addScaledVector(dir, sign).addScaledVector(upDir, step);
        for (const nudge of [-0.06, 0.06]) {
          const y = Math.floor(swimProbe.y + nudge);
          const id = worldGetBlock(Math.floor(swimProbe.x), y, Math.floor(swimProbe.z));
          if (!isLiquidBlock(id) && id !== AIR) return true;
        }
      }
    }
  }
  return false;
}

// Gravity-aware the same way spaceWalkStep already is: velocity decomposes
// into "along gravity" (buoyancy/exit-boost, tracked here as `upSpeed`,
// speed away from gravity — exactly what vel.y already meant on flat
// Earth) and "tangential" (WASD swimming), using the same yaw-then-align
// composition spaceWalkStep uses so a level camera and swimming "forward"
// always agree. moveOnSphere/worldIsSolid replace the literal moveBox call
// — moveOnSphere reduces to exactly moveBox when gravity is world -Y (see
// tests/sphericalMotion.test.js), so this one function is now correct on
// both flat Earth and a curved body with no isSpace() branch of its own.
function swimStep(dt) {
  player.crouching = false;   // no crouch stance while swimming
  const g = gravityAt(player.pos);
  swimGravityDir.copy(g.dir);
  swimUp.copy(swimGravityDir).negate();
  updateAlignQuaternion(player.spaceAlignQuat, swimGravityDir);

  const speed = isSprintHeld() ? SWIM_SPEED * 1.25 : SWIM_SPEED;
  const moveDir = readMoveInput();
  const upSpeed = player.vel.dot(swimUp);
  if (moveDir.lengthSq() > 0) {
    moveDir.normalize().multiplyScalar(speed);
    swimYawQuat.setFromAxisAngle(yawAxis, player.yaw);
    moveDir.applyQuaternion(swimYawQuat).applyQuaternion(player.spaceAlignQuat);
    player.vel.copy(moveDir).addScaledVector(swimUp, upSpeed);
  } else {
    swimTangentVel.copy(player.vel).addScaledVector(swimUp, -upSpeed);
    swimTangentVel.multiplyScalar(WATER_DRAG);
    player.vel.copy(swimTangentVel).addScaledVector(swimUp, upSpeed);
  }

  // Space swims up, Ctrl swims down; let go of both and buoyancy/gravity
  // settle you towards neutral rather than holding a fixed depth.
  //
  // Within the topmost water layer, Space gives a real jump instead — a
  // constant SWIM_VERTICAL_SPEED can't outrun gravity pulling you back in the
  // instant you clear the top, which is what made a shore with any lip at
  // all impossible to climb out onto no matter how long you held Space.
  // WATER_EXIT_BOOST over land's own JUMP_FORCE is deliberate: a land jump
  // launches from a firm stance at foot level, but this one launches from
  // wherever inside that top layer the feet happen to be, which can be
  // nearly a body-height below the surface — it needs the extra push to
  // reliably clear a shore that sits above the waterline at all, then carries
  // straight into normal land physics once isSwimming() goes false.
  // A step of exactly 1 unit would be enough under perfectly axis-aligned
  // gravity, but gravityAt() is only ever exactly world -Y at a body's own
  // face centres — everywhere else it's a hair off, so a feet position that
  // happens to sit exactly on an integer boundary (any settled stance can)
  // could step to just short of the next cell up by a few parts in a
  // million and still floor back down into the same water layer. 1.01
  // covers that with room to spare while still probing "one cell up", not
  // meaningfully further.
  swimProbe.copy(player.pos).addScaledVector(swimUp, 1.01);
  const breachingSurface = !isLiquidBlock(worldGetBlock(
    Math.floor(swimProbe.x), Math.floor(swimProbe.y), Math.floor(swimProbe.z)
  ));
  // Breaching alone isn't enough — that's true at the surface of ANY open
  // water, not just a shore. It also has to be beside something solid, or
  // this is just open water and the boost stays off; see nearWaterEdge().
  const canExitBoost = breachingSurface && nearWaterEdge(player.pos, swimUp);
  let newUpSpeed;
  if (keys['Space']) {
    newUpSpeed = canExitBoost ? JUMP_FORCE * WATER_EXIT_BOOST : SWIM_VERTICAL_SPEED;
  } else if (isCrouchHeld()) {
    newUpSpeed = -SWIM_VERTICAL_SPEED;
  } else {
    newUpSpeed = THREE.MathUtils.clamp(
      (upSpeed + WATER_GRAVITY * dt) * WATER_DRAG, -SWIM_VERTICAL_SPEED, SWIM_VERTICAL_SPEED
    );
  }
  player.vel.addScaledVector(swimUp, newUpSpeed - player.vel.dot(swimUp));

  player.onGround = moveOnSphere(
    player.pos, player.vel, dt, PLAYER_RADIUS, PLAYER_HEIGHT, false, SNEAK_STEPS,
    swimGravityDir, worldIsSolid
  );

  // Never accrues fall damage while swimming, at any depth — surfacing and
  // falling again afterwards measures fresh from wherever you left the water.
  player.fallStartY = player.pos.y;
}

function flyStep(dt) {
  const speed = isCrouchHeld() ? CROUCH_SPEED : isSprintHeld() ? SPRINT_SPEED * 1.5 : WALK_SPEED * 1.5;
  const moveDir = readMoveInput();
  if (keys['Space'])  moveDir.y += 1;
  if (isCrouchHeld()) moveDir.y -= 1;
  moveDir.normalize().multiplyScalar(speed * 2);
  applyYaw(moveDir);
  player.pos.addScaledVector(moveDir, dt);
}

// Walking on a planet under directional gravity — generalised the same way
// world/sphericalMotion.js generalises moveBox: gravity applies along
// whatever direction gravityAt() actually returns, instead of a bare -Y
// scalar, and every velocity/collision op that used to touch `.y` directly
// now decomposes into "along gravity" (falling/jumping) and "tangential"
// (walking) components instead. `fallStartY` keeps its name but its meaning
// generalises too: `-pos.dot(gravityDir)` is exactly `pos.y` when gravityDir
// is world -Y, so every existing fall-damage/reset call site elsewhere
// (gameMode.js, main.js, devConsole.js, core/input.js) still just assigns
// it a plain number, they just now assign THIS number instead of a literal Y.
//
// Crouch ledge-protection, fall damage and a terminal-velocity clamp were
// all deferred here originally, back when the home planet was still small
// enough that falls were short and low-risk — now that it's planet-sized
// (world/starSystem.js's HOME_RADIUS) with real mountainous terrain and
// real cliffs, that's no longer true, so all three are implemented below
// the same way Earth's own flat branch always did them, just along the
// local gravity axis instead of a fixed world Y (world/sphericalMotion.js's
// hasFootSupportOnSphere is collision.js's own hasFootSupport, generalised
// the same way moveOnSphere generalises moveBox).
function spaceWalkStep(dt, wasOnGround) {
  const g = gravityAt(player.pos);
  spaceGravityDir.copy(g.dir);

  player.vel.addScaledVector(spaceGravityDir, g.g * dt);

  player.crouching = isCrouchHeld();
  const speed = player.crouching ? CROUCH_SPEED : isSprintHeld() ? SPRINT_SPEED : WALK_SPEED;
  const moveDir = readMoveInput();
  const alongGrav = player.vel.dot(spaceGravityDir);

  if (moveDir.lengthSq() > 0) {
    moveDir.normalize().multiplyScalar(speed);
    // Rotated by yaw exactly like Earth's applyYaw, then bent onto the local
    // tangent plane by the same align rotation the camera uses (player/
    // view.js) — so walking "forward" always matches where a level camera
    // is looking, on any face, at any tilt.
    spaceYawQuat.setFromAxisAngle(yawAxis, player.yaw);
    updateAlignQuaternion(player.spaceAlignQuat, spaceGravityDir);
    moveDir.applyQuaternion(spaceYawQuat).applyQuaternion(player.spaceAlignQuat);
    // Replace the tangential component of velocity; leave the along-gravity
    // component (falling/jumping speed) exactly as it was — the same split
    // Earth's own vel.x/vel.z-vs-vel.y makes.
    player.vel.copy(moveDir).addScaledVector(spaceGravityDir, alongGrav);
  } else {
    spaceTangentVel.copy(player.vel).addScaledVector(spaceGravityDir, -alongGrav);
    spaceTangentVel.multiplyScalar(FRICTION);
    player.vel.copy(spaceTangentVel).addScaledVector(spaceGravityDir, alongGrav);
  }

  if (keys['Space'] && player.onGround) {
    const currentAlongGrav = player.vel.dot(spaceGravityDir);
    player.vel.addScaledVector(spaceGravityDir, -JUMP_FORCE - currentAlongGrav);
    player.onGround = false;
  }

  // Terminal velocity: caps how fast gravity alone can accelerate a fall —
  // the direct generalisation of Earth's own
  // `vel.y = Math.max(vel.y, TERMINAL_VEL)`. TERMINAL_VEL is a negative
  // constant (config.js); the along-gravity SPEED (positive means falling)
  // is capped at its positive equivalent.
  const fallSpeed = player.vel.dot(spaceGravityDir);
  if (fallSpeed > -TERMINAL_VEL) {
    player.vel.addScaledVector(spaceGravityDir, -TERMINAL_VEL - fallSpeed);
  }

  // Track the height fall damage is measured from: while grounded this just
  // follows the player; the moment they leave the ground it freezes at
  // launch height until they land again. See this function's own module
  // comment for why `-pos.dot(gravityDir)` is the right generalisation of a
  // literal world Y here.
  if (wasOnGround || player.fallStartY === null) player.fallStartY = -player.pos.dot(spaceGravityDir);

  // Only clamp to ledges when the player is actually standing on something —
  // otherwise a crouch held mid-air would freeze horizontal movement.
  const sneak = player.crouching && wasOnGround &&
                hasFootSupportOnSphere(player.pos, PLAYER_RADIUS, spaceGravityDir, spaceIsSolid);

  player.onGround = moveOnSphere(
    player.pos, player.vel, dt, PLAYER_RADIUS, PLAYER_HEIGHT, sneak, SNEAK_STEPS,
    spaceGravityDir, spaceIsSolid
  );

  if (!wasOnGround && player.onGround) {
    const fallDist = player.fallStartY - (-player.pos.dot(spaceGravityDir));
    // Damage is scaled by actual impact ENERGY (g * distance), not raw
    // distance. JUMP_FORCE is a fixed launch speed regardless of a body's
    // own gravity, so a low-gravity moon's jump apex is much higher (apex
    // height is JUMP_FORCE^2 / (2*g)) — but landing back at launch height
    // regains exactly JUMP_FORCE of impact speed by energy conservation,
    // NO MATTER how weak gravity is. SAFE_FALL_DIST/FALL_DAMAGE_PER_BLK were
    // tuned against HOME_GRAVITY_MAG, so comparing energy (g * fallDist)
    // against that same fixed safe-energy threshold, rather than comparing
    // raw fallDist against a fixed distance, is what makes a plain jump-and-
    // land safe on every body: the jump's own energy contribution never
    // depends on g, only the safe threshold does, and it's g-independent
    // here too. A genuine net elevation drop (a real cliff, not just a
    // jump's own arc) still scales in — less punishing under weak gravity,
    // exactly like a real fall would be. On the home planet (g ==
    // HOME_GRAVITY_MAG) this reduces to exactly the original formula.
    const fallEnergy = fallDist * g.g;
    const safeEnergy = SAFE_FALL_DIST * HOME_GRAVITY_MAG;
    if (fallEnergy > safeEnergy) {
      const dmg = (fallEnergy - safeEnergy) / HOME_GRAVITY_MAG * FALL_DAMAGE_PER_BLK;
      hurtPlayer(Math.round(dmg), { kind: 'fall' });
    }
    player.fallStartY = -player.pos.dot(spaceGravityDir);
  }
}

export function physicsStep(dt) {
  if (player.dead) return;

  const wasOnGround = player.onGround;

  if (player.flying) { player.swimming = false; flyStep(dt); return; }

  player.swimming = isSwimming(player.pos);
  if (player.swimming) { swimStep(dt); return; }

  spaceWalkStep(dt, wasOnGround);
}
