// The shared Save Game / Load Game slot picker — one panel, two modes,
// since both are fundamentally "pick a save slot", differing only in the
// primary action (Load vs Overwrite) and Save additionally offering "save
// as a new slot" via a name field. Game logic (actually reading/writing
// slots — src/save/saveGame.js) is injected as handlers, same as every
// other view in ui/.

let mode = 'load';
let handlers = {};

export function initSaveSlotPicker({ onLoad, onOverwrite, onSaveNew, onDelete, onBack }) {
  handlers = { onLoad, onOverwrite, onSaveNew, onDelete, onBack };

  const backBtn = document.getElementById('slot-picker-back-btn');
  if (backBtn) backBtn.addEventListener('click', () => { hideSlotPicker(); handlers.onBack(); });

  const saveNewBtn = document.getElementById('slot-save-new-btn');
  const nameInput = document.getElementById('slot-name-input');
  if (saveNewBtn) {
    saveNewBtn.addEventListener('click', () => {
      const name = (nameInput && nameInput.value.trim()) || '';
      handlers.onSaveNew(name);
    });
  }

  const list = document.getElementById('slot-list');
  if (list) {
    list.addEventListener('click', e => {
      const btn = e.target.closest('button[data-action]');
      if (!btn) return;
      const id = Number(btn.dataset.id);
      if (btn.dataset.action === 'primary') {
        if (mode === 'save') handlers.onOverwrite(id);
        else handlers.onLoad(id);
      } else if (btn.dataset.action === 'delete') {
        handlers.onDelete(id);
      }
    });
  }
}

function escapeHtml(s) {
  const div = document.createElement('div');
  div.textContent = s;
  return div.innerHTML;
}

function renderSlotList(slots) {
  const list = document.getElementById('slot-list');
  const empty = document.getElementById('slot-list-empty');
  if (!list) return;
  if (empty) empty.classList.toggle('hidden', slots.length > 0);
  const primaryLabel = mode === 'save' ? 'Overwrite' : 'Load';
  list.innerHTML = slots.map(s => (
    `<li>` +
    `<span class="slot-name">${escapeHtml(s.name)}</span>` +
    `<span class="slot-meta">${new Date(s.savedAt).toLocaleString()}</span>` +
    `<button type="button" data-action="primary" data-id="${s.id}">${primaryLabel}</button>` +
    `<button type="button" data-action="delete" data-id="${s.id}">Delete</button>` +
    `</li>`
  )).join('');
}

// `slots`: whatever src/save/saveGame.js's listSaveSlots() resolved to —
// [{id, name, savedAt, seedInput}, ...].
export function showSlotPicker(pickerMode, slots) {
  mode = pickerMode;
  const panel = document.getElementById('slot-picker');
  if (panel) panel.classList.remove('hidden');

  const title = document.getElementById('slot-picker-title');
  if (title) title.textContent = mode === 'save' ? 'Save Game' : 'Load Game';

  const saveRow = document.getElementById('slot-picker-save-row');
  if (saveRow) saveRow.classList.toggle('hidden', mode !== 'save');

  const nameInput = document.getElementById('slot-name-input');
  if (nameInput) nameInput.value = '';

  renderSlotList(slots);
}

export function hideSlotPicker() {
  const panel = document.getElementById('slot-picker');
  if (panel) panel.classList.add('hidden');
}
