// Keyboard and mouse state.
//
// This module owns raw input only. Actions that would need game logic (what a
// click does) are passed in as handlers by main.js, which keeps input.js free
// of imports from the systems that read it.

import { isLocked } from './pointerLock.js';
import { HOTBAR_SIZE, selectSlot, getSelectedSlot } from '../inventory.js';
import { player } from '../player/state.js';
import { getGameMode } from '../gameMode.js';
import { toggleDebug, showLabel } from '../ui/hud.js';
import { isInventoryOpen } from '../ui/inventoryScreen.js';
import { toggleConsole, isConsoleOpen } from '../ui/devConsole.js';
import { isDevConsoleEnabled } from '../devConsoleSetting.js';

// Keyed by KeyboardEvent.code, e.g. keys['KeyW'], keys['Space'].
export const keys = {};

export const mouse = { leftHeld: false, rightHeld: false };

// While a full-screen panel is up, movement keys stop registering — otherwise
// typing or dragging in the inventory walks you off a cliff.
let suspended = false;

export function setInputSuspended(next) {
  suspended = next;
  if (suspended) clearKeys();
}

let mouseDX = 0, mouseDY = 0;

// Returns the mouse movement since the last call and resets the accumulator.
export function consumeMouseDelta() {
  const d = { dx: mouseDX, dy: mouseDY };
  mouseDX = 0; mouseDY = 0;
  return d;
}

// Shift = sprint, Ctrl = crouch (Minecraft bindings). Both sides accepted.
export function isSprintHeld() { return !!(keys['ShiftLeft']   || keys['ShiftRight']); }
export function isCrouchHeld() { return !!(keys['ControlLeft'] || keys['ControlRight']); }

const DOUBLE_TAP_MS = 300;

export function initInput({ onLeftClick, onRightClick, onToggleInventory, onToggleVehicle, onToggleHyperspeed }) {
  document.addEventListener('keydown', e => {
    // Backtick toggles the dev console regardless of lock or suspension state
    // — but only OPENING it is gated by devConsoleSetting.js; closing an
    // already-open one always works, same as Escape always being able to
    // close the inventory regardless of anything else.
    if (e.key === '`') {
      e.preventDefault();
      if (!isConsoleOpen() && !isDevConsoleEnabled()) { showLabel('Dev console is disabled'); return; }
      toggleConsole();
      return;
    }

    // While the console is open, all other game keys are silenced — the
    // console's own input element handles keydown via stopPropagation (capture
    // phase) for keys that reach it, but non-character keys like Escape and
    // digit keys bubble here first, so we guard them too.
    if (isConsoleOpen()) return;

    // E and F still work while suspended, so you can close the panel again.
    if (!suspended) keys[e.code] = true;
    // Crouch-walking means holding Ctrl+W/A/S/D — swallow the browser's own
    // Ctrl shortcuts while playing so they don't fire mid-game.
    if (e.ctrlKey && isLocked()) e.preventDefault();

    if (e.code.startsWith('Digit')) {
      const n = parseInt(e.code.replace('Digit', '')) - 1;
      if (n >= 0 && n < HOTBAR_SIZE) selectSlot(n);
    }
    if (e.code === 'Space') {
      // Double-tap space toggles creative flight.
      const now = performance.now();
      if (now - player.lastJump < DOUBLE_TAP_MS && getGameMode() === 'creative') {
        player.flying = !player.flying;
        player.vel.set(0, 0, 0);
        player.fallStartY = null;   // reset fall tracking; physicsStep recomputes it fresh next tick
      }
      player.lastJump = now;
    }
    if (e.code === 'F3') toggleDebug();
    // Not repeated while held down — these are toggles.
    if (e.code === 'KeyE' && !e.repeat) onToggleInventory();
    if (e.code === 'KeyF' && !e.repeat) onToggleVehicle();
    // Hyperspeed is a toggle (lock on once, cruise, disengage once), not a
    // held button — same reasoning as E/F above, and it's a no-op call
    // whenever nothing is piloted or the held craft has no hyperspeed drive
    // (vehicles/rocket.js's own toggleHyperspeed handles that, the same way
    // onToggleVehicle already handles "not holding a vehicle").
    if (e.code === 'KeyH' && !e.repeat) onToggleHyperspeed();
    // Escape does exactly what E does, and nothing more, whenever the
    // inventory is open — no special Escape-only handling here at all. If
    // it's already closed, this falls through to do nothing: the browser's
    // own Escape-exits-pointer-lock behaviour (while actually playing) is
    // what reveals the pause overlay, via the pointerlockchange listener in
    // ui/overlay.js.
    if (e.code === 'Escape' && !e.repeat && isInventoryOpen()) onToggleInventory();
  });

  document.addEventListener('keyup', e => { keys[e.code] = false; });

  document.addEventListener('mousemove', e => {
    if (!isLocked()) return;
    mouseDX += e.movementX;
    mouseDY += e.movementY;
  });

  document.addEventListener('wheel', e => {
    if (!isLocked()) return;
    const dir = e.deltaY > 0 ? 1 : -1;
    selectSlot((getSelectedSlot() + dir + HOTBAR_SIZE) % HOTBAR_SIZE);
  }, { passive: true });

  document.addEventListener('mousedown', e => {
    if (!isLocked()) return;
    if (e.button === 0) { mouse.leftHeld  = true; onLeftClick(); }
    if (e.button === 2) { mouse.rightHeld = true; onRightClick(); }
  });

  document.addEventListener('mouseup', e => {
    if (e.button === 0) mouse.leftHeld  = false;
    if (e.button === 2) mouse.rightHeld = false;
  });

  document.addEventListener('contextmenu', e => e.preventDefault());

  // Losing the lock must clear held buttons, or the player keeps firing after
  // tabbing away.
  document.addEventListener('pointerlockchange', () => {
    if (!isLocked()) { mouse.leftHeld = false; mouse.rightHeld = false; }
  });
}

// Clears all held keys — used when the player dies so movement doesn't resume
// on respawn from a key that was held during the death.
export function clearKeys() {
  for (const code of Object.keys(keys)) keys[code] = false;
}
