// Trigger handling: cooldowns, ammo, and turning a shot into rays or shells.

import * as THREE from 'three';
import { camera } from '../core/scene.js';
import { mouse } from '../core/input.js';
import { player } from '../player/state.js';
import { raycastWeapon } from '../player/raycast.js';
import { getSelectedItem, consumeSelected } from '../inventory.js';
import { hitMob } from '../entities/mobs.js';
import { sendHit } from '../net/client.js';
import { triggerFire } from '../player/viewmodel.js';
import { scaleOutgoing } from '../difficulty.js';
import { WEAPON_TYPES, zoneDamage } from './types.js';
import { spawnTracer, spawnPlayerProjectile, spawnHeadshotFX } from './effects.js';

let weaponCooldown = 0;

function fireHitscan(wd) {
  const camDir = new THREE.Vector3();
  camera.getWorldDirection(camDir);
  const origin = camera.position.clone();

  for (let i = 0; i < wd.pellets; i++) {
    const dir = camDir.clone();
    if (wd.spread > 0) {
      dir.x += (Math.random() - 0.5) * wd.spread;
      dir.y += (Math.random() - 0.5) * wd.spread;
      dir.z += (Math.random() - 0.5) * wd.spread;
      dir.normalize();
    }
    const result = raycastWeapon(dir, wd.range);
    const dmg = zoneDamage(wd.damage, result.zone);
    if (result.mob) hitMob(result.mob, dmg);
    else if (result.playerId !== null) sendHit(result.playerId, scaleOutgoing(dmg));
    if (result.zone === 'head' && (result.mob || result.playerId !== null)) {
      spawnHeadshotFX(result.hitPoint);
    }
    spawnTracer(origin, dir, result.dist, wd.color);
  }
}

function fireProjectileWeapon(wd) {
  const dir = new THREE.Vector3();
  camera.getWorldDirection(dir);
  // Spawn ahead of the camera so the shell doesn't detonate on the player.
  const origin = camera.position.clone().addScaledVector(dir, 0.7);
  spawnPlayerProjectile(wd, origin, dir);
}

// One shot from the selected weapon, if it's off cooldown. Spends one round.
export function fireWeapon() {
  const item = getSelectedItem();
  if (!item || item.kind !== 'weapon' || weaponCooldown > 0) return;

  const wd = WEAPON_TYPES[item.weaponKey];
  weaponCooldown = 1 / wd.fireRate;
  consumeSelected();
  triggerFire();

  if (wd.kind === 'hitscan') fireHitscan(wd);
  else fireProjectileWeapon(wd);
}

// Keeps automatic weapons firing while the left button is held.
export function updateWeaponFiring(dt) {
  weaponCooldown = Math.max(0, weaponCooldown - dt);
  if (!mouse.leftHeld || player.dead) return;
  const item = getSelectedItem();
  if (!item || item.kind !== 'weapon') return;
  if (WEAPON_TYPES[item.weaponKey].auto && weaponCooldown <= 0) fireWeapon();
}
