// Player damage, death, and the timers behind the red damage flash.

import { player } from './state.js';
import { isCreative } from '../gameMode.js';
import { updateHpBar, setDamageFlash } from '../ui/hud.js';
import { showDeathScreen } from '../ui/overlay.js';
import { sendDied } from '../net/client.js';
import { scaleIncoming } from '../difficulty.js';
import { deathMessage } from '../deathMessages.js';

const FLASH_TIME      = 0.35;  // seconds of red screen after a hit
const INVINCIBLE_TIME = 0.6;   // seconds before the player can be hit again

// `dmg` is the raw amount; the deeper into a run you are, the more of it
// lands. Applied here so every source — mobs, other players, explosions,
// falls — escalates together.
//
// `source` describes what's hitting you, e.g. { kind: 'fall' },
// { kind: 'mob', mobType: 'ghoul' } or { kind: 'player', id, name } — kept
// entirely separate from `player.lastAttacker`, which stays a bare network
// id (or null) because that's specifically what sendDied's PvP kill credit
// needs on the wire. `source` only ever drives the death-screen message.
export function hurtPlayer(dmg, source = null) {
  if (isCreative()) return;
  if (player.invincible > 0 || player.dead) return;
  if (source) {
    player.lastDamageSource = source;
    if (source.kind === 'player' && source.id != null) player.lastAttacker = source.id;
  }
  player.hp = Math.max(0, player.hp - scaleIncoming(dmg));
  player.damageFlash = FLASH_TIME;
  player.invincible  = INVINCIBLE_TIME;
  updateHpBar(player.hp, player.maxHp);
  if (player.hp <= 0) killPlayer();
}

export function healPlayer(amount) {
  player.hp = Math.min(player.maxHp, player.hp + amount);
  updateHpBar(player.hp, player.maxHp);
}

export function killPlayer() {
  player.dead = true;
  document.exitPointerLock();
  showDeathScreen(deathMessage(player.lastDamageSource));
  // Naming the killer lets their client award itself the points.
  sendDied(player.lastAttacker);   // no-op when offline
  player.lastAttacker = null;
  player.lastDamageSource = null;
}

// Ticks the flash/invincibility timers. Uses a fixed step rather than dt to
// match the original behaviour; at 60fps they're the same thing.
export function updateDamageTimers() {
  player.damageFlash = Math.max(0, player.damageFlash - 0.016);
  player.invincible  = Math.max(0, player.invincible  - 0.016);
  setDamageFlash(player.damageFlash > 0 ? (player.damageFlash / FLASH_TIME) * 0.5 : 0);
}
