// Raw voxel storage and queries. No three.js, no DOM — this module is pure
// data, which is what makes the physics testable outside a browser.
//
// Chunks are Uint8Array columns of CHUNK_SIZE x CHUNK_HEIGHT x CHUNK_SIZE,
// keyed by "chunkX,chunkZ". Writes here do NOT rebuild meshes — world/
// spaceSession.js and world/planetStreaming.js own that, calling back into
// render/planetMesher.js after a write.
//
// getBlock is one of the hottest functions in the game — meshing, physics,
// raycasts and mob grounding all bottom out here — so it avoids allocating
// (no key string on the common path) and memoises the last chunk it
// touched, since callers almost always walk within one chunk.
//
// createVoxelStore() is a factory: every planet gets its own six per-face
// instances (world/planetTerrain.js), each with its own independent chunk
// map and its own chunk height (planets are far smaller than the home
// body's own crust — see CLAUDE.md's "Storage, terrain and the mesher").

import { CHUNK_SIZE, CHUNK_HEIGHT, CHUNK_SHIFT, CHUNK_MASK } from '../config.js';
import { AIR, STONE, LEAVES, isLiquidBlock } from './blocks.js';

export function chunkKey(cx, cz) { return cx + ',' + cz; }

export function createVoxelStore({ chunkHeight = CHUNK_HEIGHT } = {}) {
  const chunks = new Map();
  const storeBlockIndex = (lx, y, lz) => lx + CHUNK_SIZE * (y + chunkHeight * lz);

  // Memo for the last chunk looked up, invalidated whenever the map changes.
  let memoCx = 0x7fffffff, memoCz = 0x7fffffff, memoChunk;

  function invalidateMemo() { memoCx = 0x7fffffff; memoCz = 0x7fffffff; memoChunk = undefined; }

  function getChunk(cx, cz) {
    if (cx === memoCx && cz === memoCz) return memoChunk;
    memoChunk = chunks.get(chunkKey(cx, cz));
    memoCx = cx; memoCz = cz;
    return memoChunk;
  }

  // All chunk map mutations go through these so the memo can't go stale.
  function setChunk(cx, cz, data) {
    chunks.set(chunkKey(cx, cz), data);
    invalidateMemo();
  }

  function deleteChunk(key) {
    chunks.delete(key);
    invalidateMemo();
  }

  function clearChunks() {
    chunks.clear();
    invalidateMemo();
  }

  function hasChunk(cx, cz) { return chunks.has(chunkKey(cx, cz)); }

  // Ungenerated chunks read as STONE so the player can never fall through the
  // edge of the loaded world while terrain streams in.
  function getBlock(wx, wy, wz) {
    if (wy < 0) return STONE;
    if (wy >= chunkHeight) return AIR;
    const chunk = getChunk(wx >> CHUNK_SHIFT, wz >> CHUNK_SHIFT);
    if (chunk === undefined) return STONE;
    return chunk[(wx & CHUNK_MASK) + CHUNK_SIZE * (wy + chunkHeight * (wz & CHUNK_MASK))];
  }

  // Writes one voxel without touching meshes. Returns the chunk/local coords
  // so callers can batch mesh rebuilds, or null if the chunk isn't loaded.
  function writeBlockRaw(wx, wy, wz, id) {
    if (wy < 0 || wy >= chunkHeight) return null;
    const cx = wx >> CHUNK_SHIFT, cz = wz >> CHUNK_SHIFT;
    const chunk = getChunk(cx, cz);
    if (chunk === undefined) return null;
    const lx = wx & CHUNK_MASK, lz = wz & CHUNK_MASK;
    chunk[storeBlockIndex(lx, wy, lz)] = id;
    return { cx, cz, lx, lz };
  }

  // Accepts fractional world coordinates — floors them itself.
  function isSolid(wx, wy, wz) {
    const id = getBlock(Math.floor(wx), Math.floor(wy), Math.floor(wz));
    return id !== AIR && !isLiquidBlock(id) && id !== LEAVES;
  }

  // Y of the highest non-air block in a column, used to drop mobs and
  // pickups onto the ground. Reads the column array directly rather than
  // going through getBlock once per height.
  function surfaceAt(wx, wz) {
    const chunk = getChunk(Math.floor(wx) >> CHUNK_SHIFT, Math.floor(wz) >> CHUNK_SHIFT);
    if (chunk === undefined) return chunkHeight - 1;
    const lx = Math.floor(wx) & CHUNK_MASK, lz = Math.floor(wz) & CHUNK_MASK;
    const base = lx + CHUNK_SIZE * chunkHeight * lz;
    for (let y = chunkHeight - 1; y > 0; y--) {
      if (chunk[base + CHUNK_SIZE * y] !== AIR) return y;
    }
    return 0;
  }

  return {
    chunkHeight,
    chunks,
    getChunk, setChunk, deleteChunk, clearChunks, hasChunk,
    getBlock, writeBlockRaw, isSolid, surfaceAt,
    blockIndex: storeBlockIndex,
  };
}
