// Everything weapons spawn into the world: bullet tracers, rockets/nukes in
// flight, and explosions (damage + crater + visual).

import * as THREE from 'three';
import { worldIsSolid } from '../world/activeWorld.js';
import { spaceCarveCrater } from '../world/spaceSession.js';
import { scene, camera } from '../core/scene.js';
import { player } from '../player/state.js';
import { hurtPlayer } from '../player/health.js';
import { whiteFlash } from '../ui/hud.js';
import { mobs, hitMob } from '../entities/mobs.js';
import { spawnBurst } from '../entities/deathFx.js';
import { remotePlayerTargets } from '../net/remotePlayers.js';
import { sendHit, sendCrater } from '../net/client.js';
import { scaleOutgoing } from '../difficulty.js';

const TRACER_LIFE    = 0.07;
const EXPLOSION_LIFE = 0.45;
const HEADSHOT_LIFE  = 0.4;

const tracers           = [];
const playerProjectiles = [];
const explosionFX       = [];
const headshotFX        = [];

// ── Tracers ──────────────────────────────────────────────

export function spawnTracer(origin, dir, dist, color) {
  const end = origin.clone().addScaledVector(dir, dist);
  const geo = new THREE.BufferGeometry().setFromPoints([origin, end]);
  const mat = new THREE.LineBasicMaterial({ color: color || 0xffff99, transparent: true, opacity: 0.9 });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  tracers.push({ line, life: TRACER_LIFE, maxLife: TRACER_LIFE });
}

export function updateTracers(dt) {
  for (let i = tracers.length - 1; i >= 0; i--) {
    const t = tracers[i];
    t.life -= dt;
    if (t.life <= 0) {
      scene.remove(t.line);
      t.line.geometry.dispose();
      tracers.splice(i, 1);
      continue;
    }
    t.line.material.opacity = (t.life / t.maxLife) * 0.9;
  }
}

// ── Headshot celebration ─────────────────────────────────
//
// A little gold/white/red bullseye that pops out from the hit point and
// fades, plus a scatter of gold sparks reusing the same particle system mob
// deaths use rather than inventing a second one. Billboarded to the camera
// every frame — RingGeometry lies flat, and this needs to read as a target
// however the player is looking at it, not just from directly in front.

const RING_COLORS = [0xffe066, 0xffffff, 0xff3b3b];   // gold, white, red rings

export function spawnHeadshotFX(point) {
  const group = new THREE.Group();
  group.position.copy(point);
  for (let i = 0; i < RING_COLORS.length; i++) {
    const geo = new THREE.RingGeometry(0.07 + i * 0.05, 0.10 + i * 0.05, 20);
    const mat = new THREE.MeshBasicMaterial({
      color: RING_COLORS[i], transparent: true, opacity: 0.95,
      side: THREE.DoubleSide, depthWrite: false, depthTest: false,
    });
    group.add(new THREE.Mesh(geo, mat));
  }
  scene.add(group);
  headshotFX.push({ group, life: HEADSHOT_LIFE, maxLife: HEADSHOT_LIFE });

  spawnBurst(point, {
    color: 0xffe066, count: 10, speed: 2.6, upBias: 2, size: 0.09,
    life: 0.45, gravityScale: 0.5,
  });
}

export function updateHeadshotFX(dt) {
  for (let i = headshotFX.length - 1; i >= 0; i--) {
    const h = headshotFX[i];
    h.life -= dt;
    if (h.life <= 0) {
      scene.remove(h.group);
      for (const m of h.group.children) { m.geometry.dispose(); m.material.dispose(); }
      headshotFX.splice(i, 1);
      continue;
    }
    const t = 1 - h.life / h.maxLife;
    h.group.quaternion.copy(camera.quaternion);
    h.group.scale.setScalar(1 + t * 4.5);
    for (const m of h.group.children) m.material.opacity = 0.95 * (1 - t);
  }
}

// ── Player projectiles ───────────────────────────────────

function buildPlayerProjectileMesh(wd) {
  const isNuke = wd.glow;
  const geo = isNuke
    ? new THREE.SphereGeometry(0.35, 10, 8)
    : new THREE.CylinderGeometry(0.09, 0.09, 0.55, 8);
  const mat = new THREE.MeshLambertMaterial({
    color: wd.color,
    emissive: isNuke ? 0xccff66 : 0x552200,
    emissiveIntensity: isNuke ? 0.9 : 0.4,
  });
  // No PointLight here on purpose: adding one mid-flight makes three.js
  // recompile every lit material in the scene, which stutters exactly when a
  // rocket is in the air. The emissive material carries the glow instead.
  return new THREE.Mesh(geo, mat);
}

export function spawnPlayerProjectile(wd, origin, dir) {
  const mesh = buildPlayerProjectileMesh(wd);
  mesh.position.copy(origin);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(mesh);

  playerProjectiles.push({
    wd, mesh,
    pos:  origin.clone(),
    vel:  dir.clone().multiplyScalar(wd.speed),
    life: wd.range / wd.speed,
  });
}

export function updatePlayerProjectiles(dt) {
  for (let i = playerProjectiles.length - 1; i >= 0; i--) {
    const p = playerProjectiles[i];
    p.life -= dt;
    p.pos.addScaledVector(p.vel, dt);
    p.mesh.position.copy(p.pos);

    let exploded = p.life <= 0 || worldIsSolid(p.pos.x, p.pos.y, p.pos.z);
    if (!exploded) {
      for (const mob of mobs) {
        if (mob.dead) continue;
        if (p.pos.distanceTo(mob.pos) < 1.0) { exploded = true; break; }
      }
    }

    if (exploded) {
      explode(p.pos.clone(), p.wd);
      scene.remove(p.mesh);
      playerProjectiles.splice(i, 1);
    }
  }
}

// ── Explosions ───────────────────────────────────────────

// Damage falls off linearly to zero at blastRadius. The player is not immune
// to their own blast.
export function explode(center, wd) {
  for (const mob of mobs) {
    if (mob.dead) continue;
    const d = mob.pos.distanceTo(center);
    if (d < wd.blastRadius) {
      hitMob(mob, Math.round(wd.blastDamage * (1 - d / wd.blastRadius)));
    }
  }

  const pd = player.pos.distanceTo(center);
  if (pd < wd.blastRadius) {
    hurtPlayer(Math.round(wd.blastDamage * (1 - pd / wd.blastRadius)), { kind: 'explosion' });
  }

  // Everyone else in the blast takes damage too, and every client carves the
  // same crater so the world stays in step.
  for (const target of remotePlayerTargets()) {
    const d = target.pos.distanceTo(center);
    if (d < wd.blastRadius) {
      sendHit(target.id, scaleOutgoing(Math.round(wd.blastDamage * (1 - d / wd.blastRadius))));
    }
  }
  sendCrater(center.x, center.y, center.z, wd.craterRadius);

  spaceCarveCrater(center, wd.craterRadius);
  spawnExplosionVFX(center, wd);
}

function spawnExplosionVFX(center, wd) {
  const color = wd.glow ? 0xffee88 : 0xff8844;
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(1, 14, 10),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.85 })
  );
  mesh.position.copy(center);
  mesh.scale.setScalar(0.3);
  scene.add(mesh);
  explosionFX.push({ mesh, life: EXPLOSION_LIFE, maxLife: EXPLOSION_LIFE, maxScale: wd.blastRadius * 1.1 });

  if (wd.glow) whiteFlash();
}

export function updateExplosionFX(dt) {
  for (let i = explosionFX.length - 1; i >= 0; i--) {
    const fx = explosionFX[i];
    fx.life -= dt;
    if (fx.life <= 0) {
      scene.remove(fx.mesh);
      fx.mesh.geometry.dispose();
      fx.mesh.material.dispose();
      explosionFX.splice(i, 1);
      continue;
    }
    const t = 1 - fx.life / fx.maxLife;
    fx.mesh.scale.setScalar(0.3 + t * fx.maxScale);
    fx.mesh.material.opacity = 0.85 * (1 - t);
  }
}

export function clearWeaponEffects() {
  for (const t of tracers) { scene.remove(t.line); t.line.geometry.dispose(); }
  tracers.length = 0;
  for (const p of playerProjectiles) scene.remove(p.mesh);
  playerProjectiles.length = 0;
  for (const fx of explosionFX) { scene.remove(fx.mesh); fx.mesh.geometry.dispose(); }
  explosionFX.length = 0;
  for (const h of headshotFX) {
    scene.remove(h.group);
    for (const m of h.group.children) { m.geometry.dispose(); m.material.dispose(); }
  }
  headshotFX.length = 0;
}
