// Health bars floating above mobs.
//
// A bar only appears once something has actually hurt the mob — an untouched
// world shouldn't be cluttered with full green bars over everything wandering
// about.
//
// Each bar is two sprites: a shared dark backing and a coloured fill. Sprites
// always face the camera, and setting `center` to the left edge means the fill
// can be scaled from 0..1 without also having to slide it along.
//
// The fill needs its own material per mob to carry its own colour, but they're
// all SpriteMaterial with identical settings, so three reuses one shader
// program for the lot — no recompiles.

import * as THREE from 'three';
import { scene } from '../core/scene.js';
import { healthColorHex } from '../ui/healthColor.js';

const BAR_WIDTH  = 0.9;
const BAR_HEIGHT = 0.12;
const HOVER      = 0.34;   // how far above the head the bar floats

const backingMaterial = new THREE.SpriteMaterial({ color: 0x11131a, depthTest: true });

export function attachHealthBar(entity) {
  if (entity.healthBar) return entity.healthBar;

  const backing = new THREE.Sprite(backingMaterial);
  backing.scale.set(BAR_WIDTH, BAR_HEIGHT, 1);

  const fillMaterial = new THREE.SpriteMaterial({ color: 0x4ccf5a, depthTest: true });
  const fill = new THREE.Sprite(fillMaterial);
  fill.center.set(0, 0.5);                  // grow from the left edge
  fill.scale.set(BAR_WIDTH * 0.94, BAR_HEIGHT * 0.66, 1);

  scene.add(backing);
  scene.add(fill);
  entity.healthBar = { backing, fill, fillMaterial };
  return entity.healthBar;
}

export function updateHealthBar(entity, height) {
  const bar = entity.healthBar;
  if (!bar) return;

  const fraction = Math.max(0, Math.min(1, entity.hp / entity.maxHp));
  const y = entity.pos.y + height + HOVER;

  bar.backing.position.set(entity.pos.x, y, entity.pos.z);
  bar.fill.position.set(entity.pos.x - BAR_WIDTH * 0.47, y, entity.pos.z);
  bar.fill.scale.x = Math.max(0.0001, BAR_WIDTH * 0.94 * fraction);
  bar.fillMaterial.color.setHex(healthColorHex(fraction));
}

export function removeHealthBar(entity) {
  const bar = entity.healthBar;
  if (!bar) return;
  scene.remove(bar.backing);
  scene.remove(bar.fill);
  bar.fillMaterial.dispose();
  entity.healthBar = null;
}
