// Procedural terrain for a cubed-sphere planet: a heightmap sampled over
// each face's own tangent (u, v) plane, exactly the same "sample a scalar
// field, fill a column" shape terrain.js already uses for Earth — with one
// substitution: "height" is measured as radial distance from the planet's
// own center (like a store index counting outward from a per-planet
// baseline) instead of a fixed world Y.
//
// This file itself stays a thin column-fill loop, the same relationship
// world/earthTerrain.js has to world/biomes.js: every real biome-variety
// decision — which theme a planet is, how canyons/basins/craters shape its
// surface, what its ore tiers are, what its flora looks like — lives in
// world/alienBiomes.js instead. createPlanet() builds the descriptor and
// its 6 per-face voxel stores (one createVoxelStore() instance each — see
// store.js); generatePlanetChunk() fills exactly one chunk on one face —
// world/planetStreaming.js calls it progressively, based on player
// proximity, the same way world/world.js calls Earth's own generateChunk().
// Nothing here touches Earth's own terrain.js, noise cache or store
// instance at all.

import { CHUNK_SIZE, CHUNK_HEIGHT } from '../config.js';
import { AIR } from './blocks.js';
import { createVoxelStore } from './store.js';
import { makeNoise, hash32 } from './noise.js';
import { FACE_IDS } from './cubeSphere.js';
import { themeFor, alienSurfaceRadiusAt, alienOreAt } from './alienBiomes.js';

// Re-exported for backward compatibility — world/starSystem.js (and
// anything else that used to import the hash helper from here) still
// imports it from this file; it actually lives in noise.js now, alongside
// faceHash, so world/alienBiomes.js can use it too without depending on
// this file (which itself now depends on alienBiomes.js).
export { hash32 };

// A planet only needs a HANDFUL of chunks per face to already feel like a
// small, walkable world (see CLAUDE.md's Space environment section on why
// planets are deliberately small) — 3x3 chunks per face is a comfortable
// default: enough room to walk a full face. Streaming (world/
// planetStreaming.js) is what makes a much larger chunkSpan affordable too.
export const DEFAULT_CHUNK_SPAN = 3;

// Builds a planet descriptor and its 6 empty (ungenerated) per-face stores.
// `radius` is the mean surface radius; `amplitude` is how far terrain can
// rise/dip around it. coreRadius is chosen so that baseline sits at the
// middle of the store's own column, leaving equal headroom for hills and
// for craters — the same "amplitude has to fit under the ceiling" reasoning
// terrain.js's MOUNTAINS_AMP-vs-CHUNK_HEIGHT comment describes for Earth.
// This same "middle of the column" choice is also exactly a theme's own
// liquid level (world/alienBiomes.js's flood rule reads it straight off
// `planet.radius - planet.coreRadius`), so a themed lake always sits at the
// planet's own nominal surface radius, the same contract Earth's own
// SEA_LEVEL keeps (see CLAUDE.md's "Storage, terrain and the mesher").
export function createPlanet({
  center, radius, amplitude = 6, chunkSpan = DEFAULT_CHUNK_SPAN,
  chunkHeight = CHUNK_HEIGHT, seed = 1, craterCount = 2, coreRadius,
}) {
  const halfExtent = (chunkSpan * CHUNK_SIZE) / 2;
  // Defaults to centring the column on `radius`, which is exactly right
  // for THIS file's own alien generator (a SYMMETRIC amplitude either side
  // of radius). world/earthTerrain.js's real generator is asymmetric
  // instead (SEA_LEVEL sits low within the column, with far more headroom
  // above for mountains than below for basins/canyons — see biomes.js), so
  // world/spaceSession.js passes an explicit `coreRadius` for the home body
  // specifically, picked so a flat, sea-level column's own surface lands
  // exactly at `radius` — the same "planet.radius genuinely means where
  // the surface is" contract every OTHER consumer (spawn placement,
  // atmosphere margins, gravity range, a theme's own liquid level) already
  // assumes.
  if (coreRadius === undefined) coreRadius = radius - Math.floor(chunkHeight / 2);
  const faces = {};
  for (const faceId of FACE_IDS) faces[faceId] = createVoxelStore({ chunkHeight });

  return {
    center: center.clone(), radius, amplitude, coreRadius,
    halfExtent, chunkSpan, chunkHeight, seed, craterCount,
    faces, _noise: null, _oreNoise: null, _craters: null, _theme: null,
    // Defaults to this file's own alien generator, so a planet built
    // directly via createPlanet() (any test, or future code, that doesn't
    // go through world/spaceSession.js's initSpaceSession()) is already
    // usable without extra wiring. spaceSession.js overrides this for the
    // home body specifically (world/earthTerrain.js's real generator) —
    // see that module's own comment.
    generateChunk: generatePlanetChunk,
  };
}

function ensureNoise(planet) {
  if (planet._noise) return planet._noise;
  planet._noise = makeNoise(planet.seed >>> 0);
  return planet._noise;
}

// A second field, so ore veins don't line up with the surface they sit
// under — the exact reasoning and the exact seed offset (`^ 0x5eed`)
// terrain.js's/earthTerrain.js's own ensureOreNoise() uses.
function ensureOreNoise(planet) {
  if (planet._oreNoise) return planet._oreNoise;
  planet._oreNoise = makeNoise((planet.seed ^ 0x5eed) >>> 0);
  return planet._oreNoise;
}

// Fills chunk (cx, cv) of `faceId` — the exact tangent-plane analogue of
// terrain.js's generateChunk(cx, cz): (u, v) here plays the role (wx, wz)
// plays there, and the store's own r-index plays the role y plays there,
// right down to reusing store.js's "index < 0 reads as solid, index >=
// chunkHeight reads as air" rule for free (createPlanet's coreRadius is
// exactly what makes that rule land in the right place for THIS planet).
export function generatePlanetChunk(planet, faceId, cx, cv) {
  const store = planet.faces[faceId];
  const noise = ensureNoise(planet);
  const oreNoise = ensureOreNoise(planet);
  const theme = themeFor(planet);
  const data = new Uint8Array(CHUNK_SIZE * planet.chunkHeight * CHUNK_SIZE);
  const u0 = cx * CHUNK_SIZE - planet.halfExtent;
  const v0 = cv * CHUNK_SIZE - planet.halfExtent;
  // A flat, undisturbed column's surface sits exactly at planet.radius by
  // construction (see createPlanet's own comment) — this is the level a
  // theme's own liquid floods up to, the direct generalisation of
  // Earth's own fixed SEA_LEVEL.
  const liquidLevelIndex = Math.round(planet.radius - planet.coreRadius);

  for (let lu = 0; lu < CHUNK_SIZE; lu++) {
    for (let lv = 0; lv < CHUNK_SIZE; lv++) {
      const u = u0 + lu, v = v0 + lv;
      const surfaceRadius = alienSurfaceRadiusAt(planet, faceId, noise, u, v);
      const surfaceIndex = Math.round(surfaceRadius - planet.coreRadius);
      const topIndex = Math.min(planet.chunkHeight - 1, Math.max(surfaceIndex, liquidLevelIndex));

      for (let ri = 0; ri <= topIndex; ri++) {
        let id = AIR;
        if (ri < surfaceIndex - 4) id = alienOreAt(theme, oreNoise, u, ri, v, planet.chunkHeight);
        else if (ri < surfaceIndex) id = theme.rock;
        else if (ri === surfaceIndex) id = theme.surface;
        else if (theme.liquid !== null && ri <= liquidLevelIndex && ri > surfaceIndex) id = theme.liquid;
        data[store.blockIndex(lu, ri, lv)] = id;
      }

      // Flora, only on dry land — a column whose surface sits at or below
      // the liquid level is underwater (or would be, on a themed body with
      // no liquid at all, simply low ground), same "not underwater" gate
      // earthTerrain.js's own tree placement uses.
      if (theme.flora && surfaceIndex > liquidLevelIndex) {
        theme.flora(data, store, planet, lu, lv, surfaceIndex, noise, u, v);
      }
    }
  }

  store.setChunk(cx, cv, data);
}

// Fills every chunk on every face — a convenience for anything that wants
// a FULLY generated planet up front rather than the progressive, proximity-
// driven generation world/planetStreaming.js does for the live game (a
// physics test exercising a whole walk/flight in isolation, a future
// debug/creative tool, etc.). The live space session itself no longer
// calls this — see world/planetStreaming.js's own module comment for why
// eager whole-planet generation stopped being affordable once planets
// could get bigger and more numerous.
export function generatePlanet(planet) {
  for (const faceId of FACE_IDS) {
    for (let cx = 0; cx < planet.chunkSpan; cx++) {
      for (let cv = 0; cv < planet.chunkSpan; cv++) {
        generatePlanetChunk(planet, faceId, cx, cv);
      }
    }
  }
}
