// Aiming down a scope: narrows the camera's field of view, adds a small
// sway so a headshot still takes some skill rather than being a free
// pixel-perfect zoom, and shows a scope overlay in place of the crosshair.
// Only a weapon flagged `scoped` in weapons/types.js (the sniper) supports
// this at all — holding right-click with anything else selected does
// nothing here, same as it always has for a weapon (see actions.js's
// `placeBlock`, which already no-ops for any item.kind === 'weapon').

import { DEFAULT_FOV, SCOPE_FOV, SCOPE_SWAY } from '../config.js';
import { camera } from '../core/scene.js';
import { mouse } from '../core/input.js';
import { getSelectedItem } from '../inventory.js';
import { player } from '../player/state.js';
import { WEAPON_TYPES } from './types.js';
import { setScopeOverlay } from '../ui/hud.js';

const FOV_LERP_RATE = 14;   // per second; a quick but not instant zoom

let scoped = false;

export function isScoped() { return scoped; }

// A small, organic wobble — two summed sine waves at different rates each
// axis, rather than one, so it doesn't read as a metronome. Computed fresh
// every call rather than accumulated, so releasing right-click steadies the
// view immediately and completely rather than easing out of a build-up.
export function scopeSway() {
  if (!scoped) return { yaw: 0, pitch: 0 };
  const t = performance.now() * 0.001;
  return {
    yaw:   (Math.sin(t * 1.3) + Math.sin(t * 2.7) * 0.5) * SCOPE_SWAY,
    pitch: (Math.sin(t * 1.7) + Math.sin(t * 3.1) * 0.5) * SCOPE_SWAY,
  };
}

export function updateScope(dt) {
  const item = getSelectedItem();
  const wd = item && item.kind === 'weapon' ? WEAPON_TYPES[item.weaponKey] : null;
  const wantsScope = !player.dead && !!(wd && wd.scoped) && mouse.rightHeld;
  if (wantsScope !== scoped) {
    scoped = wantsScope;
    setScopeOverlay(scoped);
  }

  const targetFov = scoped ? SCOPE_FOV : DEFAULT_FOV;
  if (camera.fov !== targetFov) {
    const next = camera.fov + (targetFov - camera.fov) * Math.min(1, FOV_LERP_RATE * dt);
    camera.fov = Math.abs(next - targetFov) < 0.01 ? targetFov : next;
    camera.updateProjectionMatrix();
  }
}

// Used on respawn and by tests — resets the module's own state without
// waiting for updateScope() to notice the mouse and selection have changed.
export function clearScope() {
  scoped = false;
  camera.fov = DEFAULT_FOV;
  camera.updateProjectionMatrix();
  setScopeOverlay(false);
}
