// The local player's name and look, persisted between sessions.
//
// Appearance is four colour choices which get baked into the humanoid model
// other players see. Keeping it to swatches means the whole profile is four
// small integers on the wire.

const STORAGE_KEY = 'blocksProfile';

export const SWATCHES = {
  shirt: [
    { name: 'Crimson',   hex: 0xc0392b },
    { name: 'Ocean',     hex: 0x1f6fb2 },
    { name: 'Forest',    hex: 0x2e8b2e },
    { name: 'Violet',    hex: 0x7d3cb5 },
    { name: 'Sunflower', hex: 0xe0a91b },
    { name: 'Slate',     hex: 0x40484f },
  ],
  shorts: [
    { name: 'Denim',   hex: 0x2c4a7c },
    { name: 'Khaki',   hex: 0xb5a878 },
    { name: 'Charcoal',hex: 0x2b2b2b },
    { name: 'Rust',    hex: 0x9c4a1e },
    { name: 'White',   hex: 0xf0f0f0 },
    { name: 'Emerald', hex: 0x1f7a55 },
  ],
  skin: [
    { name: 'Porcelain', hex: 0xf6d5bd },
    { name: 'Sand',      hex: 0xe8b98c },
    { name: 'Honey',     hex: 0xc98d5a },
    { name: 'Umber',     hex: 0x8d5a35 },
    { name: 'Cocoa',     hex: 0x5c3722 },
    { name: 'Ebony',     hex: 0x3b2417 },
  ],
  hair: [
    { name: 'Black',    hex: 0x161616 },
    { name: 'Brown',    hex: 0x4a2800 },
    { name: 'Blonde',   hex: 0xd8b45a },
    { name: 'Ginger',   hex: 0xb5501a },
    { name: 'Silver',   hex: 0xc8c8c8 },
    { name: 'Bubblegum',hex: 0xe563a8 },
  ],
};

export const APPEARANCE_PARTS = Object.keys(SWATCHES);

const DEFAULT_PROFILE = {
  name: '',
  shirt: 0,
  shorts: 0,
  skin: 0,
  hair: 1,
};

let profile = { ...DEFAULT_PROFILE };

export function getProfile() { return profile; }

// Clamps every index so a hand-edited or out-of-date saved profile can't
// produce an undefined colour.
export function sanitiseProfile(p) {
  const out = { ...DEFAULT_PROFILE, ...(p || {}) };
  for (const part of APPEARANCE_PARTS) {
    const n = Number(out[part]);
    out[part] = Number.isInteger(n) && n >= 0 && n < SWATCHES[part].length ? n : 0;
  }
  out.name = String(out.name || '').slice(0, 20);
  return out;
}

export function setProfile(next) {
  profile = sanitiseProfile(next);
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(profile)); } catch { /* private mode */ }
  return profile;
}

export function initProfile() {
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); } catch { /* ignore */ }
  profile = sanitiseProfile(saved);
  if (!profile.name) profile.name = 'Player ' + Math.floor(100 + Math.random() * 900);
  return profile;
}

// The subset that goes over the wire — just the swatch indices.
export function appearanceOf(p = profile) {
  return { shirt: p.shirt, shorts: p.shorts, skin: p.skin, hair: p.hair };
}

// Turns swatch indices into the colour map the humanoid mesh builder wants.
export function appearanceColors(appearance) {
  const a = sanitiseProfile(appearance);
  return {
    shirt:   SWATCHES.shirt[a.shirt].hex,
    shorts:  SWATCHES.shorts[a.shorts].hex,
    skin:    SWATCHES.skin[a.skin].hex,
    hair:    SWATCHES.hair[a.hair].hex,
    boots:   0x2a2a2a,
    glasses: 0x222222,
  };
}
