// Everything you're carrying.
//
// One flat array of slots: 0..HOTBAR_SIZE-1 are the hotbar you can select from
// while playing, the rest are the backpack you only see on the inventory
// screen. Keeping it flat means drag-and-drop between the two is just a move
// between two indices, with no special cases.
//
// A slot holds either null, a block stack { id, kind:'block', count }, a weapon
// { id, kind:'weapon', weaponKey, count } where count is ammo, or a vehicle
// { id, kind:'vehicle', vehicleKey, count }.
//
// UI updates go one way: this module tells ui/hotbar what to draw.

import { HOTBAR_SIZE, BACKPACK_ROWS } from './config.js';
import { BLOCK_NAMES } from './world/blocks.js';
import { WEAPON_TYPES } from './weapons/types.js';
import { VEHICLE_TYPES } from './vehicles/types.js';
import { refreshHotbar, setActiveSlot } from './ui/hotbar.js';
import { showLabel } from './ui/hud.js';

export { HOTBAR_SIZE };

export const BACKPACK_SIZE = HOTBAR_SIZE * BACKPACK_ROWS;
export const SLOT_COUNT = HOTBAR_SIZE + BACKPACK_SIZE;

// Index 0..HOTBAR_SIZE-1 is the hotbar; the rest is the backpack.
export const slots = Array(SLOT_COUNT).fill(null);

// Kept for readability at call sites that only care about the hotbar; it's the
// same array, and ui/hotbar only ever reads the first HOTBAR_SIZE entries.
export const inventory = slots;

let selectedSlot = 0;
const changeListeners = [];

export function onInventoryChange(fn) { changeListeners.push(fn); }

function changed() {
  refreshHotbar(slots);
  for (const fn of changeListeners) fn();
}

export function getSelectedSlot() { return selectedSlot; }
export function getSelectedItem() { return slots[selectedSlot]; }

export function selectSlot(n) {
  selectedSlot = n;
  setActiveSlot(n);
  const item = slots[n];
  if (item) showLabel(itemLabel(item));
}

export function itemLabel(item) {
  if (!item) return '';
  if (item.kind === 'weapon')  return WEAPON_TYPES[item.weaponKey].label + ' (' + item.count + ')';
  if (item.kind === 'vehicle') return VEHICLE_TYPES[item.vehicleKey].label;
  return BLOCK_NAMES[item.id] + (item.count > 1 ? ' x' + item.count : '');
}

// True when two stacks are the same thing and can merge.
export function sameItem(a, b) {
  if (!a || !b || a.kind !== b.kind) return false;
  if (a.kind === 'weapon')  return a.weaponKey === b.weaponKey;
  if (a.kind === 'vehicle') return false;      // vehicles never stack
  return a.id === b.id;
}

// Stacks onto an existing pile first, then takes the first free slot — hotbar
// before backpack, so what you pick up is to hand.
export function addToInventory(id, count = 1) {
  for (let i = 0; i < SLOT_COUNT; i++) {
    const s = slots[i];
    if (s && s.kind === 'block' && s.id === id) {
      s.count += count;
      changed();
      return true;
    }
  }
  for (let i = 0; i < SLOT_COUNT; i++) {
    if (!slots[i]) {
      slots[i] = { id, kind: 'block', count };
      changed();
      return true;
    }
  }
  return false;   // nowhere to put it
}

export function addItem(item) {
  for (let i = 0; i < SLOT_COUNT; i++) {
    if (!slots[i]) {
      slots[i] = item;
      changed();
      return true;
    }
  }
  return false;
}

// Picking up a weapon you already hold tops up its ammo instead of taking a
// second slot.
export function pickUpWeapon(weaponKey) {
  const wd = WEAPON_TYPES[weaponKey];
  for (let i = 0; i < SLOT_COUNT; i++) {
    const it = slots[i];
    if (it && it.kind === 'weapon' && it.weaponKey === weaponKey) {
      it.count += wd.ammo;
      changed();
      showLabel('+' + wd.ammo + ' ' + wd.label + ' ammo');
      return;
    }
  }
  if (addItem({ id: wd.id, kind: 'weapon', weaponKey, count: wd.ammo })) {
    showLabel('Picked up ' + wd.label + '!');
  } else {
    showLabel('Inventory full!');
  }
}

// Spends one block / one round from the selected slot, clearing it when empty.
export function consumeSelected() {
  const item = slots[selectedSlot];
  if (!item) return;
  item.count--;
  if (item.count <= 0) slots[selectedSlot] = null;
  changed();
}

export function clearInventory() {
  for (let i = 0; i < SLOT_COUNT; i++) slots[i] = null;
  changed();
}

// How many of a block you're carrying, across every slot.
export function countMaterial(id) {
  let total = 0;
  for (const s of slots) if (s && s.kind === 'block' && s.id === id) total += s.count;
  return total;
}

// Removes `count` of a block from wherever it is. Returns false and changes
// nothing if you don't have enough.
export function takeMaterial(id, count) {
  if (countMaterial(id) < count) return false;
  let left = count;
  for (let i = 0; i < SLOT_COUNT && left > 0; i++) {
    const s = slots[i];
    if (!s || s.kind !== 'block' || s.id !== id) continue;
    const taken = Math.min(left, s.count);
    s.count -= taken;
    left -= taken;
    if (s.count <= 0) slots[i] = null;
  }
  changed();
  return true;
}

// Drag-and-drop: merge onto the target if they're the same thing, otherwise
// swap. Used by the inventory screen for both the backpack and the hotbar,
// which is the whole reason the slots are one flat array.
export function moveSlot(from, to) {
  if (from === to) return;
  if (from < 0 || to < 0 || from >= SLOT_COUNT || to >= SLOT_COUNT) return;
  const src = slots[from];
  if (!src) return;

  const dst = slots[to];
  if (dst && sameItem(src, dst)) {
    dst.count += src.count;
    slots[from] = null;
  } else {
    slots[to] = src;
    slots[from] = dst || null;
  }
  changed();
}

// Notify listeners without changing anything — used after external mutations.
export function refreshInventory() { changed(); }
