// Guns lying around the world, plus the drops mobs leave behind.
//
// The world's own random ground-level spawner (placing pistols by a flat
// column lookup) was retired along with flat Earth — it has no meaning on
// a curved planet and was never essential to the loop (see CLAUDE.md's
// Non-goals). Every pickup that exists now comes from spawnGunPickupAt,
// called with a real position — mob drops (entities/mobs.js).

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { scene } from '../core/scene.js';
import { player } from '../player/state.js';
import { pickUpWeapon } from '../inventory.js';
import { WEAPON_TYPES } from '../weapons/types.js';

const PICKUP_RADIUS      = 1.4;

export const gunPickups = [];

// Built once per weapon type and shared by every pickup of that type: one
// merged geometry, one material, one draw call.
//
// These used to carry a PointLight. Lights are expensive here for a subtler
// reason than shading cost: three.js keys shader programs partly on the scene's
// light count, so every pickup spawning or being collected invalidated and
// recompiled the program for every lit material in the scene. The emissive
// material alone still reads as "glowing".
const pickupCache = new Map();

function gunPickupTemplate(weaponKey) {
  let cached = pickupCache.get(weaponKey);
  if (cached) return cached;

  const wd = WEAPON_TYPES[weaponKey];
  const parts = [
    new THREE.BoxGeometry(0.5, 0.22, 0.16),
    new THREE.BoxGeometry(0.35, 0.09, 0.09).translate(0.32, 0.02, 0),
    new THREE.BoxGeometry(0.1, 0.22, 0.14).translate(-0.14, -0.18, 0),
  ];
  const geometry = mergeGeometries(parts, false);
  for (const p of parts) p.dispose();

  const material = new THREE.MeshLambertMaterial({
    color: wd.color,
    emissive: wd.glow ? wd.color : 0x000000,
    emissiveIntensity: wd.glow ? 0.9 : 0,
  });

  cached = { geometry, material };
  pickupCache.set(weaponKey, cached);
  return cached;
}

function buildGunPickupMesh(weaponKey) {
  const { geometry, material } = gunPickupTemplate(weaponKey);
  return new THREE.Mesh(geometry, material);
}

// Drops a gun at an exact point — used for mob drops, which should land where
// the mob died rather than on the surface far below.
export function spawnGunPickupAt(weaponKey, position) {
  const mesh = buildGunPickupMesh(weaponKey);
  const pos  = position.clone();
  mesh.position.copy(pos);
  scene.add(mesh);
  gunPickups.push({ weaponKey, mesh, pos, spin: Math.random() * Math.PI * 2 });
}

export function clearGunPickups() {
  for (const p of gunPickups) scene.remove(p.mesh);
  gunPickups.length = 0;
}

export function updateGunPickups(dt) {
  for (let i = gunPickups.length - 1; i >= 0; i--) {
    const p = gunPickups[i];
    p.spin += dt * 1.6;
    p.mesh.rotation.y = p.spin;
    p.mesh.position.y = p.pos.y + Math.sin(performance.now() * 0.002 + i) * 0.12;

    if (!player.dead && p.pos.distanceTo(player.pos) < PICKUP_RADIUS) {
      pickUpWeapon(p.weaponKey);
      scene.remove(p.mesh);
      gunPickups.splice(i, 1);
    }
  }
}
