// Health pickups dropped by dying mobs.
//
// Killing something no longer heals you outright — it scatters hearts you have
// to walk over, so you have to break off and collect them.

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { worldIsSolid } from '../world/activeWorld.js';
import { gravityAt } from '../world/gravity.js';
import { scene } from '../core/scene.js';
import { player } from '../player/state.js';
import { healPlayer } from '../player/health.js';

export const HEART_HEAL = 8;          // hp restored per heart
const PICKUP_RADIUS = 1.3;
const LIFETIME      = 45;             // seconds before an uncollected heart fades
const MAX_HEARTS    = 60;
const COLLECT_DELAY = 0.4;            // stops them being hoovered up mid-burst

export const hearts = [];

// A chunky pixel-art heart, so it reads at a glance and matches the blocky
// look. Built once and shared by every heart in the world.
const HEART_ROWS = [
  '.XX.XX.',
  'XXXXXXX',
  'XXXXXXX',
  '.XXXXX.',
  '..XXX..',
  '...X...',
];
const PIXEL = 0.075;

let heartGeometry = null;
const heartMaterial = new THREE.MeshLambertMaterial({
  color: 0xff3355, emissive: 0x551119, emissiveIntensity: 0.6,
});

function getHeartGeometry() {
  if (heartGeometry) return heartGeometry;
  const cubes = [];
  const rows = HEART_ROWS.length, cols = HEART_ROWS[0].length;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (HEART_ROWS[r][c] !== 'X') continue;
      const g = new THREE.BoxGeometry(PIXEL, PIXEL, PIXEL * 0.6);
      g.translate((c - (cols - 1) / 2) * PIXEL, ((rows - 1) / 2 - r) * PIXEL, 0);
      cubes.push(g);
    }
  }
  heartGeometry = mergeGeometries(cubes, false);
  for (const g of cubes) g.dispose();
  return heartGeometry;
}

// Hearts pop out of the corpse and tumble to the ground.
export function spawnHeart(origin, spreadSpeed = 3.5) {
  if (hearts.length >= MAX_HEARTS) {
    const oldest = hearts.shift();
    scene.remove(oldest.mesh);
  }
  const mesh = new THREE.Mesh(getHeartGeometry(), heartMaterial);
  mesh.position.copy(origin);
  scene.add(mesh);

  const angle = Math.random() * Math.PI * 2;
  const speed = spreadSpeed * (0.4 + Math.random() * 0.8);
  hearts.push({
    mesh,
    pos: origin.clone(),
    vel: new THREE.Vector3(Math.cos(angle) * speed, 4 + Math.random() * 2.5, Math.sin(angle) * speed),
    life: LIFETIME,
    age: 0,
    resting: false,
    spin: Math.random() * Math.PI * 2,
  });
}

export function updateHearts(dt) {
  for (let i = hearts.length - 1; i >= 0; i--) {
    const h = hearts[i];
    h.life -= dt;
    h.age  += dt;

    if (!h.resting) {
      // "Below" is along whatever gravity points away from here, not
      // always -Y — same generalisation player/physics.js's spaceWalkStep
      // makes. No exact floor-snap on landing (that needs the real local
      // surface radius, not worth it for a decorative pickup) — a heart
      // just stops wherever it was the moment it touched something.
      const g = gravityAt(h.pos);
      h.vel.addScaledVector(g.dir, g.g * dt);
      h.pos.addScaledVector(h.vel, dt);
      if (worldIsSolid(h.pos.x + g.dir.x * 0.15, h.pos.y + g.dir.y * 0.15, h.pos.z + g.dir.z * 0.15)) {
        h.vel.set(0, 0, 0);
        h.resting = true;
      } else if (worldIsSolid(h.pos.x, h.pos.y, h.pos.z)) {
        h.vel.set(0, 0, 0);
      }
    }

    h.spin += dt * 2.2;
    h.mesh.rotation.y = h.spin;
    h.mesh.position.set(h.pos.x, h.pos.y + Math.sin(h.age * 3) * 0.08, h.pos.z);

    // Only worth picking up if it'll actually heal something.
    const collectable = h.age > COLLECT_DELAY && !player.dead && player.hp < player.maxHp;
    if (collectable && h.pos.distanceTo(player.pos) < PICKUP_RADIUS) {
      healPlayer(HEART_HEAL);
      scene.remove(h.mesh);
      hearts.splice(i, 1);
      continue;
    }

    if (h.life <= 0) {
      scene.remove(h.mesh);
      hearts.splice(i, 1);
    }
  }
}

export function clearHearts() {
  for (const h of hearts) scene.remove(h.mesh);
  hearts.length = 0;
}
