// The click-to-play overlay, its settings panel, and the death screen.
// Game logic is injected as handlers so this stays a pure view module.

import { requestLock, isLocked } from '../core/pointerLock.js';
import { isInventoryOpen } from './inventoryScreen.js';
import { syncMenuHudVisibility } from './hud.js';
import {
  GRAPHICS_PRESETS, POTATO, NEXT_LEVEL, onGraphicsChange, getGraphics,
} from '../settings.js';
// randomWorldSeed() is a pure, side-effect-free string generator — no
// different from importing a constant out of settings.js — so pulling it in
// directly here doesn't cross the "UI never imports game logic" line the way
// actually applying a seed (setWorldSeed / regenerating the world) would.
// That part stays behind the injected onWorldSeedApply handler below.
import { randomWorldSeed } from '../worldSeed.js';

// Whether a game is actually running (New Game or Load Game has been
// clicked, and Quit to Title hasn't been clicked since) — main.js's own
// hasActiveGame, mirrored here via setGameActive() rather than passed into
// every syncOverlayVisibility() call site, the same "small piece of local
// UI state" shape settings.js's own `current` preset already uses. While
// false, #title-screen owns the view (ui/titleScreen.js) and #overlay
// never shows at all — which is also what keeps the Multiplayer panel
// inside #overlay's own settings section unreachable before a game exists,
// with no separate gating needed for that specifically.
let gameActive = false;
export function setGameActive(active) {
  gameActive = active;
  syncOverlayVisibility();
}

// Shown whenever a game is active AND the player isn't actually playing —
// which means neither locked in NOR looking at the inventory. Without the
// second half, opening the inventory (which has to release pointer lock to
// get a free cursor) would leave this sitting visible the whole time
// underneath the inventory panel's own higher z-index, and closing the
// inventory again would instantly reveal it. If closing the inventory
// doesn't immediately re-acquire the lock (pointer lock can fail or lag for
// reasons outside this game's control — the PLAY button hits the exact same
// thing on a plain click), this shows, same as it does the first time;
// clicking it again tries again, exactly like clicking PLAY again does.
// That's deliberately ALL this does — an earlier version tried to paper
// over a failed re-lock with retry timers and other machinery, which added
// real complexity without actually fixing anything, since the underlying
// flakiness isn't this code's to fix.
// Exported so main.js's toggleInventory() can re-evaluate this the moment
// the inventory opens or closes, rather than waiting on a pointerlockchange
// event that may be delayed (or, while opening the inventory, never fire a
// second time at all).
export function syncOverlayVisibility() {
  const overlay = document.getElementById('overlay');
  if (overlay) overlay.classList.toggle('hidden', !gameActive || isLocked() || isInventoryOpen());
  syncMenuHudVisibility();
}

// The loading screen shown from page load (and again after regenerating the
// world) until main.js's own worldReady flag flips — see its own comment on
// why waiting for world/planetStreaming.js's pendingPlanetChunkWork() to
// reach zero, rather than just showing #overlay immediately, is what fixes
// the "walk three metres and the rest of the world hasn't loaded yet" bug.
// Sits above #overlay (higher z-index, index.html) so Play can't be reached
// underneath it while shown.
// `status` overrides the default "Loading terrain…" message — main.js's own
// graphics-preset switch (a synchronous chunk remesh with no real progress
// of its own to report) uses this so the screen reads as what's actually
// happening rather than a lie about streaming terrain.
export function showLoadingScreen(status) {
  const el = document.getElementById('loading-screen');
  if (el) el.classList.remove('hidden');
  setLoadingProgress(0);
  const statusEl = document.getElementById('loading-status');
  if (statusEl) statusEl.textContent = status || 'Loading terrain…';
  syncMenuHudVisibility();
}

export function hideLoadingScreen() {
  const el = document.getElementById('loading-screen');
  if (el) el.classList.add('hidden');
  syncMenuHudVisibility();
}

export function setLoadingProgress(fraction) {
  const fill = document.getElementById('loading-bar-fill');
  if (fill) fill.style.width = `${Math.round(Math.max(0, Math.min(1, fraction)) * 100)}%`;
}

export function initOverlay({
  onSelectMode, onRespawn, onSelectGraphics, onDifficulty, onToggleSpawnEscalation,
  onRenderDistance, onDayLength, onWorldSeedApply, onSaveGame, onQuitToTitle, onToggleDevConsole,
}) {
  const overlay = document.getElementById('overlay');
  if (overlay) {
    overlay.addEventListener('click', () => requestLock());
    document.addEventListener('pointerlockchange', syncOverlayVisibility);
  }

  // Clicks inside the settings panel must not bubble to the overlay, which
  // would grab pointer lock and start the game.
  const settings = document.getElementById('settings-section');
  if (settings) settings.addEventListener('click', e => e.stopPropagation());

  const survivalBtn = document.getElementById('mode-survival');
  const creativeBtn = document.getElementById('mode-creative');
  if (survivalBtn) survivalBtn.addEventListener('click', () => onSelectMode('survival'));
  if (creativeBtn) creativeBtn.addEventListener('click', () => onSelectMode('creative'));

  const potatoBtn = document.getElementById('gfx-potato');
  const nextBtn   = document.getElementById('gfx-nextlevel');
  if (potatoBtn) potatoBtn.addEventListener('click', () => onSelectGraphics(POTATO));
  if (nextBtn)   nextBtn.addEventListener('click', () => onSelectGraphics(NEXT_LEVEL));

  onGraphicsChange(renderGraphicsUI);
  renderGraphicsUI(getGraphics());

  const slider = document.getElementById('difficulty-slider');
  if (slider) {
    slider.addEventListener('input', () => onDifficulty(Number(slider.value)));
    // The overlay grabs pointer lock on click; the slider must not trigger it.
    slider.addEventListener('click', e => e.stopPropagation());
  }

  const spawnBtn = document.getElementById('spawn-escalation');
  if (spawnBtn) spawnBtn.addEventListener('click', () => onToggleSpawnEscalation());

  const devConsoleBtn = document.getElementById('dev-console-toggle');
  if (devConsoleBtn) devConsoleBtn.addEventListener('click', () => onToggleDevConsole());

  const renderSlider = document.getElementById('render-distance-slider');
  if (renderSlider) {
    renderSlider.addEventListener('input', () => onRenderDistance(Number(renderSlider.value)));
    renderSlider.addEventListener('click', e => e.stopPropagation());
  }

  const dayLengthSlider = document.getElementById('day-length-slider');
  if (dayLengthSlider) {
    dayLengthSlider.addEventListener('input', () => onDayLength(Number(dayLengthSlider.value)));
    dayLengthSlider.addEventListener('click', e => e.stopPropagation());
  }

  const seedInput  = document.getElementById('world-seed-input');
  const seedRandom = document.getElementById('world-seed-random');
  const seedApply  = document.getElementById('world-seed-apply');
  if (seedInput) {
    seedInput.addEventListener('click', e => e.stopPropagation());
    // Enter applies the same as clicking the button, same as a form submit.
    seedInput.addEventListener('keydown', e => {
      if (e.key === 'Enter') onWorldSeedApply(seedInput.value);
    });
  }
  if (seedRandom) {
    seedRandom.addEventListener('click', () => {
      // Only fills the field — it doesn't regenerate anything on its own.
      // Regenerating the world throws away chunks, mobs and pickups, so
      // that only ever happens from the explicit "Generate New World" click.
      if (seedInput) seedInput.value = randomWorldSeed();
    });
  }
  if (seedApply) {
    seedApply.addEventListener('click', () => onWorldSeedApply(seedInput ? seedInput.value : ''));
  }

  const respawnBtn = document.getElementById('respawn-btn');
  if (respawnBtn) respawnBtn.addEventListener('click', () => onRespawn());

  // Both live directly in #overlay-box, outside #settings-section, so —
  // like every other clickable thing out there — a plain click would
  // otherwise also bubble up to the overlay's own "click anywhere resumes"
  // handler above.
  const saveBtn = document.getElementById('save-game-btn');
  if (saveBtn) saveBtn.addEventListener('click', e => { e.stopPropagation(); onSaveGame(); });

  const quitBtn = document.getElementById('quit-to-title-btn');
  if (quitBtn) quitBtn.addEventListener('click', e => { e.stopPropagation(); onQuitToTitle(); });
}

// `pointsPerKill` and `killsToPeak` are worked out by the caller so this stays
// a view: it explains the current setting in the game's own terms rather than
// making the player interpret a bare number.
export function renderDifficultyUI({ slider, escalatingSpawns, pointsPerKill, killsToPeak }) {
  const input = document.getElementById('difficulty-slider');
  if (input && Number(input.value) !== slider) input.value = String(slider);
  const value = document.getElementById('difficulty-value');
  if (value) value.textContent = String(slider);

  const desc = document.getElementById('difficulty-desc');
  if (desc) {
    desc.textContent =
      `Score climbs ${pointsPerKill}x faster and the game turns hostile in about ` +
      `${killsToPeak} kills. Higher means you take more damage and deal less, sooner.`;
  }

  const btn = document.getElementById('spawn-escalation');
  if (btn) {
    btn.textContent = 'Escalating spawns: ' + (escalatingSpawns ? 'On' : 'Off');
    btn.classList.toggle('active', escalatingSpawns);
  }
  const spawnDesc = document.getElementById('spawn-desc');
  if (spawnDesc) {
    spawnDesc.textContent = escalatingSpawns
      ? 'More mobs, spawning faster and closer, as your score climbs.'
      : 'Mob spawning stays at its opening rate no matter how high you score.';
  }
}

// `enabled`/`local` can differ while a room's own policy is in effect
// (devConsoleSetting.js's multiplayer override) — the button always shows
// the value that's ACTUALLY in force right now, with the description
// explaining why that might not match what's about to be clicked.
export function renderDevConsoleUI({ enabled, local, overridden }) {
  const btn = document.getElementById('dev-console-toggle');
  if (btn) {
    btn.textContent = 'Dev console: ' + (enabled ? 'Enabled' : 'Disabled');
    btn.classList.toggle('active', enabled);
  }
  const desc = document.getElementById('dev-console-desc');
  if (desc) {
    desc.textContent = overridden
      ? `Enforced ${enabled ? 'enabled' : 'disabled'} by the host while connected — your own ` +
        `preference (${local ? 'enabled' : 'disabled'}) applies again once you disconnect.`
      : (enabled
        ? 'The ` key opens it, in solo play and while hosting or joining multiplayer alike. ' +
          'Whoever joins a room first sets this for everyone connected.'
        : 'Nobody — including you — can open it right now. Disabling it before hosting or ' +
          'joining multiplayer is what keeps connected players honest.');
  }
}

// `blocks` is worked out by the caller, same reasoning as renderDifficultyUI —
// "8 chunks" means little, "128 blocks out" is what a player can picture.
export function renderRenderDistanceUI({ dist, blocks }) {
  const input = document.getElementById('render-distance-slider');
  if (input && Number(input.value) !== dist) input.value = String(dist);
  const value = document.getElementById('render-distance-value');
  if (value) value.textContent = String(dist);

  const desc = document.getElementById('render-distance-desc');
  if (desc) {
    desc.textContent =
      `${blocks} blocks out. Higher looks better from further away but costs FPS — ` +
      `push it as far as your machine is happy with (F3 shows your frame rate).`;
  }
}

export function renderDayLengthUI({ minutes }) {
  const input = document.getElementById('day-length-slider');
  if (input && Number(input.value) !== minutes) input.value = String(minutes);
  const value = document.getElementById('day-length-value');
  if (value) value.textContent = String(minutes);

  const desc = document.getElementById('day-length-desc');
  if (desc) {
    desc.textContent = `Day lasts ${minutes} minute${minutes === 1 ? '' : 's'}, ` +
      `then night lasts the same. Mobs only spawn after dark.`;
  }
}

// `seed` is the numeric value terrain.js actually builds its noise from;
// `input` is the raw text the player typed (or '' for the default world).
export function renderWorldSeedUI({ seed, input }) {
  const field = document.getElementById('world-seed-input');
  // Only overwrite what's typed if it doesn't already match — this fires
  // after every regeneration (including the very first one at startup), and
  // stomping the field mid-keystroke would fight the player's own typing the
  // same way the render-distance slider guards against re-snapping itself.
  if (field && field.value !== input && document.activeElement !== field) field.value = input;

  const desc = document.getElementById('world-seed-desc');
  if (desc) {
    desc.textContent = input
      ? `Seed "${input}" (${seed}). Click "Generate New World" after typing a new one — ` +
        `it rebuilds the world from scratch, so anything on the ground stays behind.`
      : `The default world — leave this blank to always get the one the game ships with. ` +
        `Playing with friends? Everyone needs to type the exact same seed.`;
  }
}

export function renderGraphicsUI(preset) {
  const potatoBtn = document.getElementById('gfx-potato');
  const nextBtn   = document.getElementById('gfx-nextlevel');
  if (potatoBtn) potatoBtn.classList.toggle('active', preset === POTATO);
  if (nextBtn)   nextBtn.classList.toggle('active', preset === NEXT_LEVEL);
  const desc = document.getElementById('gfx-desc');
  if (desc) desc.textContent = GRAPHICS_PRESETS[preset].blurb;
}

export function renderModeUI(mode) {
  const survBtn = document.getElementById('mode-survival');
  const creaBtn = document.getElementById('mode-creative');
  if (survBtn) survBtn.classList.toggle('active', mode === 'survival');
  if (creaBtn) creaBtn.classList.toggle('active', mode === 'creative');
  const desc = document.getElementById('mode-desc');
  if (desc) {
    desc.textContent = mode === 'creative'
      ? 'Fly freely, no damage, no health bar.'
      : 'No flying. Take damage from enemies and falls.';
  }
}

export function showDeathScreen(message) {
  const el = document.getElementById('death-screen');
  if (el) el.classList.remove('hidden');
  const cause = document.getElementById('death-cause');
  if (cause && message) cause.textContent = message;
}

export function hideDeathScreen() {
  const el = document.getElementById('death-screen');
  if (el) el.classList.add('hidden');
}
