// Flying the things you build.
//
// An arcade flight model, not a simulator — the aim is that a jet feels fast
// and a hangglider feels like it's barely holding on, and that both are fun
// within a few seconds of taking off.
//
//   W / S    throttle up and down
//   A / D    rudder (yaw)
//   mouse    roll (left/right) and pitch (up/down)
//   click    fire whatever weapon is in your hand
//   F        get in / get out
//
// While you're flying, `player.pos` tracks the craft, so mobs still see you,
// multiplayer still broadcasts you, and getting out drops you where you are.
//
// Gravity-aware the same way vehicles/rocket.js already is (that file's own
// module comment describes the exact substitution: gravityAt() instead of
// a literal world -Y constant, alignQuaternionFor for the look-direction
// resync on dismount) — this file predates the rocket and was never
// ported, which was a latent bug even before the merge (mounting a plane
// while in space would have queried the flat Earth store directly, either
// crashing at mount or flying through everything, depending on what
// happened to be loaded there) and would affect EVERY flight now that the
// sphere is the only world there is.

import * as THREE from 'three';
import { scene, camera } from '../core/scene.js';
import { keys, consumeMouseDelta } from '../core/input.js';
import { player } from '../player/state.js';
import { hurtPlayer } from '../player/health.js';
import { showLabel } from '../ui/hud.js';
import { getSelectedItem } from '../inventory.js';
import { gravityAt } from '../world/gravity.js';
import { alignQuaternionFor } from '../world/sphericalMotion.js';
import { worldIsSolid, worldChunkLoaded } from '../world/activeWorld.js';
import { VEHICLE_TYPES } from './types.js';
import { buildVehicleMesh } from './models.js';

const MOUSE_ROLL  = 0.0022;
const MOUSE_PITCH = 0.0018;
const THROTTLE_RATE = 0.9;      // per second, full range in ~1.1s
const CHASE_UP = 2.4;   // how far above; the distance back is per-vehicle
// Hitting terrain above this speed hurts and throws you out.
const CRASH_SPEED = 18;

let active = null;      // { key, def, mesh }
const orientation = new THREE.Quaternion();
const velocity = new THREE.Vector3();
let throttle = 0;

// Scratch, reused every frame.
const forward = new THREE.Vector3();
const up = new THREE.Vector3();
const right = new THREE.Vector3();
const spin = new THREE.Quaternion();
const axis = new THREE.Vector3();
const chase = new THREE.Vector3();
const glideTarget = new THREE.Vector3();
const gravityDir = new THREE.Vector3();
const alignQuat = new THREE.Quaternion();
const invAlignQuat = new THREE.Quaternion();
const localForward = new THREE.Vector3();

export function isFlying() { return active !== null; }
export function activeVehicle() { return active; }
export function getThrottle() { return throttle; }
export function getAirspeed() { return velocity.length(); }

// Mounts whatever vehicle is in the selected hotbar slot.
export function mountVehicle() {
  const item = getSelectedItem();
  if (!item || item.kind !== 'vehicle') {
    showLabel('Hold a vehicle to board it');
    return false;
  }
  const def = VEHICLE_TYPES[item.vehicleKey];
  if (!def) return false;
  if (def.mode === 'boat') {
    showLabel(def.label + ' needs water, not sky');
    return false;
  }

  const mesh = buildVehicleMesh(item.vehicleKey);
  scene.add(mesh);
  active = { key: item.vehicleKey, def, mesh };

  // Start level, facing where the player was looking, a little above the
  // ground so a hangglider doesn't scrape off immediately. player.yaw is
  // stored relative to the local gravity-aligned frame (player/physics.js,
  // player/view.js), so "level" here means bending that frame's own
  // nominal up onto wherever gravity here actually points away from —
  // vehicles/rocket.js's own mountRocket() composes orientation the same
  // way; on flat ground (alignQuat = identity) this reduces to exactly
  // flight.js's own original formula.
  const g0 = gravityAt(player.pos);
  alignQuaternionFor(g0.dir, alignQuat);
  orientation.copy(alignQuat).multiply(new THREE.Quaternion().setFromEuler(new THREE.Euler(0, player.yaw, 0, 'YXZ')));
  // A launch shove, the way you'd run off a slope with a glider — without it
  // an unpowered craft has no airspeed and simply drops.
  velocity.set(0, 0, -1).applyQuaternion(orientation).multiplyScalar(def.thrust > 0 ? 4 : 11);
  throttle = def.thrust > 0 ? 0.5 : 0;
  up.copy(g0.dir).negate();
  player.pos.addScaledVector(up, 1.2);
  player.piloting = true;
  showLabel(def.label + ' — W/S throttle, A/D rudder, mouse to fly, F to land');
  return true;
}

export function dismountVehicle(reason = '') {
  if (!active) return;
  scene.remove(active.mesh);
  active = null;
  player.piloting = false;
  player.vel.set(0, 0, 0);
  if (reason) showLabel(reason);
}

export function toggleVehicle() {
  if (active) dismountVehicle('Landed');
  else mountVehicle();
}

// Turns the craft by `angle` about one of its own axes, so controls stay
// relative to the pilot however far over you're rolled.
function rotateLocal(localAxis, angle) {
  if (!angle) return;
  axis.copy(localAxis).applyQuaternion(orientation).normalize();
  spin.setFromAxisAngle(axis, angle);
  orientation.premultiply(spin);
  orientation.normalize();
}

const X_AXIS = new THREE.Vector3(1, 0, 0);
const Y_AXIS = new THREE.Vector3(0, 1, 0);
const Z_AXIS = new THREE.Vector3(0, 0, 1);

export function updateFlight(dt) {
  if (!active) return;
  const def = active.def;

  // ── Input ──
  const { dx, dy } = consumeMouseDelta();
  const speed = velocity.length();
  // Below stall speed the surfaces stop biting and the craft goes vague.
  const authority = def.stallSpeed > 0
    ? Math.max(0.25, Math.min(1, speed / def.stallSpeed))
    : 1;

  rotateLocal(Z_AXIS, -dx * MOUSE_ROLL * def.rollRate * authority);
  rotateLocal(X_AXIS, -dy * MOUSE_PITCH * def.pitchRate * authority);

  let yaw = 0;
  if (keys['KeyA']) yaw += 1;
  if (keys['KeyD']) yaw -= 1;
  rotateLocal(Y_AXIS, yaw * def.yawRate * dt * authority);

  if (def.thrust > 0) {
    if (keys['KeyW']) throttle = Math.min(1, throttle + THROTTLE_RATE * dt);
    if (keys['KeyS']) throttle = Math.max(0, throttle - THROTTLE_RATE * dt);
  }

  // ── Forces ──
  forward.set(0, 0, -1).applyQuaternion(orientation);
  up.set(0, 1, 0).applyQuaternion(orientation);
  right.set(1, 0, 0).applyQuaternion(orientation);

  if (def.thrust > 0) {
    velocity.addScaledVector(forward, def.thrust * throttle * dt);
    // A jetpack pushes against gravity as well as forward, which is what makes
    // it a hover rather than a plane.
    // Has to out-push gravity or it is not a hover, it is a slow fall.
    if (def.hover) velocity.addScaledVector(up, def.thrust * throttle * 1.5 * dt);
  }

  const g = gravityAt(player.pos);
  gravityDir.copy(g.dir);
  velocity.addScaledVector(gravityDir, g.g * dt);

  // The wing redirects: whatever speed you have gets bent towards where the
  // nose points. This is what makes a glider work — pitch down, gravity builds
  // speed, the wing turns that speed into forward motion, and forward motion
  // becomes lift. Without it an unpowered craft just drops like a brick.
  const speedNow = velocity.length();
  if (speedNow > 0.01) {
    const grip = 1 - Math.exp(-def.grip * dt);
    glideTarget.copy(forward).multiplyScalar(speedNow);
    velocity.lerp(glideTarget, grip);
  }

  // Lift: the faster you're going forward, the more of gravity the wing
  // cancels. g.g is already the positive magnitude equivalent of the old
  // literal "-GRAVITY" (GRAVITY itself is a negative constant, config.js)
  // — no extra negation needed on top of it.
  const forwardSpeed = Math.max(0, velocity.dot(forward));
  const liftFraction = Math.min(1, forwardSpeed / Math.max(1, def.maxSpeed * 0.55));
  velocity.addScaledVector(up, g.g * def.lift * liftFraction * dt);

  // Stalled and unpowered craft sink rather than hanging in the air.
  if (forwardSpeed < def.stallSpeed) velocity.addScaledVector(gravityDir, def.sink * dt * 0.5);

  // Drag, and a cap so nothing runs away with itself.
  velocity.multiplyScalar(Math.max(0, 1 - def.drag * dt));
  if (velocity.length() > def.maxSpeed) velocity.setLength(def.maxSpeed);

  // ── Move, and hit things ──
  const stepX = player.pos.x + velocity.x * dt;
  const stepY = player.pos.y + velocity.y * dt;
  const stepZ = player.pos.z + velocity.z * dt;

  // Ungenerated terrain reads as solid (both Earth's store and a planet's
  // own — see store.js's own comment) so the player can't fall out of a
  // world that hasn't streamed in yet — but a fast plane can outrun that
  // streaming, and crashing into terrain that simply hasn't loaded is no
  // fun. Only collide where the world actually exists — worldChunkLoaded
  // is the environment-agnostic version of flight.js's own original
  // hasChunk gate (world/activeWorld.js dispatches to whichever world is
  // active). Unlike vehicles/rocket.js, this can't skip the check: a
  // rocket spends almost all of its flight in genuine, checked-and-empty
  // vacuum (where nothing needs generating at all), but a plane flies
  // close to a body's surface the entire time, exactly where outrunning
  // streaming is actually possible.
  const loaded = worldChunkLoaded(stepX, stepY, stepZ);
  if (loaded && worldIsSolid(stepX, stepY, stepZ)) {
    const impact = velocity.length();
    if (impact > CRASH_SPEED) {
      hurtPlayer(Math.round(impact * 1.6), { kind: 'crash' });
      dismountVehicle('You crashed!');
    } else {
      // A gentle touchdown just puts you back on your feet.
      dismountVehicle('Landed');
    }
    return;
  }

  player.pos.set(stepX, stepY, stepZ);
  // Keep the player's own velocity in step, so stepping out mid-air carries
  // your momentum into the fall.
  player.vel.copy(velocity);

  // ── Presentation ──
  active.mesh.position.copy(player.pos);
  active.mesh.quaternion.copy(orientation);

  // Chase camera, behind and above, looking where the nose points.
  chase.copy(player.pos)
    .addScaledVector(forward, -(def.chase || 7))
    .addScaledVector(up, CHASE_UP);
  camera.position.copy(chase);
  camera.quaternion.copy(orientation);

  // Keep the stored look direction roughly in step, so dismounting doesn't
  // snap the view — the same alignQuat-rotated decompose vehicles/
  // rocket.js's own updateRocket() uses, since player/view.js's space
  // camera builds its own look direction as alignQuat * Euler(pitch, yaw):
  // yaw/pitch have to be expressed in THAT frame, not in world space
  // directly. On flat ground (alignQuat = identity) this reduces to
  // exactly flight.js's own original formula.
  alignQuaternionFor(gravityDir, alignQuat);
  invAlignQuat.copy(alignQuat).invert();
  localForward.copy(forward).applyQuaternion(invAlignQuat);
  player.yaw = Math.atan2(-localForward.x, -localForward.z);
  player.pitch = Math.asin(THREE.MathUtils.clamp(localForward.y, -1, 1));
}

export function clearFlight() {
  if (active) {
    scene.remove(active.mesh);
    active = null;
  }
  player.piloting = false;
  velocity.set(0, 0, 0);
  throttle = 0;
}
