// Holds the whole session's state: a seeded star system (world/starSystem.js)
// of planets and moons, each a full planet with its own generated faces and
// rendered chunk meshes — the "world" that world/gravity.js,
// world/sphericalMotion.js, render/planetBodies.js and the player-facing
// read/write helpers (world/activeWorld.js, vehicles/rocket.js) all read
// against, once a session has been started (initSpaceSession()).
//
// Every body sits in the SAME shared coordinate frame, far enough apart
// that the space between any two is genuine, unassigned vacuum
// (resolveWorldPos below) — this is what makes flying from one to another a
// single, continuous, unbroken flight rather than a loading-screen swap:
// nothing here ever needs to know which body (if any) a given position is
// near until the moment it's actually asked.

import * as THREE from 'three';
import { CHUNK_SIZE, CHUNK_SHIFT, CHUNK_MASK } from '../config.js';
import { AIR, LEAVES, isLiquidBlock } from './blocks.js';
import { createPlanet, generatePlanetChunk } from './planetTerrain.js';
import { generateEarthPlanetChunk } from './earthTerrain.js';
import { generateStarSystem } from './starSystem.js';
import { getWorldSeed } from '../worldSeed.js';
import * as editLog from './editLog.js';
import { worldToFace, warpToSphere } from './cubeSphere.js';
import { setGravityBodies, clearGravityBodies } from './gravity.js';
import {
  rebuildPlanetChunkMesh, clearAllPlanetMeshes,
  preloadPlanetChunksNear, resetPlanetStreamingFocus,
} from './planetStreaming.js';

// planets[0] is always the home body, at the origin — every other index is
// some other planet/moon, ordered nearest-first by construction (world/
// starSystem.js grows each body's own distance with its index), so "the
// nearest other body" (getMoon() below) is simply planets[1].
let planets = [];
const posScratch = new THREE.Vector3();

function activePlanets() { return planets; }

// Every active planet — world/planetStreaming.js's updatePlanetStreaming
// takes this as a plain argument each frame rather than importing this
// module itself, which is what keeps the two modules from needing each
// other both ways (see planetStreaming.js's own module comment).
export function getActivePlanets() { return activePlanets(); }

export function initSpaceSession() {
  const descriptors = generateStarSystem(getWorldSeed());
  planets = descriptors.map(d => {
    const planet = createPlanet({
      center: d.center, radius: d.radius, amplitude: d.amplitude,
      chunkSpan: d.chunkSpan, chunkHeight: d.chunkHeight, seed: d.seed,
      coreRadius: d.coreRadius,   // only the home descriptor sets this; undefined for every other body, falling back to createPlanet's own default
    });
    planet.id = d.id;
    // Decorative colour (render/planetBodies.js) and gravity strength/reach
    // are per-body but not otherwise part of createPlanet()'s own contract
    // (which only knows about terrain) — tacked on here since this is the
    // one place both the descriptor and the built planet object meet.
    planet.color = d.color;
    planet.gravity = d.gravity;
    planet.gravityRange = d.gravityRange;
    // The home body gets Earth's own real generator (biomes, ore, water,
    // trees — world/earthTerrain.js); every other body keeps the simpler
    // alien one (world/planetTerrain.js). Set once here, read by
    // world/planetStreaming.js's own generic `planet.generateChunk(...)`
    // calls — that module never has to know which one it's actually
    // calling, or that home is special at all. Wrapped so a loaded save's
    // own edits (world/editLog.js) reappear the instant a chunk streams
    // back in, without world/planetStreaming.js needing to know edits
    // exist at all — it just keeps calling `planet.generateChunk(...)`
    // exactly as it always has.
    const realGenerateChunk = d.id === 'home' ? generateEarthPlanetChunk : generatePlanetChunk;
    planet.generateChunk = (p, faceId, cx, cv) => {
      realGenerateChunk(p, faceId, cx, cv);
      const saved = editLog.editsForChunk(p.id, faceId, cx, cv);
      if (!saved) return;
      const store = p.faces[faceId];
      for (const [au, ri, av, id] of saved) store.writeBlockRaw(au, ri, av, id);
    };
    return planet;
  });

  // Only the home body's own spawn tile is generated up front, so the
  // player never lands on ungenerated ground the instant the session
  // starts — every other tile on the home planet, and every other body
  // entirely, wakes up purely through proximity once updatePlanetStreaming
  // (called from main.js's loop) notices the player is close enough.
  preloadPlanetChunksNear(planets[0], 'py', 0, 0, 1);
  resetPlanetStreamingFocus();

  setGravityBodies(planets.map(p => (
    { center: p.center, radius: p.radius, gravityRange: p.gravityRange, gravity: p.gravity }
  )));
  return planets[0];
}

export function clearSpaceSession() {
  clearAllPlanetMeshes();
  resetPlanetStreamingFocus();
  planets = [];
  clearGravityBodies();
}

export function getHomePlanet() { return planets[0] || null; }
// The nearest other body to the home planet — there's no longer a single
// designated "moon" once a seeded system can have anywhere from 3 to 8
// other bodies (world/starSystem.js), but callers that just want "some
// other body to fly to" (tests, anything demoing the rocket) still want
// the closest one, which is always index 1 by construction.
export function getMoon() { return planets[1] || null; }

// Every body worth drawing as a decorative sphere in the sky
// (render/planetBodies.js) — the home planet included, since even the one
// you're standing on needs a distant-silhouette version for when you're
// far enough from it (e.g. flying away) that its own real chunk meshes are
// out of render range. `id` rides along too — render/planetBodies.js has no
// use for it, but vehicles/rocket.js's hyperspeed target-lock (findAimedBody)
// needs SOME stable identity to hand back to bodyLabel() below, and this is
// the one place a body's own descriptor and its live center/radius already
// meet.
export function getVisibleBodies() {
  return planets.map(p => ({ id: p.id, center: p.center, radius: p.radius, color: p.color }));
}

// A human-readable name for a body id — 'home' -> "Home", world/starSystem.js's
// own zero-based "body0", "body1", ... -> "Body 1", "Body 2", ... (1-based,
// since "Body 0" reads like an off-by-one bug even though it isn't one).
// Nothing else in the game names a body today (there's no map, no compass
// entry for planets — see CLAUDE.md's own radar section, which is about
// PLAYERS, not bodies) — this exists purely so a hyperspeed lock has
// something to show the player besides a raw internal id.
export function bodyLabel(id) {
  if (id === 'home') return 'Home';
  const m = /^body(\d+)$/.exec(id);
  return m ? `Body ${parseInt(m[1], 10) + 1}` : id;
}

// A fresh spawn must never drop the player straight into water — a fixed
// (u, v) landing spot (the 'py' face centre) can genuinely be a lake or
// ocean for some seeds, purely by chance, since terrain is seeded
// independently of where spawn happens to sit. Generates whatever chunk a
// candidate column falls in on demand (same direct planet.generateChunk()
// call preloadPlanetChunks already makes), so the answer is always real
// generated terrain, never store.js's own "ungenerated reads as solid"
// fallback standing in for an actual verdict.
const SPAWN_LAND_SEARCH_RADIUS = 64;

function ensureChunkAt(planet, faceId, u, v) {
  const store = planet.faces[faceId];
  const cx = Math.floor((u + planet.halfExtent) / CHUNK_SIZE);
  const cv = Math.floor((v + planet.halfExtent) / CHUNK_SIZE);
  if (!store.hasChunk(cx, cv)) planet.generateChunk(planet, faceId, cx, cv);
}

// Returns true only when the column at (u, v) AND its four immediate
// orthogonal neighbours are all non-liquid at the surface. Checking
// neighbours is what prevents spawning on a shoreline: the player has
// physical width and straddles adjacent columns, so a single-column check
// can pass while a neighbouring water column is still within reach of the
// player's body on first physics contact.
function isLandColumn(planet, faceId, u, v) {
  for (const [du, dv] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const cu = u + du, cv = v + dv;
    ensureChunkAt(planet, faceId, cu, cv);
    const store = planet.faces[faceId];
    const au = Math.floor(cu + planet.halfExtent);
    const av = Math.floor(cv + planet.halfExtent);
    let columnIsLand = true;
    for (let ri = planet.chunkHeight - 1; ri >= 0; ri--) {
      const id = store.getBlock(au, ri, av);
      if (id !== AIR) { columnIsLand = !isLiquidBlock(id); break; }
    }
    if (!columnIsLand) return false;
  }
  return true;
}

// Every cell at exactly Chebyshev distance `r` from the origin, so
// findLandSpot below checks strictly nearer rings before farther ones —
// close enough to "nearest column" for a one-off spawn search without the
// cost of a true distance sort.
function ringOffsets(r) {
  if (r === 0) return [[0, 0]];
  const out = [];
  for (let du = -r; du <= r; du++) { out.push([du, -r], [du, r]); }
  for (let dv = -r + 1; dv <= r - 1; dv++) { out.push([-r, dv], [r, dv]); }
  return out;
}

// Searches outward from (u0, v0) in expanding rings for the nearest column
// whose surface isn't a liquid. Falls back to the centre itself if nothing
// within range qualifies — astronomically unlikely at this radius (it would
// mean a single lake/ocean wider than 128 blocks centred almost exactly on
// the spawn point), but a spawn point must always resolve to SOMEWHERE
// rather than searching forever.
function findLandSpot(planet, faceId, u0, v0) {
  for (let r = 0; r <= SPAWN_LAND_SEARCH_RADIUS; r++) {
    for (const [du, dv] of ringOffsets(r)) {
      const u = u0 + du, v = v0 + dv;
      if (isLandColumn(planet, faceId, u, v)) return { u, v };
    }
  }
  return { u: u0, v: v0 };
}

// A safe point on the surface to drop the player at — searches outward from
// 'py' face centre (which by construction, cubeSphere.js, is always the
// direction straight along that face's own normal) for the nearest dry
// column. This is what makes "you always spawn on land" true for New Game,
// world regeneration and respawning after death alike — every caller of
// this function wants the same guarantee. Loading a save is the one
// deliberate exception: that path restores the player's exact saved
// position verbatim (main.js's applyLoadedGame), water included, since it's
// genuinely putting the player back wherever they actually were.
export function spawnPointOnHomePlanet(out) {
  const planet = getHomePlanet();
  const { u, v } = findLandSpot(planet, 'py', 0, 0);
  return surfacePointOn(planet, 'py', u, v, out);
}

function surfaceIndexAt(planet, faceId, u, v) {
  const store = planet.faces[faceId];
  const au = Math.floor(u + planet.halfExtent);
  const av = Math.floor(v + planet.halfExtent);
  for (let ri = planet.chunkHeight - 1; ri >= 0; ri--) {
    if (store.getBlock(au, ri, av) !== AIR) return ri;
  }
  return 0;
}

// A point just clear of the real ground at (faceId, u, v) on `planet` —
// used for the home planet's own spawn above, and reusable for anything
// else that ever needs to place something on a generated surface (tests,
// future spawn points on the moon). +1 clears the surface block by exactly
// one radial unit — enough to stand on it without spawning inside it or
// high enough above it to take fall damage on the first landing.
export function surfacePointOn(planet, faceId, u, v, out) {
  const surfaceIndex = surfaceIndexAt(planet, faceId, u, v);
  const radius = planet.coreRadius + surfaceIndex + 1;
  return warpToSphere(faceId, u, v, radius, planet.halfExtent, planet.center, out);
}

// Given an arbitrary world position (e.g. a point offset from the player
// along their own local tangent plane), finds whichever active planet it's
// actually nearest the SURFACE of and returns a point just clear of that
// planet's own generated ground directly below/radially-inward from it —
// entities/mobs.js's space spawner uses this so it never needs to know
// which planet or face a given spot happens to be over.
//
// "Nearest the surface of" — minimising |distance to that body's own
// centre minus its own radius| — is deliberately NOT the same as "nearest
// by raw centre distance". The two coincide as long as bodies sit far
// enough apart relative to their own radii, which used to always be true,
// but stopped being a safe assumption once other bodies were retuned to sit
// much closer to home (world/starSystem.js, so several are typically
// visible in the sky right at spawn): a point standing right on HOME's own
// 20,000-radius surface can easily be closer, in raw straight-line terms,
// to some OTHER (much smaller) body's centre than to home's own centre,
// if that body's seeded direction happens to roughly align with the
// point's own — even though the point is obviously on home's surface, not
// that other body's. A real, confirmed regression from the raw-distance
// version: mob spawns (which only ever offset ~20-35 blocks from the
// player) started landing thousands of units away, on a completely
// different planet. Comparing against each body's own surface radius
// instead is what keeps this correct regardless of how close two bodies'
// centres happen to sit.
//
// Split out of surfaceNear below (which used to inline this same search)
// so callers that want to know WHICH planet/face/tile a position
// corresponds to — without wanting a point projected onto that planet's
// generated ground — can reuse the exact same "nearest by surface, not raw
// centre distance" comparison. main.js's loadGame uses this to preload
// chunks around a saved player position, which could be mid-air or
// underground, not necessarily sitting exactly on the surface the way a
// mob spawn point always does.
export function nearestPlanetTo(pos) {
  let best = null, bestDelta = Infinity;
  for (const planet of activePlanets()) {
    const delta = Math.abs(pos.distanceTo(planet.center) - planet.radius);
    if (delta < bestDelta) { bestDelta = delta; best = planet; }
  }
  return best;
}

export function surfaceNear(pos, out) {
  const best = nearestPlanetTo(pos);
  if (!best) return null;
  const { faceId, u, v } = worldToFace(pos, best.center, best.halfExtent);
  return surfacePointOn(best, faceId, u, v, out);
}

// Like surfaceNear, but skips liquid-surface columns — searches outward
// in expanding rings (same as findLandSpot) until it finds a dry column.
// Used by the mob spawner and weapon-drop code so neither ever places
// things in the middle of a lake or ocean.
const surfaceLandScratch = new THREE.Vector3();
export function surfaceNearLand(pos, out) {
  const best = nearestPlanetTo(pos);
  if (!best) return null;
  const { faceId, u, v } = worldToFace(pos, best.center, best.halfExtent);
  const { u: lu, v: lv } = findLandSpot(best, faceId, Math.round(u), Math.round(v));
  return surfacePointOn(best, faceId, lu, lv, out);
}

// Resolves a world position (fractional or integer — caller's choice) to
// whichever active planet's own volume actually contains it, and the voxel
// there. Returns null when it's nowhere near any active planet — open
// vacuum, not "no planet loaded yet" (there's nothing to load: see
// planetTerrain.js on why every chunk already exists up front). Picks
// whichever candidate planet's own radius (i.e. distance from THAT body's
// centre) is smallest — cheap and unambiguous given how far apart the
// bodies are kept; nothing here assumes there are only ever two.
function resolveWorldPos(x, y, z) {
  posScratch.set(x, y, z);
  let best = null, bestRadius = Infinity;
  for (const planet of activePlanets()) {
    const { faceId, u, v, radius } = worldToFace(posScratch, planet.center, planet.halfExtent);
    const ri = Math.floor(radius - planet.coreRadius);
    // Comfortably outside this planet's own store column range (which
    // already reads as solid below 0 / air above chunkHeight) is open
    // vacuum as far as THIS planet is concerned — it just might still be
    // within a different one.
    if (ri < -8 || ri >= planet.chunkHeight + 8) continue;
    if (radius < bestRadius) {
      bestRadius = radius;
      const store = planet.faces[faceId];
      const au = Math.floor(u + planet.halfExtent);
      const av = Math.floor(v + planet.halfExtent);
      best = { planet, store, faceId, au, ri, av };
    }
  }
  return best;
}

// (wx, wy, wz) are treated as block-cell integer coordinates, exactly like
// store.js's getBlock — sampling the cell's own centre so a position exactly
// on a face seam always resolves to one unambiguous face.
export function spaceGetBlock(wx, wy, wz) {
  const r = resolveWorldPos(wx + 0.5, wy + 0.5, wz + 0.5);
  return r ? r.store.getBlock(r.au, r.ri, r.av) : AIR;
}

// The public name for resolveWorldPos — world/blockTarget.js is the one
// caller outside this file that needs the raw resolved cell (not just a
// block id), so raycasting/mining/placing can all agree on EXACTLY one
// cell rather than each re-resolving a literal (wx, wy, wz) independently.
// That distinction matters once cells shrink below one world unit deep
// underground (see CLAUDE.md's Space environment section): re-resolving
// from a plain integer position a second time can land on a different
// cell than the one actually intended.
export function spaceResolveCell(wx, wy, wz) {
  return resolveWorldPos(wx, wy, wz);
}

// Reads/writes a cell that's already been resolved (e.g. by raycastBlock,
// once per aim rather than re-resolved per read/write) — the cell-based
// counterparts to spaceGetBlock/spaceSetBlock above, which resolve fresh
// from a position every time.
export function spaceGetBlockAt(cell) {
  return cell ? cell.store.getBlock(cell.au, cell.ri, cell.av) : AIR;
}

// Reconstructs a real world point inside `cell` (its own centre, safely
// away from any resolve boundary) — used only to give the network relay
// SOME literal (x, y, z) to send, since spaceSetBlockAt's caller
// (world/blockTarget.js's setTargetBlock, used by player/mining.js) only
// ever has the resolved cell on hand, not the original aim point.
const notifyPointScratch = new THREE.Vector3();
function worldPointForCell(cell) {
  const { planet, faceId, au, ri, av } = cell;
  const u = au - planet.halfExtent + 0.5, v = av - planet.halfExtent + 0.5;
  warpToSphere(faceId, u, v, planet.coreRadius + ri + 0.5, planet.halfExtent, planet.center, notifyPointScratch);
  return notifyPointScratch;
}

export function spaceSetBlockAt(cell, id) {
  if (!writeAndRemeshCell(cell, id)) return false;
  editLog.recordEdit(cell.planet.id, cell.faceId, cell.au, cell.ri, cell.av, id);
  if (blockChangeListener) {
    const p = worldPointForCell(cell);
    blockChangeListener(p.x, p.y, p.z, id);
  }
  return true;
}

// How many radial layers of guaranteed-unbreakable rock sit above the
// store's own true "ri < 0 reads as solid, and writeBlockRaw silently
// refuses to touch it" floor (world/store.js — the same convention Earth's
// bottom uses). That floor is real but silent: digging into it just does
// nothing, with no explanation. This margin turns it into an EXPLICIT,
// communicated stop (world/blockTarget.js's isBedrockTarget, shown as a
// message by player/actions.js and player/mining.js) a bit before the true
// edge. Both planets now keep their whole crust thin relative to their own
// radius (see HOME_PLANET_CHUNK_HEIGHT/MOON_CHUNK_HEIGHT above), so a cell's
// real-world size never shrinks anywhere near as far as it used to by the
// time digging reaches this margin — 4 is comfortable headroom rather than
// the much larger buffer the old, far deeper crust needed.
export const BEDROCK_MARGIN = 4;

export function isBedrockCell(cell) {
  return !!cell && cell.ri < BEDROCK_MARGIN;
}

// Scratch corner array reused by spaceCellCorners below — 8 THREE.Vector3,
// one per corner of a cell's own warped hexahedron. Module-level rather
// than per-call since this runs every frame the highlight/break-overlay is
// visible in space (render/cellHighlight.js).
const cellCorners = Array.from({ length: 8 }, () => new THREE.Vector3());

// The 8 real-world corners of a resolved cell's own warped hexahedron,
// written into `out` (an array of >= 8 THREE.Vector3 — pass your own
// scratch, e.g. render/cellHighlight.js's makeCornerScratch(), or omit to
// use this module's own). Exactly the per-corner warpToSphere() call
// world/planetMesher.js uses to build a whole chunk, just for one cell on
// demand — this is what lets the highlight wireframe and break-progress
// overlay show the cell's ACTUAL shape and size instead of a fixed unit
// cube, which is what made both visibly misalign once a cell stopped being
// close to one world unit across (see CLAUDE.md's Space environment
// section on why cells shrink towards the core).
export function spaceCellCorners(cell, out = cellCorners) {
  const { planet, faceId, au, ri, av } = cell;
  const u0 = au - planet.halfExtent, u1 = u0 + 1;
  const v0 = av - planet.halfExtent, v1 = v0 + 1;
  const r0 = planet.coreRadius + ri, r1 = r0 + 1;
  const { center, halfExtent } = planet;
  warpToSphere(faceId, u0, v0, r0, halfExtent, center, out[0]);
  warpToSphere(faceId, u1, v0, r0, halfExtent, center, out[1]);
  warpToSphere(faceId, u0, v1, r0, halfExtent, center, out[2]);
  warpToSphere(faceId, u1, v1, r0, halfExtent, center, out[3]);
  warpToSphere(faceId, u0, v0, r1, halfExtent, center, out[4]);
  warpToSphere(faceId, u1, v0, r1, halfExtent, center, out[5]);
  warpToSphere(faceId, u0, v1, r1, halfExtent, center, out[6]);
  warpToSphere(faceId, u1, v1, r1, halfExtent, center, out[7]);
  return out;
}

// Accepts fractional world coordinates directly — moveOnSphere's (and
// vehicles/rocket.js's) contract, mirroring store.js's own isSolid. This is
// what a rocket crossing open space between the two bodies calls every
// frame; returning false here for the whole vacuum in between, with no
// special-casing, is what lets that flight stay unbroken.
export function spaceIsSolid(wx, wy, wz) {
  const r = resolveWorldPos(wx, wy, wz);
  if (!r) return false;
  const id = r.store.getBlock(r.au, r.ri, r.av);
  return id !== AIR && !isLiquidBlock(id) && id !== LEAVES;
}

// Whether the chunk containing (wx, wy, wz) has actually been generated —
// the space analogue of store.js's hasChunk, for callers that need to know
// whether a "solid" reading from spaceIsSolid is trustworthy or just an
// ungenerated-chunk fallback (store.js's own "index < 0 reads as solid,
// but so does an ungenerated chunk" convention). vehicles/flight.js needs
// this: a fast plane can outrun a body's own budgeted streaming
// (world/planetStreaming.js), and crashing into terrain that simply
// hasn't loaded yet is no fun — the exact same reasoning flight.js's own
// original hasChunk gate had for flat Earth. Open vacuum (no body nearby
// at all) reports true — there's nothing to generate there, and
// spaceIsSolid's own "false" for it is already correct on its own.
export function spaceChunkLoaded(wx, wy, wz) {
  const r = resolveWorldPos(wx, wy, wz);
  if (!r) return true;
  return r.store.hasChunk(r.au >> CHUNK_SHIFT, r.av >> CHUNK_SHIFT);
}

// Notified whenever THIS client edits a block, so multiplayer can relay it
// — the space analogue of world/world.js's own onBlockChange. Edits arriving
// FROM the network go through spaceApplyRemoteBlock instead, which
// deliberately doesn't notify — otherwise two clients would echo forever.
let blockChangeListener = null;
export function onSpaceBlockChange(fn) { blockChangeListener = fn; }

// Writes one voxel and rebuilds its own chunk's mesh, plus any neighbouring
// chunk the edit sits on the border of — the same border-aware remesh
// world/world.js's own writeAndRemesh does for Earth, generalised to a
// planet's own bounded (au, av) chunk grid on one face. A face's own OUTER
// edge (cx/cv at 0 or chunkSpan-1) has no neighbour to rebuild on that
// side — the neighbour across a face's own seam is a genuinely different
// face, and cross-face seam stitching stays the same accepted, separate
// limitation it's always been (see CLAUDE.md's Non-goals).
function writeAndRemeshCell(cell, id) {
  if (!cell) return false;
  const { planet, faceId, store } = cell;
  const w = store.writeBlockRaw(cell.au, cell.ri, cell.av, id);
  if (!w) return false;
  const { cx, cz: cv, lx, lz } = w;
  const span = planet.chunkSpan;
  rebuildPlanetChunkMesh(planet, faceId, cx, cv);
  if (lx === 0          && cx > 0)        rebuildPlanetChunkMesh(planet, faceId, cx - 1, cv);
  if (lx === CHUNK_MASK && cx < span - 1) rebuildPlanetChunkMesh(planet, faceId, cx + 1, cv);
  if (lz === 0          && cv > 0)        rebuildPlanetChunkMesh(planet, faceId, cx, cv - 1);
  if (lz === CHUNK_MASK && cv < span - 1) rebuildPlanetChunkMesh(planet, faceId, cx, cv + 1);
  return true;
}

// Writes one voxel and rebuilds its chunk's mesh (border-aware, see
// writeAndRemeshCell above) — the space analogue of world.js's setBlock,
// including notifying the network the same way that does.
export function spaceSetBlock(wx, wy, wz, id) {
  const r = resolveWorldPos(wx + 0.5, wy + 0.5, wz + 0.5);
  if (!writeAndRemeshCell(r, id)) return false;
  editLog.recordEdit(r.planet.id, r.faceId, r.au, r.ri, r.av, id);
  if (blockChangeListener) blockChangeListener(wx, wy, wz, id);
  return true;
}

// Same edit, without telling the network about it — for edits arriving FROM
// the network (see the module comment above). Still recorded into the edit
// log: the local voxel store is the true state regardless of who caused
// the edit, so a hosted save that skipped peers' own edits would silently
// drop whatever they built.
export function spaceApplyRemoteBlock(wx, wy, wz, id) {
  const r = resolveWorldPos(wx + 0.5, wy + 0.5, wz + 0.5);
  if (writeAndRemeshCell(r, id)) editLog.recordEdit(r.planet.id, r.faceId, r.au, r.ri, r.av, id);
}

// Destroys every block within `radius` of `center` (sphere), batching mesh
// rebuilds to once per affected chunk — the space analogue of
// world/world.js's own carveCrater. Scans a genuinely 3D world-space box
// (not Earth's 2D x/z box over a fixed Y range) since there's no single
// axis that's always "up" here; each candidate point is independently
// resolved to whichever body/face/cell actually contains it, so a crater
// spanning a face seam (extremely unlikely at any real explosion radius,
// but not assumed away) still clears correctly on both sides.
export function spaceCarveCrater(center, radius) {
  const x0 = Math.floor(center.x - radius), x1 = Math.ceil(center.x + radius);
  const y0 = Math.floor(center.y - radius), y1 = Math.ceil(center.y + radius);
  const z0 = Math.floor(center.z - radius), z1 = Math.ceil(center.z + radius);
  const r2 = radius * radius;
  const dirty = new Map();   // "planetId|faceId|cx|cv" -> { planet, faceId, cx, cv }

  const markDirty = (planet, faceId, cx, cv) => {
    if (cx < 0 || cx >= planet.chunkSpan || cv < 0 || cv >= planet.chunkSpan) return;
    dirty.set(planet.id + '|' + faceId + '|' + cx + '|' + cv, { planet, faceId, cx, cv });
  };

  for (let x = x0; x <= x1; x++) {
    for (let y = y0; y <= y1; y++) {
      for (let z = z0; z <= z1; z++) {
        const dx = x + 0.5 - center.x, dy = y + 0.5 - center.y, dz = z + 0.5 - center.z;
        if (dx * dx + dy * dy + dz * dz > r2) continue;
        const r = resolveWorldPos(x + 0.5, y + 0.5, z + 0.5);
        if (!r) continue;
        const res = r.store.writeBlockRaw(r.au, r.ri, r.av, AIR);
        if (!res) continue;
        const { planet, faceId } = r;
        editLog.recordEdit(planet.id, faceId, r.au, r.ri, r.av, AIR);
        markDirty(planet, faceId, res.cx, res.cz);
        if (res.lx === 0)          markDirty(planet, faceId, res.cx - 1, res.cz);
        if (res.lx === CHUNK_MASK) markDirty(planet, faceId, res.cx + 1, res.cz);
        if (res.lz === 0)          markDirty(planet, faceId, res.cx, res.cz - 1);
        if (res.lz === CHUNK_MASK) markDirty(planet, faceId, res.cx, res.cz + 1);
      }
    }
  }

  for (const { planet, faceId, cx, cv } of dirty.values()) rebuildPlanetChunkMesh(planet, faceId, cx, cv);
}
