// Survival vs Creative. Persisted to localStorage between sessions.

import { player } from './player/state.js';
import { renderModeUI } from './ui/overlay.js';
import { updateHpBar, setHpBarVisible } from './ui/hud.js';

const STORAGE_KEY = 'blocksGameMode';

let gameMode = 'survival';

export function getGameMode() { return gameMode; }
export function isCreative()  { return gameMode === 'creative'; }

export function setGameMode(mode) {
  if (mode !== 'survival' && mode !== 'creative') return;
  gameMode = mode;
  try { localStorage.setItem(STORAGE_KEY, mode); } catch { /* private mode */ }
  if (gameMode === 'survival') player.flying = false;
  player.fallStartY = null;   // reset fall tracking; physicsStep recomputes it fresh next tick
  renderModeUI(gameMode);
  setHpBarVisible(gameMode !== 'creative');
  updateHpBar(player.hp, player.maxHp);
}

// Reads the saved mode. Called from main.js so importing this module has no
// side effects.
export function initGameMode() {
  let saved = null;
  try { saved = localStorage.getItem(STORAGE_KEY); } catch { /* private mode */ }
  setGameMode(saved === 'creative' ? 'creative' : 'survival');
}
