// Blocky models for the flying machines, built once per type and shared.
// Each faces down -z, matching the direction the craft flies.

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

const cache = new Map();

// Unlit, with the shading baked into the vertex colours — the same trick the
// chunk mesher uses. A lit material would be near-black under Potato's flat
// ambient (three divides Lambert irradiance by PI), and these need to read the
// same in both presets.
const material = new THREE.MeshBasicMaterial({ vertexColors: true });

// BoxGeometry lays out +x, -x, +y, -y, +z, -z with four vertices each. Same
// face brightnesses as the terrain, so a wing reads against the sky.
const FACE_SHADE = [0.72, 0.72, 1.0, 0.55, 0.86, 0.86];

function part(w, h, d, x, y, z, hex) {
  const g = new THREE.BoxGeometry(w, h, d);
  g.translate(x, y, z);
  const c = new THREE.Color(hex);
  const n = g.getAttribute('position').count;
  const colors = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const shade = FACE_SHADE[Math.floor(i / 4)] ?? 1;
    colors[i * 3]     = c.r * shade;
    colors[i * 3 + 1] = c.g * shade;
    colors[i * 3 + 2] = c.b * shade;
  }
  g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return g;
}

