// Earth's real terrain generator — heightmap, biomes, ore, water, trees —
// ported onto the planet-chunk architecture, for the home body only.
// world/spaceSession.js wires `planet.generateChunk = generateEarthPlanetChunk`
// for the home body specifically; every other body still uses
// world/planetTerrain.js's own simpler alien generator (regolith/alien
// rock/starmetal, no biomes, no trees). Kept in its own file rather than
// folded into planetTerrain.js for exactly that reason — this needs
// terrain.js's ore tiers and tree logic that the alien generator never had,
// so planetTerrain.js stays the simple, untouched "generic alien body"
// path.
//
// The substitution is exactly the one planetTerrain.js already proved out
// for the alien generator: face-tangent (u, v) plays the role terrain.js's
// (wx, wz) plays, and a radial index (`ri`, relative to planet.coreRadius)
// plays the role absolute world Y plays there. biomes.js's own
// terrainColumn (now parameterized — see that file) and noise.js are
// reused completely unchanged; only this column-fill loop is a genuine
// port, not a wrap, since terrain.js's own generateChunk writes into a
// single global flat store rather than a per-face, per-planet one.

import { CHUNK_SIZE, SEA_LEVEL } from '../config.js';
import {
  AIR, GRASS, DIRT, STONE, SAND, WOOD, LEAVES, WATER, SNOW, GRAVEL,
  IRON, TITANIUM, CRYSTAL,
} from './blocks.js';
import { makeNoise } from './noise.js';
import { terrainColumn } from './biomes.js';

// The exact ore table terrain.js uses (see that file's own comment on
// tuning against bench/ores.js). `maxY` is already "depth below the
// surface, near the bottom of the column" there, which means the same
// thing in radial-index terms (`ri`, 0-based from a planet's own
// coreRadius) as it does in absolute world Y on flat Earth — no
// translation needed beyond the variable itself.
const ORES = [
  { id: CRYSTAL,  maxY: 10, threshold: 0.72, scale: 0.42 },
  { id: TITANIUM, maxY: 18, threshold: 0.62, scale: 0.34 },
  { id: IRON,     maxY: 30, threshold: 0.50, scale: 0.28 },
];

function oreAt(oreNoise, u, ri, v) {
  for (const ore of ORES) {
    if (ri > ore.maxY) continue;
    // Offsetting by ri makes veins wander radially instead of forming
    // columns — the exact reasoning terrain.js's own comment gives for
    // offsetting by y.
    const n = oreNoise.noise2(u * ore.scale + ri * 0.7, v * ore.scale - ri * 0.5);
    if (n > ore.threshold) return ore.id;
  }
  return STONE;
}

// A per-planet noise cache, mirroring planetTerrain.js's own ensureNoise —
// each planet's own generation seed is fixed at construction time (world/
// starSystem.js), unlike Earth's flat terrain.js, which has to watch a
// LIVE, changeable world seed instead (worldSeed.js) and rebuild if it
// ever moves. A planet's own seed never moves, so "build once, cache on
// the planet object" is all this needs.
function ensureNoise(planet) {
  if (planet._noise) return planet._noise;
  planet._noise = makeNoise(planet.seed >>> 0);
  return planet._noise;
}

// A second field, so ore veins don't line up with the surface they sit
// under — the exact reasoning and the exact seed offset (`^ 0x5eed`)
// terrain.js's own ensureNoise() uses.
function ensureOreNoise(planet) {
  if (planet._oreNoise) return planet._oreNoise;
  planet._oreNoise = makeNoise((planet.seed ^ 0x5eed) >>> 0);
  return planet._oreNoise;
}

// Fills chunk (cx, cv) of `faceId` on `planet` — the planet-chunk-calling-
// convention twin of terrain.js's own generateChunk(cx, cz), with the same
// call signature generatePlanetChunk (the alien generator) already uses,
// so world/spaceSession.js can assign either one to a body's own
// `generateChunk` interchangeably.
export function generateEarthPlanetChunk(planet, faceId, cx, cv) {
  const store = planet.faces[faceId];
  const noise = ensureNoise(planet);
  const oreNoise = ensureOreNoise(planet);
  const data = new Uint8Array(CHUNK_SIZE * planet.chunkHeight * CHUNK_SIZE);
  const u0 = cx * CHUNK_SIZE - planet.halfExtent;
  const v0 = cv * CHUNK_SIZE - planet.halfExtent;
  // The same "leave headroom below the ceiling" margin biomes.js's own
  // default already uses for flat Earth (CHUNK_HEIGHT - 4) — passed
  // explicitly here since a planet's own chunkHeight (world/starSystem.js's
  // HOME_CHUNK_HEIGHT) is a value, not the global CHUNK_HEIGHT constant.
  const ceiling = planet.chunkHeight - 4;

  for (let lu = 0; lu < CHUNK_SIZE; lu++) {
    for (let lv = 0; lv < CHUNK_SIZE; lv++) {
      const u = u0 + lu, v = v0 + lv;
      // seaLevel is passed through as the literal SEA_LEVEL constant
      // (unchanged) — terrainColumn's own "height" and this generator's
      // radial index already use the same units by construction (the
      // same substitution planetTerrain.js already validated), so no
      // translation is needed beyond which baseline number gets passed.
      const { surfaceY: surfaceIndex, isSandy, isSnowy, isVolcanic } =
        terrainColumn(noise, u, v, { seaLevel: SEA_LEVEL, ceiling });

      // The array starts zeroed and AIR is 0, so everything above the
      // surface (and above sea level) is already correct — no need to
      // walk to the roof, exactly as terrain.js's own comment notes.
      const topIndex = Math.min(planet.chunkHeight - 1, Math.max(surfaceIndex, SEA_LEVEL));
      for (let ri = 0; ri <= topIndex; ri++) {
        let id = AIR;
        if (ri === 0) {
          id = STONE;                          // bedrock layer, never ore — matches terrain.js's own y===0 rule
        } else if (ri < surfaceIndex - 4) {
          id = oreAt(oreNoise, u, ri, v);
        } else if (ri < surfaceIndex) {
          id = isVolcanic ? STONE : isSandy ? SAND : DIRT;
        } else if (ri === surfaceIndex) {
          id = isVolcanic ? GRAVEL : isSandy ? SAND : isSnowy ? SNOW : GRASS;
        } else if (ri <= SEA_LEVEL && ri > surfaceIndex) {
          id = WATER;
        }
        data[store.blockIndex(lu, ri, lv)] = id;
      }

      // Trees. Leaves are only written inside this chunk, so canopies clip
      // at chunk borders — the same accepted trade-off terrain.js's own
      // comment describes, now with one more case: a tree near a cube
      // FACE's own outer edge (not just a chunk edge within one face)
      // clips the same way, since the two faces meeting there have
      // genuinely different (u, v) mappings and reaching across isn't
      // possible without real cross-face writes (see CLAUDE.md's Space
      // environment section on cross-face seam stitching).
      if (!isSandy && !isSnowy && !isVolcanic && surfaceIndex > SEA_LEVEL + 1) {
        const treeNoise = noise.noise2(u * 0.3 + 100, v * 0.3 + 100);
        if (treeNoise > 0.55) {
          const ty = surfaceIndex + 1;
          for (let i = 0; i < 4; i++) {
            if (ty + i < planet.chunkHeight) data[store.blockIndex(lu, ty + i, lv)] = WOOD;
          }
          for (let du = -2; du <= 2; du++) {
            for (let dv = -2; dv <= 2; dv++) {
              for (let dri = 3; dri <= 5; dri++) {
                if (Math.abs(du) === 2 && Math.abs(dv) === 2) continue;
                const lri = ty + dri;
                const llu = lu + du, llv = lv + dv;
                if (lri < planet.chunkHeight && llu >= 0 && llu < CHUNK_SIZE && llv >= 0 && llv < CHUNK_SIZE) {
                  if (data[store.blockIndex(llu, lri, llv)] === AIR)
                    data[store.blockIndex(llu, lri, llv)] = LEAVES;
                }
              }
            }
          }
        }
      }
    }
  }

  store.setChunk(cx, cv, data);
}
