// Hotbar icons, drawn to canvases at runtime.
//
// A flat colour swatch told you nothing apart from roughly what colour a thing
// was — a pistol and a chaingun were both just orange-ish squares. Blocks now
// get an isometric cube in their own top/side colours, and every weapon gets
// its own silhouette, so a glance at the bar is enough.
//
// Icons are cached by key, so each is painted once.

import { BLOCK_COLORS, BLOCK_NAMES } from '../world/blocks.js';
import { TOOL_TYPES } from '../tools/types.js';

const SIZE = 64;
const cache = new Map();

const hex = n => '#' + n.toString(16).padStart(6, '0');

function shade(color, amount) {
  const r = Math.max(0, Math.min(255, ((color >> 16) & 0xff) + amount));
  const g = Math.max(0, Math.min(255, ((color >> 8) & 0xff) + amount));
  const b = Math.max(0, Math.min(255, (color & 0xff) + amount));
  return `rgb(${r},${g},${b})`;
}

function newCanvas() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = SIZE;
  const ctx = canvas.getContext('2d');
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  return { canvas, ctx };
}

function poly(ctx, points, fill) {
  ctx.beginPath();
  ctx.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
}

// ── Blocks ───────────────────────────────────────────────

// A cube seen from above-left: bright top, mid-tone left, dark right. The same
// three-tone treatment the world mesh uses, so icons match what you dig up.
function drawBlockIcon(ctx, id) {
  const col = BLOCK_COLORS[id] || BLOCK_COLORS[3];
  const cx = SIZE / 2, top = 8, h = 15, w = 22, bodyH = 20;

  poly(ctx, [[cx, top], [cx + w, top + h], [cx, top + h * 2], [cx - w, top + h]], hex(col.top));
  poly(ctx, [[cx - w, top + h], [cx, top + h * 2], [cx, top + h * 2 + bodyH], [cx - w, top + h + bodyH]],
    shade(col.side, -18));
  poly(ctx, [[cx + w, top + h], [cx, top + h * 2], [cx, top + h * 2 + bodyH], [cx + w, top + h + bodyH]],
    shade(col.side, -46));
}

// ── Weapons ──────────────────────────────────────────────

function drawPistol(ctx) {
  ctx.fillStyle = '#8d949b';
  ctx.fillRect(14, 22, 34, 9);          // slide
  ctx.fillStyle = '#6e757c';
  ctx.fillRect(42, 25, 10, 4);          // barrel
  poly(ctx, [[18, 31], [30, 31], [26, 48], [16, 48]], '#4a4f55');   // grip
  ctx.strokeStyle = '#3a3f45';
  ctx.lineWidth = 2.5;
  ctx.beginPath();                       // trigger guard
  ctx.arc(33, 34, 6, 0.1 * Math.PI, 1.0 * Math.PI);
  ctx.stroke();
}

function drawShotgun(ctx) {
  ctx.save();
  ctx.translate(32, 32);
  ctx.rotate(-0.22);
  ctx.fillStyle = '#5b6066';
  ctx.fillRect(-6, -7, 34, 5);           // upper barrel
  ctx.fillRect(-6, -1, 34, 5);           // lower barrel
  ctx.fillStyle = '#8a5a2b';
  ctx.fillRect(-26, -6, 21, 11);         // stock
  ctx.fillStyle = '#6b4420';
  ctx.fillRect(2, 5, 13, 6);             // pump
  ctx.restore();
}

function drawChaingun(ctx) {
  ctx.fillStyle = '#3f4348';
  ctx.fillRect(8, 24, 22, 16);           // receiver
  ctx.fillStyle = '#cc6600';
  // Barrel cluster — the giveaway that it's the fast one.
  for (const y of [23, 29, 35]) ctx.fillRect(30, y, 24, 5);
  ctx.fillStyle = '#2a2d31';
  ctx.fillRect(52, 22, 5, 20);           // muzzle plate
  ctx.fillRect(12, 40, 8, 12);           // grip
}

function drawRocket(ctx) {
  ctx.save();
  ctx.translate(32, 32);
  ctx.rotate(-0.18);
  ctx.fillStyle = '#43484d';
  ctx.fillRect(-24, -8, 46, 15);         // tube
  ctx.fillStyle = '#2c3034';
  ctx.fillRect(-27, -10, 6, 19);         // back rim
  ctx.fillStyle = '#b5352c';
  poly(ctx, [[22, -8], [32, -1], [22, 7]], '#b5352c');   // warhead
  ctx.fillStyle = '#33373b';
  ctx.fillRect(-8, 7, 9, 10);            // grip
  ctx.restore();
}

function drawNuke(ctx) {
  // Glowing warhead, so it stands out as the thing you save for a rainy day.
  const glow = ctx.createRadialGradient(32, 30, 2, 32, 30, 26);
  glow.addColorStop(0, 'rgba(180,255,80,.85)');
  glow.addColorStop(1, 'rgba(180,255,80,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, SIZE, SIZE);

  ctx.fillStyle = '#9acd32';
  ctx.beginPath();
  ctx.ellipse(32, 30, 11, 15, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#7fae22';
  poly(ctx, [[24, 40], [40, 40], [36, 52], [28, 52]], '#7fae22');   // fins
  ctx.fillStyle = '#e9ffbe';
  ctx.beginPath();
  ctx.ellipse(28, 25, 3.5, 5, -0.3, 0, Math.PI * 2);
  ctx.fill();                                                       // highlight
}

// ── Vehicles ─────────────────────────────────────────────

function drawHangglider(ctx) {
  poly(ctx, [[32, 14], [58, 34], [32, 30], [6, 34]], '#e4cf8c');
  poly(ctx, [[32, 30], [42, 40], [32, 38], [22, 40]], '#cbb26a');
  ctx.strokeStyle = '#6b5330';
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(32, 30); ctx.lineTo(32, 50); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(22, 50); ctx.lineTo(42, 50); ctx.stroke();
}

function drawJetpack(ctx) {
  ctx.fillStyle = '#7a4a1c';
  ctx.fillRect(24, 16, 16, 26);
  ctx.fillStyle = '#b9772f';
  ctx.fillRect(13, 14, 10, 30);
  ctx.fillRect(41, 14, 10, 30);
  ctx.fillStyle = '#4a4f55';
  ctx.fillRect(14, 44, 8, 6);
  ctx.fillRect(42, 44, 8, 6);
  // exhaust
  poly(ctx, [[15, 50], [21, 50], [18, 60]], '#ff9a3c');
  poly(ctx, [[43, 50], [49, 50], [46, 60]], '#ff9a3c');
}

function drawPlane(ctx) {
  ctx.fillStyle = '#c7d2dc';
  poly(ctx, [[32, 8], [37, 22], [37, 46], [27, 46], [27, 22]], '#c7d2dc');   // fuselage
  ctx.fillStyle = '#a9b6c4';
  ctx.fillRect(4, 26, 56, 7);                                                // wing
  ctx.fillRect(18, 46, 28, 5);                                               // tailplane
  ctx.fillStyle = '#2f3b47';
  ctx.fillRect(28, 16, 8, 8);                                                // canopy
  ctx.fillStyle = '#8b6a3a';
  ctx.fillRect(29, 4, 6, 4);                                                 // prop
}

function drawJetFighter(ctx) {
  ctx.fillStyle = '#7f8b99';
  poly(ctx, [[32, 3], [38, 24], [38, 48], [26, 48], [26, 24]], '#7f8b99');
  ctx.fillStyle = '#6b7684';
  poly(ctx, [[26, 30], [4, 50], [26, 46]], '#6b7684');                       // delta wings
  poly(ctx, [[38, 30], [60, 50], [38, 46]], '#6b7684');
  ctx.fillStyle = '#24303c';
  ctx.fillRect(29, 13, 6, 9);                                                // canopy
  ctx.fillStyle = '#ff8a3a';
  ctx.fillRect(27, 48, 4, 7);                                                // afterburners
  ctx.fillRect(33, 48, 4, 7);
}

// A hull-plus-cabin template shared by the four boats, the same reuse pattern
// as the digger/feller/drill rigs below: bigger scale and an extra cabin deck
// at each tier reads as "the same kind of thing, but a lot more of it".
function drawBoatHull(ctx, color, scale, { cabin = 0, mast = false } = {}) {
  ctx.save();
  ctx.translate(32, 38);
  ctx.scale(scale, scale);
  poly(ctx, [[-24, 6], [-14, -8], [16, -8], [24, 6], [14, 14], [-14, 14]], color);
  poly(ctx, [[-24, 6], [24, 6], [14, 14], [-14, 14]], shade(color, -35));   // waterline shade
  if (cabin > 0) {
    ctx.fillStyle = '#e9ece6';
    ctx.fillRect(-11, -8 - cabin, 22, cabin);
  }
  if (mast) {
    ctx.strokeStyle = '#8d949b';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(4, -8 - cabin); ctx.lineTo(4, -8 - cabin - 14); ctx.stroke();
  }
  ctx.restore();
}

function drawDinghy(ctx) {
  drawBoatHull(ctx, '#d6dadc', 0.6);
  ctx.strokeStyle = '#6b5330';
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(40, 24); ctx.lineTo(54, 44); ctx.stroke();   // paddle
}

function drawSpeedboat(ctx) {
  drawBoatHull(ctx, '#e6e9eb', 0.85);
  ctx.fillStyle = '#2f3b47';
  ctx.fillRect(24, 20, 4, 12);                                             // windscreen
}

function drawYacht(ctx)      { drawBoatHull(ctx, '#f2f2ee', 1.0,  { cabin: 12, mast: true }); }
function drawSuperYacht(ctx) { drawBoatHull(ctx, '#faf6e8', 1.15, { cabin: 20, mast: true }); }

// Upright, not the weapon rocket launcher's horizontal drawRocket above (a
// separate function despite the similar name/shape) — this one launches
// straight up, so a standing silhouette reads right in the hotbar.
function drawRocketCraft(ctx) {
  ctx.fillStyle = '#dadad8';                                        // body tube, matches VEHICLE_TYPES.rocket's own colour
  ctx.fillRect(26, 20, 12, 30);
  ctx.fillStyle = '#b5352c';
  poly(ctx, [[26, 20], [32, 6], [38, 20]], '#b5352c');               // nose cone
  ctx.fillStyle = '#8f9497';
  poly(ctx, [[26, 40], [18, 56], [26, 50]], '#8f9497');              // left fin
  poly(ctx, [[38, 40], [46, 56], [38, 50]], '#8f9497');              // right fin
  ctx.fillStyle = '#2f3b47';
  ctx.fillRect(28, 25, 8, 8);                                        // window
  poly(ctx, [[27, 50], [37, 50], [32, 62]], '#ff9a3c');              // exhaust flame
}

// Same standing silhouette as drawRocketCraft above, widened and given twin
// engines and a bright cyan ring band — the same "hyperdrive ring" tell
// vehicles/models.js's own 3D model uses, so the hotbar icon and the ship
// you actually see read as the same craft.
function drawStarCruiser(ctx) {
  ctx.fillStyle = '#9aa6b0';                                         // hull, matches VEHICLE_TYPES.starcruiser's own colour family
  ctx.fillRect(22, 16, 20, 34);
  ctx.fillStyle = '#c9d3db';
  poly(ctx, [[22, 16], [32, 4], [42, 16]], '#c9d3db');               // swept nose
  ctx.fillStyle = '#5ec8ff';
  ctx.fillRect(20, 27, 24, 5);                                       // hyperdrive ring
  ctx.fillStyle = '#2f3b47';
  ctx.fillRect(27, 19, 10, 7);                                       // cockpit canopy
  ctx.fillStyle = '#7f8b99';
  ctx.fillRect(14, 38, 8, 16);                                       // left nacelle
  ctx.fillRect(42, 38, 8, 16);                                       // right nacelle
  poly(ctx, [[13, 54], [23, 54], [18, 62]], '#ff9a3c');              // left exhaust
  poly(ctx, [[41, 54], [51, 54], [46, 62]], '#ff9a3c');              // right exhaust
}

const VEHICLE_ICONS = {
  hangglider: drawHangglider,
  jetpack:    drawJetpack,
  plane:      drawPlane,
  jetfighter: drawJetFighter,
  dinghy:     drawDinghy,
  speedboat:  drawSpeedboat,
  yacht:      drawYacht,
  superyacht: drawSuperYacht,
  rocket:     drawRocketCraft,
  starcruiser: drawStarCruiser,
};

// ── Tools and machinery ──────────────────────────────────
//
// The four hand tools each get a bespoke silhouette, like the weapons above.
// The machine lines share one template per category (digger / feller / drill
// rig) drawn bigger and in a more saturated colour at each tier, which reads
// as "the same kind of thing, but a lot more of it" without hand-drawing a
// dozen near-identical machines.

function drawSpade(ctx) {
  ctx.fillStyle = '#7a4a1c';
  ctx.fillRect(29, 8, 6, 30);                                     // handle
  ctx.fillStyle = '#3a3f45';
  ctx.fillRect(24, 34, 16, 6);                                    // crossbar grip
  ctx.fillStyle = '#aeb4ba';
  poly(ctx, [[20, 40], [44, 40], [40, 58], [24, 58]], '#aeb4ba'); // blade
  ctx.fillStyle = '#8d949b';
  poly(ctx, [[24, 58], [40, 58], [32, 62]], '#8d949b');           // blade tip
}

function drawAxe(ctx) {
  ctx.fillStyle = '#6b4420';
  ctx.fillRect(29, 10, 6, 44);                                    // handle
  ctx.fillStyle = '#9aa0a6';
  poly(ctx, [[32, 10], [54, 18], [50, 32], [32, 26]], '#9aa0a6'); // blade
  ctx.fillStyle = '#7a7f85';
  poly(ctx, [[50, 32], [54, 18], [58, 22], [55, 34]], '#7a7f85'); // edge highlight
}

function drawHammer(ctx) {
  ctx.fillStyle = '#6e4a28';
  ctx.fillRect(29, 22, 6, 34);                                    // handle
  ctx.fillStyle = '#6e757c';
  ctx.fillRect(16, 10, 32, 16);                                   // head
  ctx.fillStyle = '#565c62';
  ctx.fillRect(16, 10, 32, 5);                                    // head highlight
}

function drawPickaxe(ctx) {
  ctx.fillStyle = '#6e4a28';
  ctx.fillRect(29, 16, 6, 40);                                    // handle
  ctx.fillStyle = '#7a7f85';
  poly(ctx, [[32, 20], [10, 14], [16, 8], [32, 14]], '#7a7f85');  // left pick
  poly(ctx, [[32, 20], [54, 14], [48, 8], [32, 14]], '#7a7f85');  // right pick
}

function drawElectricSpade(ctx) {
  drawSpade(ctx);
  ctx.fillStyle = '#e0b23c';
  ctx.fillRect(23, 10, 18, 12);                                   // battery pack
  ctx.strokeStyle = '#8a6a1c';
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(32, 22); ctx.lineTo(32, 34); ctx.stroke(); // cable
}

function drawChainsaw(ctx) {
  ctx.fillStyle = '#d6541f';
  ctx.fillRect(12, 30, 22, 18);                                   // body
  ctx.fillStyle = '#3a3f45';
  ctx.fillRect(30, 34, 28, 6);                                    // bar
  ctx.fillStyle = '#8d949b';
  for (let x = 32; x < 56; x += 5) ctx.fillRect(x, 33, 2, 8);     // chain teeth
  ctx.fillStyle = '#a83c14';
  ctx.fillRect(16, 20, 8, 12);                                    // rear handle
}

function drawHandDrill(ctx) {
  ctx.fillStyle = '#5a6b7a';
  ctx.fillRect(14, 26, 26, 16);                                   // body
  ctx.fillStyle = '#3f4a55';
  ctx.fillRect(40, 30, 18, 8);                                    // chuck
  ctx.fillStyle = '#8d949b';
  ctx.fillRect(56, 31, 6, 6);                                     // bit
  ctx.fillStyle = '#3a3f45';
  ctx.fillRect(18, 40, 8, 16);                                    // grip
}

function drawPneumaticDrill(ctx) {
  ctx.fillStyle = '#3f5566';
  ctx.fillRect(20, 12, 14, 32);                                   // body
  ctx.fillStyle = '#2f4250';
  ctx.fillRect(16, 10, 22, 8);                                    // handles bar
  ctx.fillStyle = '#8d949b';
  ctx.fillRect(24, 44, 6, 16);                                    // bit
}

// A tracked/wheeled machine body with a boom arm and a bucket at the end,
// scaled and coloured per tier — miniDigger, excavator, earthMover.
function drawDiggerRig(ctx, color, scale) {
  const s = scale;
  ctx.save();
  ctx.translate(32, 40);
  ctx.scale(s, s);
  ctx.fillStyle = '#3a3f45';
  ctx.fillRect(-20, 6, 40, 10);                                   // tracks
  ctx.fillStyle = shade(color, -10);
  ctx.fillRect(-14, -8, 28, 16);                                  // body
  ctx.fillStyle = color;
  ctx.fillRect(-14, -8, 28, 6);                                   // cab band
  ctx.strokeStyle = shade(color, -30);
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(4, -6); ctx.lineTo(20, -22); ctx.lineTo(28, -12);     // boom + stick
  ctx.stroke();
  ctx.fillStyle = shade(color, -20);
  poly(ctx, [[26, -14], [34, -8], [28, -2], [22, -8]], shade(color, -20));  // bucket
  ctx.restore();
}

// A tracked machine with a felling head instead of a bucket — fellingMachine
// and fellingHarvester.
function drawFellerRig(ctx, color, scale) {
  const s = scale;
  ctx.save();
  ctx.translate(32, 40);
  ctx.scale(s, s);
  ctx.fillStyle = '#3a3f45';
  ctx.fillRect(-20, 6, 40, 10);
  ctx.fillStyle = shade(color, -10);
  ctx.fillRect(-14, -8, 28, 16);
  ctx.fillStyle = color;
  ctx.fillRect(-14, -8, 28, 6);
  ctx.strokeStyle = shade(color, -30);
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(4, -6); ctx.lineTo(22, -20);
  ctx.stroke();
  ctx.fillStyle = shade(color, -20);
  ctx.beginPath();
  ctx.arc(24, -20, 8, 0, Math.PI * 2);                            // felling disc head
  ctx.fill();
  ctx.strokeStyle = '#1c1f22';
  ctx.lineWidth = 1.5;
  for (let a = 0; a < 6; a++) {
    const t = (a / 6) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(24, -20);
    ctx.lineTo(24 + Math.cos(t) * 8, -20 + Math.sin(t) * 8);
    ctx.stroke();
  }
  ctx.restore();
}

// A digger rig with a drill/auger on the arm instead of a bucket —
// rockDigger, rockExcavator, rockDestroyer.
function drawDrillRig(ctx, color, scale) {
  const s = scale;
  ctx.save();
  ctx.translate(32, 40);
  ctx.scale(s, s);
  ctx.fillStyle = '#3a3f45';
  ctx.fillRect(-20, 6, 40, 10);
  ctx.fillStyle = shade(color, -10);
  ctx.fillRect(-14, -8, 28, 16);
  ctx.fillStyle = color;
  ctx.fillRect(-14, -8, 28, 6);
  ctx.strokeStyle = shade(color, -30);
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(4, -6); ctx.lineTo(20, -22); ctx.lineTo(30, -14);
  ctx.stroke();
  ctx.strokeStyle = shade(color, -20);
  ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(30, -14); ctx.lineTo(40, -6); ctx.stroke();  // drill bit
  ctx.fillStyle = shade(color, -20);
  for (let i = 0; i < 3; i++) ctx.fillRect(30 + i * 3.5, -15 + i * 3, 3, 3); // auger flutes
  ctx.restore();
}

const TOOL_ICONS = {
  spade:            drawSpade,
  axe:              drawAxe,
  hammer:           drawHammer,
  pickaxe:          drawPickaxe,
  electricSpade:    drawElectricSpade,
  miniDigger:       (ctx, color) => drawDiggerRig(ctx, color, 0.7),
  excavator:        (ctx, color) => drawDiggerRig(ctx, color, 0.95),
  earthMover:       (ctx, color) => drawDiggerRig(ctx, color, 1.2),
  chainsaw:         drawChainsaw,
  fellingMachine:   (ctx, color) => drawFellerRig(ctx, color, 0.8),
  fellingHarvester: (ctx, color) => drawFellerRig(ctx, color, 1.1),
  handDrill:        drawHandDrill,
  pneumaticDrill:   drawPneumaticDrill,
  rockDigger:       (ctx, color) => drawDrillRig(ctx, color, 0.8),
  rockExcavator:    (ctx, color) => drawDrillRig(ctx, color, 1.0),
  rockDestroyer:    (ctx, color) => drawDrillRig(ctx, color, 1.25),
};

function drawSniper(ctx) {
  ctx.save();
  ctx.translate(32, 32);
  ctx.rotate(-0.12);
  ctx.fillStyle = '#37412f';
  ctx.fillRect(-28, -3, 50, 6);                                  // barrel
  ctx.fillStyle = '#2a3122';
  ctx.fillRect(18, -7, 15, 14);                                  // stock
  ctx.fillStyle = '#14170f';
  ctx.fillRect(-11, -17, 22, 6);                                 // scope tube
  ctx.beginPath();
  ctx.arc(-11, -14, 4, 0, Math.PI * 2);
  ctx.fillStyle = '#4a6fa5';                                     // lens glint
  ctx.fill();
  ctx.fillStyle = '#22271a';
  ctx.fillRect(6, 2, 8, 13);                                     // grip
  ctx.restore();
}

const WEAPON_ICONS = {
  pistol:   drawPistol,
  shotgun:  drawShotgun,
  chaingun: drawChaingun,
  rocket:   drawRocket,
  nuke:     drawNuke,
  sniper:   drawSniper,
};

// ── Public ───────────────────────────────────────────────

// Returns a data URL for an inventory item, or null if there's nothing to draw.
export function itemIconUrl(item) {
  if (!item) return null;
  const key = item.kind === 'weapon' ? 'w:' + item.weaponKey
            : item.kind === 'vehicle' ? 'v:' + item.vehicleKey
            : item.kind === 'tool' ? 't:' + item.toolKey
            : 'b:' + item.id;
  const hit = cache.get(key);
  if (hit) return hit;

  const { canvas, ctx } = newCanvas();
  if (item.kind === 'weapon') {
    const draw = WEAPON_ICONS[item.weaponKey];
    if (!draw) return null;
    draw(ctx);
  } else if (item.kind === 'vehicle') {
    const draw = VEHICLE_ICONS[item.vehicleKey];
    if (!draw) return null;
    draw(ctx);
  } else if (item.kind === 'tool') {
    const draw = TOOL_ICONS[item.toolKey];
    if (!draw) return null;
    draw(ctx, hex(TOOL_TYPES[item.toolKey].color));
  } else {
    if (!BLOCK_NAMES[item.id]) return null;
    drawBlockIcon(ctx, item.id);
  }

  const url = canvas.toDataURL();
  cache.set(key, url);
  return url;
}
