// Turns whatever last hit the player into a death-screen message — the
// actual cause, with a bit of variety, rather than one fixed line regardless
// of what actually killed you.
//
// Pure text generation: no game state, so it's trivial to test every branch
// without a world or a player object.

import { MOB_TYPES } from './entities/mobTypes.js';

const FALL_LINES = [
  'Died from fall damage.',
  'Gravity won that one.',
  'Took the fast way down.',
  'Forgot to pack a parachute.',
];

const CRASH_LINES = [
  'Died in a fiery crash.',
  'That landing did not go well.',
  'Should have throttled down sooner.',
  'Walked away from many landings. Not that one.',
];

const EXPLOSION_LINES = [
  'Blew yourself up.',
  'Stood too close to your own explosion.',
  'Learned the hard way what "blast radius" means.',
];

const MOB_VERBS = [
  'Taken out by', 'Wiped out by', 'Completely dismantled by',
  'Flattened by', 'Sent flying by', 'Put down by',
];

const PLAYER_VERBS = [
  'Taken out by', 'Wiped out by', 'Completely dismantled by',
  'Destroyed by', 'Humiliated by', 'Put down by',
];

const GENERIC_LINES = ['You died.'];

const CONSOLE_LINES = [
  'Died by dev console.',
  'Smitten by the /kill command.',
  'Chose the console over living.',
];

function pick(list) { return list[Math.floor(Math.random() * list.length)]; }

// "a Ghoul" vs "an unknown horror" — only mob labels need this; player names don't.
function withArticle(label) {
  return (/^[aeiou]/i.test(label) ? 'an ' : 'a ') + label;
}

// `source` is whatever player.lastDamageSource holds: null, or
// { kind: 'fall' | 'crash' | 'explosion' | 'mob' | 'player', ...details }.
export function deathMessage(source) {
  if (!source) return pick(GENERIC_LINES);

  switch (source.kind) {
    case 'fall':      return pick(FALL_LINES);
    case 'crash':     return pick(CRASH_LINES);
    case 'explosion': return pick(EXPLOSION_LINES);
    case 'console':   return pick(CONSOLE_LINES);
    case 'mob': {
      const label = MOB_TYPES[source.mobType]?.label || 'something';
      return `${pick(MOB_VERBS)} ${withArticle(label)}.`;
    }
    case 'player': {
      const name = source.name || 'another player';
      return `${pick(PLAYER_VERBS)} ${name}.`;
    }
    default: return pick(GENERIC_LINES);
  }
}
