// Heads-up display: health bar, item name popup, damage flash, debug toggle.
// Pure rendering — callers pass in the values to show.

import { healthColorCss } from './healthColor.js';
import { WATER, UNDERWATER_TINT } from '../world/blocks.js';

let labelTimer = null;

// Derives the overlay's two CSS gradient stops from a single tint hex
// (world/blocks.js's UNDERWATER_TINT) rather than hand-picking rgba pairs
// per liquid — the inner stop is lightened so the "looking through it"
// vignette still pops against the (darker) outer stop, the same relationship
// the original hand-tuned water-only version had.
function hexToRgb(hex) { return { r: (hex >> 16) & 0xff, g: (hex >> 8) & 0xff, b: hex & 0xff }; }
function rgba({ r, g, b }, a) { return `rgba(${r},${g},${b},${a})`; }
function lighten({ r, g, b }, amt) {
  return { r: Math.min(255, r + amt), g: Math.min(255, g + amt), b: Math.min(255, b + amt) };
}

// Green when full, through amber, to red near zero — the same ramp used above
// mobs and other players.
export function updateHpBar(hp, maxHp) {
  const fraction = maxHp > 0 ? hp / maxHp : 0;
  const el = document.getElementById('hp-bar-fill');
  if (el) {
    el.style.width = (fraction * 100) + '%';
    el.style.background = healthColorCss(fraction);
  }
  const txt = document.getElementById('hp-text');
  if (txt) txt.textContent = hp + ' / ' + maxHp;
}

// Score, personal best, and how far the difficulty spiral has wound up.
export function updateScoreDisplay(score, best, threat) {
  const scoreEl = document.getElementById('score-value');
  if (scoreEl) scoreEl.textContent = score.toLocaleString();
  const bestEl = document.getElementById('score-best');
  if (bestEl) bestEl.textContent = best > 0 ? 'best ' + best.toLocaleString() : '';

  const fill = document.getElementById('threat-fill');
  if (fill) {
    fill.style.width = (threat * 100).toFixed(0) + '%';
    // Threat runs the opposite way to health: harmless green up to lethal red.
    fill.style.background = healthColorCss(1 - threat);
  }
  const label = document.getElementById('threat-label');
  if (label) label.textContent = 'Threat ' + Math.round(threat * 100) + '%';
}

export function setHpBarVisible(visible) {
  const hpBar = document.getElementById('hp-bar');
  if (hpBar) hpBar.style.display = visible ? '' : 'none';
}

// Transient text above the hotbar, e.g. the name of the selected item.
export function showLabel(text) {
  const el = document.getElementById('block-label');
  if (!el) return;
  el.textContent = text;
  el.classList.add('show');
  clearTimeout(labelTimer);
  labelTimer = setTimeout(() => el.classList.remove('show'), 1500);
}

// The ring around the crosshair (index.html/style.css) — `fraction` is
// 0..1, or null to hide it entirely. Deliberately separate from the crack
// decal on the block itself (render/crackTexture.js): that decal is
// randomised/organic on purpose (it's meant to look like real damage, not
// a progress meter), which makes it a poor way to judge exactly how much
// longer a block has left — this ring is the plain, linear answer to that,
// shown alongside it rather than instead of it.
export function setMiningProgress(fraction) {
  const ring = document.getElementById('mining-progress');
  if (!ring) return;
  if (fraction === null) {
    ring.classList.remove('show');
    return;
  }
  ring.classList.add('show');
  ring.style.setProperty('--mining-pct', String(Math.max(0, Math.min(1, fraction)) * 100));
}

export function setDamageFlash(opacity) {
  const flash = document.getElementById('damage-flash');
  if (flash) flash.style.opacity = String(opacity);
}

// The coloured tint over the whole screen while the eye is inside a liquid
// block — which colour depends on `liquidId` (a block id, or null), so a
// planet's own acid/magma/cryofluid reads as visibly different from plain
// water, not just "underwater" in the abstract.
export function setUnderwaterOverlay(active, liquidId = null) {
  const el = document.getElementById('underwater-overlay');
  if (!el) return;
  el.classList.toggle('visible', active);
  if (active) {
    const base = hexToRgb(UNDERWATER_TINT[liquidId] ?? UNDERWATER_TINT[WATER]);
    el.style.setProperty('--underwater-inner', rgba(lighten(base, 55), 0.28));
    el.style.setProperty('--underwater-outer', rgba(base, 0.55));
  }
}

// The sniper scope's vignette-and-crosshair, shown instead of the normal
// crosshair while aiming down it.
export function setScopeOverlay(active) {
  const el = document.getElementById('scope-overlay');
  if (el) el.classList.toggle('hidden', !active);
  const crosshair = document.getElementById('crosshair');
  if (crosshair) crosshair.style.display = active ? 'none' : '';
}

// Full-white screen flash used by the nuke, separate from the red damage flash.
export function whiteFlash() {
  const flash = document.getElementById('damage-flash');
  if (!flash) return;
  flash.style.transition = 'none';
  flash.style.background = '#fff';
  flash.style.opacity = '0.8';
  requestAnimationFrame(() => {
    flash.style.transition = 'opacity 0.6s';
    flash.style.opacity = '0';
    setTimeout(() => { flash.style.background = '#c00'; flash.style.transition = ''; }, 650);
  });
}

// Score, the hotbar and the F3 debug readout belong to actual gameplay
// only. Their own stacking order already sits below every full-screen menu
// (loading/title/pause), but those menus' backdrop is a translucent tint
// over the nebula image rather than a fully opaque layer, so relying on
// z-index alone still let bright HUD text bleed through underneath them.
// Call this after showing/hiding any of the three menu screens (ui/overlay.js,
// ui/titleScreen.js) so it can never drift out of sync with what's on screen.
export function syncMenuHudVisibility() {
  const isShown = id => {
    const el = document.getElementById(id);
    return !!el && !el.classList.contains('hidden');
  };
  const anyMenuOpen = isShown('loading-screen') || isShown('title-screen') || isShown('overlay');
  document.body.classList.toggle('menu-open', anyMenuOpen);
}

export function toggleDebug() {
  const dbg = document.getElementById('debug');
  if (!dbg) return;
  dbg.style.display = dbg.style.display === 'none' ? '' : 'none';
}

export function isDebugVisible() {
  const dbg = document.getElementById('debug');
  return !!dbg && dbg.style.display !== 'none';
}

export function setDebugText(text) {
  const dbg = document.getElementById('debug');
  if (dbg) dbg.textContent = text;
}
