// Mob death animations. Each type dies its own way, and the mob is only
// removed once its animation finishes.
//
// The animations move the MESH, not the mob's collision box — a dying mob is
// out of the fight, so it doesn't need to collide with anything. Everything is
// driven off `mob.deathT` (seconds since death) so the routines stay readable.
//
// Nothing here fades a mob's material: mobs share one material, and cloning it
// per corpse would cost a shader program each. Scale-to-nothing plus particles
// gives the same "pop" for free.

import * as THREE from 'three';
import { GRAVITY } from '../config.js';
import { player } from '../player/state.js';
import { spawnBurst, spawnShockwave } from './deathFx.js';

const LAUNCH_DURATION     = 1.05;
const FACEPLANT_DURATION  = 1.35;
const FACEPLANT_IMPACT    = 0.5;    // seconds in, when the body hits the floor
const COLLAPSE_DURATION   = 0.9;
const SHATTER_DURATION    = 0.7;
const INCINERATE_DURATION = 0.85;
const FREEZE_DURATION     = 0.85;
const DISSOLVE_DURATION   = 0.8;

const DURATIONS = {
  launch:     LAUNCH_DURATION,
  faceplant:  FACEPLANT_DURATION,
  collapse:   COLLAPSE_DURATION,
  shatter:    SHATTER_DURATION,
  incinerate: INCINERATE_DURATION,
  freeze:     FREEZE_DURATION,
  dissolve:   DISSOLVE_DURATION,
};

const away = new THREE.Vector3();

// Direction from the player to the mob, so corpses fly away from the shot.
function awayFromPlayer(mob) {
  away.set(mob.pos.x - player.pos.x, 0, mob.pos.z - player.pos.z);
  if (away.lengthSq() < 1e-4) away.set(1, 0, 0);
  return away.normalize();
}

export function beginDeath(mob) {
  mob.dying = true;
  mob.deathT = 0;
  mob.impacted = false;
  const style = mob.typeDef.deathStyle;
  mob.deathDuration = DURATIONS[style] ?? LAUNCH_DURATION;

  const c = mob.typeDef.colors;
  const mid = mob.pos.clone();
  mid.y += mob.typeDef.height * 0.5;

  if (style === 'launch') {
    // Ghoul gets yeeted: launched backwards, tumbling end over end.
    const dir = awayFromPlayer(mob);
    mob.deathVel = new THREE.Vector3(dir.x * 7, 13, dir.z * 7);
    mob.deathSpin = 16 + Math.random() * 8;
    mob.impacted = true;   // no ground impact beat in this one
    spawnBurst(mid, { color: c.shirt, count: 26, speed: 7, upBias: 4, size: 0.16, life: 0.9 });
    spawnBurst(mid, { color: 0x222244, count: 14, speed: 5, upBias: 3, size: 0.12, life: 1.0 });
  } else if (style === 'faceplant') {
    // Wretch topples like a felled tree and slams into the floor.
    mob.deathVel = new THREE.Vector3(0, 0, 0);
    mob.deathSpin = 0;
    spawnBurst(mid, { color: c.shirt, count: 12, speed: 2.5, upBias: 1.5, size: 0.12, life: 0.6 });
  }
  // collapse/shatter/incinerate/freeze/dissolve all start their own particle
  // beat partway through updateDeath below (mob.impacted gates it) rather
  // than on this very first frame.
}

// Advances the animation. Returns true when the mob should be removed.
export function updateDeath(mob, dt) {
  mob.deathT += dt;
  const t = mob.deathT;
  const mesh = mob.mesh;

  switch (mob.typeDef.deathStyle) {
    case 'launch':      updateLaunch(mob, dt, t, mesh); break;
    case 'faceplant':   updateFaceplant(mob, dt, t, mesh); break;
    case 'collapse':    updateCollapse(mob, t, mesh); break;
    case 'shatter':     updateShatter(mob, t, mesh); break;
    case 'incinerate':  updateIncinerate(mob, t, mesh); break;
    case 'freeze':      updateFreeze(mob, t, mesh); break;
    case 'dissolve':    updateDissolve(mob, t, mesh); break;
    default:            updateLaunch(mob, dt, t, mesh); break;
  }

  return t >= mob.deathDuration;
}

// ── Ghoul: launched, spinning, then confetti ─────────────
function updateLaunch(mob, dt, t, mesh) {
  const p = t / mob.deathDuration;

  // Floaty gravity so the arc hangs long enough to enjoy.
  mob.deathVel.y += GRAVITY * 0.55 * dt;
  mob.pos.addScaledVector(mob.deathVel, dt);

  mesh.position.copy(mob.pos);
  mesh.rotation.z += mob.deathSpin * dt;
  mesh.rotation.y += mob.deathSpin * 0.6 * dt;

  // Squash-and-stretch wobble, then shrink away over the last third.
  const wobble = 1 + Math.sin(t * 26) * 0.18 * (1 - p);
  const shrink = p < 0.66 ? 1 : 1 - (p - 0.66) / 0.34;
  mesh.scale.setScalar(Math.max(0.001, wobble * shrink));

  // Confetti pop as it vanishes.
  if (!mob.popped && p >= 0.66) {
    mob.popped = true;
    const c = mob.typeDef.colors;
    spawnBurst(mob.pos, { color: c.shorts, count: 30, speed: 8, upBias: 2, size: 0.13, life: 0.7 });
    spawnBurst(mob.pos, { color: c.shirt,  count: 20, speed: 6, upBias: 2, size: 0.11, life: 0.7 });
  }
}

// ── Wretch: stiff timber-fall, ground slam, then flattened ──
function updateFaceplant(mob, dt, t, mesh) {
  mesh.position.copy(mob.pos);

  if (t < FACEPLANT_IMPACT) {
    // Tip over, accelerating as it goes — like a felled tree.
    const p = t / FACEPLANT_IMPACT;
    const eased = p * p;
    mesh.rotation.x = -eased * (Math.PI / 2);
    // Rock slightly on the way down.
    mesh.rotation.z = Math.sin(t * 18) * 0.08 * (1 - p);
    mesh.scale.set(1, 1, 1);
    return;
  }

  if (!mob.impacted) {
    mob.impacted = true;
    const c = mob.typeDef.colors;
    spawnShockwave(mob.pos, { color: 0xd9c9a3, maxRadius: 5, life: 0.55 });
    spawnBurst(mob.pos, { color: 0xd9c9a3, count: 34, speed: 7, upBias: 1.5, size: 0.15, life: 0.8, gravityScale: 0.7 });
    spawnBurst(mob.pos, { color: c.shirt,  count: 16, speed: 4, upBias: 3, size: 0.13, life: 0.7 });
  }

  // Flattened into the floor, spreading out as it goes.
  const p = (t - FACEPLANT_IMPACT) / (mob.deathDuration - FACEPLANT_IMPACT);
  mesh.rotation.x = -Math.PI / 2;
  const squash = Math.max(0.001, 1 - p);
  const spread = 1 + p * 0.7;
  // Hold the pancake briefly, then shrink it out of existence.
  const vanish = p < 0.55 ? 1 : 1 - (p - 0.55) / 0.45;
  mesh.scale.set(spread * vanish, squash * vanish, spread * vanish);
}

// ── Husk: crumbles straight down into dust, no toppling ──
function updateCollapse(mob, t, mesh) {
  const p = t / mob.deathDuration;
  mesh.position.copy(mob.pos);
  mesh.position.y -= p * mob.typeDef.height * 0.55;

  if (!mob.impacted && p >= 0.3) {
    mob.impacted = true;
    const c = mob.typeDef.colors;
    const mid = mob.pos.clone();
    mid.y += mob.typeDef.height * 0.4;
    spawnBurst(mid, { color: c.skin, count: 24, speed: 3, upBias: 1, size: 0.13, life: 0.7, gravityScale: 0.6 });
    spawnBurst(mid, { color: c.shirt, count: 12, speed: 2, upBias: 0.5, size: 0.11, life: 0.6, gravityScale: 0.6 });
  }

  const squash = Math.max(0.001, 1 - p * 0.9);
  mesh.scale.set(1 + p * 0.12, squash, 1 + p * 0.12);
}

// ── Shard Stalker: freezes, cracks, then bursts into shards ──
function updateShatter(mob, t, mesh) {
  mesh.position.copy(mob.pos);
  const p = t / mob.deathDuration;

  if (p < 0.4) {
    // A quick crack-shudder before it lets go.
    mesh.rotation.z = Math.sin(t * 40) * 0.05;
    mesh.scale.setScalar(1);
    return;
  }

  if (!mob.impacted) {
    mob.impacted = true;
    const c = mob.typeDef.colors;
    const mid = mob.pos.clone();
    mid.y += mob.typeDef.height * 0.5;
    spawnBurst(mid, { color: c.glasses, count: 28, speed: 9, upBias: 3, size: 0.12, life: 0.6 });
    spawnBurst(mid, { color: c.skin,    count: 16, speed: 6, upBias: 2, size: 0.1,  life: 0.55 });
  }

  const p2 = (p - 0.4) / 0.6;
  mesh.scale.setScalar(Math.max(0.001, 1 - p2));
}

// ── Cinderfiend: burns up on the spot, ash and embers ──
function updateIncinerate(mob, t, mesh) {
  mesh.position.copy(mob.pos);
  const p = t / mob.deathDuration;
  mesh.rotation.z = Math.sin(t * 22) * 0.15 * (1 - p);

  if (!mob.impacted && p >= 0.15) {
    mob.impacted = true;
    const mid = mob.pos.clone();
    mid.y += mob.typeDef.height * 0.5;
    spawnBurst(mid, { color: 0xff7a1a, count: 30, speed: 5, upBias: 4, size: 0.15, life: 0.9, gravityScale: 0.3 });
    spawnBurst(mid, { color: 0x2a2a2a, count: 14, speed: 3, upBias: 5, size: 0.14, life: 1.0, gravityScale: 0.15 });
  }

  mesh.scale.setScalar(Math.max(0.001, 1 - p));
}

// ── Frostbiter: locks rigid, then crumples forward into ice chunks ──
function updateFreeze(mob, t, mesh) {
  mesh.position.copy(mob.pos);
  const p = t / mob.deathDuration;

  if (p < 0.35) {
    mesh.rotation.x = 0;
    mesh.scale.setScalar(1 + p * 0.08);   // faint expansion, like frost forming
    return;
  }

  if (!mob.impacted) {
    mob.impacted = true;
    const c = mob.typeDef.colors;
    const mid = mob.pos.clone();
    mid.y += mob.typeDef.height * 0.5;
    spawnBurst(mid, { color: 0xdff5ff, count: 22, speed: 4, upBias: 0.5, size: 0.11, life: 0.6, gravityScale: 1.1 });
    spawnBurst(mid, { color: c.skin,   count: 14, speed: 3, upBias: 0,   size: 0.1,  life: 0.55, gravityScale: 1.2 });
  }

  const p2 = (p - 0.35) / 0.65;
  mesh.rotation.x = p2 * (Math.PI / 2) * 0.6;   // crumples forward
  mesh.scale.setScalar(Math.max(0.001, 1.08 * (1 - p2)));
}

// ── Bloatspore: bloats, then pops into a toxic puddle ──
function updateDissolve(mob, t, mesh) {
  mesh.position.copy(mob.pos);
  const p = t / mob.deathDuration;

  if (p < 0.3) {
    const bloat = 1 + Math.sin((p / 0.3) * Math.PI) * 0.25;
    mesh.scale.set(bloat, 1, bloat);
    return;
  }

  if (!mob.impacted) {
    mob.impacted = true;
    const c = mob.typeDef.colors;
    spawnBurst(mob.pos, { color: c.skin, count: 26, speed: 5, upBias: 1.5, size: 0.14, life: 0.7, gravityScale: 0.8 });
    spawnShockwave(mob.pos, { color: c.shirt, maxRadius: 3, life: 0.4 });
  }

  const p2 = (p - 0.3) / 0.7;
  mesh.scale.set(1 + p2 * 0.4, Math.max(0.001, 1 - p2), 1 + p2 * 0.4);
}
