// How long day and night each last, in real minutes. A continuous slider
// like difficulty and render distance, persisted the same way.
//
// The cycle is symmetric by construction — sky.js's day/night split is
// defined by the sun's height, which spends exactly half the cycle above the
// horizon and half below — so setting one number sets both "day lasts N
// minutes" and "night lasts N minutes" at once, matching how they're always
// asked for together.

const STORAGE_KEY = 'blocksDayLength';

export const MIN_DAY_MINUTES = 1;
export const MAX_DAY_MINUTES = 60;
const DEFAULT_DAY_MINUTES = 10;

let dayMinutes = DEFAULT_DAY_MINUTES;
const listeners = [];

export function getDayLengthMinutes() { return dayMinutes; }

export function onDayLengthChange(fn) { listeners.push(fn); }

function clamp(value) {
  return Math.max(MIN_DAY_MINUTES, Math.min(MAX_DAY_MINUTES, Math.round(Number(value) || DEFAULT_DAY_MINUTES)));
}

export function setDayLengthMinutes(value) {
  const next = clamp(value);
  if (next === dayMinutes) return;
  dayMinutes = next;
  try { localStorage.setItem(STORAGE_KEY, String(next)); } catch { /* private mode */ }
  for (const fn of listeners) fn(dayMinutes);
}

// Reads the saved value. Called from main.js so importing this module has no
// side effects.
export function initDayLength() {
  let saved = null;
  try { saved = localStorage.getItem(STORAGE_KEY); } catch { /* private mode */ }
  dayMinutes = saved !== null ? clamp(saved) : DEFAULT_DAY_MINUTES;
  for (const fn of listeners) fn(dayMinutes);
}
