// Weapon definitions. Weapon `id`s start at 100 to stay clear of block IDs.
//
// Where a weapon comes from:
//   worldSpawn — lies around in the world to be walked over. Pistols only.
//   mobDrop    — only obtainable by killing mobs.
//
// Drop rates are DERIVED from how much damage a weapon does, not hand-tuned:
// see weaponPower() below. Add a weapon and its rarity falls out of its stats.
//
//   kind 'hitscan'    — instant ray, uses damage/pellets/spread/range
//   kind 'projectile' — spawns a travelling shell, uses speed/blast*/crater*

export const WEAPON_TYPES = {
  pistol: {
    label: 'Pistol', id: 100, rarity: 'Common', worldSpawn: true,
    kind: 'hitscan', auto: false, pellets: 1,
    damage: 18, fireRate: 3, range: 45, spread: 0.01, ammo: 24,
    color: 0x9aa0a6,
  },
  shotgun: {
    label: 'Shotgun', id: 101, rarity: 'Uncommon', mobDrop: true,
    kind: 'hitscan', auto: false, pellets: 8,
    damage: 9, fireRate: 1.1, range: 16, spread: 0.14, ammo: 16,
    color: 0x6b4a2b,
  },
  chaingun: {
    label: 'Chaingun', id: 102, rarity: 'Rare', mobDrop: true,
    kind: 'hitscan', auto: true, pellets: 1,
    damage: 7, fireRate: 12, range: 50, spread: 0.05, ammo: 150,
    color: 0xcc6600,
  },
  sniper: {
    label: 'Sniper Rifle', id: 105, rarity: 'Rare', mobDrop: true,
    kind: 'hitscan', auto: false, pellets: 1,
    // A body shot is solid but not overwhelming — it's the HEAD_MULTIPLIER in
    // zoneDamage() below (3x) that turns this into a one-shot kill, and
    // that's exactly the shot the scope's sway makes you work for.
    damage: 40, fireRate: 0.8, range: 140, spread: 0.0015, ammo: 5,
    color: 0x37412f, scoped: true,
  },
  rocket: {
    label: 'Rocket Launcher', id: 103, rarity: 'Very Rare', mobDrop: true,
    kind: 'projectile', auto: false,
    damage: 0, fireRate: 0.9, range: 90, ammo: 6, speed: 26,
    blastRadius: 6, blastDamage: 65, craterRadius: 3.5,
    color: 0x3a3a3a,
  },
  nuke: {
    label: 'Nuclear Bomb', id: 104, rarity: 'Ultra Rare', mobDrop: true,
    kind: 'projectile', auto: false,
    damage: 0, fireRate: 0.15, range: 120, ammo: 1, speed: 18,
    blastRadius: 28, blastDamage: 500, craterRadius: 15,
    color: 0x9acd32, glow: true,
  },
};

// How destructive one trigger pull is.
//   hitscan    — damage across all pellets, scaled up for high rates of fire
//   projectile — blast damage, scaled up for how much area it covers
// The exact curve matters less than the ordering it produces:
//   pistol 18 < chaingun 28 < shotgun 72 < rocket 130 < nuke ~2800
export function weaponPower(wd) {
  if (wd.kind === 'projectile') {
    return wd.blastDamage * (1 + wd.blastRadius / 6);
  }
  return wd.damage * (wd.pellets || 1) * Math.max(1, wd.fireRate / 3);
}

// Rarer the harder it hits. Inverse power means the nuke turns up roughly a
// hundred times less often than the chaingun.
export function dropWeight(wd) {
  return 100 / weaponPower(wd);
}

// Where a hitscan shot landed on the target's box scales the damage: a
// headshot is the payoff shot, a torso hit is the weapon's damage exactly as
// listed (so nothing about existing weapons' numbers changes for a
// centre-mass hit), and a limb is barely worth pulling the trigger for.
export const ZONE_MULTIPLIERS = { head: 3, torso: 1, arm: 0.5, leg: 0.5 };

export function zoneDamage(baseDamage, zone) {
  return Math.round(baseDamage * (ZONE_MULTIPLIERS[zone] ?? 1));
}

const worldKeys   = Object.keys(WEAPON_TYPES).filter(k => WEAPON_TYPES[k].worldSpawn);
const mobDropKeys = Object.keys(WEAPON_TYPES).filter(k => WEAPON_TYPES[k].mobDrop);

function pickWeighted(keys) {
  const total = keys.reduce((sum, k) => sum + dropWeight(WEAPON_TYPES[k]), 0);
  let r = Math.random() * total;
  for (const k of keys) {
    r -= dropWeight(WEAPON_TYPES[k]);
    if (r <= 0) return k;
  }
  return keys[keys.length - 1];
}

// What spawns lying around in the world.
export function pickWorldWeapon() { return pickWeighted(worldKeys); }

// What a mob drops when killed.
export function pickMobDropWeapon() { return pickWeighted(mobDropKeys); }

// Each mob-drop weapon's share of drops, as percentages — used by tests and
// handy when retuning.
export function mobDropTable() {
  const total = mobDropKeys.reduce((sum, k) => sum + dropWeight(WEAPON_TYPES[k]), 0);
  return mobDropKeys.map(key => ({
    key,
    power: +weaponPower(WEAPON_TYPES[key]).toFixed(1),
    share: +((dropWeight(WEAPON_TYPES[key]) / total) * 100).toFixed(2),
  }));
}
