// The mining break-progress overlay's own texture: a set of increasingly
// dense damage "chips" (small dark pits, an alpha channel over a
// transparent background), swapped in as progress climbs — the visible
// signal that a block is being mined. Painted onto a canvas at runtime, no
// image assets, the same "no assets to ship or load" approach
// render/textures.js already uses for the block atlas — just an
// alpha-carrying decal instead of a coloured tile, so it can sit on TOP of
// whatever block texture/colour is underneath rather than replacing it.
//
// Every stage draws a PREFIX of the same deterministic dot sequence (one
// fixed random draw, cached once) rather than a fresh scatter per stage —
// so a dot that appears at an early stage is never moved, resized or
// redrawn differently once a later stage reveals more of them alongside
// it. That's what makes mining read as damage genuinely ACCUMULATING in
// place, dot by dot, rather than the pattern jumping to a new arrangement
// every time the stage ticks over.

import * as THREE from 'three';

const SIZE = 64;
export const STAGE_COUNT = 8;

const MIN_DOTS = 3;    // visible the instant mining starts
const MAX_DOTS = 48;   // on screen right before the block breaks

function makeRng(seed) {
  let s = seed >>> 0 || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5;  s >>>= 0;
    return s / 4294967296;
  };
}

// One damage chip: a soft, darker outer disc plus a smaller, darker core —
// reads as a tiny pit/crater rather than a flat, uniform blob.
function drawChip(ctx, x, y, radius, alpha) {
  ctx.beginPath();
  ctx.fillStyle = `rgba(12,9,7,${alpha * 0.5})`;
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.fillStyle = `rgba(8,6,5,${alpha})`;
  ctx.arc(x, y, radius * 0.48, 0, Math.PI * 2);
  ctx.fill();
}

// The one, fixed pool every stage draws its own prefix from — built once
// and cached, deterministic per session run (same seed every time, same as
// textures.js's own tiles) rather than reseeded per stage.
let dotPool = null;
function getDotPool() {
  if (dotPool) return dotPool;
  const rng = makeRng(0xc4ac1);
  dotPool = [];
  for (let i = 0; i < MAX_DOTS; i++) {
    dotPool.push({
      // Kept off the rim, the same "damage spreads from within the block"
      // reasoning the old crack decal used, not scuffs right at the edge.
      x: SIZE * (0.12 + rng() * 0.76),
      y: SIZE * (0.12 + rng() * 0.76),
      radius: SIZE * (0.02 + rng() * 0.05),
      alpha: 0.55 + rng() * 0.4,
    });
  }
  return dotPool;
}

// `stage` is 0-indexed; density scales from "just started" to "about to
// break" across STAGE_COUNT. Growth is deliberately accelerating (density
// raised to a power > 1) so the very first stages stay sparse — a handful
// of chips, not an instant scatter — and density visibly gathers pace
// toward the final stage instead of climbing as a flat line.
function paintStage(ctx, stage) {
  ctx.clearRect(0, 0, SIZE, SIZE);
  const density = (stage + 1) / STAGE_COUNT;
  const count = Math.round(MIN_DOTS + (MAX_DOTS - MIN_DOTS) * Math.pow(density, 1.4));
  const dots = getDotPool();
  for (let i = 0; i < count; i++) {
    const d = dots[i];
    drawChip(ctx, d.x, d.y, d.radius, d.alpha);
  }
}

let stageTextures = null;

// Built once, on first use, and cached — one small canvas per stage. Used
// as a Mesh's `map` directly (see core/scene.js's spaceBreakOverlayMesh and
// player/mining.js's own per-frame stage selection); the material's base
// colour stays white so this texture's own painted colour comes through
// unmultiplied.
export function getCrackStageTexture(stage) {
  if (!stageTextures) {
    stageTextures = [];
    for (let s = 0; s < STAGE_COUNT; s++) {
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = SIZE;
      const ctx = canvas.getContext('2d');
      paintStage(ctx, s);
      const tex = new THREE.CanvasTexture(canvas);
      tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.needsUpdate = true;
      stageTextures.push(tex);
    }
  }
  return stageTextures[Math.max(0, Math.min(STAGE_COUNT - 1, stage))];
}
