// The title screen: shown whenever no game is active
// (ui/overlay.js's own gameActive flag owns exactly when #overlay itself
// shows instead — this module only wires its own two buttons and
// shows/hides its own element). Replaces the old "a world already exists
// at page load, Play just requests pointer lock" startup with an explicit
// New Game / Load Game choice. Randomising the seed each time New Game is
// clicked is main.js's own newGame()'s job, not this view's.

import { syncMenuHudVisibility } from './hud.js';

export function initTitleScreen({ onNewGame, onLoadGameRequest }) {
  const newBtn = document.getElementById('new-game-btn');
  if (newBtn) newBtn.addEventListener('click', onNewGame);

  const loadBtn = document.getElementById('load-game-btn');
  if (loadBtn) loadBtn.addEventListener('click', onLoadGameRequest);
}

export function showTitleScreen() {
  const el = document.getElementById('title-screen');
  if (el) el.classList.remove('hidden');
  syncMenuHudVisibility();
}

export function hideTitleScreen() {
  const el = document.getElementById('title-screen');
  if (el) el.classList.add('hidden');
  syncMenuHudVisibility();
}
