// Developer console — toggled with ` (backtick).
//
// Commands are plain strings like `/give grass 64` or `/tp 100 80 100`.
// All game side-effects are injected via initDevConsole() so this module
// stays a pure view/router with no direct game imports.
//
// Autocomplete: pressing Tab (or ArrowRight at end-of-input) accepts the
// highlighted suggestion. Whenever there's more than one candidate for
// whatever's currently being typed, ArrowUp/Down cycles through them
// instead of browsing command history — history browsing only kicks in
// once there's nothing left to complete (0 or 1 candidates).

let handlers = {};   // filled by initDevConsole
let isOpen = false;

// ── History ──────────────────────────────────────────────

const MAX_HISTORY = 64;
const history = [];
let historyIdx = -1;   // -1 = not browsing history

// ── DOM refs ─────────────────────────────────────────────

function el(id) { return document.getElementById(id); }

function logLine(text, kind = 'info') {
  const log = el('dev-console-log');
  if (!log) return;
  const line = document.createElement('div');
  line.className = 'dcl-line dcl-' + kind;
  line.textContent = text;
  log.appendChild(line);
  // Keep at most 200 lines so the DOM doesn't balloon.
  while (log.children.length > 200) log.removeChild(log.firstChild);
  log.scrollTop = log.scrollHeight;
}

// ── Suggestion engine ─────────────────────────────────────
//
// A command declares its own completable options via `completions(parts)`
// — a function returning the full list of valid strings for whatever
// argument slot is currently being typed (not yet filtered by prefix; the
// engine below does that centrally, once, for every command alike).

let suggestionPrefix = '';       // the exact substring already typed for the slot being completed
let suggestionCandidates = [];   // full matching strings (not suffixes), sorted
let suggestionIndex = 0;         // which candidate is currently highlighted

// Recomputes candidates for the CURRENT input value and resets which one is
// highlighted back to the first match — called whenever the underlying text
// actually changes (typing, accepting a suggestion, browsing history).
function refreshSuggestions(value) {
  const trimmed = value.trimStart();
  suggestionPrefix = '';
  suggestionCandidates = [];
  suggestionIndex = 0;
  if (!trimmed) { renderGhost(); return; }

  const parts = trimmed.split(/\s+/);
  const cmd = parts[0];

  if (parts.length === 1 && !trimmed.endsWith(' ')) {
    // Still typing the command name itself.
    suggestionPrefix = cmd;
    suggestionCandidates = Object.keys(handlers)
      .filter(k => k.toLowerCase().startsWith(cmd.toLowerCase()))
      .sort();
    renderGhost();
    return;
  }

  const h = handlers[cmd];
  const argParts = parts.slice(1);
  // Every command here only ever completes its FIRST argument slot — a
  // trailing count, coordinate, etc. never has a meaningful completion list.
  if (h && h.completions && argParts.length <= 1) {
    suggestionPrefix = argParts[0] || '';
    const options = h.completions(argParts) || [];
    suggestionCandidates = options
      .filter(o => o.toLowerCase().startsWith(suggestionPrefix.toLowerCase()))
      .sort();
  }
  renderGhost();
}

function renderGhost() {
  const input = el('dev-console-input');
  const ghost = el('dev-console-ghost');
  if (!input || !ghost) return;
  const candidate = suggestionCandidates[suggestionIndex];
  const suffix = candidate ? candidate.slice(suggestionPrefix.length) : '';
  // The ghost span shares the input's own left edge (see style.css), so its
  // text has to start with an invisible copy of whatever's already typed —
  // without it, the suggestion renders UNDER the typed text instead of
  // after it, since both would otherwise start at x=0.
  ghost.textContent = '';
  const typed = document.createElement('span');
  typed.style.visibility = 'hidden';
  typed.textContent = input.value;
  ghost.appendChild(typed);
  ghost.appendChild(document.createTextNode(suffix));
}

// ── Open / close ──────────────────────────────────────────

export function isConsoleOpen() { return isOpen; }

export function openConsole() {
  if (isOpen) return;
  isOpen = true;
  const panel = el('dev-console');
  if (panel) panel.classList.remove('hidden');
  const input = el('dev-console-input');
  if (input) { input.value = ''; input.focus(); }
  refreshSuggestions('');
}

export function closeConsole() {
  if (!isOpen) return;
  isOpen = false;
  const panel = el('dev-console');
  if (panel) panel.classList.add('hidden');
  const input = el('dev-console-input');
  if (input) input.blur();
}

export function toggleConsole() {
  if (isOpen) closeConsole();
  else openConsole();
}

// ── Command execution ─────────────────────────────────────

function execute(raw) {
  const text = raw.trim();
  if (!text) return;

  // Push to history (dedup consecutive identical).
  if (history[history.length - 1] !== text) {
    history.push(text);
    if (history.length > MAX_HISTORY) history.shift();
  }
  historyIdx = -1;

  logLine('> ' + text, 'input');

  const parts = text.split(/\s+/);
  const cmd   = parts[0];
  const args  = parts.slice(1);

  const h = handlers[cmd];
  if (!h) {
    logLine(`Unknown command: "${cmd}". Type /help for a list.`, 'error');
    return;
  }
  try {
    const result = h.run(args);
    if (result) logLine(result, 'ok');
  } catch (err) {
    logLine('Error: ' + err.message, 'error');
  }
}

// ── Init ──────────────────────────────────────────────────

export function initDevConsole({
  // Inventory — a single name -> giver function, built in main.js from the
  // real block/weapon/vehicle/tool tables (see its own comment for why).
  giveItem, givableItemNames,
  // Mob spawning
  spawnMobs, mobTypeNames,
  // Player position + velocity
  player,
  // Sky time
  setDayTime,
  // Settings
  setDayLengthMinutes, getDayLengthMinutes,
  setRenderDistance, getRenderDistance,
  setSlider, getSlider,
  setGraphics, getGraphics,
  setGameMode,
  // HP
  hurtPlayer, killPlayer, refreshHpBar,
}) {
  // ── Command registry ────────────────────────────────────

  // /give <block|weapon|vehicle|tool> [count]
  handlers['/give'] = {
    usage: '/give <item> [count]',
    desc:  'Add an item to your inventory. No item lists everything givable.',
    completions: () => givableItemNames,
    run(args) {
      if (!args[0]) {
        logLine('Give any of:', 'info');
        logLine('  ' + [...givableItemNames].sort().join(', '), 'info');
        return null;
      }
      const name  = args[0].toLowerCase();
      const count = Math.max(1, Math.min(9999, parseInt(args[1]) || 1));
      return giveItem(name, count);
    },
  };

  // /tp <x> <y> <z>
  handlers['/tp'] = {
    usage: '/tp <x> <y> <z>',
    desc:  'Teleport to world coordinates.',
    run(args) {
      const [x, y, z] = args.map(Number);
      if ([x, y, z].some(v => !Number.isFinite(v))) throw new Error('Usage: ' + handlers['/tp'].usage);
      player.pos.set(x, y, z);
      player.vel.set(0, 0, 0);
      player.fallStartY = null;   // reset fall tracking; physicsStep recomputes it fresh next tick
      return `Teleported to ${x.toFixed(1)} ${y.toFixed(1)} ${z.toFixed(1)}`;
    },
  };

  // /pos — print current coordinates
  handlers['/pos'] = {
    usage: '/pos',
    desc:  'Print your current coordinates.',
    run() {
      const { x, y, z } = player.pos;
      return `Position: ${x.toFixed(2)} ${y.toFixed(2)} ${z.toFixed(2)}`;
    },
  };

  // /time <0..1 | dawn|day|dusk|night>
  handlers['/time'] = {
    usage: '/time <0–1 | dawn | day | dusk | night>',
    desc:  'Set the time of day (0=midnight, 0.25=dawn, 0.5=noon, 0.75=dusk).',
    completions: () => ['dawn', 'day', 'dusk', 'night'],
    run(args) {
      const PRESETS = { dawn: 0.25, day: 0.5, dusk: 0.75, night: 0.0 };
      if (!args[0]) throw new Error('Usage: ' + handlers['/time'].usage);
      const raw = args[0].toLowerCase();
      const t = raw in PRESETS ? PRESETS[raw] : parseFloat(raw);
      if (!Number.isFinite(t) || t < 0 || t > 1) throw new Error('Time must be 0–1 or a preset name');
      setDayTime(t);
      return `Time set to ${t.toFixed(3)} (${raw})`;
    },
  };

  // /daylength <minutes>
  handlers['/daylength'] = {
    usage: '/daylength <minutes>',
    desc:  'Set the day/night cycle length in minutes (1–60).',
    run(args) {
      const v = parseInt(args[0]);
      if (!Number.isFinite(v)) throw new Error('Usage: ' + handlers['/daylength'].usage);
      setDayLengthMinutes(v);
      return `Day length set to ${getDayLengthMinutes()} min`;
    },
  };

  // /renderdist <chunks>
  handlers['/renderdist'] = {
    usage: '/renderdist <chunks>',
    desc:  'Set render distance in chunks.',
    run(args) {
      const v = parseInt(args[0]);
      if (!Number.isFinite(v)) throw new Error('Usage: ' + handlers['/renderdist'].usage);
      setRenderDistance(v);
      return `Render distance set to ${getRenderDistance()} chunks`;
    },
  };

  // /difficulty <1..100>
  handlers['/difficulty'] = {
    usage: '/difficulty <1–100>',
    desc:  'Set the difficulty slider (1–100).',
    run(args) {
      const v = parseInt(args[0]);
      if (!Number.isFinite(v)) throw new Error('Usage: ' + handlers['/difficulty'].usage);
      setSlider(v);
      return `Difficulty set to ${getSlider()}`;
    },
  };

  // /graphics <potato|nextlevel>
  handlers['/graphics'] = {
    usage: '/graphics <potato | nextlevel>',
    desc:  'Switch graphics preset.',
    completions: () => ['potato', 'nextlevel'],
    run(args) {
      const v = (args[0] || '').toLowerCase();
      if (!['potato', 'nextlevel'].includes(v)) throw new Error('Usage: ' + handlers['/graphics'].usage);
      setGraphics(v);
      return `Graphics set to ${getGraphics()}`;
    },
  };

  // /mode <survival|creative>
  handlers['/mode'] = {
    usage: '/mode <survival | creative>',
    desc:  'Switch game mode.',
    completions: () => ['survival', 'creative'],
    run(args) {
      const v = (args[0] || '').toLowerCase();
      if (!['survival', 'creative'].includes(v)) throw new Error('Usage: ' + handlers['/mode'].usage);
      setGameMode(v);
      return `Game mode set to ${v}`;
    },
  };

  // /spawn <mob type> [count]
  handlers['/spawn'] = {
    usage: `/spawn <${mobTypeNames.join(' | ')}> [count]`,
    desc:  'Spawn mobs near your position.',
    completions: () => mobTypeNames,
    run(args) {
      const type = (args[0] || '').toLowerCase();
      if (!mobTypeNames.includes(type)) throw new Error('Usage: ' + handlers['/spawn'].usage);
      const count = Math.max(1, Math.min(50, parseInt(args[1]) || 1));
      return spawnMobs(type, count);
    },
  };

  // /hp <value>
  handlers['/hp'] = {
    usage: '/hp <value>',
    desc:  'Set your HP directly.',
    run(args) {
      const v = parseInt(args[0]);
      if (!Number.isFinite(v) || v < 0) throw new Error('Usage: ' + handlers['/hp'].usage);
      player.hp = Math.min(player.maxHp, v);
      refreshHpBar();
      return `HP set to ${player.hp}`;
    },
  };

  // /heal
  handlers['/heal'] = {
    usage: '/heal',
    desc:  'Restore HP to maximum.',
    run() {
      player.hp = player.maxHp;
      refreshHpBar();
      return `Healed to ${player.hp}`;
    },
  };

  // /damage <amount>
  handlers['/damage'] = {
    usage: '/damage <amount>',
    desc:  'Deal damage to yourself, scaled by difficulty like any other hit.',
    run(args) {
      const v = parseInt(args[0]);
      if (!Number.isFinite(v) || v <= 0) throw new Error('Usage: ' + handlers['/damage'].usage);
      hurtPlayer(v, { kind: 'console' });
      return `Dealt ${v} damage`;
    },
  };

  // /kill — instant death, even in Creative (hurtPlayer no-ops there).
  handlers['/kill'] = {
    usage: '/kill',
    desc:  'Instantly kill yourself.',
    run() {
      killPlayer();
      return 'Ouch.';
    },
  };

  // /clear
  handlers['/clear'] = {
    usage: '/clear',
    desc:  'Clear the console output.',
    run() {
      const log = el('dev-console-log');
      if (log) log.innerHTML = '';
      return null;
    },
  };

  // /help [command]
  handlers['/help'] = {
    usage: '/help [command]',
    desc:  'List all commands, or show details for one.',
    // Without the leading slash — that's what the user types as the
    // argument (e.g. "/help give"), even though handlers are keyed with it.
    completions: () => Object.keys(handlers).map(k => k.slice(1)),
    run(args) {
      if (args[0]) {
        const key = args[0].startsWith('/') ? args[0] : '/' + args[0];
        const h = handlers[key];
        if (!h) throw new Error(`No command "${key}"`);
        logLine(h.usage, 'ok');
        logLine('  ' + h.desc, 'info');
        return null;
      }
      logLine('─── Dev Console Commands ───', 'info');
      for (const [key, h] of Object.entries(handlers)) {
        logLine(`  ${key.padEnd(16)} ${h.desc}`, 'info');
      }
      return null;
    },
  };

  // ── DOM wiring ──────────────────────────────────────────

  const inputEl = el('dev-console-input');
  const formEl  = el('dev-console-form');

  if (formEl) {
    formEl.addEventListener('submit', e => {
      e.preventDefault();
      const val = inputEl ? inputEl.value : '';
      execute(val);
      if (inputEl) inputEl.value = '';
      refreshSuggestions('');
    });
  }

  if (inputEl) {
    inputEl.addEventListener('input', () => refreshSuggestions(inputEl.value));

    // A single listener, not split across capture/bubble phases: capture-
    // phase listeners on a target fire BEFORE same-target bubble listeners,
    // so a separate capturing "stop the game seeing this key" listener
    // (the previous shape of this code) silently swallowed every key —
    // Tab, Escape, backtick, the arrows — before this logic ever ran.
    // Stopping propagation as the very first thing this listener does gets
    // the same "the game never sees console keystrokes" result without
    // that ordering trap, since it's the same listener's own later code
    // that still runs regardless of what stopPropagation() affects.
    inputEl.addEventListener('keydown', e => {
      e.stopPropagation();

      if (e.key === '`') { e.preventDefault(); closeConsole(); return; }
      if (e.key === 'Escape') { e.preventDefault(); closeConsole(); return; }

      // Tab or ArrowRight at end of input: accept whichever suggestion is
      // currently highlighted (defaults to the first match).
      if (e.key === 'Tab' || (e.key === 'ArrowRight' && inputEl.selectionStart === inputEl.value.length)) {
        e.preventDefault();
        const candidate = suggestionCandidates[suggestionIndex];
        if (candidate) {
          inputEl.value += candidate.slice(suggestionPrefix.length);
          refreshSuggestions(inputEl.value);
        }
        return;
      }

      // With two or more live candidates, Up/Down cycles through THEM
      // instead of history — there's nothing useful to browse past yet
      // when you're still choosing what to type. Only one (or zero)
      // candidates falls through to ordinary history browsing below.
      if ((e.key === 'ArrowUp' || e.key === 'ArrowDown') && suggestionCandidates.length > 1) {
        e.preventDefault();
        const dir = e.key === 'ArrowUp' ? -1 : 1;
        suggestionIndex = (suggestionIndex + dir + suggestionCandidates.length) % suggestionCandidates.length;
        renderGhost();
        return;
      }

      // History browsing.
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (history.length === 0) return;
        historyIdx = historyIdx < 0
          ? history.length - 1
          : Math.max(0, historyIdx - 1);
        inputEl.value = history[historyIdx];
        refreshSuggestions(inputEl.value);
        // Move caret to end.
        requestAnimationFrame(() => { inputEl.selectionStart = inputEl.selectionEnd = inputEl.value.length; });
        return;
      }
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (historyIdx < 0) return;
        historyIdx++;
        if (historyIdx >= history.length) { historyIdx = -1; inputEl.value = ''; }
        else inputEl.value = history[historyIdx];
        refreshSuggestions(inputEl.value);
        return;
      }
    });

    // keyup has no other listener on this element to lose, so a plain
    // capturing stopPropagation here is safe — unlike keydown above, there's
    // no ordering trap to fall into.
    inputEl.addEventListener('keyup', e => e.stopPropagation(), true);
  }

  // Close-button.
  const closeBtn = el('dev-console-close');
  if (closeBtn) closeBtn.addEventListener('click', closeConsole);

  logLine('Dev console ready. Type /help for commands.', 'info');
}
