// The inventory screen: backpack, hotbar, a 3x3 crafting grid, and the recipe
// book. Opened with E.
//
// A view module — it renders slot arrays it's handed and reports moves back
// through handlers, so it never touches game state itself.
//
// Picking things up is click-based, Minecraft-style, rather than classic
// drag-and-drop: click a stack and it lifts onto the cursor, following mouse
// movement with no button held, until another click places or swaps it. It's
// built on plain pointer events (not HTML5 drag-and-drop, which doesn't give
// usable control over the drag image and misbehaves once pointer lock has
// been involved), so a single continuous press-drag-release still works too
// — see the comment above the pointer handlers below for exactly how the two
// map onto one state machine.

import { HOTBAR_SIZE, BACKPACK_ROWS } from '../config.js';
import { BLOCK_NAMES } from '../world/blocks.js';
import { VEHICLE_TYPES, VEHICLE_RECIPES } from '../vehicles/types.js';
import { TOOL_TYPES, TOOL_RECIPES } from '../tools/types.js';
import { GRID_SIZE, GRID_CELLS } from '../crafting.js';
import { itemIconUrl } from './itemIcons.js';

let handlers = null;
let open = false;
let ghost = null;
let ghostCount = null;
// Cursor position, tracked continuously so a freshly-picked-up item's ghost
// can appear under the cursor immediately rather than at (0,0).
let lastX = 0, lastY = 0;

// Current press state, from pointerdown to pointerup:
let pointerDown = false;
// Where this press started: { zone, index }.
let dragOrigin = null;
// True if this press was the one that picked the held item up (as opposed to
// a later press meant to place/swap/distribute it).
let pickedThisPress = false;
// Craft cells already filled during this press, so sweeping back over one
// doesn't deposit a second item into it.
let dragVisitedCraft = null;

export function isInventoryOpen() { return open; }

export function initInventoryScreen(h) {
  handlers = h;
  const root = document.getElementById('inventory-screen');
  if (!root) return;

  buildGrid('inv-backpack', HOTBAR_SIZE * BACKPACK_ROWS, 'slots', HOTBAR_SIZE);
  buildGrid('inv-hotbar', HOTBAR_SIZE, 'slots', 0);
  buildGrid('craft-grid', GRID_CELLS, 'craft', 0);
  buildRecipeBook();

  const close = document.getElementById('inv-close');
  if (close) close.addEventListener('click', () => handlers.onClose());

  // Drags are tracked on the document so releasing outside a slot still ends
  // cleanly rather than leaving a stuck ghost.
  document.addEventListener('pointermove', onPointerMove);
  document.addEventListener('pointerup', onPointerUp);

  const takeBtn = document.getElementById('craft-take');
  if (takeBtn) takeBtn.addEventListener('click', () => handlers.onTakeResult());
}

function buildGrid(hostId, count, zone, offset) {
  const host = document.getElementById(hostId);
  if (!host) return;
  host.innerHTML = '';
  for (let i = 0; i < count; i++) {
    const cell = document.createElement('div');
    cell.className = 'inv-slot';
    cell.dataset.zone = zone;
    cell.dataset.index = String(offset + i);
    cell.innerHTML = '<div class="inv-icon"></div><span class="inv-count"></span>';
    cell.addEventListener('pointerdown', e => onPointerDown(e, zone, offset + i));
    host.appendChild(cell);
  }
}

// ── Picking up and placing ──────────────────────────────────
//
// Four gestures share this one state machine:
//  - Shift-click a crafting cell with nothing held: sends it straight back to
//    the inventory, no pickup involved.
//  - A click that starts and ends on the same cell, with nothing held: picks
//    up the whole stack and leaves it "in hand" — pickedThisPress tells
//    pointerup NOT to immediately place it right back down. Whether the
//    cursor trembled a few pixels along the way doesn't matter; only where
//    it's released does. (An earlier version judged this from pixels moved
//    instead, which made real clicks — never perfectly still — register as
//    a drag unpredictably; released-cell is the one thing that's exact.)
//  - A click while already holding something: places it on whatever cell
//    it's released over (merging or swapping as needed) — including the
//    origin cell, which is exactly how you'd intentionally put something back.
//  - A press that ends over a DIFFERENT cell than it started, having also
//    done the picking up itself — places there on release, same as a classic
//    drag. Along the way, if the cursor crosses crafting cells while
//    something is held, each new one gets one item peeled off the held stack
//    (dragFillCraftCell), so a single held stack can be spread across the
//    grid without repeated clicks.

function onPointerDown(e, zone, index) {
  if (!open) return;
  e.preventDefault();
  lastX = e.clientX; lastY = e.clientY;
  // Shift-click a crafting cell: send it straight back to the inventory
  // (merging with a matching stack, or into an empty slot) instead of
  // picking it up. Only when empty-handed — with something already held,
  // it's treated as a normal click.
  if (e.shiftKey && zone === 'craft' && !handlers.getHeld()) {
    handlers.shiftReturn(index);
    return;
  }
  pointerDown = true;
  dragOrigin = { zone, index };
  dragVisitedCraft = new Set();
  pickedThisPress = false;
  if (!handlers.getHeld()) {
    handlers.pick(zone, index);
    pickedThisPress = true;
  }
}

function moveGhost(x, y) {
  if (!ghost) return;
  ghost.style.left = x + 'px';
  ghost.style.top = y + 'px';
}

function cellUnder(x, y) {
  const el = document.elementFromPoint(x, y);
  const slot = el && el.closest ? el.closest('.inv-slot') : null;
  if (!slot) return null;
  return { zone: slot.dataset.zone, index: Number(slot.dataset.index) };
}

function onPointerMove(e) {
  if (!open) return;
  lastX = e.clientX; lastY = e.clientY;
  moveGhost(lastX, lastY);
  if (!pointerDown) return;

  const target = cellUnder(lastX, lastY);
  const held = handlers.getHeld();
  if (!held || !target || target.zone !== 'craft') return;
  // Only once the cursor has genuinely reached a DIFFERENT cell does this
  // count as a drag rather than a stationary click — checked explicitly,
  // not inferred from "we got a pointermove at all". A click on a craft cell
  // fires at least one pointermove at the very position it started from (or
  // a sub-pixel jitter that still resolves to the same cell), and without
  // this check that alone was enough to immediately deposit the item just
  // picked up right back into the cell it came from, leaving it behind.
  if (target.zone === dragOrigin.zone && target.index === dragOrigin.index) return;

  // The cell the drag started from only gets filled now that real movement
  // to another cell has confirmed this is a drag — fills retroactively here.
  if (dragOrigin.zone === 'craft' && !dragVisitedCraft.has(dragOrigin.index)) {
    dragVisitedCraft.add(dragOrigin.index);
    handlers.dragFillCraftCell(dragOrigin.index);
  }
  if (dragVisitedCraft.has(target.index)) return;
  dragVisitedCraft.add(target.index);
  handlers.dragFillCraftCell(target.index);
}

function onPointerUp(e) {
  if (!open || !pointerDown) return;
  pointerDown = false;
  lastX = e.clientX; lastY = e.clientY;

  const held = handlers.getHeld();
  const target = cellUnder(lastX, lastY);
  const releasedOnOrigin = target && dragOrigin &&
    target.zone === dragOrigin.zone && target.index === dragOrigin.index;

  // Skip placing if this press was a stationary click that just picked
  // something up — it stays held until a later click places it. Anything
  // else (already holding before this press, or released somewhere other
  // than where it started) places immediately.
  if (held && (!pickedThisPress || !releasedOnOrigin)) {
    if (target && !(target.zone === 'craft' && dragVisitedCraft.has(target.index))) {
      handlers.place(target.zone, target.index);
    }
  }
  dragOrigin = null;
  dragVisitedCraft = null;
  pickedThisPress = false;
}

// Keeps the floating ghost icon in sync with whatever's held — created when
// something's picked up, removed once it's placed.
function syncGhost(held) {
  if (!held) {
    if (ghost) { ghost.remove(); ghost = null; ghostCount = null; }
    return;
  }
  if (!ghost) {
    ghost = document.createElement('div');
    ghost.className = 'inv-ghost';
    ghostCount = document.createElement('span');
    ghostCount.className = 'inv-ghost-count';
    ghost.appendChild(ghostCount);
    document.body.appendChild(ghost);
    moveGhost(lastX, lastY);
  }
  const url = itemIconUrl(held);
  ghost.style.backgroundImage = url ? `url(${url})` : 'none';
  ghostCount.textContent = held.count > 1 ? String(held.count) : '';
}

// ── Rendering ────────────────────────────────────────────

function paintCell(cell, item) {
  const icon = cell.querySelector('.inv-icon');
  const count = cell.querySelector('.inv-count');
  const url = item ? itemIconUrl(item) : null;
  icon.style.backgroundImage = url ? `url(${url})` : 'none';
  count.textContent = item && item.count > 1 ? String(item.count) : '';
  cell.title = item ? describe(item) : '';
}

function describe(item) {
  if (item.kind === 'vehicle') return VEHICLE_TYPES[item.vehicleKey].label;
  if (item.kind === 'tool') return TOOL_TYPES[item.toolKey].label;
  if (item.kind === 'weapon') return item.weaponKey;
  return BLOCK_NAMES[item.id];
}

// The crafting slot's preview item and label, for either recipe pool.
function resultItem(result) {
  if (!result) return null;
  return result.kind === 'vehicle'
    ? { kind: 'vehicle', vehicleKey: result.vehicleKey }
    : { kind: 'tool', toolKey: result.toolKey };
}

function resultLabel(result) {
  if (!result) return 'Nothing yet';
  return result.kind === 'vehicle'
    ? VEHICLE_TYPES[result.vehicleKey].label
    : TOOL_TYPES[result.toolKey].label;
}

export function renderInventory({ slots, craft, result, selected, held, craftable }) {
  syncGhost(held);
  for (const cell of document.querySelectorAll('.inv-slot')) {
    const zone = cell.dataset.zone;
    const index = Number(cell.dataset.index);
    paintCell(cell, zone === 'craft' ? craft[index] : slots[index]);
    cell.classList.toggle('selected', zone === 'slots' && index === selected);
  }

  const out = document.getElementById('craft-result');
  if (out) {
    const url = itemIconUrl(resultItem(result));
    out.style.backgroundImage = url ? `url(${url})` : 'none';
    out.classList.toggle('has-result', !!result);
  }
  const label = document.getElementById('craft-result-label');
  if (label) {
    label.textContent = resultLabel(result);
  }
  const takeBtn = document.getElementById('craft-take');
  if (takeBtn) takeBtn.disabled = !result;

  if (craftable) updateRecipeCraftable(craftable);
}

// ── Recipe book ──────────────────────────────────────────
//
// Every recipe, grouped under its own category heading and filterable by a
// tab bar above them — a full backpack of ores and machines is hard to
// search by eye alone. Cards for anything the current inventory can already
// build are brightened with a tick (updateRecipeCraftable, called from
// renderInventory on every change) and become clickable: one click drops the
// pattern straight into the crafting grid instead of placing nine blocks by
// hand.

const ALL_FILTER = 'All';

function addRecipeCard(host, pool, key, def, recipe) {
  const card = document.createElement('div');
  card.className = 'recipe-card';
  card.dataset.pool = pool;
  card.dataset.key = key;
  card.dataset.category = def.category || '';
  card.title = 'Craft it once you have every ingredient';

  const title = document.createElement('div');
  title.className = 'recipe-title';
  title.textContent = def.label;
  card.appendChild(title);

  const body = document.createElement('div');
  body.className = 'recipe-body';

  const grid = document.createElement('div');
  grid.className = 'recipe-grid';
  for (let i = 0; i < GRID_SIZE * GRID_SIZE; i++) {
    const cell = document.createElement('div');
    cell.className = 'recipe-cell';
    const id = recipe[i];
    if (id != null) {
      const url = itemIconUrl({ kind: 'block', id, count: 1 });
      if (url) cell.style.backgroundImage = `url(${url})`;
      cell.title = BLOCK_NAMES[id];
    } else {
      cell.classList.add('empty');
    }
    grid.appendChild(cell);
  }
  body.appendChild(grid);

  const notes = document.createElement('div');
  notes.className = 'recipe-notes';
  notes.textContent = def.blurb;
  body.appendChild(notes);

  card.appendChild(body);
  card.addEventListener('click', () => {
    if (!card.classList.contains('craftable')) return;
    handlers.onCraftFromRecipe(pool, key);
  });
  host.appendChild(card);
}

// Every recipe as one flat, ordered list, tagged with its pool and category —
// vehicles (flying, then boats) followed by tools (hand, then each machine
// line), which is also the order categories appear in the filter bar.
function allRecipes() {
  const list = [];
  for (const [key, recipe] of Object.entries(VEHICLE_RECIPES)) {
    list.push({ pool: 'vehicle', key, def: VEHICLE_TYPES[key], recipe });
  }
  for (const [key, recipe] of Object.entries(TOOL_RECIPES)) {
    list.push({ pool: 'tool', key, def: TOOL_TYPES[key], recipe });
  }
  return list;
}

function setRecipeFilter(host, filter) {
  for (const btn of host.querySelectorAll('.recipe-filter-btn')) {
    btn.classList.toggle('active', btn.dataset.filter === filter);
  }
  for (const el of host.querySelectorAll('.recipe-category, .recipe-card')) {
    el.classList.toggle('filtered-out', filter !== ALL_FILTER && el.dataset.category !== filter);
  }
}

// Static: recipes don't change at runtime, so the cards are built once. What
// DOES change — which cards are craftable — is applied separately by
// updateRecipeCraftable, so opening the inventory doesn't rebuild this.
function buildRecipeBook() {
  const host = document.getElementById('recipe-book');
  if (!host) return;
  host.innerHTML = '';

  const recipes = allRecipes();
  const categories = [...new Set(recipes.map(r => r.def.category || 'Other'))];

  const filterBar = document.createElement('div');
  filterBar.id = 'recipe-filter';
  for (const name of [ALL_FILTER, ...categories]) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'recipe-filter-btn';
    btn.textContent = name;
    btn.dataset.filter = name;
    btn.addEventListener('click', () => setRecipeFilter(host, name));
    filterBar.appendChild(btn);
  }
  host.appendChild(filterBar);

  for (const category of categories) {
    const heading = document.createElement('div');
    heading.className = 'recipe-category';
    heading.textContent = category;
    heading.dataset.category = category;
    host.appendChild(heading);

    for (const r of recipes.filter(r => (r.def.category || 'Other') === category)) {
      addRecipeCard(host, r.pool, r.key, r.def, r.recipe);
    }
  }

  setRecipeFilter(host, ALL_FILTER);
}

// Brightens and ticks every card the current inventory can build right now.
// `craftable` is a Set of 'pool:key' strings, computed by main.js so this
// stays a plain view — it never asks the inventory anything itself.
function updateRecipeCraftable(craftable) {
  const host = document.getElementById('recipe-book');
  if (!host) return;
  for (const card of host.querySelectorAll('.recipe-card')) {
    const isCraftable = craftable.has(card.dataset.pool + ':' + card.dataset.key);
    card.classList.toggle('craftable', isCraftable);
  }
}

export function setInventoryOpen(next) {
  open = next;
  const root = document.getElementById('inventory-screen');
  if (root) root.classList.toggle('hidden', !open);
  if (!open) {
    pointerDown = false;
    dragOrigin = null;
    dragVisitedCraft = null;
    pickedThisPress = false;
    if (ghost) { ghost.remove(); ghost = null; ghostCount = null; }
  }
}
