// Beating another player is worth more than any mob.
const PVP_KILL_SCORE = 120;
const MAX_FRAME_DT = 0.05;   // clamp so a long stall can't tunnel the player
// While the loading screen is up, nothing else is happening — no physics,
// no mobs, no render() (see loop() below) — so chunk streaming can spend
// far more of the frame than its normal CHUNK_BUDGET_MS share without
// costing anything real, which is what turns "wait 10-20s after Play" into
// a real, shown wait instead of just hiding the same delay behind a spinner.
const LOADING_CHUNK_BUDGET_MS = 16;
// config.js's own CAMERA_FAR is sized for Earth's old, much smaller flat
// world. The home planet's own far side, and any other revealed body
// (world/spaceSession.js), needs a much larger far plane so nothing is
// clipped before it's even in view. The BINDING constraint here is
// render/planetBodies.js's own reveal radius, not world/starSystem.js's own
// placement distances — a body can be genuinely "revealed" (isBodyVisibleFrom
// returning true) at any distance up to its own revealRadius(), regardless
// of how far starSystem.js actually placed it, so this has to clear
// revealRadius()'s own worst case (getRenderDistance() maxed out — see
// renderDistance.js's MAX_RENDER_DIST — times CHUNK_SIZE times
// planetBodies.js's own REVEAL_MULTIPLIER, currently ~307,000) plus the
// largest body that could ever be revealed at that distance (home's own
// HOME_RADIUS, 20,000, since home itself can be "revealed" when standing on
// a DIFFERENT body looking back at it). Getting this wrong is a real,
// previously-shipped bug: an earlier retuning of REVEAL_MULTIPLIER pushed
// the worst case well past the far plane that was sized for an older,
// smaller value, silently frustum-clipping bodies the reveal-radius check
// itself said should already be visible.
const SPACE_CAMERA_FAR = 400000;

// Drops the player onto a fixed safe point on the home planet's own surface.
function placeAtSpawn() {
  spawnPointOnHomePlanet(player.pos);
  player.vel.set(0, 0, 0);
  player.fallStartY = null;
}

// True once the spawn area's own render-distance ring has actually streamed
// in (loop() below), not merely once a session/spawn point exists — see
// LOADING_CHUNK_BUDGET_MS's own comment. `initialPendingChunkWork` is the
// queued-chunk count loop() captures the first time it's known (right after
// the very first updatePlanetStreaming() call, which is also when it starts
// draining that queue — so this slightly undercounts the true starting
// total by whatever one budgeted pass already cleared, which only ever
// shows up as the progress bar's very first frame starting a little above
// 0% rather than at it), used to turn "how many chunks are still queued"
// into a fraction for the loading bar.
let worldReady = false;
let initialPendingChunkWork = null;

// Set just before beginWorldLoading() by newGame()/applyLoadedGame() only
// (never regenerateWorld(), which fires from the settings panel mid-session
// and should leave the player right where they already were, paused) — the
// moment loop() below sees worldReady flip true, it tries requestLock() so
// New Game/Load Game drop the player straight into gameplay once the
// loading animation finishes, instead of leaving the title screen's own
// click behind them stranded on the pause overlay. This can still silently
// fail and fall back to showing the overlay — requestPointerLock() needs a
// recent-enough user gesture, and a long load can outlast that window — but
// that's exactly today's existing behaviour (see core/pointerLock.js's own
// module comment), never worse than it already was.
let autoResumeOnReady = false;

// Called once at startup and again every time regenerateWorld() throws the
// world away and rebuilds it — both leave the spawn area's own terrain
// entirely unstreamed, the exact condition the loading screen exists for.
function beginWorldLoading() {
  worldReady = false;
  initialPendingChunkWork = null;
  showLoadingScreen();
}

// Mirrors worldReady/initialPendingChunkWork above, for the OTHER thing
// that shows this same loading screen: a graphics-preset switch (main.js's
// onGraphicsChange below). Kept as its own pair rather than reusing
// worldReady itself — the two are genuinely different states (loop()'s
// own streaming/render gate must keep working normally throughout a
// graphics rebuild; only the bar's progress source changes), and this one
// is never true at the same time as worldReady is false, since a preset
// switch is only ever reachable once a world has already finished loading.
let graphicsRebuildPending = false;
let initialGraphicsRebuildWork = null;

function refreshWorldSeedUI() {
  renderWorldSeedUI({ seed: getWorldSeed(), input: getWorldSeedInput() });
}

// Wipes the whole world and rebuilds it from whatever seed the player typed
// (or the default, for blank input) — a bigger, more explicit action than
// just changing a setting, since it throws away every chunk, mob and pickup
// currently out in the world. Deliberately does NOT touch score or
// inventory: this regenerates the world, not the run. Rebuilds the whole
// star system, not just terrain underfoot — world/starSystem.js derives
// body count, sizes and distances from the seed too, so a new seed visibly
// gives a different sky as well as different ground.
function regenerateWorld(seedInput) {
  setWorldSeed(seedInput);
  // A different seed means genuinely different terrain underneath every
  // recorded edit's own (au, ri, av) — keeping the old log would just
  // vandalise the new world with edits that made sense against a world
  // that no longer exists.
  editLog.clearEdits();
  clearMobs();
  clearMobProjectiles();
  clearGunPickups();
  clearHearts();
  clearDeathFx();
  clearWeaponEffects();

  clearSpaceSession();
  clearPlanetBodies();
  initSpaceSession();
  initPlanetBodies();

  placeAtSpawn();
  resetPlanetStreamingFocus();
  beginWorldLoading();
  refreshWorldSeedUI();
}

function respawnPlayer() {
  hideDeathScreen();
  player.dead = false;
  player.hp = player.maxHp;
  player.damageFlash = 0;
  player.invincible  = 1;
  clearMobs();
  clearMobProjectiles();
  clearWeaponEffects();
  clearHearts();
  clearDeathFx();
  clearGunPickups();
  clearFlight();
  clearBoat();
  clearRocket();
  clearScope();
  clearCraftGrid();
  clearInventory();
  resetScore();
  player.lastAttacker = null;
  player.lastDamageSource = null;
  updateHpBar(player.hp, player.maxHp);
  placeAtSpawn();
  requestLock();
}

// ── New Game, Save/Load, Quit to Title ──────────────────

let hasActiveGame = false;
let currentSlotId = null;     // which save slot (if any) this session is tied to
let currentSlotName = null;
let currentPickerMode = 'load';
let cachedSlotList = [];      // whatever the slot picker last listed, so
                               // onOverwrite/onLoad can look up a slot's name without a second round-trip

// Starts a brand new game: a freshly randomised seed — a different one
// every time, the whole point of New Game over just clicking into
// whatever world already happened to exist — an empty edit log, and
// score/mobs/vehicles/inventory all reset. Nothing to lose here (there
// was no active game before this), so unlike Load Game and Quit to Title,
// this never needs the unsaved-changes confirmation.
function newGame() {
  currentSlotId = null;
  currentSlotName = null;
  pendingRestores = new Map();
  setWorldSeed(randomWorldSeed());

  clearMobs();
  clearMobProjectiles();
  clearGunPickups();
  clearHearts();
  clearDeathFx();
  clearWeaponEffects();
  clearFlight();
  clearBoat();
  clearRocket();
  clearScope();
  clearCraftGrid();
  clearInventory();
  resetScore();
  player.dead = false;
  player.hp = player.maxHp;
  player.lastAttacker = null;
  player.lastDamageSource = null;

  clearSpaceSession();
  clearPlanetBodies();
  initSpaceSession();
  initPlanetBodies();
  placeAtSpawn();
  resetPlanetStreamingFocus();
  autoResumeOnReady = true;
  beginWorldLoading();
  refreshWorldSeedUI();
  updateHpBar(player.hp, player.maxHp);

  hasActiveGame = true;
  setGameActive(true);
  hideTitleScreen();
  // Last: clearInventory()/resetScore() above notify their own listeners
  // (see onInventoryChange's markDirty registration below), which would
  // otherwise leave a brand new game already reporting unsaved changes.
  editLog.clearEdits();
}

// Applies a save's own blob (src/save/saveGame.js's shape) to live game
// state: seed + edit log first (so the world regenerates correctly), then
// the space session itself, then everything the save actually restores —
// player position/orientation/health, inventory, game mode. Mobs are
// deliberately NOT restored (see the save/load feature's own scoping) —
// they respawn fresh, same as any other session.
async function applyLoadedGame(data, slotId, slotName) {
  currentSlotId = slotId;
  currentSlotName = slotName ?? null;
  // Keyed by name, consumed one at a time as matching peers actually
  // rejoin — see maybeRestoreJoiningPlayer. A save with nobody connected
  // at the time has no multiplayerPlayers field at all (saveGame.js).
  pendingRestores = new Map((data.multiplayerPlayers || []).map(p => [p.name, p]));

  setWorldSeed(data.seedInput);

  clearMobs();
  clearMobProjectiles();
  clearGunPickups();
  clearHearts();
  clearDeathFx();
  clearWeaponEffects();
  clearFlight();
  clearBoat();
  clearRocket();
  clearScope();
  clearCraftGrid();

  clearSpaceSession();
  clearPlanetBodies();
  initSpaceSession();
  initPlanetBodies();

  setGameMode(data.gameMode);

  for (let i = 0; i < slots.length; i++) slots[i] = data.inventory.slots[i] ?? null;
  selectSlot(data.inventory.selectedSlot ?? 0);
  refreshInventory();

  player.pos.set(data.player.pos.x, data.player.pos.y, data.player.pos.z);
  player.vel.set(0, 0, 0);
  player.yaw = data.player.yaw;
  player.pitch = data.player.pitch;
  player.hp = data.player.hp;
  player.maxHp = data.player.maxHp;
  player.flying = data.player.flying;
  player.spaceAlignQuat.set(
    data.player.spaceAlignQuat.x, data.player.spaceAlignQuat.y,
    data.player.spaceAlignQuat.z, data.player.spaceAlignQuat.w,
  );
  player.dead = false;
  player.fallStartY = null;
  player.lastAttacker = null;
  player.lastDamageSource = null;

  // Preload chunks around the SAVED position specifically, not the
  // default spawn tile — the player could have saved anywhere, on any
  // body, and initSpaceSession() above only ever preloads home's own
  // 'py' spawn tile on its own.
  const planet = nearestPlanetTo(player.pos);
  if (planet) {
    const { faceId, u, v } = worldToFace(player.pos, planet.center, planet.halfExtent);
    preloadPlanetChunksNear(planet, faceId, u, v, 2);
  }

  resetPlanetStreamingFocus();
  autoResumeOnReady = true;
  beginWorldLoading();
  refreshWorldSeedUI();
  updateHpBar(player.hp, player.maxHp);

  hasActiveGame = true;
  setGameActive(true);
  hideTitleScreen();
  // Last, for the same reason newGame() does this last — a freshly loaded
  // game has nothing unsaved yet, regardless of what refreshInventory()
  // above notified.
  editLog.loadEdits(data.edits);
}

async function performSave(name, overwriteId) {
  const id = await persistGame(name, overwriteId != null ? { overwriteId } : undefined);
  currentSlotId = id;
  currentSlotName = name || null;
  return id;
}

// The "Save & Quit" fast path (see quitToTitle below) — reuses whatever
// slot this session is already tied to, silently creating one the first
// time, rather than making the player pick a slot mid-quit the way the
// explicit Save Game button does.
function quickSave() {
  return performSave(currentSlotName, currentSlotId);
}

async function openLoadGameMenu() {
  currentPickerMode = 'load';
  try {
    cachedSlotList = await listSaveSlots();
  } catch {
    showLabel('Could not read saved games');
    return;
  }
  showSlotPicker('load', cachedSlotList);
}

async function openSaveGameMenu() {
  currentPickerMode = 'save';
  try {
    cachedSlotList = await listSaveSlots();
  } catch {
    showLabel('Could not read saved games');
    return;
  }
  showSlotPicker('save', cachedSlotList);
}

function quitToTitleImmediately() {
  hasActiveGame = false;
  currentSlotId = null;
  currentSlotName = null;
  setGameActive(false);
  showTitleScreen();
}

// Esc-equivalent "leave this game" from the pause overlay. Disconnects
// multiplayer first — Connect is only ever reachable once a game is
// active (ui/overlay.js's own gameActive gating), so leaving one means
// leaving the other too — then warns before discarding unsaved changes,
// exactly like closing a document with unsaved edits would.
function quitToTitle() {
  if (net.isOnline()) {
    net.disconnect();
    clearRemotePlayers();
    refreshPlayerList();
  }
  if (!editLog.isDirty()) {
    quitToTitleImmediately();
    return;
  }
  showConfirmDialog({
    title: 'Unsaved changes',
    message: "You haven't saved recently. Quit anyway?",
    buttons: [
      {
        label: 'Save & Quit', primary: true,
        onClick: () => {
          quickSave()
            .then(() => { showLabel('Game saved'); quitToTitleImmediately(); })
            .catch(() => showLabel('Could not save — quit cancelled'));
        },
      },
      { label: 'Quit Without Saving', onClick: quitToTitleImmediately },
      { label: 'Cancel', onClick: () => {} },
    ],
  });
}

// ── Multiplayer ──────────────────────────────────────────

// A loaded save's own multiplayerPlayers snapshot (saveGame.js), keyed by
// name — the only identifier the protocol gives us to recognise "this is
// the same person rejoining" with, since network ids are per-connection
// and never stable across a reconnect. Consumed one entry at a time as
// matching names actually rejoin (see maybeRestoreJoiningPlayer below),
// not applied all at once, since who rejoins and when is out of our
// control. Empty whenever the active game has no such snapshot to restore
// (a brand new game via newGame(), or a save nobody was connected for).
let pendingRestores = new Map();

function refreshPlayerList() {
  renderPlayerList([...remotePlayers.values()].map(p => ({ name: p.name })));
}

// Fires for every peer that joins while we're connected, host or not —
// this relay has no real "host" role (see protocol.js's own comment), so
// whoever happens to be holding a pending-restore entry for that name is
// the one who hands it back, regardless of who's technically running the
// server. Consumes the entry so a second rejoin later in the same session
// doesn't re-restore an already-moved player back to a stale position.
function maybeRestoreJoiningPlayer(data) {
  const saved = pendingRestores.get(data.name);
  if (!saved) return;
  pendingRestores.delete(data.name);
  net.sendRestorePlayer(data.id, [saved.pos.x, saved.pos.y, saved.pos.z], saved.yaw, saved.hp);
}

function setupNetworking() {
  const profile = initProfile();

  initMultiplayerUI({
    profile,
    defaultUrl: net.defaultServerUrl(),
    onProfileChange: patch => {
      const next = setProfile({ ...getProfile(), ...patch });
      // Live update so others see a rename or a new outfit immediately.
      net.sendProfile(next.name, appearanceOf(next));
    },
    onConnect: url => net.connect(url, () => ({
      name: getProfile().name,
      appearance: appearanceOf(),
      // The room adopts whichever seed its first joiner brings (server/
      // index.js) and echoes it back in WELCOME to everyone after — see
      // that handler below for what happens when it differs from ours.
      seedInput: getWorldSeedInput(),
      // Same room-wide-policy pattern, for whether the dev console can be
      // opened at all while connected — see devConsoleSetting.js's own
      // module comment for why this exists.
      devConsoleEnabled: getLocalDevConsoleEnabled(),
    })),
    onDisconnect: () => {
      net.disconnect();
      clearRemotePlayers();
      refreshPlayerList();
    },
  });

  net.onStatusChange((status, detail) => {
    renderNetStatus(status, detail);
    if (status !== 'online') {
      clearRemotePlayers();
      refreshPlayerList();
      // The room's own dev-console policy only applies while actually
      // connected to it — losing the connection, for any reason, reverts
      // to whatever the player's own local preference already was.
      clearDevConsoleMultiplayerOverride();
    }
  });
  renderNetStatus('offline');

  net.on(MSG.WELCOME, data => {
    // Covers a peer who rejoins AFTER us (via PLAYER_JOINED below) as well
    // as one who was already connected before we got here — WELCOME's own
    // roster is the only place we ever see the latter, since we joined
    // too late to catch their own PLAYER_JOINED.
    for (const p of data.players) { addRemotePlayer(p); maybeRestoreJoiningPlayer(p); }
    refreshPlayerList();
    // Everyone in the room ends up on the same seed automatically — no
    // confirmation, matching "starting multiplayer... will transmit the
    // world seed... so you always end up in the same world seed
    // automatically". regenerateWorld() already does exactly what's needed
    // here (new seed, empty edit log, fresh session/spawn) since joining a
    // differently-seeded room has nothing of the old one worth keeping.
    if (typeof data.seedInput === 'string' && data.seedInput !== getWorldSeedInput()) {
      regenerateWorld(data.seedInput);
      showLabel('Joined — world reseeded to match the host');
    }
    // Same automatic-adoption treatment for the room's dev-console policy —
    // the onDevConsoleEnabledChange listener (wired in start()) is what
    // actually refreshes the settings-panel button and force-closes an
    // already-open console if this makes it newly disallowed.
    if (typeof data.devConsoleEnabled === 'boolean') {
      setDevConsoleMultiplayerOverride(data.devConsoleEnabled);
    }
  });
  net.on(MSG.PLAYER_JOINED, data => {
    addRemotePlayer(data);
    refreshPlayerList();
    maybeRestoreJoiningPlayer(data);
  });
  net.on(MSG.PLAYER_LEFT,   data => { removeRemotePlayer(data.id); refreshPlayerList(); });
  net.on(MSG.PLAYER_PROFILE, data => { updateRemoteProfile(data); refreshPlayerList(); });
  net.on(MSG.SNAPSHOT, data => applySnapshot(data.players, net.getSelfId()));

  // Someone shot us. Their client decided the hit landed; we own the damage.
  // Their name is snapshotted here, at hit-time — by the time the death
  // screen shows it, they may have already left.
  net.on(MSG.HIT_YOU, data => hurtPlayer(data.damage, {
    kind: 'player', id: data.from, name: remotePlayers.get(data.from)?.name,
  }));

  // World edits from other players, applied without re-broadcasting.
  net.on(MSG.BLOCK,  d => spaceApplyRemoteBlock(d.x, d.y, d.z, d.id));
  net.on(MSG.CRATER, d => spaceCarveCrater({ x: d.x, y: d.y, z: d.z }, d.radius));

  net.on(MSG.PLAYER_DIED, data => {
    const p = remotePlayers.get(data.id);
    if (p) p.dead = true;
    // The victim names their killer, so credit lands on the right client.
    if (data.by != null && data.by === net.getSelfId()) addScore(PVP_KILL_SCORE);
  });

  // Someone (whoever holds a pending-restore entry for us — see
  // maybeRestoreJoiningPlayer below) is handing our own saved position back
  // to us. We apply it to our own state; nobody else ever forces it.
  net.on(MSG.RESTORE_STATE, data => {
    player.pos.set(data.pos[0], data.pos[1], data.pos[2]);
    player.vel.set(0, 0, 0);
    player.yaw = data.yaw;
    player.hp = data.hp;
    player.fallStartY = null;
    updateHpBar(player.hp, player.maxHp);
    showLabel('Your saved position was restored');
  });

  // Our own edits go out to everyone else.
  onSpaceBlockChange((x, y, z, id) => net.sendBlock(x, y, z, id));
}

let sinceStateSend = 0;

function sendLocalState(dt) {
  if (!net.isOnline()) return;
  sinceStateSend += dt * 1000;
  if (sinceStateSend < TICK_MS) return;
  sinceStateSend = 0;
  net.sendState({
    pos: [+player.pos.x.toFixed(2), +player.pos.y.toFixed(2), +player.pos.z.toFixed(2)],
    yaw: +player.yaw.toFixed(3),
    pitch: +player.pitch.toFixed(3),
    crouching: player.crouching,
    hp: player.hp,
    dead: player.dead,
  });
}

// Translates the raw slider into something a player can act on: how much
// faster score comes in, and roughly how many kills it takes to max out.
function refreshDifficultyUI() {
  const killPoints = Math.round(20 * scoreMultiplier());
  renderDifficultyUI({
    slider: getSlider(),
    escalatingSpawns: getEscalatingSpawns(),
    pointsPerKill: (scoreMultiplier()).toFixed(1),
    killsToPeak: Math.max(1, Math.round(threatSpan() / killPoints)),
  });
  updateScoreDisplay(getScore(), getBestScore(), getThreat());
}

// The setting is a chunk count; the description translates that into blocks,
// which is what actually means something to a player picking a distance.
function refreshRenderDistanceUI() {
  const dist = getRenderDistance();
  renderRenderDistanceUI({ dist, blocks: dist * CHUNK_SIZE });
}

function refreshDayLengthUI() {
  renderDayLengthUI({ minutes: getDayLengthMinutes() });
}

function refreshDevConsoleUI() {
  renderDevConsoleUI({
    enabled: isDevConsoleEnabled(),
    local: getLocalDevConsoleEnabled(),
    overridden: isDevConsoleOverridden(),
  });
}

// ── Inventory screen ─────────────────────────────────────

// Whatever's currently picked up and following the cursor — Minecraft-style:
// a click lifts a whole stack off a slot and it stays "in hand" (no need to
// keep the mouse button held) until another click places or swaps it.
let heldItem = null;

function getHeldItem() { return heldItem; }

// The screen needs the cursor, so it releases pointer lock while it's up.
function toggleInventory() {
  const next = !isInventoryOpen();
  setInventoryOpen(next);
  setInputSuspended(next);
  if (next) {
    // Only actually exits if currently locked — an unconditional call still
    // counts against Chrome's re-lock cooldown even when there was nothing
    // to exit, which made a quick open/close (e.g. Esc right after opening)
    // more likely to hit that cooldown than it needed to.
    if (isLocked()) document.exitPointerLock();
    drawInventory();
  } else {
    // Anything left in the crafting grid — or on the cursor — goes back
    // rather than vanishing.
    for (let i = 0; i < GRID_CELLS; i++) {
      if (craftGrid[i]) { addItem(craftGrid[i]); craftGrid[i] = null; }
    }
    if (heldItem) { returnToInventory(heldItem); heldItem = null; }
    // If this doesn't take immediately, the overlay shows below — same as
    // it would for the PLAY button on a plain click. Nothing more to it.
    requestLock();
  }
  // Recomputed immediately rather than waiting on a pointerlockchange event:
  // opening the inventory releases the lock right above, which would
  // otherwise leave the overlay visible (just hidden behind the inventory
  // panel) for as long as the inventory stays open.
  syncOverlayVisibility();
}

// Every recipe the current inventory can build right now, as 'pool:key'
// strings — computed fresh each render rather than cached, since picking up
// or spending a single block can flip several recipes at once. The recipe
// book is a view, so it gets this as plain data rather than importing
// inventory.js itself to work it out.
function craftableRecipes() {
  const set = new Set();
  for (const [key, recipe] of Object.entries(VEHICLE_RECIPES)) {
    if (canCraftRecipe(recipe, countMaterial)) set.add('vehicle:' + key);
  }
  for (const [key, recipe] of Object.entries(TOOL_RECIPES)) {
    if (canCraftRecipe(recipe, countMaterial)) set.add('tool:' + key);
  }
  return set;
}

function drawInventory() {
  if (!isInventoryOpen()) return;
  renderInventory({
    slots,
    craft: craftGrid,
    result: craftingResult(),
    selected: getSelectedSlot(),
    held: heldItem,
    craftable: craftableRecipes(),
  });
}

function itemAt(zone, index) {
  return zone === 'craft' ? craftGrid[index] : slots[index];
}

function setCell(zone, index, item) {
  if (zone === 'craft') craftGrid[index] = item;
  else slots[index] = item;
}

// Puts one item back wherever it fits, merging with a matching stack first.
function returnToInventory(item) {
  if (!item) return;
  if (item.kind === 'block') addToInventory(item.id, item.count);
  else addItem(item);
}

// Click on an empty hand: lifts the whole stack off a slot/cell onto the
// cursor. No-op if the cell is empty or something's already held.
function pickCell(zone, index) {
  if (heldItem) return;
  const item = itemAt(zone, index);
  if (!item) return;
  heldItem = item;
  setCell(zone, index, null);
  refreshInventory();
  drawInventory();
}

// Click while holding something: drops it on the cell, merging with a
// matching stack or swapping with a mismatched one (the displaced item then
// becomes what's held, same as Minecraft).
function placeCell(zone, index) {
  if (!heldItem) return;
  const dst = itemAt(zone, index);
  if (!dst) {
    setCell(zone, index, heldItem);
    heldItem = null;
  } else if (sameItem(dst, heldItem)) {
    dst.count += heldItem.count;
    heldItem = null;
  } else {
    setCell(zone, index, heldItem);
    heldItem = dst;
  }
  refreshInventory();
  drawInventory();
}

// Shift-click a crafting cell: send it straight back to the inventory
// (merging with a matching stack, or an empty slot) rather than picking it up.
function shiftReturnCraftCell(index) {
  const item = craftGrid[index];
  if (!item) return;
  returnToInventory(item);
  craftGrid[index] = null;
  refreshInventory();
  drawInventory();
}

// One item peeled off the held stack into a crafting cell — used while
// dragging across the grid with a stack already picked up. A no-op once the
// held stack runs out, or if the cell holds something else entirely.
function dragFillCraftCell(index) {
  if (!heldItem) return;
  const dst = craftGrid[index];
  if (dst && !sameItem(dst, heldItem)) return;
  if (dst) dst.count++;
  else craftGrid[index] = { ...heldItem, count: 1 };
  heldItem.count--;
  if (heldItem.count <= 0) heldItem = null;
  refreshInventory();
  drawInventory();
}

function takeCrafted() {
  const item = takeCraftingResult();
  if (!item) return;
  if (!addItem(item)) {
    showLabel('No room for that');
    return;
  }
  drawInventory();
}

// Clicking a craftable card in the recipe book: builds the pattern straight
// into the crafting grid, taking the ingredients from wherever they are in
// the inventory. The recipe book only ever calls this on cards it has
// already marked craftable, but canCraftRecipe is checked again here too —
// state can move between a render and a click (e.g. two clicks in the same
// frame), and this must never leave the grid short of what a recipe needs.
function craftFromRecipeBook(pool, key) {
  const recipe = pool === 'vehicle' ? VEHICLE_RECIPES[key] : TOOL_RECIPES[key];
  if (!recipe || !canCraftRecipe(recipe, countMaterial)) {
    showLabel('Missing materials');
    return;
  }
  // Whatever's already in the grid (and on the cursor) goes back to the
  // inventory first, the same as closing the screen does, so nothing already
  // placed gets silently overwritten or double-counted.
  for (let i = 0; i < GRID_CELLS; i++) {
    if (craftGrid[i]) { returnToInventory(craftGrid[i]); craftGrid[i] = null; }
  }
  if (heldItem) { returnToInventory(heldItem); heldItem = null; }

  for (let i = 0; i < GRID_CELLS; i++) {
    const id = recipe[i];
    if (id == null) continue;
    takeMaterial(id, 1);
    craftGrid[i] = { id, kind: 'block', count: 1 };
  }
  refreshInventory();
  drawInventory();
}

// Speed and throttle readout, shown while piloting anything — a plane, a
// boat and a rocket all just have a name, a speed and a throttle, so one
// HUD covers all three.
function updateFlightHud() {
  const hud = document.getElementById('flight-hud');
  if (!hud) return;
  const flying = isFlying(), boating = isBoating(), rocketing = isRocketing();
  hud.classList.toggle('hidden', !flying && !boating && !rocketing);
  if (flying) {
    document.getElementById('flight-name').textContent = activeVehicle().def.label;
    document.getElementById('flight-speed').textContent = getAirspeed().toFixed(0);
    document.getElementById('throttle-fill').style.width = (getThrottle() * 100).toFixed(0) + '%';
  } else if (boating) {
    document.getElementById('flight-name').textContent = activeBoat().def.label;
    document.getElementById('flight-speed').textContent = getBoatSpeed().toFixed(0);
    document.getElementById('throttle-fill').style.width = (getBoatThrottle() * 100).toFixed(0) + '%';
  } else if (rocketing) {
    document.getElementById('flight-name').textContent = activeRocket().def.label;
    document.getElementById('flight-speed').textContent = getRocketSpeed().toFixed(0);
    document.getElementById('throttle-fill').style.width = (getRocketThrottle() * 100).toFixed(0) + '%';
  }

  // Hyperspeed status — only ever non-empty while a hyperspeed-capable ship
  // (the Star Cruiser) actually has a lock engaged, so this stays hidden for
  // every other vehicle, and for the Star Cruiser itself right up until H
  // is actually pressed.
  const hyperEl = document.getElementById('hyperspeed-status');
  if (hyperEl) {
    const active = rocketing && isHyperspeedActive();
    hyperEl.classList.toggle('hidden', !active);
    if (active) {
      hyperEl.textContent = `HYPERSPEED — ${getHyperspeedTargetLabel()} (${getHyperspeedDistance().toFixed(0)}m)`;
    }
  }
}

// F key: board whatever's held, or get out of whatever you're in. Flying,
// boating and rocketing are three separate systems (vehicles/flight.js,
// vehicles/boats.js, vehicles/rocket.js) that know nothing of each other,
// so this is the one place that decides which applies — reading the held
// item's own `mode` rather than guessing.
function toggleVehicleAny() {
  if (isFlying())    { dismountVehicle('Landed'); return; }
  if (isBoating())   { dismountBoat('Docked'); return; }
  if (isRocketing()) { dismountRocket('Landed'); return; }
  const item = getSelectedItem();
  const def = item && item.kind === 'vehicle' ? VEHICLE_TYPES[item.vehicleKey] : null;
  if (def && def.mode === 'boat') mountBoat();
  else if (def && def.mode === 'rocket') mountRocket();
  else mountVehicle();
}

function applyGraphics() {
  const cfg = graphicsConfig();
  setMaxPixelRatio(cfg.maxPixelRatio);
  setLightingEnabled(cfg.lit);
}

// ── Dev console glue ──────────────────────────────────────────────────
//
// devConsole.js stays a pure view/router with no game imports of its own
// (same rule every other UI module follows), so anything it needs that
// touches real game state — giving an item, spawning a mob, killing the
// player — is built here instead and handed in as a plain function.

// One combined name -> giver table for /give, built from each item kind's
// own label rather than hand-duplicated id/ammo tables, so a new block,
// weapon, vehicle or tool is givable for free the moment it's added to its
// own types file. Keyed by a slug of the label (e.g. "Rocket Launcher" ->
// "rocket_launcher") rather than the internal object key, specifically
// because the weapon key and the vehicle key are BOTH literally "rocket"
// (the rocket launcher vs. the rocket ship) — their labels aren't, so
// slugging the label is what keeps /give unambiguous between them.
function slugify(label) {
  return label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

const GIVE_TABLE = new Map();   // slug -> (count) => result string

for (let id = 1; id < BLOCK_NAMES.length; id++) {   // skip 0 (Air) — nothing to give
  const label = BLOCK_NAMES[id];
  GIVE_TABLE.set(slugify(label), count => {
    addToInventory(id, count);
    return `Gave ${count}x ${label}`;
  });
}
for (const key of Object.keys(WEAPON_TYPES)) {
  const label = WEAPON_TYPES[key].label;
  // Ammo comes from the weapon's own definition via pickUpWeapon — a count
  // beyond 1 doesn't mean "give N weapons", it has no useful meaning here,
  // so it's ignored exactly like the very first version of this command did.
  GIVE_TABLE.set(slugify(label), () => {
    pickUpWeapon(key);
    return `Gave ${label}`;
  });
}
for (const key of Object.keys(VEHICLE_TYPES)) {
  const label = VEHICLE_TYPES[key].label;
  GIVE_TABLE.set(slugify(label), count => {
    let given = 0;
    for (let i = 0; i < count; i++) { if (addItem(vehicleItem(key))) given++; }
    return given ? `Gave ${given}x ${label}` : 'Inventory full!';
  });
}
for (const key of Object.keys(TOOL_TYPES)) {
  const label = TOOL_TYPES[key].label;
  GIVE_TABLE.set(slugify(label), count => {
    let given = 0;
    for (let i = 0; i < count; i++) { if (addItem(toolItem(key))) given++; }
    return given ? `Gave ${given}x ${label}` : 'Inventory full!';
  });
}

const GIVABLE_ITEM_NAMES = [...GIVE_TABLE.keys()];

function devGiveItem(name, count) {
  const giver = GIVE_TABLE.get(name.toLowerCase());
  if (!giver) throw new Error(`Unknown item "${name}"`);
  return giver(Math.max(1, Math.min(9999, count)));
}

const DEV_SPAWN_MIN_DIST = 6, DEV_SPAWN_MAX_DIST = 10;
const MOB_TYPE_NAMES = Object.keys(MOB_TYPES);

// Reuses entities/mobs.js's own spawnMobNear so a console-spawned mob in
// space snaps to the planet's real curved ground, the same as the automatic
// night spawner, instead of floating at the player's own height.
function devSpawnMobs(type, count) {
  for (let i = 0; i < count; i++) spawnMobNear(type, player.pos, DEV_SPAWN_MIN_DIST, DEV_SPAWN_MAX_DIST);
  return `Spawned ${count}x ${type}`;
}

// hurtPlayer no-ops entirely in Creative mode (see player/health.js), which
// is exactly the mode /kill is most likely to be used in for quick testing —
// killPlayer() has no such gate, so /kill uses that directly instead.
function devKillPlayer() {
  player.lastDamageSource = { kind: 'console' };
  killPlayer();
}

function start() {
  const canvas = document.getElementById('game-canvas');
  initRenderer(canvas);
  setLockTarget(canvas);

  initHotbar();
  refreshHotbar(inventory);
  initOverlay({
    onSelectMode: setGameMode,
    onRespawn: respawnPlayer,
    onSelectGraphics: setGraphics,
    onDifficulty: setSlider,
    onToggleSpawnEscalation: () => setEscalatingSpawns(!getEscalatingSpawns()),
    onRenderDistance: setRenderDistance,
    onDayLength: setDayLengthMinutes,
    onWorldSeedApply: regenerateWorld,
    onSaveGame: openSaveGameMenu,
    onQuitToTitle: quitToTitle,
    onToggleDevConsole: () => setDevConsoleEnabled(!getLocalDevConsoleEnabled()),
  });
  initTitleScreen({ onNewGame: newGame, onLoadGameRequest: openLoadGameMenu });
  initConfirmDialog();
  initSaveSlotPicker({
    onLoad: async id => {
      let data;
      try {
        data = await loadSavedGame(id);
      } catch {
        showLabel('Could not read that save');
        return;
      }
      if (!data) { showLabel('Save not found'); return; }
      const meta = cachedSlotList.find(s => s.id === id);
      hideSlotPicker();
      await applyLoadedGame(data, id, meta ? meta.name : null);
    },
    onOverwrite: async id => {
      const existing = cachedSlotList.find(s => s.id === id);
      try {
        await performSave(existing ? existing.name : null, id);
      } catch {
        showLabel('Could not save');
        return;
      }
      hideSlotPicker();
      showLabel('Game saved');
    },
    onSaveNew: async name => {
      try {
        await performSave(name || null, null);
      } catch {
        showLabel('Could not save');
        return;
      }
      hideSlotPicker();
      showLabel('Game saved');
    },
    onDelete: async id => {
      try {
        await deleteSaveSlot(id);
        cachedSlotList = await listSaveSlots();
      } catch {
        showLabel('Could not delete that save');
        return;
      }
      showSlotPicker(currentPickerMode, cachedSlotList);
    },
    onBack: () => {},
  });
  initGameMode();

  // Read before the world's first generateChunk() call so spawn itself
  // already uses whatever seed was persisted, rather than generating the
  // default world and only picking up a custom seed on the next regenerate.
  onWorldSeedChange(refreshWorldSeedUI);
  initWorldSeed();

  onDifficultyChange(refreshDifficultyUI);
  initDifficulty();

  // Applies the saved value without the streaming side effect below — no
  // world exists yet for it to act on, same reasoning as initGraphics().
  onRenderDistanceChange(refreshRenderDistanceUI);
  initRenderDistance();

  onDayLengthChange(refreshDayLengthUI);
  initDayLength();

  // Fires on every LOCAL toggle AND every multiplayer-override change
  // (devConsoleSetting.js's own notify() covers both) — refreshing the
  // settings-panel button either way, and force-closing an already-open
  // console the instant it stops being allowed (a room's own policy taking
  // effect after WELCOME, most notably).
  onDevConsoleEnabledChange(enabled => {
    refreshDevConsoleUI();
    if (!enabled && isConsoleOpen()) closeConsole();
  });
  initDevConsoleSetting();

  initInput({
    onLeftClick: handleLeftClick,
    onRightClick: placeBlock,
    onToggleInventory: toggleInventory,
    onToggleVehicle: toggleVehicleAny,
    onToggleHyperspeed: toggleHyperspeed,
  });
  initInventoryScreen({
    getHeld: getHeldItem, pick: pickCell, place: placeCell, dragFillCraftCell,
    shiftReturn: shiftReturnCraftCell, onClose: toggleInventory, onTakeResult: takeCrafted,
    onCraftFromRecipe: craftFromRecipeBook,
  });
  onInventoryChange(drawInventory);

  // Load the saved preset and apply it before anything is meshed — no
  // listeners are registered yet, so this can't trigger a rebuild.
  initGraphics();
  applyGraphics();

  // No space session yet, and no loading screen either — there's nothing
  // to stream until New Game/Load Game actually starts one (newGame()/
  // applyLoadedGame() above). initStarfield()/setCameraFar() are harmless,
  // session-independent renderer setup that can happen unconditionally.
  initStarfield();
  setCameraFar(SPACE_CAMERA_FAR);
  updateHpBar(player.hp, player.maxHp);

  setupNetworking();

  initDevConsole({
    giveItem: devGiveItem,
    givableItemNames: GIVABLE_ITEM_NAMES,
    spawnMobs: devSpawnMobs,
    mobTypeNames: MOB_TYPE_NAMES,
    player,
    setDayTime,
    setDayLengthMinutes,
    getDayLengthMinutes,
    setRenderDistance,
    getRenderDistance,
    setSlider,
    getSlider,
    setGraphics,
    getGraphics,
    setGameMode,
    hurtPlayer,
    killPlayer: devKillPlayer,
    refreshHpBar: () => updateHpBar(player.hp, player.maxHp),
  });

  // From here on, switching preset applies immediately. Potato and Next
  // Level are genuinely different chunk geometry (world/planetMesher.js),
  // so every currently-meshed chunk needs rebuilding, not just the held-item
  // model (which bakes in whether it's textured, same as before). Doing
  // that all in one synchronous call could freeze the tab for a couple of
  // seconds at a real render distance — long enough to read as a crash
  // rather than ordinary work — with no way to show real progress either,
  // since one long blocking call has nothing to report partway through.
  // queueGraphicsRebuild() + loop()'s own budgeted drain below turns it
  // into the same kind of progressing loading bar the initial world load
  // already uses, instead of either a frozen tab or a bar stuck at 0%.
  onGraphicsChange(() => {
    applyGraphics();
    resetViewmodelModels();
    showLoadingScreen('Applying graphics…');
    queueGraphicsRebuild(getActivePlanets());
    graphicsRebuildPending = true;
    initialGraphicsRebuildWork = null;
  });

  // From here on, changing render distance widens or narrows the streaming
  // rings immediately rather than waiting for the next chunk border crossing.
  onRenderDistanceChange(() => {
    resetPlanetStreamingFocus();
  });

  // Inventory changes count as unsaved progress worth the quit reminder,
  // same as a placed/mined block — registered as a SECOND onInventoryChange
  // listener (drawInventory above is the first), not a replacement.
  // newGame()/applyLoadedGame() both explicitly clear the dirty flag last,
  // specifically to override whatever this fires during their own
  // clearInventory()/refreshInventory() calls.
  onInventoryChange(() => editLog.markDirty());

  // No game exists yet — #title-screen owns the view until New Game or
  // Load Game actually starts one.
  setGameActive(false);
  showTitleScreen();

  requestAnimationFrame(loop);
}

let lastTime = performance.now();

function loop(now) {
  requestAnimationFrame(loop);
  // Measure the real frame time, then clamp the copy the game simulates with.
  const rawDt = (now - lastTime) / 1000;
  const dt = Math.min(rawDt, MAX_FRAME_DT);
  lastTime = now;
  recordFrame(rawDt);

  // Nothing to stream/render/pilot at all before New Game or Load Game —
  // #title-screen owns the view until hasActiveGame flips true (see the
  // "New Game, Save/Load, Quit to Title" section above).
  if (hasActiveGame) {
    if (worldReady) {
      if (graphicsRebuildPending) {
        // Dedicate the whole budget to the rebuild while it's running, the
        // same "nothing else is happening" reasoning LOADING_CHUNK_BUDGET_MS
        // already uses below — splitting it with normal streaming would
        // only stretch out how long the loading screen stays up for no
        // benefit, since the screen covers the view either way.
        drainGraphicsRebuildQueue(getActivePlanets(), LOADING_CHUNK_BUDGET_MS);
        const pending = pendingGraphicsRebuildWork();
        if (initialGraphicsRebuildWork === null) initialGraphicsRebuildWork = Math.max(pending, 1);
        if (pending === 0) {
          graphicsRebuildPending = false;
          hideLoadingScreen();
        } else {
          setLoadingProgress(1 - pending / initialGraphicsRebuildWork);
        }
      } else {
        updatePlanetStreaming(getActivePlanets(), player.pos, CHUNK_BUDGET_MS);
      }
    } else {
      updatePlanetStreaming(getActivePlanets(), player.pos, LOADING_CHUNK_BUDGET_MS);
      const pending = pendingPlanetChunkWork();
      if (initialPendingChunkWork === null) initialPendingChunkWork = Math.max(pending, 1);
      if (pending === 0) {
        worldReady = true;
        hideLoadingScreen();
        if (autoResumeOnReady) {
          autoResumeOnReady = false;
          requestLock();
        }
      } else {
        setLoadingProgress(1 - pending / initialPendingChunkWork);
      }
    }
    updatePlanetBodies(player.pos);
    updateStarfield(camera.position);
  }

  const worldPaused = isWorldPaused();

  updateScope(dt);
  if (!worldPaused) {
    if (isFlying()) {
      updateFlight(dt);
    } else if (isBoating()) {
      updateBoat(dt);
    } else if (isRocketing()) {
      updateRocket(dt);
    } else {
      physicsStep(dt);
      updateCamera();
    }
    updateFlightHud();
    updateDamageTimers();
    updateHighlight();
    updateMining(dt);
    updateSky(dt, player.pos, player.underwaterLiquid);

    // Mobs, their projectiles, hearts and gun pickups all carry their own
    // directional-gravity branch (entities/mobs.js, entities/hearts.js,
    // entities/mobProjectiles.js). The world's own random gun spawner
    // (entities/pickups.js's updateGunSpawner) is retired, not called from
    // here — it placed pistols by a flat (wx, wz) + surfaceAt lookup with
    // no meaning on a curved planet, and extra loot spawning in the world
    // was never essential to mobs actually working; mob-dropped weapons
    // (updateGunPickups) are unaffected.
    updateMobProjectiles(dt);
    updateMobs(dt);
    updateMobSpawner(dt);
    updateGunPickups(dt);
    updateHearts(dt);
    updateDeathFx(dt);
  }

  // Always on: with nobody connected these are no-ops (empty remote-player
  // map), and with somebody connected this is what keeps you visible to them
  // and them moving for you, regardless of whether your own world is paused.
  updateRemotePlayers(dt);
  updateRadar(remotePlayerBearings(player.pos, player.yaw));
  sendLocalState(dt);

  if (!worldPaused) {
    updateWeaponFiring(dt);
    updateBlockPlacing(dt);
    updatePlayerProjectiles(dt);
    updateTracers(dt);
    updateExplosionFX(dt);
    updateHeadshotFX(dt);
  }

  updateViewmodel(dt);

  updateScoreDisplay(getScore(), getBestScore(), getThreat());

  updateDebug();
  // Skip drawing entirely before a game exists (title screen owns the view)
  // or while the loading screen covers the whole viewport anyway — that
  // time is worth far more spent on LOADING_CHUNK_BUDGET_MS's own streaming
  // budget above.
  if (hasActiveGame && worldReady) {
    render();
    renderViewmodel();   // drawn over the world, after everything else
  }
}

start();
