// Hold-to-mine: in survival, breaking a block takes real time, scaled by the
// block's hardness (world/blocks.js) and whatever's in your hand
// (tools/types.js). Creative stays instant, exactly as mining always was
// before this module existed.
//
// The break-progress overlay (a darkening box over the targeted block) lives
// here too rather than in player/view.js, since it's driven by the same
// progress state — see core/scene.js for the mesh itself.

import {
  AIR, MINE_CATEGORY, BASE_MINE_SECONDS, DEFAULT_MINE_SECONDS,
} from '../world/blocks.js';
import { worldGetBlock, worldSetBlock } from '../world/activeWorld.js';
import {
  sameTarget, getTargetBlock, setTargetBlock, isBedrockTarget, targetCorners, recentreOnTarget,
} from '../world/blockTarget.js';
import { addToInventory, getSelectedItem, getSelectedSlot } from '../inventory.js';
import { TOOL_TYPES } from '../tools/types.js';
import { isCreative } from '../gameMode.js';
import { mouse } from '../core/input.js';
import { player } from './state.js';
import { raycastBlock } from './raycast.js';
import { breakOverlayMesh, spaceBreakOverlayMesh } from '../core/scene.js';
import { updateCellSolid, makeCornerScratch } from '../render/cellHighlight.js';
import { getCrackStageTexture, STAGE_COUNT } from '../render/crackTexture.js';
import { triggerSwing } from './viewmodel.js';
import { showLabel, setMiningProgress } from '../ui/hud.js';

// The crack decal's own full strength — short of fully opaque, so the block
// underneath still reads through the gaps between cracks rather than the
// overlay ever looking like a solid sticker.
const MAX_OVERLAY_OPACITY = 0.95;
// How much of the very first stage's own fade-in counts toward "visible at
// all" — starting the decal already partway faded in (rather than from a
// literal 0) is what keeps the very first instant of mining from reading as
// a sudden pop, without needing a whole extra stage just for that.
const MIN_VISIBLE_OPACITY = 0.35;

const overlayCorners = makeCornerScratch();

let currentTarget = null;   // the resolved target (world/blockTarget.js) being mined
let lastSlot = -1;
let progress = 0;           // 0..1
let bedrockNotified = false;   // only show the "hit bedrock" label once per hold

export function miningProgress() { return progress; }

function resetProgress() {
  currentTarget = null;
  lastSlot = -1;
  progress = 0;
  bedrockNotified = false;
  breakOverlayMesh.visible = false;
  spaceBreakOverlayMesh.visible = false;
  setMiningProgress(null);
}

// How much faster than bare hands the held item mines this category. Wrong
// tool for the job is no better (and no worse) than bare hands.
function toolMultiplier(item, category) {
  if (!item || item.kind !== 'tool') return 1;
  const def = TOOL_TYPES[item.toolKey];
  return def.categories.includes(category) ? def.speedMul : 1;
}

// Breaks whatever's at literal world coordinates (bx,by,bz) — used only by
// the radius sweep below, which walks nearby integer WORLD offsets. In
// space this keeps the same literal-world-unit imprecision every block
// query used to have before world/blockTarget.js existed (a world unit
// isn't always one voxel cell there — see that module's own comment).
// Walking neighbour CELLS instead, face seams included, would be needed to
// fix that fully; left as a known limitation since it only affects a
// machine's radius, not the single block actually under the crosshair.
function breakOneBlock(bx, by, bz) {
  const id = worldGetBlock(bx, by, bz);
  if (id === AIR) return;
  worldSetBlock(bx, by, bz, AIR);
  addToInventory(id);
}

// Machines clear a radius of same-category blocks around the one you were
// aiming at — a bucket-sized bite instead of one block at a time. Hand tools
// have radius 0, so this is a no-op for them.
function clearRadius(bx, by, bz, item) {
  if (!item || item.kind !== 'tool') return;
  const def = TOOL_TYPES[item.toolKey];
  if (def.radius <= 0) return;
  const category = MINE_CATEGORY[worldGetBlock(bx, by, bz)];
  if (!def.categories.includes(category)) return;
  for (let dx = -def.radius; dx <= def.radius; dx++) {
    for (let dy = -def.radius; dy <= def.radius; dy++) {
      for (let dz = -def.radius; dz <= def.radius; dz++) {
        if (dx === 0 && dy === 0 && dz === 0) continue;
        const nx = bx + dx, ny = by + dy, nz = bz + dz;
        if (MINE_CATEGORY[worldGetBlock(nx, ny, nz)] === category) breakOneBlock(nx, ny, nz);
      }
    }
  }
}

// Breaks the EXACT cell the player is aiming at, via the resolved target —
// unlike breakOneBlock above, this can never alias onto a neighbouring
// cell once cells shrink below a world unit (world/blockTarget.js). Never
// clears more than this one cell; recentreOnTarget keeps the player from
// getting stuck on a neighbour instead of clearing it — see that
// function's own comment in world/blockTarget.js.
function breakTarget(target) {
  const id = getTargetBlock(target);
  if (id === AIR) return;
  setTargetBlock(target, AIR);
  addToInventory(id);
  recentreOnTarget(target, player.pos);
}

function finishMining(item, bx, by, bz, target) {
  // The radius check needs the ORIGINAL block's category, so it runs before
  // the aimed block itself is cleared.
  clearRadius(bx, by, bz, item);
  breakTarget(target);
  resetProgress();
}

export function updateMining(dt) {
  if (player.dead) { resetProgress(); return; }
  const item = getSelectedItem();
  if (item && item.kind === 'weapon') { resetProgress(); return; }
  if (!mouse.leftHeld) { resetProgress(); return; }

  const r = raycastBlock();
  if (!r.hit) { resetProgress(); return; }

  // The planet's own bedrock floor — see world/blockTarget.js and
  // world/spaceSession.js's BEDROCK_MARGIN.
  if (isBedrockTarget(r.target)) {
    if (!bedrockNotified) showLabel("Solid bedrock — can't dig any deeper.");
    resetProgress();
    bedrockNotified = true;
    return;
  }

  // Switching targets — a different block, or a different tool selected
  // mid-dig — restarts progress, same as looking away in Minecraft.
  const slot = getSelectedSlot();
  if (!sameTarget(r.target, currentTarget) || slot !== lastSlot) {
    currentTarget = r.target;
    lastSlot = slot;
    progress = 0;
  }

  if (isCreative()) {
    finishMining(item, r.bx, r.by, r.bz, currentTarget);
    return;
  }

  const id = getTargetBlock(currentTarget);
  const category = MINE_CATEGORY[id];
  const base = BASE_MINE_SECONDS[id] ?? DEFAULT_MINE_SECONDS;
  const required = base / toolMultiplier(item, category);

  progress += dt / required;
  triggerSwing();   // keeps the arm swinging for as long as the hold lasts

  // Which crack stage to show, plus a smooth ease-in as progress moves
  // through that stage's own slice of the bar — a discrete texture swap
  // with no fade at all would still read as a small pop each time a new
  // stage cuts in, and this fixes that without needing to cross-blend two
  // textures at once. MIN_VISIBLE_OPACITY keeps the very first instant of
  // mining from reading as a sudden appearance out of nowhere.
  const clamped = Math.min(1, progress);
  const stage = Math.min(STAGE_COUNT - 1, Math.floor(clamped * STAGE_COUNT));
  const stageFrac = clamped * STAGE_COUNT - stage;
  const opacity = (MIN_VISIBLE_OPACITY + stageFrac * (1 - MIN_VISIBLE_OPACITY)) * MAX_OVERLAY_OPACITY;
  // The crack decal above is deliberately random-looking, which makes it a
  // poor way to actually judge how much longer this block has left — the
  // ring is the plain, linear answer to that, shown alongside it.
  setMiningProgress(clamped);
  // The material's `map` starts null (core/scene.js can't assume a real
  // `document` exists at its own import time) — the ONE time this actually
  // matters is the very first assignment, which needs `needsUpdate` so the
  // shader recompiles with USE_MAP defined; every later reassignment (a
  // different already-built texture in the same, already-active slot)
  // needs no such flag.
  if (!spaceBreakOverlayMesh.material.map) spaceBreakOverlayMesh.material.needsUpdate = true;
  spaceBreakOverlayMesh.material.map = getCrackStageTexture(stage);
  // A planet's own cell is a warped, variably-sized hexahedron, not a unit
  // cube (world/cubeSphere.js) — the overlay's actual geometry has to match
  // it, not just move a fixed-size box into position.
  const corners = targetCorners(currentTarget, overlayCorners);
  breakOverlayMesh.visible = false;
  if (corners) {
    updateCellSolid(spaceBreakOverlayMesh.geometry, corners);
    spaceBreakOverlayMesh.visible = true;
    spaceBreakOverlayMesh.material.opacity = opacity;
  }

  if (progress >= 1) finishMining(item, r.bx, r.by, r.bz, currentTarget);
}
