// Procedurally generated block texture atlas.
//
// Everything is painted onto a canvas at runtime — no image assets to ship or
// load. One atlas means one material and one draw call per chunk, exactly as
// the untextured path has.
//
// Layout is a 4x4 grid of TILE-sized cells. UVs are inset by a texel and a
// half so mipmapping can't bleed neighbouring tiles into each other.

import * as THREE from 'three';

const GRID = 4;
const TILE = 128;
export const ATLAS_SIZE = GRID * TILE;

// Slot index per tile name. Add a tile, add it to the painter table below.
export const TILES = {
  grassTop:  0,
  grassSide: 1,
  dirt:      2,
  stone:     3,
  sand:      4,
  woodTop:   5,
  woodSide:  6,
  leaves:    7,
  water:     8,
  snowTop:   9,
  snowSide: 10,
  gravel:   11,
  iron:     12,
  titanium: 13,
  crystal:  14,
};

// Which atlas tile each block uses, indexed by face type (0 top, 1 side,
// 2 bottom). Lives here rather than in the mesher because the held-item
// viewmodel needs the same mapping.
export const BLOCK_TILES = {
  1: [TILES.grassTop, TILES.grassSide, TILES.dirt],      // grass
  2: [TILES.dirt,     TILES.dirt,      TILES.dirt],      // dirt
  3: [TILES.stone,    TILES.stone,     TILES.stone],     // stone
  4: [TILES.sand,     TILES.sand,      TILES.sand],      // sand
  5: [TILES.woodTop,  TILES.woodSide,  TILES.woodTop],   // wood
  6: [TILES.leaves,   TILES.leaves,    TILES.leaves],    // leaves
  7: [TILES.water,    TILES.water,     TILES.water],     // water
  8: [TILES.snowTop,  TILES.snowSide,  TILES.dirt],      // snow
  9:  [TILES.gravel,   TILES.gravel,   TILES.gravel],    // gravel
  10: [TILES.iron,     TILES.iron,     TILES.iron],      // iron ore
  11: [TILES.titanium, TILES.titanium, TILES.titanium],  // titanium ore
  12: [TILES.crystal,  TILES.crystal,  TILES.crystal],   // crystal ore
};

// Deterministic per-tile noise, so the atlas is identical every run.
function makeRng(seed) {
  let s = seed >>> 0 || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5;  s >>>= 0;
    return s / 4294967296;
  };
}

function shade(hex, amount) {
  const r = Math.max(0, Math.min(255, ((hex >> 16) & 0xff) + amount));
  const g = Math.max(0, Math.min(255, ((hex >> 8) & 0xff) + amount));
  const b = Math.max(0, Math.min(255, (hex & 0xff) + amount));
  return `rgb(${r|0},${g|0},${b|0})`;
}

// Speckled base: the workhorse for stone/dirt/sand style surfaces.
function paintGrain(ctx, x0, y0, base, spread, density, blob) {
  const rng = makeRng(base ^ (x0 * 31 + y0 * 17));
  ctx.fillStyle = shade(base, 0);
  ctx.fillRect(x0, y0, TILE, TILE);
  const count = Math.floor(TILE * TILE * density);
  for (let i = 0; i < count; i++) {
    const px = x0 + rng() * TILE;
    const py = y0 + rng() * TILE;
    const size = 1 + rng() * blob;
    ctx.fillStyle = shade(base, (rng() - 0.5) * 2 * spread);
    ctx.fillRect(px, py, size, size);
  }
}

function paintGrassTop(ctx, x, y) {
  paintGrain(ctx, x, y, 0x4c9a34, 42, 0.5, 3);
  const rng = makeRng(0x9155);
  // Tufts of lighter and darker blades.
  for (let i = 0; i < 260; i++) {
    const px = x + rng() * TILE, py = y + rng() * TILE;
    const h = 2 + rng() * 5;
    ctx.fillStyle = shade(0x4c9a34, rng() < 0.5 ? 34 : -30);
    ctx.fillRect(px, py, 1, h);
  }
}

function paintGrassSide(ctx, x, y) {
  paintGrain(ctx, x, y, 0x7a5535, 30, 0.45, 3);
  // Grass overhanging the top edge, ragged so it doesn't read as a straight line.
  const rng = makeRng(0x5133);
  const lip = TILE * 0.28;
  for (let px = 0; px < TILE; px++) {
    const depth = lip * (0.55 + rng() * 0.75);
    ctx.fillStyle = shade(0x4c9a34, (rng() - 0.5) * 50);
    ctx.fillRect(x + px, y, 1, depth);
  }
}

function paintWood(ctx, x, y, rings) {
  paintGrain(ctx, x, y, 0x6f5327, 20, 0.35, 2);
  const rng = makeRng(rings ? 0x777 : 0x778);
  if (rings) {
    // End grain: concentric rings.
    const cx = x + TILE / 2, cy = y + TILE / 2;
    for (let r = TILE / 2; r > 2; r -= 4 + rng() * 4) {
      ctx.strokeStyle = shade(0x6f5327, (rng() - 0.5) * 46);
      ctx.lineWidth = 1 + rng() * 2;
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.stroke();
    }
  } else {
    // Bark: vertical streaks.
    for (let i = 0; i < 70; i++) {
      const px = x + rng() * TILE;
      ctx.fillStyle = shade(0x5b4420, (rng() - 0.5) * 54);
      ctx.fillRect(px, y, 1 + rng() * 2, TILE);
    }
  }
}

function paintLeaves(ctx, x, y) {
  paintGrain(ctx, x, y, 0x2f7a24, 40, 0.6, 4);
  const rng = makeRng(0x1eaf);
  // Dark gaps so the canopy reads as clumps rather than a solid slab.
  for (let i = 0; i < 90; i++) {
    ctx.fillStyle = shade(0x14330f, 0);
    ctx.fillRect(x + rng() * TILE, y + rng() * TILE, 2 + rng() * 4, 2 + rng() * 4);
  }
}

function paintWater(ctx, x, y) {
  paintGrain(ctx, x, y, 0x2a63c4, 16, 0.3, 5);
}

function paintGravel(ctx, x, y) {
  paintGrain(ctx, x, y, 0x8f8f83, 30, 0.3, 2);
  const rng = makeRng(0x9ace);
  // Pebbles.
  for (let i = 0; i < 90; i++) {
    const px = x + rng() * TILE, py = y + rng() * TILE;
    const r = 2 + rng() * 5;
    ctx.fillStyle = shade(0x8f8f83, (rng() - 0.5) * 60);
    ctx.beginPath();
    ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fill();
  }
}

// Ore: stone, with blobs of the metal scattered through it. Reads as "there's
// something in this rock" the way Minecraft's ores do.
function paintOre(ctx, x, y, oreColor, blobCount, sparkle) {
  paintGrain(ctx, x, y, 0x8a8a8a, 26, 0.5, 3);
  const rng = makeRng(oreColor);
  for (let i = 0; i < blobCount; i++) {
    const px = x + 8 + rng() * (TILE - 20);
    const py = y + 8 + rng() * (TILE - 20);
    const r = 4 + rng() * 7;
    ctx.fillStyle = shade(oreColor, (rng() - 0.5) * 40);
    ctx.beginPath();
    ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fill();
    if (sparkle) {
      ctx.fillStyle = shade(oreColor, 90);
      ctx.fillRect(px - r * 0.3, py - r * 0.3, r * 0.5, r * 0.5);
    }
  }
}

const PAINTERS = {
  [TILES.grassTop]:  paintGrassTop,
  [TILES.grassSide]: paintGrassSide,
  [TILES.dirt]:      (c, x, y) => paintGrain(c, x, y, 0x7a5535, 34, 0.5, 3),
  [TILES.stone]:     (c, x, y) => paintGrain(c, x, y, 0x8a8a8a, 30, 0.55, 3),
  [TILES.sand]:      (c, x, y) => paintGrain(c, x, y, 0xd8c98a, 22, 0.6, 2),
  [TILES.woodTop]:   (c, x, y) => paintWood(c, x, y, true),
  [TILES.woodSide]:  (c, x, y) => paintWood(c, x, y, false),
  [TILES.leaves]:    paintLeaves,
  [TILES.water]:     paintWater,
  [TILES.snowTop]:   (c, x, y) => paintGrain(c, x, y, 0xecf0f8, 12, 0.5, 3),
  [TILES.snowSide]:  (c, x, y) => paintGrain(c, x, y, 0xdde3ee, 16, 0.45, 3),
  [TILES.gravel]:    paintGravel,
  [TILES.iron]:      (c, x, y) => paintOre(c, x, y, 0xb07a52, 7, false),
  [TILES.titanium]:  (c, x, y) => paintOre(c, x, y, 0xc6ccd6, 5, true),
  [TILES.crystal]:   (c, x, y) => paintOre(c, x, y, 0x63e6d8, 4, true),
};

let atlasTexture = null;

// Built on first use and cached — switching presets doesn't repaint it.
export function getBlockAtlas() {
  if (atlasTexture) return atlasTexture;

  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = ATLAS_SIZE;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, ATLAS_SIZE, ATLAS_SIZE);

  for (const slot of Object.values(TILES)) {
    const x = (slot % GRID) * TILE;
    const y = Math.floor(slot / GRID) * TILE;
    PAINTERS[slot](ctx, x, y);
  }

  atlasTexture = new THREE.CanvasTexture(canvas);
  atlasTexture.wrapS = atlasTexture.wrapT = THREE.ClampToEdgeWrapping;
  atlasTexture.magFilter = THREE.LinearFilter;
  atlasTexture.minFilter = THREE.LinearMipmapLinearFilter;
  atlasTexture.generateMipmaps = true;
  atlasTexture.anisotropy = 4;
  atlasTexture.colorSpace = THREE.SRGBColorSpace;
  atlasTexture.needsUpdate = true;
  return atlasTexture;
}

// UV rectangle for a tile, inset so mip levels can't sample a neighbour.
const INSET = 1.5 / ATLAS_SIZE;
const CELL  = 1 / GRID;

export function tileUV(slot) {
  const col = slot % GRID;
  const row = Math.floor(slot / GRID);
  return {
    u0: col * CELL + INSET,
    v0: 1 - (row + 1) * CELL + INSET,
    u1: (col + 1) * CELL - INSET,
    v1: 1 - row * CELL - INSET,
  };
}
