// Materials for the planet mesher's Next Level path — a shared, lit,
// textured material for opaque terrain, and one shared, shaded water
// ShaderMaterial per liquid type (world/blocks.js's own isLiquidBlock/
// UNDERWATER_TINT), reviving the wave/fresnel/specular water shader the old
// flat-Earth mesher used, adapted only in one way: its shallow/deep colour
// uniforms are picked per liquid instead of one hardcoded blue, so a themed
// alien lake (acid, magma, cryofluid) gets its own shaded water look too —
// the shader itself has no flat-world assumptions baked in, it only ever
// reads the actual world-space position/normal a mesh hands it.
//
// Every planet chunk that needs one of these shares it — never a per-chunk
// clone — so building or rebuilding chunk meshes never costs a new shader
// program.

import * as THREE from 'three';
import { getBlockAtlas } from './textures.js';
import { BLOCK_COLORS, UNDERWATER_TINT, WATER } from '../world/blocks.js';

let texturedMaterial = null;

// Vertex colour here carries baked ambient occlusion (world/planetMesher.js's
// Next Level path), not the block's own colour — that comes from the atlas
// map instead, which is the whole point of this material over Potato's own.
export function getTexturedChunkMaterial() {
  if (texturedMaterial) return texturedMaterial;
  texturedMaterial = new THREE.MeshLambertMaterial({
    map: getBlockAtlas(),
    vertexColors: true,
    side: THREE.FrontSide,
  });
  return texturedMaterial;
}

const waterVertex = `
varying vec3 vWorldPos;
varying vec3 vNormal;
void main() {
  vec4 worldPos = modelMatrix * vec4(position, 1.0);
  vWorldPos = worldPos.xyz;
  vNormal = normalize(mat3(modelMatrix) * normal);
  gl_Position = projectionMatrix * viewMatrix * worldPos;
}
`;

const waterFragment = `
uniform float uTime;
uniform vec3  uSunDir;
uniform vec3  uSunColor;
uniform vec3  uSkyColor;
uniform vec3  uShallow;
uniform vec3  uDeep;
uniform vec3  uFogColor;
uniform float uFogNear;
uniform float uFogFar;

varying vec3 vWorldPos;
varying vec3 vNormal;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

void main() {
  vec2 p = vWorldPos.xz;
  float w1 = noise(p * 0.55 + vec2(uTime * 0.28, uTime * 0.16));
  float w2 = noise(p * 1.20 - vec2(uTime * 0.19, uTime * 0.33));
  float wave = (w1 + w2) * 0.5;

  float e = 0.35;
  float dx = noise((p + vec2(e, 0.0)) * 0.55 + vec2(uTime * 0.28, uTime * 0.16)) - w1;
  float dz = noise((p + vec2(0.0, e)) * 0.55 + vec2(uTime * 0.28, uTime * 0.16)) - w1;
  vec3 normal = normalize(vNormal + vec3(-dx, 0.0, -dz) * 3.2);

  vec3 viewDir = normalize(cameraPosition - vWorldPos);
  float facing = max(dot(normal, viewDir), 0.0);
  float fresnel = pow(1.0 - facing, 3.0);

  vec3 body = mix(uDeep, uShallow, wave * 0.65 + 0.2);
  vec3 color = mix(body, uSkyColor, clamp(fresnel * 0.9, 0.0, 0.85));

  vec3 halfway = normalize(uSunDir + viewDir);
  float spec = pow(max(dot(normal, halfway), 0.0), 90.0);
  color += uSunColor * spec * 1.6;

  float diffuse = clamp(dot(normal, uSunDir) * 0.5 + 0.6, 0.0, 1.2);
  color *= diffuse;

  float depth = length(cameraPosition - vWorldPos);
  float fogAmount = smoothstep(uFogNear, uFogFar, depth);
  color = mix(color, uFogColor, fogAmount);

  gl_FragColor = vec4(color, mix(0.86, 0.97, fresnel));
}
`;

const waterMaterials = new Map();   // liquidId -> THREE.ShaderMaterial

// One shared material per liquid type, built lazily the first time a chunk
// with that liquid actually meshes. `uShallow` comes from the liquid's own
// BLOCK_COLORS top colour (the same "brightest, facing-up" tone every other
// preset already uses for it); `uDeep` reuses UNDERWATER_TINT (already
// tuned for "the mood of being submerged in this specific liquid" — see
// player/view.js's own underwater overlay) rather than inventing a second,
// separate colour pair per liquid from scratch.
export function getWaterMaterialFor(liquidId) {
  let mat = waterMaterials.get(liquidId);
  if (mat) return mat;
  const shallowHex = (BLOCK_COLORS[liquidId] || BLOCK_COLORS[WATER]).top;
  const deepHex = UNDERWATER_TINT[liquidId] ?? UNDERWATER_TINT[WATER];
  mat = new THREE.ShaderMaterial({
    vertexShader: waterVertex,
    fragmentShader: waterFragment,
    transparent: true,
    side: THREE.DoubleSide,
    uniforms: {
      uTime:     { value: 0 },
      uSunDir:   { value: new THREE.Vector3(0.4, 0.9, 0.2).normalize() },
      uSunColor: { value: new THREE.Color(0xfff2d0) },
      uSkyColor: { value: new THREE.Color(0x7a1414) },
      uShallow:  { value: new THREE.Color(shallowHex) },
      uDeep:     { value: new THREE.Color(deepHex) },
      uFogColor: { value: new THREE.Color(0x7a1414) },
      uFogNear:  { value: 40 },
      uFogFar:   { value: 100 },
    },
  });
  waterMaterials.set(liquidId, mat);
  return mat;
}

// Called once a frame (sky.js's own updateSky, the same hook the old
// flat-Earth water shader used) — updates every water material actually
// created so far, not just whichever liquid the player currently stands
// near, since more than one could be visible on screen at once (a home
// lake and a themed alien one, from orbit, say).
export function updateWaterMaterials(dt, { sunDir, sunColor, skyColor, fogColor, fogNear, fogFar } = {}) {
  for (const mat of waterMaterials.values()) {
    const u = mat.uniforms;
    u.uTime.value += dt;
    if (sunDir)   u.uSunDir.value.copy(sunDir);
    if (sunColor) u.uSunColor.value.copy(sunColor);
    if (skyColor) u.uSkyColor.value.copy(skyColor);
    u.uFogColor.value.copy(fogColor || skyColor);
    if (fogNear !== undefined) u.uFogNear.value = fogNear;
    if (fogFar  !== undefined) u.uFogFar.value  = fogFar;
  }
}
