// The thing in your hands: a gun, or the block you're about to place.
//
// Rendered in its OWN scene and camera, drawn over the world with the depth
// buffer cleared. That's what stops the model poking through walls when you
// stand in a corner, and it keeps the world's fog and shadow rig from touching
// it. Its lights live in this scene alone, so they can't trigger shader
// recompiles for the world's materials.
//
// Every weapon has its own recoil animation — see FIRE_ANIMATIONS at the
// bottom, which is the part worth reading if you're adding a weapon.

import * as THREE from 'three';
import { BLOCK_COLORS } from '../world/blocks.js';
import { TOOL_TYPES } from '../tools/types.js';
import { getBlockAtlas, BLOCK_TILES, tileUV } from '../render/textures.js';
import { renderer } from '../core/scene.js';
import { isNextLevel } from '../settings.js';
import { getSelectedItem } from '../inventory.js';
import { isScoped } from '../weapons/scope.js';
import { player } from './state.js';

export const viewScene = new THREE.Scene();
export const viewCamera = new THREE.PerspectiveCamera(50, 16 / 9, 0.01, 20);
viewCamera.position.set(0, 0, 0);

// Lit from the front-left so edges read, with a fill from the other side so
// nothing goes solid black.
//
// These intensities look high because three divides irradiance by PI for
// Lambert shading (physically-correct lighting, on by default since r155), so
// an intensity of 1 lands at roughly 0.32 on screen. The world gets away with
// low numbers because its terrain is unlit vertex colour; this scene doesn't.
const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
keyLight.position.set(-0.6, 0.8, 1);
viewScene.add(keyLight);

const rimLight = new THREE.DirectionalLight(0xdCE8ff, 1.2);
rimLight.position.set(0.9, 0.2, 0.4);
viewScene.add(rimLight);

viewScene.add(new THREE.AmbientLight(0xffffff, 2.0));

// ── Shared materials ─────────────────────────────────────

const materials = new Map();
function mat(color, opts = {}) {
  const key = color + ':' + JSON.stringify(opts);
  let m = materials.get(key);
  if (!m) {
    m = new THREE.MeshLambertMaterial({ color, ...opts });
    materials.set(key, m);
  }
  return m;
}

function box(w, h, d, x, y, z, color, opts) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color, opts));
  mesh.position.set(x, y, z);
  return mesh;
}

// ── Weapon models ────────────────────────────────────────
//
// Each builder returns { group, parts }. Anything in `parts` can be animated
// independently — a pistol slide, a shotgun pump, a spinning barrel cluster.
// Models point down -z, which is where the camera looks.

function buildPistol() {
  const group = new THREE.Group();
  const grip = box(0.075, 0.17, 0.09, 0, -0.10, 0.05, 0x3a3f45);
  grip.rotation.x = -0.28;
  group.add(grip);
  group.add(box(0.07, 0.075, 0.30, 0, 0, -0.06, 0x5c636b));      // frame
  const slide = box(0.075, 0.07, 0.26, 0, 0.055, -0.08, 0x8d949b);
  group.add(slide);
  group.add(box(0.03, 0.03, 0.06, 0, 0.02, -0.23, 0x2c2f33));    // muzzle
  return { group, parts: { slide }, muzzle: new THREE.Vector3(0, 0.03, -0.26) };
}

function buildShotgun() {
  const group = new THREE.Group();
  group.add(box(0.055, 0.055, 0.50, -0.035, 0.03, -0.16, 0x5b6066));  // barrels
  group.add(box(0.055, 0.055, 0.50, 0.035, 0.03, -0.16, 0x5b6066));
  group.add(box(0.10, 0.12, 0.22, 0, -0.02, 0.13, 0x8a5a2b));         // stock
  const pump = box(0.13, 0.09, 0.13, 0, -0.04, -0.14, 0x6b4420);
  group.add(pump);
  group.add(box(0.05, 0.13, 0.07, 0, -0.10, 0.06, 0x6b4420));         // grip
  return { group, parts: { pump }, muzzle: new THREE.Vector3(0, 0.03, -0.42) };
}

function buildChaingun() {
  const group = new THREE.Group();
  group.add(box(0.17, 0.17, 0.26, 0, 0, 0.06, 0x3f4348));             // receiver
  const barrels = new THREE.Group();
  // Six barrels around a hub — the spin is the whole point of this one.
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    barrels.add(box(0.035, 0.035, 0.36, Math.cos(a) * 0.055, Math.sin(a) * 0.055, -0.18, 0xcc6600));
  }
  group.add(barrels);
  group.add(box(0.055, 0.14, 0.08, 0, -0.15, 0.10, 0x2a2d31));        // grip
  return { group, parts: { barrels }, muzzle: new THREE.Vector3(0, 0, -0.38) };
}

function buildRocket() {
  const group = new THREE.Group();
  group.add(box(0.14, 0.14, 0.56, 0, 0.02, -0.10, 0x6a727b));         // tube
  group.add(box(0.16, 0.16, 0.05, 0, 0.02, 0.19, 0x474d54));          // back rim
  const warhead = box(0.10, 0.10, 0.14, 0, 0.02, -0.42, 0xc4453a);
  group.add(warhead);
  group.add(box(0.05, 0.13, 0.08, 0, -0.10, 0.02, 0x50565d));         // grip
  group.add(box(0.04, 0.06, 0.16, 0.09, 0.10, 0.02, 0x474d54));       // sight
  return { group, parts: { warhead }, muzzle: new THREE.Vector3(0, 0.02, -0.5) };
}

function buildSniper() {
  const group = new THREE.Group();
  group.add(box(0.05, 0.05, 0.62, 0, 0, -0.14, 0x37412f));            // barrel/receiver
  group.add(box(0.07, 0.10, 0.22, 0, -0.03, 0.16, 0x2a3122));         // stock
  group.add(box(0.045, 0.11, 0.10, 0, -0.11, -0.02, 0x22271a));       // magazine
  const bolt = box(0.03, 0.03, 0.09, 0.045, 0.035, 0.05, 0x8d949b);
  group.add(bolt);
  group.add(box(0.05, 0.05, 0.18, 0, 0.075, -0.12, 0x14170f));        // scope tube
  group.add(box(0.06, 0.02, 0.02, 0, 0.10, -0.20, 0x0e100a));         // scope objective rim
  group.add(box(0.05, 0.13, 0.07, 0, -0.16, 0.10, 0x2a3122));         // grip
  return { group, parts: { bolt }, muzzle: new THREE.Vector3(0, 0, -0.46) };
}

function buildNuke() {
  const group = new THREE.Group();
  group.add(box(0.17, 0.17, 0.44, 0, 0, 0.02, 0x6d7a55));             // launcher
  group.add(box(0.19, 0.19, 0.05, 0, 0, 0.23, 0x4d5740));
  const warhead = box(0.14, 0.14, 0.24, 0, 0, -0.32, 0x9acd32,
    { emissive: 0x6c9c22, emissiveIntensity: 0.9 });
  group.add(warhead);
  group.add(box(0.05, 0.14, 0.08, 0, -0.13, 0.06, 0x464f38));         // grip
  return { group, parts: { warhead }, muzzle: new THREE.Vector3(0, 0, -0.45) };
}

const WEAPON_BUILDERS = {
  pistol: buildPistol,
  shotgun: buildShotgun,
  chaingun: buildChaingun,
  rocket: buildRocket,
  nuke: buildNuke,
  sniper: buildSniper,
};

// Where each model sits relative to the eye, and how long its recoil runs.
// The z values matter more than they look: the camera is 50° across and these
// models are only a few tenths of a unit long, so pulling one in even slightly
// makes it swallow the screen. Around -0.8 puts a gun in the lower right at
// roughly a quarter of the frame, which is where an FPS viewmodel wants to be.
const WEAPON_POSE = {
  pistol:   { pos: [0.24, -0.22, -0.78], rot: [0.02, 0.10, 0],   duration: 0.20 },
  shotgun:  { pos: [0.23, -0.24, -0.82], rot: [0.02, 0.08, 0],   duration: 0.55 },
  // Far enough back that the barrel cluster reads, rather than the receiver
  // filling the corner.
  chaingun: { pos: [0.31, -0.27, -1.14], rot: [0.00, 0.06, 0],   duration: 0.10 },
  rocket:   { pos: [0.29, -0.24, -1.08], rot: [0.03, 0.09, 0],   duration: 0.65 },
  nuke:     { pos: [0.30, -0.25, -1.12], rot: [0.02, 0.08, 0],   duration: 0.95 },
  // Not that it matters while scoped — see updateViewmodel's isScoped()
  // check below, which hides the whole model rather than posing it — this
  // is only what's on screen for the moment right after unscoping too.
  sniper:   { pos: [0.28, -0.23, -1.05], rot: [0.01, 0.07, 0],   duration: 0.85 },
};

// A cube held at an angle presents its diagonal, so it reads noticeably bigger
// than a gun of the same nominal size — hence the smaller model and the extra
// distance.
const BLOCK_POSE = { pos: [0.30, -0.28, -0.92], rot: [0.35, -0.55, 0.15], duration: 0.28 };
const BLOCK_SIZE = 0.19;

// ── Held tools and machinery ─────────────────────────────
//
// One generic handle-plus-head builder, coloured per tool and scaled up for
// the "machine" tier — same idea as the icon templates, so 16 tools don't
// need 16 bespoke models. Machines sit further back and lower, the same way
// the bulkier weapons do, so they don't swallow the screen.

const TOOL_POSE_HAND    = { pos: [0.27, -0.26, -0.85], rot: [0.10, -0.35, 0.05], duration: 0.30 };
const TOOL_POSE_MACHINE = { pos: [0.33, -0.31, -1.10], rot: [0.08, -0.30, 0.05], duration: 0.40 };

function buildToolModel(item) {
  const def = TOOL_TYPES[item.toolKey];
  const scale = def.tier === 'machine' ? 1.6 : 1;
  const group = new THREE.Group();
  group.add(box(0.055 * scale, 0.055 * scale, 0.32 * scale, 0, 0, -0.02, 0x5c4326));           // handle
  group.add(box(0.16 * scale, 0.15 * scale, 0.18 * scale, 0, 0.03, -0.26 * scale, def.color));  // head / body
  group.add(box(0.06 * scale, 0.17 * scale, 0.09 * scale, 0, -0.12 * scale, 0.06, 0x3a3f45));   // grip
  return { group, parts: {}, muzzle: null };
}

// ── Held block ───────────────────────────────────────────

// BoxGeometry lays its faces out +x, -x, +y, -y, +z, -z, four vertices each.
// Index 0 is the top colour, 1 the sides, 2 the bottom.
const FACE_KIND = [1, 1, 0, 2, 1, 1];

function buildBlockModel(id) {
  const geo = new THREE.BoxGeometry(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  const colours = BLOCK_COLORS[id] || BLOCK_COLORS[3];
  const byKind = [colours.top, colours.side, colours.bottom];

  const count = geo.getAttribute('position').count;
  const colorAttr = new Float32Array(count * 3);
  const c = new THREE.Color();
  for (let face = 0; face < 6; face++) {
    c.setHex(byKind[FACE_KIND[face]]);
    for (let v = 0; v < 4; v++) {
      const i = (face * 4 + v) * 3;
      colorAttr[i] = c.r; colorAttr[i + 1] = c.g; colorAttr[i + 2] = c.b;
    }
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colorAttr, 3));

  // In Next Level the block in your hand should match the one in the
  // world, so remap the default 0..1 face UVs into the atlas tile.
  let material;
  if (isNextLevel() && BLOCK_TILES[id]) {
    const uv = geo.getAttribute('uv');
    for (let face = 0; face < 6; face++) {
      const rect = tileUV(BLOCK_TILES[id][FACE_KIND[face]]);
      for (let v = 0; v < 4; v++) {
        const i = face * 4 + v;
        uv.setXY(i,
          rect.u0 + uv.getX(i) * (rect.u1 - rect.u0),
          rect.v0 + uv.getY(i) * (rect.v1 - rect.v0));
      }
    }
    uv.needsUpdate = true;
    material = new THREE.MeshLambertMaterial({ map: getBlockAtlas(), vertexColors: false });
  } else {
    material = new THREE.MeshLambertMaterial({ vertexColors: true });
  }

  const group = new THREE.Group();
  group.add(new THREE.Mesh(geo, material));
  return { group, parts: {}, muzzle: null };
}

// ── Muzzle flash ─────────────────────────────────────────

const flashMaterial = new THREE.MeshBasicMaterial({
  color: 0xffe08a, transparent: true, opacity: 0, depthWrite: false,
  blending: THREE.AdditiveBlending,
});
const flash = new THREE.Mesh(new THREE.PlaneGeometry(0.22, 0.22), flashMaterial);
flash.visible = false;
viewScene.add(flash);
let flashT = 0;

// ── State ────────────────────────────────────────────────

let heldKey = null;       // identifies what's currently modelled
let held = null;          // { group, parts, muzzle }
let pose = BLOCK_POSE;
let fireT = -1;           // seconds into the fire animation, -1 when idle
let swingT = -1;          // seconds into the place/mine swing
let bobPhase = 0;
let spin = 0;             // chaingun barrel angle
let spinRate = 0;
let swayX = 0, swayY = 0;
let lastYaw = 0, lastPitch = 0;

const modelCache = new Map();

function keyFor(item) {
  if (!item) return null;
  if (item.kind === 'weapon') return 'w:' + item.weaponKey;
  if (item.kind === 'tool') return 't:' + item.toolKey;
  return 'b:' + item.id;
}

function setHeld(item) {
  const key = keyFor(item);
  if (key === heldKey) return;
  heldKey = key;

  if (held) viewScene.remove(held.group);
  held = null;
  if (!key) return;

  let model = modelCache.get(key);
  if (!model) {
    model = item.kind === 'weapon' ? (WEAPON_BUILDERS[item.weaponKey] || buildPistol)()
      : item.kind === 'tool' ? buildToolModel(item)
      : buildBlockModel(item.id);
    modelCache.set(key, model);
  }
  held = model;
  pose = item.kind === 'weapon' ? (WEAPON_POSE[item.weaponKey] || WEAPON_POSE.pistol)
    : item.kind === 'tool' ? (TOOL_TYPES[item.toolKey].tier === 'machine' ? TOOL_POSE_MACHINE : TOOL_POSE_HAND)
    : BLOCK_POSE;
  viewScene.add(held.group);
  fireT = -1;
  swingT = -1;
}

// Rebuilt on preset change, because the block model bakes in whether it's
// textured.
export function resetViewmodelModels() {
  if (held) viewScene.remove(held.group);
  for (const model of modelCache.values()) {
    model.group.traverse(o => { if (o.geometry) o.geometry.dispose(); });
  }
  modelCache.clear();
  held = null;
  heldKey = null;
}

export function triggerFire() {
  fireT = 0;
  flashT = 0.05;
  if (heldKey === 'w:chaingun') spinRate = 26;
}

export function triggerSwing() {
  if (swingT < 0 || swingT > 0.1) swingT = 0;
}

// ── Animation ────────────────────────────────────────────

// Fast out, slow back — reads as a punch rather than a wobble.
function punch(t) {
  return t < 0.28 ? t / 0.28 : 1 - (t - 0.28) / 0.72;
}

const FIRE_ANIMATIONS = {
  // Snappy kick, muzzle flips up, slide cycles.
  pistol(parts, t, g) {
    const p = punch(t);
    g.position.z += p * 0.10;
    g.rotation.x -= p * 0.30;
    if (parts.slide) parts.slide.position.z = -0.08 + p * 0.075;
  },

  // Heavy shove, then the pump is worked on the way back.
  shotgun(parts, t, g) {
    const p = punch(Math.min(1, t / 0.55));
    g.position.z += p * 0.20;
    g.position.y += p * 0.03;
    g.rotation.x -= p * 0.38;
    if (parts.pump) {
      const pumpT = Math.max(0, (t - 0.45) / 0.55);   // starts after the kick
      parts.pump.position.z = -0.14 + Math.sin(pumpT * Math.PI) * 0.16;
    }
  },

  // Barely kicks; the barrels do the talking.
  chaingun(parts, t, g) {
    const p = punch(t);
    g.position.z += p * 0.035;
    g.rotation.x -= p * 0.05;
    g.position.x += Math.sin(t * 90) * 0.006;         // vibration
  },

  // Big push back, muzzle climbs, slow settle.
  rocket(parts, t, g) {
    const p = punch(t);
    g.position.z += p * 0.26;
    g.rotation.x -= p * 0.42;
    g.rotation.z += p * 0.10;
    // The warhead has just left the tube; it comes back as you reload.
    if (parts.warhead) parts.warhead.visible = t > 0.75;
  },

  // A sharp kick then a slow bolt cycle — matches the slow fire rate, and
  // it's mostly moot anyway since the model is hidden while scoped and this
  // only plays for the moment right after firing, before it's hidden again.
  sniper(parts, t, g) {
    const p = punch(Math.min(1, t / 0.3));
    g.position.z += p * 0.28;
    g.rotation.x -= p * 0.5;
    if (parts.bolt) {
      const boltT = Math.max(0, (t - 0.3) / 0.7);
      parts.bolt.position.z = 0.05 - Math.sin(boltT * Math.PI) * 0.10;
    }
  },

  // Slow, heavy, and it takes a moment to recover.
  nuke(parts, t, g) {
    const p = punch(t);
    g.position.z += p * 0.34;
    g.position.y -= p * 0.05;
    g.rotation.x -= p * 0.5;
    g.rotation.z += Math.sin(t * 14) * 0.06 * (1 - t);
    if (parts.warhead) parts.warhead.visible = t > 0.8;
  },
};

export function updateViewmodel(dt) {
  setHeld(player.dead ? null : getSelectedItem());

  // Look-sway: the model lags behind the camera a little when you turn.
  const dYaw = player.yaw - lastYaw;
  const dPitch = player.pitch - lastPitch;
  lastYaw = player.yaw; lastPitch = player.pitch;
  const follow = 1 - Math.exp(-9 * dt);
  swayX += (THREE.MathUtils.clamp(dYaw * 0.9, -0.09, 0.09) - swayX) * follow;
  swayY += (THREE.MathUtils.clamp(-dPitch * 0.6, -0.07, 0.07) - swayY) * follow;

  if (flashT > 0) {
    flashT -= dt;
    flashMaterial.opacity = Math.max(0, flashT / 0.05) * 0.9;
    flash.visible = flashT > 0;
  }

  if (!held) return;
  // Aiming down the scope puts the eye behind the lens, not behind the gun —
  // hide the model entirely rather than posing it somewhere that would just
  // clip through the scope overlay.
  held.group.visible = !isScoped();
  const g = held.group;

  // Walk bob, scaled by how fast you're actually moving on the ground.
  const speed = Math.hypot(player.vel.x, player.vel.z);
  const grounded = player.onGround ? 1 : 0;
  bobPhase += dt * (4 + speed * 1.1);
  const bob = Math.min(1, speed / 6) * grounded;

  g.position.set(pose.pos[0] + swayX, pose.pos[1] + swayY, pose.pos[2]);
  g.rotation.set(pose.rot[0], pose.rot[1], pose.rot[2]);
  g.position.x += Math.cos(bobPhase) * 0.012 * bob;
  g.position.y += Math.abs(Math.sin(bobPhase)) * 0.014 * bob;
  g.rotation.z += Math.cos(bobPhase) * 0.03 * bob;

  // Mining / placing swing, used when you're not holding a gun.
  if (swingT >= 0) {
    swingT += dt;
    const t = swingT / pose.duration;
    if (t >= 1) {
      swingT = -1;
    } else {
      const p = Math.sin(t * Math.PI);
      g.position.z += p * 0.13;
      g.position.y -= p * 0.09;
      g.rotation.x -= p * 0.75;
    }
  }

  // Recoil.
  if (fireT >= 0) {
    fireT += dt;
    const t = fireT / pose.duration;
    if (t >= 1) {
      fireT = -1;
      for (const part of Object.values(held.parts)) {
        if (part && part.visible === false) part.visible = true;
      }
    } else {
      const key = heldKey && heldKey.startsWith('w:') ? heldKey.slice(2) : null;
      const anim = FIRE_ANIMATIONS[key];
      if (anim) anim(held.parts, t, g);
    }
  }

  // The chaingun keeps spinning down after the trigger is released.
  if (held.parts.barrels) {
    spinRate = Math.max(0, spinRate - dt * 14);
    spin += spinRate * dt;
    held.parts.barrels.rotation.z = spin;
  }

  // Close enough for something on screen for 50 ms — no need to run the
  // muzzle offset through the group's rotation.
  if (flash.visible && held.muzzle) {
    flash.position.set(
      g.position.x + held.muzzle.x,
      g.position.y + held.muzzle.y,
      g.position.z + held.muzzle.z
    );
  }
}

// Drawn after the world with the depth buffer cleared, so it can never be
// clipped by geometry the player is standing in.
export function renderViewmodel() {
  if (!renderer || !held) return;
  const size = renderer.getSize(new THREE.Vector2());
  const aspect = size.x / Math.max(1, size.y);
  if (viewCamera.aspect !== aspect) {
    viewCamera.aspect = aspect;
    viewCamera.updateProjectionMatrix();
  }
  renderer.autoClear = false;
  renderer.clearDepth();
  renderer.render(viewScene, viewCamera);
  renderer.autoClear = true;
}
