// Particle bursts and ground shockwaves, used by the mob death animations.
//
// Each burst is a single THREE.Points object (one draw call) whose vertices
// are integrated on the CPU. Bursts are short-lived and there are only ever a
// handful, so each owning its own material — needed to fade out — stays well
// inside the "share materials" rule the rest of the game follows.

import * as THREE from 'three';
import { GRAVITY } from '../config.js';
import { scene } from '../core/scene.js';

const bursts = [];
const shockwaves = [];

const MAX_BURSTS = 12;   // hard cap so a massacre can't pile up draw calls

// A puff of particles flying outwards from `origin`.
export function spawnBurst(origin, {
  color = 0xffffff,
  count = 24,
  speed = 6,
  upBias = 3,
  size = 0.14,
  life = 0.8,
  gravityScale = 1,
  spin = 0,
} = {}) {
  if (bursts.length >= MAX_BURSTS) retireBurst(0);

  const positions = new Float32Array(count * 3);
  const velocities = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    positions[i * 3]     = origin.x;
    positions[i * 3 + 1] = origin.y;
    positions[i * 3 + 2] = origin.z;
    // Random direction on a sphere, biased upwards so it reads as a "pop".
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    const s = speed * (0.4 + Math.random() * 0.6);
    velocities[i * 3]     = Math.sin(phi) * Math.cos(theta) * s;
    velocities[i * 3 + 1] = Math.cos(phi) * s + upBias;
    velocities[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * s;
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.PointsMaterial({
    color, size, transparent: true, opacity: 1, depthWrite: false,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;   // particles move well beyond their initial bounds
  scene.add(points);

  bursts.push({ points, velocities, count, life, maxLife: life, gravityScale, spin });
}

// An expanding ring on the ground — the impact of something heavy landing.
export function spawnShockwave(origin, { color = 0xffffff, maxRadius = 4, life = 0.5 } = {}) {
  const geo = new THREE.RingGeometry(0.35, 0.5, 24);
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false,
  });
  const ring = new THREE.Mesh(geo, mat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(origin.x, origin.y + 0.06, origin.z);
  scene.add(ring);
  shockwaves.push({ ring, life, maxLife: life, maxRadius });
}

function retireBurst(i) {
  const b = bursts[i];
  scene.remove(b.points);
  b.points.geometry.dispose();
  b.points.material.dispose();
  bursts.splice(i, 1);
}

function retireShockwave(i) {
  const s = shockwaves[i];
  scene.remove(s.ring);
  s.ring.geometry.dispose();
  s.ring.material.dispose();
  shockwaves.splice(i, 1);
}

export function updateDeathFx(dt) {
  for (let i = bursts.length - 1; i >= 0; i--) {
    const b = bursts[i];
    b.life -= dt;
    if (b.life <= 0) { retireBurst(i); continue; }

    const pos = b.points.geometry.getAttribute('position');
    const arr = pos.array;
    for (let p = 0; p < b.count; p++) {
      const k = p * 3;
      b.velocities[k + 1] += GRAVITY * b.gravityScale * dt;
      arr[k]     += b.velocities[k]     * dt;
      arr[k + 1] += b.velocities[k + 1] * dt;
      arr[k + 2] += b.velocities[k + 2] * dt;
    }
    pos.needsUpdate = true;
    if (b.spin) b.points.rotation.y += b.spin * dt;

    const t = b.life / b.maxLife;
    b.points.material.opacity = t;
    b.points.material.size = Math.max(0.02, b.points.material.size * (0.995 + t * 0.004));
  }

  for (let i = shockwaves.length - 1; i >= 0; i--) {
    const s = shockwaves[i];
    s.life -= dt;
    if (s.life <= 0) { retireShockwave(i); continue; }
    const t = 1 - s.life / s.maxLife;
    s.ring.scale.setScalar(0.4 + t * s.maxRadius);
    s.ring.material.opacity = 0.9 * (1 - t);
  }
}

export function clearDeathFx() {
  for (let i = bursts.length - 1; i >= 0; i--) retireBurst(i);
  for (let i = shockwaves.length - 1; i >= 0; i--) retireShockwave(i);
}
