// Sailing the things you build.
//
// Simpler than flight.js: water only ever sits at a fixed height above
// whichever body's own surface it's on — exactly body.radius+1, since a
// flat, sea-level column's surface always lands exactly at its body's own
// nominal radius by construction (world/earthTerrain.js's own coreRadius
// choice). A boat just holds itself at that fixed height above the local
// surface, steers a heading, and stops when the water runs out — there's
// no altitude to *manage* the way a plane has.
//
//   W / S    throttle forward / reverse
//   A / D    steer (rudder)
//   click    fire whatever weapon is in your hand
//   F        get in / get out
//
// While you're sailing, `player.pos` tracks the boat, the same trick
// flight.js uses, for the same reasons: mobs, multiplayer and dismounting
// all keep working unmodified.
//
// Gravity-aware the same way vehicles/flight.js is — nearestBodyOrNull()
// below finds whichever body's water this is (only the home body has any
// today, but nothing here assumes that).

import * as THREE from 'three';
import { SEA_LEVEL } from '../config.js';
import { isLiquidBlock } from '../world/blocks.js';
import { worldGetBlock } from '../world/activeWorld.js';
import { gravityAt } from '../world/gravity.js';
import { updateAlignQuaternion } from '../world/sphericalMotion.js';
import { getVisibleBodies } from '../world/spaceSession.js';
import { scene, camera } from '../core/scene.js';
import { keys } from '../core/input.js';
import { player } from '../player/state.js';
import { showLabel } from '../ui/hud.js';
import { getSelectedItem } from '../inventory.js';
import { VEHICLE_TYPES } from './types.js';
import { buildVehicleMesh } from './models.js';

const THROTTLE_RATE = 1.1;     // per second, full range in under a second
const THROTTLE_DECAY = 1.5;    // how fast it eases back to idle with no key held
const REVERSE_CAP = 0.5;       // reverse throttle tops out lower than forward
const CHASE_UP = 3.0;
const BOB_HEIGHT = 0.07;
const BOB_SPEED = 1.7;

let active = null;      // { key, def, mesh }
const orientation = new THREE.Quaternion();
const yawQuat = new THREE.Quaternion();
let yaw = 0;
let speed = 0;          // signed: +forward, -reverse
let throttle = 0;
let bobPhase = 0;

const forward = new THREE.Vector3();
const up = new THREE.Vector3(0, 1, 0);
const chase = new THREE.Vector3();
const gravityDir = new THREE.Vector3();
const surfacePoint = new THREE.Vector3();
const stepPoint = new THREE.Vector3();

const Y_AXIS = new THREE.Vector3(0, 1, 0);
const X_AXIS = new THREE.Vector3(1, 0, 0);
// A fixed downward tilt on the camera only — the boat's own orientation stays
// pure yaw (it never pitches or rolls), but a dead-level chase camera would
// stare at the horizon instead of the water right in front of the bow.
const CAMERA_PITCH = 0.14;
const camPitch = new THREE.Quaternion().setFromAxisAngle(X_AXIS, CAMERA_PITCH);
const camOrientation = new THREE.Quaternion();

export function isBoating() { return active !== null; }
export function activeBoat() { return active; }
export function getBoatThrottle() { return throttle; }
export function getBoatSpeed() { return Math.abs(speed); }

// The body whose water this is — null only if somehow called with no
// active session at all (getVisibleBodies() empty), which shouldn't happen
// during normal play.
//
// Picks whichever body's own SURFACE (its own radius) is nearest `pos`, not
// whichever body's raw centre happens to be nearest — the same fix and the
// same reasoning as world/spaceSession.js's surfaceNear (see its own
// comment): now that other bodies can sit close enough to home for several
// to be visible in the sky at once (world/starSystem.js), a boat floating
// on home's own water can genuinely be closer, in raw straight-line terms,
// to some other (much smaller) body's centre than to home's own — even
// though it's obviously on home's own water, not that other body's.
function nearestBodyOrNull(pos) {
  let best = null, bestDelta = Infinity;
  for (const body of getVisibleBodies()) {
    const delta = Math.abs(pos.distanceTo(body.center) - body.radius);
    if (delta < bestDelta) { bestDelta = delta; best = body; }
  }
  return best;
}

// Water's own surface point nearest `pos`, written into `out` — the literal
// (x, SEA_LEVEL, z) on flat Earth (`body` null), or the point at exactly
// body.radius along the direction from its centre through `pos` in space
// (see the module comment above for why that radius is exactly where a
// flooded column's surface lands). Safe to call with `out === pos`.
function waterSurfacePoint(pos, body, out) {
  if (!body) { out.set(pos.x, SEA_LEVEL, pos.z); return out; }
  out.copy(pos).sub(body.center).normalize().multiplyScalar(body.radius).add(body.center);
  return out;
}

function isWaterAt(pos, body) {
  waterSurfacePoint(pos, body, surfacePoint);
  return isLiquidBlock(worldGetBlock(Math.floor(surfacePoint.x), Math.floor(surfacePoint.y), Math.floor(surfacePoint.z)));
}

// Mounts whatever boat is in the selected hotbar slot.
export function mountBoat() {
  const item = getSelectedItem();
  if (!item || item.kind !== 'vehicle') {
    showLabel('Hold a vehicle to board it');
    return false;
  }
  const def = VEHICLE_TYPES[item.vehicleKey];
  if (!def || def.mode !== 'boat') {
    if (def) showLabel(def.label + ' needs sky, not water');
    return false;
  }
  const body = nearestBodyOrNull(player.pos);
  if (!isWaterAt(player.pos, body)) {
    showLabel('Needs open water to launch');
    return false;
  }

  const mesh = buildVehicleMesh(item.vehicleKey);
  scene.add(mesh);
  active = { key: item.vehicleKey, def, mesh };
  yaw = player.yaw;
  const g = gravityAt(player.pos);
  updateAlignQuaternion(player.spaceAlignQuat, g.dir);
  yawQuat.setFromAxisAngle(Y_AXIS, yaw);
  orientation.copy(player.spaceAlignQuat).multiply(yawQuat);
  speed = 0;
  throttle = 0;
  waterSurfacePoint(player.pos, body, surfacePoint);
  up.copy(g.dir).negate();
  player.pos.copy(surfacePoint).addScaledVector(up, 1);
  player.piloting = true;
  showLabel(def.label + ' — W/S throttle, A/D steer, F to disembark');
  return true;
}

export function dismountBoat(reason = '') {
  if (!active) return;
  scene.remove(active.mesh);
  active = null;
  player.piloting = false;
  player.vel.set(0, 0, 0);
  if (reason) showLabel(reason);
}

export function toggleBoat() {
  if (active) dismountBoat('Docked');
  else mountBoat();
}

export function updateBoat(dt) {
  if (!active) return;
  const def = active.def;

  const g = gravityAt(player.pos);
  gravityDir.copy(g.dir);
  updateAlignQuaternion(player.spaceAlignQuat, gravityDir);

  let steer = 0;
  if (keys['KeyA']) steer += 1;
  if (keys['KeyD']) steer -= 1;
  // Steering bites harder at speed and barely at all sitting still, the way
  // an actual rudder does — without this a stationary boat could still spin
  // on the spot, which reads as the water not existing at all.
  const steerAuthority = Math.min(1, 0.25 + Math.abs(speed) / Math.max(1, def.maxSpeed));
  yaw += steer * def.turnRate * dt * steerAuthority;
  yawQuat.setFromAxisAngle(Y_AXIS, yaw);
  orientation.copy(player.spaceAlignQuat).multiply(yawQuat);

  if (keys['KeyW']) throttle = Math.min(1, throttle + THROTTLE_RATE * dt);
  else if (keys['KeyS']) throttle = Math.max(-REVERSE_CAP, throttle - THROTTLE_RATE * dt);
  else throttle *= Math.max(0, 1 - THROTTLE_DECAY * dt);

  const targetSpeed = throttle * def.maxSpeed;
  if (speed < targetSpeed) speed = Math.min(targetSpeed, speed + def.thrust * dt);
  else speed = Math.max(targetSpeed, speed - def.thrust * dt);

  forward.set(0, 0, -1).applyQuaternion(orientation);
  stepPoint.copy(player.pos).addScaledVector(forward, speed * dt);

  const body = nearestBodyOrNull(player.pos);
  // Driving onto dry land just stops the boat, like nudging a dock — there's
  // no engine here forceful enough for a "crash" the way a jet gets one.
  if (!isWaterAt(stepPoint, body)) {
    speed = 0;
  } else {
    player.pos.copy(stepPoint);
  }

  // A gentle bob, faster and taller the harder the engine's working, so a
  // boat sitting idle doesn't look frozen to the water's surface. Snapping
  // back onto the exact water surface every frame (rather than just adding
  // the bob to whatever y the tangential step left) is what keeps a boat
  // glued to a curved sea in space — the same "move on the tangent plane,
  // then renormalise onto the real surface" pattern
  // world/blockTarget.js's recentreOnTarget uses for the player's own feet.
  bobPhase += dt * BOB_SPEED * (0.6 + Math.abs(speed) / Math.max(1, def.maxSpeed) * 0.5);
  up.copy(gravityDir).negate();
  waterSurfacePoint(player.pos, body, surfacePoint);
  player.pos.copy(surfacePoint).addScaledVector(up, 1 + Math.sin(bobPhase) * BOB_HEIGHT);
  player.vel.copy(forward).multiplyScalar(speed);

  // ── Presentation ──
  active.mesh.position.copy(player.pos);
  active.mesh.quaternion.copy(orientation);

  chase.copy(player.pos)
    .addScaledVector(forward, -(def.chase || 6))
    .addScaledVector(up, CHASE_UP);
  camera.position.copy(chase);
  camOrientation.copy(orientation).multiply(camPitch);
  camera.quaternion.copy(camOrientation);

  // player.yaw is read back in the gravity-aligned frame everywhere else
  // (player/view.js's space camera branch, player/physics.js's own walk) —
  // spaceAlignQuat * yaw is exactly what orientation already is above, so
  // storing the bare yaw scalar here is correct in both environments; on
  // flat ground spaceAlignQuat is the identity and this is exactly the
  // original formula.
  player.yaw = yaw;
  player.pitch = 0;
}

export function clearBoat() {
  if (active) {
    scene.remove(active.mesh);
    active = null;
  }
  player.piloting = false;
  speed = 0;
  throttle = 0;
}
